  ('ensaladas_verduras_025', 'Verduras al vapor', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 118, 4, 10, 8, 2, true, true, '{}', '[{"name":"Brócoli","amount":150,"unit":"g"},{"name":"Zanahoria","amount":100,"unit":"g"},{"name":"Judías verdes","amount":100,"unit":"g"},{"name":"Calabacín","amount":100,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Pelar zanahoria y cortar en rodajas de 1 cm.","Cortar brócoli en ramilletes de tamaño similar.","Retirar los extremos de judías verdes y cortar en trozos de 4 cm.","Cortar calabacín en rodajas de 1 cm sin pelar.","Llevar a ebullición 1 l de agua en una olla con cesto de vapor a fuego fuerte.","Disponer la zanahoria y las judías verdes en el cesto, tapar y cocer al vapor 5 min.","Añadir el brócoli y el calabacín al cesto y cocer al vapor 5 min más, hasta que todas las verduras estén tiernas pero firmes.","Retirar el cesto y escurrir las verduras sobre una fuente de servir.","Aliñar con aceite de oliva y servir de inmediato."}', 'Mix de verduras cocidas al vapor, ligeras y nutritivas', '[{"appliance":"thermomix","time":20,"difficulty":"facil","prepSummary":"Corta las verduras en trozos uniformes. Añade 500ml de agua al vaso, coloca las verduras en el recipiente Varoma y cocina 20 minutos, Varoma, velocidad 1. Aliña con el aceite de oliva al servir."},{"appliance":"vaporera","time":18,"difficulty":"facil","prepSummary":"Corta las verduras en trozos de tamaño similar. Coloca agua en la base de la vaporera y las verduras en la cesta. Cocina al vapor durante 18 minutos hasta que estén tiernas. Aliña con el aceite de oliva."},{"appliance":"olla_express","time":7,"difficulty":"facil","prepSummary":"Vierte 200ml de agua en la base de la olla y coloca las verduras en una cesta de vapor. Cierra la olla y cocina a fuego medio-alto durante 3-4 minutos desde que sube la válvula. Despresuriza y aliña con el aceite."},{"appliance":"microondas","time":8,"difficulty":"facil","prepSummary":"Corta las verduras y colócalas en un recipiente apto para microondas con un par de cucharadas de agua. Tapa y cocina a máxima potencia durante 7-8 minutos, removiendo a mitad de cocción, hasta que estén tiernas. Aliña con el aceite de oliva."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], false, '[{"text":"Pelar {{Zanahoria}} y cortar en rodajas de 1 cm.","minutes":2,"kind":"prep"},{"text":"Cortar {{Brócoli}} en ramilletes de tamaño similar.","minutes":2,"kind":"prep"},{"text":"Retirar los extremos de {{Judías verdes}} y cortar en trozos de 4 cm.","minutes":1,"kind":"prep"},{"text":"Cortar {{Calabacín}} en rodajas de 1 cm sin pelar.","minutes":1,"kind":"prep"},{"text":"Llevar a ebullición 1 l de agua en una olla con cesto de vapor a fuego fuerte.","minutes":3,"kind":"activo"},{"text":"Disponer la zanahoria y las judías verdes en el cesto, tapar y cocer al vapor 5 min.","minutes":5,"kind":"pasivo"},{"text":"Añadir el brócoli y el calabacín al cesto y cocer al vapor 5 min más, hasta que todas las verduras estén tiernas pero firmes.","minutes":5,"kind":"pasivo"},{"text":"Retirar el cesto y escurrir las verduras sobre una fuente de servir.","minutes":1,"kind":"activo"},{"text":"Aliñar con {{Aceite de oliva|chorrito}} y servir de inmediato.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'olla', NULL),
  ('ensaladas_verduras_026', 'Ensalada de espinacas, queso de cabra y nueces', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'all', 342, 10, 16, 26, 2, false, false, '{"lactosa","frutos_secos","mostaza","sulfitos"}', '[{"name":"Espinacas baby","amount":120,"unit":"g"},{"name":"Queso de cabra","amount":80,"unit":"g"},{"name":"Nueces","amount":40,"unit":"g"},{"name":"Arándanos","amount":40,"unit":"g"},{"name":"Cebolla morada","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Miel","amount":10,"unit":"g"},{"name":"Mostaza","amount":5,"unit":"g"},{"name":"Vinagre","amount":10,"unit":"ml"}]'::jsonb, '{"Pelar cebolla morada y laminar en tiras finas.","Cortar queso de cabra en trozos irregulares y reservar.","Disponer espinacas baby en una fuente o bol amplio.","Repartir el queso de cabra, nueces y arándanos sobre las espinacas.","Añadir la cebolla morada laminada sobre el resto de ingredientes.","Mezclar aceite de oliva, miel, mostaza y vinagre en un bol pequeño hasta emulsionar.","Aliñar la ensalada con la vinagreta al momento y servir."}', 'Ensalada de espinacas baby con queso de cabra, nueces, arándanos y vinagreta de miel y mostaza', '[]'::jsonb, '{}', NULL, true, NULL, '{"verdura","lacteo","frutos_secos"}', NULL, '{}'::main_protein[], false, '[{"text":"Pelar {{Cebolla morada}} y laminar en tiras finas.","minutes":2,"kind":"prep"},{"text":"Cortar {{Queso de cabra}} en trozos irregulares y reservar.","minutes":1,"kind":"prep"},{"text":"Disponer {{Espinacas baby}} en una fuente o bol amplio.","minutes":1,"kind":"prep"},{"text":"Repartir el queso de cabra, {{Nueces}} y {{Arándanos}} sobre las espinacas.","minutes":1,"kind":"prep"},{"text":"Añadir la cebolla morada laminada sobre el resto de ingredientes.","minutes":1,"kind":"prep"},{"text":"Mezclar {{Aceite de oliva}}, {{Miel}}, {{Mostaza}} y {{Vinagre}} en un bol pequeño hasta emulsionar.","minutes":1,"kind":"activo"},{"text":"Aliñar la ensalada con la vinagreta al momento y servir.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'crudo', NULL),
  ('ensaladas_verduras_027', 'Ensalada caprese', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'verano', 328, 16, 10, 24, 2, true, false, '{"lactosa","sulfitos"}', '[{"name":"Tomate","amount":300,"unit":"g"},{"name":"Mozzarella fresca","amount":150,"unit":"g"},{"name":"Albahaca fresca","amount":10,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":20,"unit":"ml"},{"name":"Crema de vinagre balsámico","amount":10,"unit":"ml"}]'::jsonb, '{"Laminar tomate en rodajas de unos 5 mm de grosor.","Laminar mozzarella fresca en rodajas del mismo grosor que el tomate.","Alternar rodajas de tomate y mozzarella en el plato, solapándolas ligeramente.","Repartir albahaca fresca sobre las rodajas.","Aliñar con aceite de oliva virgen extra y crema de vinagre balsámico en hilo fino por encima.","Servir de inmediato."}', 'Ensalada caprese con tomate, mozzarella fresca, albahaca y balsámico', '[]'::jsonb, '{}', NULL, true, NULL, '{"verdura","lacteo"}', NULL, '{}'::main_protein[], false, '[{"text":"Laminar {{Tomate}} en rodajas de unos 5 mm de grosor.","minutes":2,"kind":"prep"},{"text":"Laminar {{Mozzarella fresca}} en rodajas del mismo grosor que el tomate.","minutes":2,"kind":"prep"},{"text":"Alternar rodajas de tomate y mozzarella en el plato, solapándolas ligeramente.","minutes":1,"kind":"emplatado"},{"text":"Repartir {{Albahaca fresca}} sobre las rodajas.","minutes":1,"kind":"emplatado"},{"text":"Aliñar con {{Aceite de oliva virgen extra|chorrito}} y {{Crema de vinagre balsámico|chorrito}} en hilo fino por encima.","minutes":1,"kind":"emplatado"},{"text":"Servir de inmediato.","kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'crudo', 'italiana'),
  ('ensaladas_verduras_028', 'Ensalada de garbanzos, pimiento y maíz', 'ensaladas_verduras', 'legumbre', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'all', 312, 13, 36, 12, 2, true, true, '{"sulfitos"}', '[{"name":"Garbanzos cocidos","amount":300,"unit":"g"},{"name":"Pimiento rojo","amount":80,"unit":"g"},{"name":"Maíz dulce","amount":60,"unit":"g"},{"name":"Tomate cherry","amount":100,"unit":"g"},{"name":"Cebolla morada","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Vinagre","amount":10,"unit":"ml"}]'::jsonb, '{"Escurrir garbanzos cocidos en un colador y enjuagar bajo el grifo con agua fría hasta que el agua salga limpia.","Cortar pimiento rojo en dados pequeños.","Cortar tomate cherry por la mitad.","Picar cebolla morada en dados finos.","Mezclar en un bol los garbanzos escurridos, el pimiento en dados, los tomates cherry y la cebolla morada picada.","Añadir maíz dulce al bol y remover hasta que todos los ingredientes queden integrados.","Aliñar con aceite de oliva y vinagre, remover bien y servir."}', 'Ensalada fresca de garbanzos con pimiento, maíz, cherry y cebolla morada', '[]'::jsonb, '{}', NULL, true, NULL, '{"verdura"}', NULL, '{}'::main_protein[], false, '[{"text":"Escurrir {{Garbanzos cocidos}} en un colador y enjuagar bajo el grifo con agua fría hasta que el agua salga limpia.","minutes":1,"kind":"prep"},{"text":"Cortar {{Pimiento rojo}} en dados pequeños.","minutes":1,"kind":"prep"},{"text":"Cortar {{Tomate cherry}} por la mitad.","minutes":1,"kind":"prep"},{"text":"Picar {{Cebolla morada}} en dados finos.","minutes":1,"kind":"prep"},{"text":"Mezclar en un bol los garbanzos escurridos, el pimiento en dados, los tomates cherry y la cebolla morada picada.","minutes":1,"kind":"activo"},{"text":"Añadir {{Maíz dulce}} al bol y remover hasta que todos los ingredientes queden integrados.","minutes":1,"kind":"activo"},{"text":"Aliñar con {{Aceite de oliva|chorrito}} y {{Vinagre}}, remover bien y servir.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'crudo', NULL),
  ('ensaladas_verduras_029', 'Ensalada de lentejas, tomate y comino', 'ensaladas_verduras', 'legumbre', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'all', 298, 15, 34, 10, 2, true, true, '{"sulfitos"}', '[{"name":"Lentejas cocidas","amount":300,"unit":"g"},{"name":"Tomate","amount":120,"unit":"g"},{"name":"Pepino","amount":80,"unit":"g"},{"name":"Cebolla morada","amount":30,"unit":"g"},{"name":"Comino","amount":2,"unit":"g"},{"name":"Perejil","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Vinagre","amount":10,"unit":"ml"}]'::jsonb, '{"Escurrir lentejas cocidas y reservar en un bol grande.","Cortar tomate en dados pequeños.","Cortar pepino en dados pequeños.","Picar cebolla morada muy fina.","Picar perejil fino.","Añadir el tomate, el pepino y la cebolla morada al bol con las lentejas cocidas.","Añadir comino y el perejil picado; mezclar bien.","Aliñar con aceite de oliva y vinagre; remover hasta que todo quede bien integrado.","Servir la ensalada en platos o en el mismo bol."}', 'Ensalada de lentejas con tomate, pepino, cebolla morada y un toque de comino', '[]'::jsonb, '{}', NULL, true, NULL, '{"verdura"}', NULL, '{}'::main_protein[], false, '[{"text":"Escurrir {{Lentejas cocidas}} y reservar en un bol grande.","minutes":1,"kind":"prep"},{"text":"Cortar {{Tomate}} en dados pequeños.","minutes":2,"kind":"prep"},{"text":"Cortar {{Pepino}} en dados pequeños.","minutes":1,"kind":"prep"},{"text":"Picar {{Cebolla morada}} muy fina.","minutes":1,"kind":"prep"},{"text":"Picar {{Perejil}} fino.","minutes":1,"kind":"prep"},{"text":"Añadir el tomate, el pepino y la cebolla morada al bol con las lentejas cocidas.","minutes":1,"kind":"activo"},{"text":"Añadir {{Comino|pizca}} y el perejil picado; mezclar bien.","minutes":1,"kind":"activo"},{"text":"Aliñar con {{Aceite de oliva|chorrito}} y {{Vinagre}}; remover hasta que todo quede bien integrado.","minutes":1,"kind":"activo"},{"text":"Servir la ensalada en platos o en el mismo bol.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'crudo', NULL),
  ('ensaladas_verduras_030', 'Ensalada de tomate, aguacate y cebolla morada', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 8, 'facil', 'verano', 236, 4, 14, 18, 2, true, false, '{}', '[{"name":"Tomate","amount":300,"unit":"g"},{"name":"Aguacate","amount":1,"unit":"ud"},{"name":"Cebolla morada","amount":40,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":20,"unit":"ml"},{"name":"Orégano","amount":2,"unit":"g"}]'::jsonb, '{"Cortar tomate en gajos medianos y reservar en una fuente.","Cortar aguacate por la mitad, retirar el hueso, pelar y laminar.","Laminar cebolla morada en tiras muy finas.","Disponer los gajos de tomate, las láminas de aguacate y la cebolla morada en la fuente.","Aliñar con aceite de oliva virgen extra repartido por toda la ensalada.","Terminar con orégano por encima y servir de inmediato."}', 'Ensalada de tomate maduro con aguacate y cebolla morada', '[]'::jsonb, '{}', NULL, true, NULL, '{"verdura"}', NULL, '{}'::main_protein[], false, '[{"text":"Cortar {{Tomate}} en gajos medianos y reservar en una fuente.","minutes":2,"kind":"prep"},{"text":"Cortar {{Aguacate}} por la mitad, retirar el hueso, pelar y laminar.","minutes":2,"kind":"prep"},{"text":"Laminar {{Cebolla morada}} en tiras muy finas.","minutes":1,"kind":"prep"},{"text":"Disponer los gajos de tomate, las láminas de aguacate y la cebolla morada en la fuente.","minutes":1,"kind":"activo"},{"text":"Aliñar con {{Aceite de oliva virgen extra}} repartido por toda la ensalada.","minutes":1,"kind":"activo"},{"text":"Terminar con {{Orégano|pizca}} por encima y servir de inmediato.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'crudo', NULL),
  ('ensaladas_verduras_031', 'Tosta de burrata, tomate y pesto', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'verano', 380, 13, 28, 24, 2, true, false, '{"gluten","lactosa","frutos_secos"}', '[{"name":"Pan rústico","amount":100,"unit":"g"},{"name":"Burrata","amount":125,"unit":"g"},{"name":"Tomate cherry","amount":150,"unit":"g"},{"name":"Pesto de albahaca","amount":30,"unit":"g"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"},{"name":"Albahaca fresca","amount":5,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Lavar tomate cherry y cortar cada uno por la mitad.","Cortar pan rústico en rebanadas gruesas de unos 2 cm.","Calentar plancha a fuego fuerte y tostar las rebanadas de pan hasta que estén doradas y crujientes por ambas caras.","Frotar ajo pelado sobre cada tostada caliente para perfumarla.","Escurrir burrata y partirla en trozos irregulares con las manos.","Repartir los trozos de burrata sobre las tostadas templadas.","Colocar los tomates cherry encima y alrededor de la burrata.","Distribuir pesto de albahaca sobre cada tosta y añadir aceite de oliva.","Terminar con hojas de albahaca fresca y sal y servir enseguida."}', 'Tosta crujiente con burrata cremosa, tomate cherry fresco y pesto de albahaca.', '[{"appliance":"airfryer","time":12,"difficulty":"facil","prepSummary":"Tuesta el pan rústico a 180°C durante 5-7 minutos hasta que esté dorado y crujiente. Puedes añadir los tomates cherry con un poco de aceite los últimos 3 minutos para que se templen y ablanden ligeramente, realzando su sabor."},{"appliance":"horno","time":18,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C. Tuesta el pan durante 5-7 minutos hasta que esté dorado. Para potenciar el sabor, asa los tomates cherry partidos por la mitad con un chorrito de aceite y sal durante 10-12 minutos hasta que estén ligeramente caramelizados."}]'::jsonb, '{}', NULL, true, NULL, '{"verdura","lacteo"}', NULL, '{}'::main_protein[], false, '[{"text":"Lavar {{Tomate cherry}} y cortar cada uno por la mitad.","minutes":2,"kind":"prep"},{"text":"Cortar {{Pan rústico}} en rebanadas gruesas de unos 2 cm.","minutes":1,"kind":"prep"},{"text":"Calentar {{@Plancha}} a fuego fuerte y tostar las rebanadas de pan hasta que estén doradas y crujientes por ambas caras.","minutes":4,"kind":"activo"},{"text":"Frotar {{Ajo}} pelado sobre cada tostada caliente para perfumarla.","minutes":1,"kind":"activo"},{"text":"Escurrir {{Burrata}} y partirla en trozos irregulares con las manos.","minutes":1,"kind":"prep"},{"text":"Repartir los trozos de burrata sobre las tostadas templadas.","minutes":1,"kind":"emplatado"},{"text":"Colocar los tomates cherry encima y alrededor de la burrata.","minutes":1,"kind":"emplatado"},{"text":"Distribuir {{Pesto de albahaca}} sobre cada tosta y añadir {{Aceite de oliva|chorrito}}.","minutes":1,"kind":"emplatado"},{"text":"Terminar con hojas de {{Albahaca fresca}} y {{Sal|gusto}} y servir enseguida.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'crudo', 'italiana'),
  ('ensaladas_verduras_032', 'Nachos con guacamole y queso fundido', 'ensaladas_verduras', 'none', NULL, ARRAY['cena']::meal_role[], 'completo', NULL, 'horno', 25, 'facil', 'all', 528, 15, 45, 32, 2, true, false, '{"lactosa","sulfitos"}', '[{"name":"Nachos de maíz","amount":120,"unit":"g"},{"name":"Aguacate","amount":200,"unit":"g"},{"name":"Tomate","amount":100,"unit":"g"},{"name":"Cebolla","amount":30,"unit":"g"},{"name":"Lima","amount":20,"unit":"ml"},{"name":"Cilantro fresco","amount":5,"unit":"g"},{"name":"Queso rallado para fundir","amount":100,"unit":"g"},{"name":"Jalapeños en vinagre","amount":20,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C con función grill.","Picar cebolla en dados muy finos y dividir en dos partes iguales.","Picar tomate en dados pequeños y reservar.","Picar cilantro fresco fino y reservar.","Abrir aguacate, retirar el hueso y volcar la pulpa en un bol.","Machacar la pulpa del aguacate con un tenedor hasta obtener una textura cremosa con pequeños trozos.","Añadir la mitad de la cebolla picada, lima, el cilantro picado y sal al aguacate machacado.","Mezclar bien el guacamole hasta integrar todos los ingredientes y reservar.","Extender nachos de maíz en una fuente apta para horno formando una capa uniforme.","Repartir queso rallado para fundir de manera uniforme sobre los nachos.","Hornear con grill a 200 °C hasta que el queso funda y burbujee, unos 6 min.","Retirar la fuente del horno y repartir el tomate picado, la cebolla restante y jalapeños en vinagre sobre los nachos.","Servir de inmediato con el guacamole reservado a un lado."}', 'Capas de nachos con queso fundido, guacamole cremoso y jalapeños, listos en un momento.', '[{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Precalienta el horno a 180°C. Extiende los nachos en una bandeja, cubre con el queso rallado y los jalapeños. Hornea durante 10-12 minutos, o hasta que el queso esté completamente fundido y burbujeante. Sirve inmediatamente con el guacamole recién hecho."},{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 180°C. Coloca una capa de nachos en la cesta, cubre con el queso y los jalapeños. Cocina por 8-10 minutos, agitando ligeramente a mitad, hasta que el queso esté fundido y los nachos ligeramente crujientes. Sirve con el guacamole."}]'::jsonb, '{}', NULL, true, NULL, '{"verdura","lacteo"}', NULL, '{}'::main_protein[], false, '[{"text":"Precalentar el horno a 200 °C con función grill.","minutes":5,"kind":"pasivo"},{"text":"Picar {{Cebolla}} en dados muy finos y dividir en dos partes iguales.","minutes":2,"kind":"prep"},{"text":"Picar {{Tomate}} en dados pequeños y reservar.","minutes":2,"kind":"paralelo","during":0},{"text":"Picar {{Cilantro fresco}} fino y reservar.","minutes":1,"kind":"paralelo","during":0},{"text":"Abrir {{Aguacate}}, retirar el hueso y volcar la pulpa en un bol.","minutes":1,"kind":"prep","part":"salsa"},{"text":"Machacar la pulpa del aguacate con un tenedor hasta obtener una textura cremosa con pequeños trozos.","minutes":1,"kind":"activo","part":"salsa"},{"text":"Añadir la mitad de la cebolla picada, {{Lima}}, el cilantro picado y {{Sal|gusto}} al aguacate machacado.","minutes":1,"kind":"activo","part":"salsa"},{"text":"Mezclar bien el guacamole hasta integrar todos los ingredientes y reservar.","minutes":1,"kind":"activo","part":"salsa"},{"text":"Extender {{Nachos de maíz}} en una fuente apta para horno formando una capa uniforme.","minutes":1,"kind":"prep","part":"principal"},{"text":"Repartir {{Queso rallado para fundir}} de manera uniforme sobre los nachos.","minutes":1,"kind":"prep","part":"principal"},{"text":"Hornear con grill a 200 °C hasta que el queso funda y burbujee, unos 6 min.","minutes":6,"kind":"pasivo","part":"principal"},{"text":"Retirar la fuente del horno y repartir el tomate picado, la cebolla restante y {{Jalapeños en vinagre}} sobre los nachos.","minutes":1,"kind":"activo","part":"combinado"},{"text":"Servir de inmediato con el guacamole reservado a un lado.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true, NULL, NULL, 'crudo', 'mexicana'),
  ('ensaladas_verduras_033', 'Tortitas saladas de calabacín rallado', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 306, 14, 22, 18, 2, true, false, '{"huevo","gluten","lactosa"}', '[{"name":"Calabacín","amount":300,"unit":"g"},{"name":"Huevo","amount":100,"unit":"g"},{"name":"Harina de trigo","amount":40,"unit":"g"},{"name":"Queso parmesano rallado","amount":30,"unit":"g"},{"name":"Cebolleta","amount":20,"unit":"g"},{"name":"Eneldo fresco","amount":5,"unit":"g"},{"name":"Yogur griego","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Rallar calabacín con un rallador fino sobre un bol.","Mezclar el calabacín rallado con sal y colocarlo en un colador sobre el fregadero.","Dejar reposar el calabacín en el colador 10 min para que suelte el agua.","Picar cebolleta muy fina.","Picar eneldo fresco fino.","Mezclar yogur griego con el eneldo picado y sal en un bol pequeño hasta integrar.","Escurrir el calabacín apretando con fuerza con las manos hasta que quede lo más seco posible.","Batir huevo en un bol grande.","Añadir el calabacín escurrido, harina de trigo, queso parmesano rallado y la cebolleta picada al bol.","Mezclar bien hasta obtener una masa espesa y homogénea.","Calentar aceite de oliva en sartén a fuego medio hasta que esté caliente.","Depositar 2 cucharadas de masa por tortita en la sartén, aplanando ligeramente cada una.","Cocer las tortitas 3 min por el primer lado hasta que se doren y cuajen los bordes.","Dar la vuelta a las tortitas y cocer 3 min más por el otro lado hasta que estén doradas.","Servir las tortitas calientes con la salsa de yogur griego al lado."}', 'Tortitas doradas de calabacín rallado con queso, servidas con una salsa fresca de yogur.', '[{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190°C. Coloca las tortitas ligeramente aceitadas y cocina por 16-20 minutos, dándoles la vuelta a mitad para un dorado uniforme y crujiente."},{"appliance":"horno","time":22,"difficulty":"facil","prepSummary":"Hornea a 200°C sobre papel de horno durante 20-25 minutos, volteando a mitad de cocción. Quedarán doradas y cocidas uniformemente, con una textura ligeramente más suave."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura","lacteo"}', NULL, '{}'::main_protein[], false, '[{"text":"Rallar {{Calabacín}} con un rallador fino sobre un bol.","minutes":2,"kind":"prep"},{"text":"Mezclar el calabacín rallado con {{Sal|gusto}} y colocarlo en un colador sobre el fregadero.","minutes":1,"kind":"prep"},{"text":"Dejar reposar el calabacín en el colador 10 min para que suelte el agua.","minutes":10,"kind":"espera"},{"text":"Picar {{Cebolleta}} muy fina.","minutes":1,"kind":"paralelo","during":2},{"text":"Picar {{Eneldo fresco}} fino.","minutes":1,"kind":"paralelo","during":2},{"text":"Mezclar {{Yogur griego}} con el eneldo picado y {{Sal|gusto}} en un bol pequeño hasta integrar.","minutes":1,"kind":"paralelo","during":2},{"text":"Escurrir el calabacín apretando con fuerza con las manos hasta que quede lo más seco posible.","minutes":2,"kind":"prep"},{"text":"Batir {{Huevo}} en un bol grande.","minutes":1,"kind":"prep"},{"text":"Añadir el calabacín escurrido, {{Harina de trigo}}, {{Queso parmesano rallado}} y la cebolleta picada al bol.","minutes":1,"kind":"prep"},{"text":"Mezclar bien hasta obtener una masa espesa y homogénea.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego medio hasta que esté caliente.","minutes":1,"kind":"activo"},{"text":"Depositar 2 cucharadas de masa por tortita en la sartén, aplanando ligeramente cada una.","minutes":1,"kind":"activo"},{"text":"Cocer las tortitas 3 min por el primer lado hasta que se doren y cuajen los bordes.","minutes":3,"kind":"activo"},{"text":"Dar la vuelta a las tortitas y cocer 3 min más por el otro lado hasta que estén doradas.","minutes":3,"kind":"activo"},{"text":"Servir las tortitas calientes con la salsa de yogur griego al lado.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL),
  ('ensaladas_verduras_034', 'Ensalada de burrata y tomate de bote', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'all', 334, 14, 20, 22, 2, true, false, '{"lactosa","gluten"}', '[{"name":"Burrata","amount":250,"unit":"g"},{"name":"Tomate triturado de bote","amount":200,"unit":"g"},{"name":"Pan rústico","amount":80,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":20,"unit":"ml"},{"name":"Orégano seco","amount":2,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Escurrir tomate triturado de bote presionando con un colador para eliminar el exceso de líquido.","Repartir el tomate escurrido en el fondo de 2 platos formando una base uniforme.","Salpimentar el tomate con sal y pimienta negra.","Añadir aceite de oliva virgen extra sobre el tomate de cada plato.","Escurrir burrata y colocarla en el centro de cada plato, entera o partida por la mitad.","Espolvorear orégano seco sobre la burrata y el tomate.","Tostar pan rústico en una tostadora o sartén a fuego medio hasta que esté crujiente.","Servir la ensalada con el pan tostado aparte para mojar."}', 'Burrata cremosa sobre tomate triturado bien aliñado, casi sin necesidad de cortar nada.', '[{"appliance":"airfryer","time":10,"difficulty":"facil","prepSummary":"Tostar el pan rústico en la airfryer a 180°C durante 5-7 minutos hasta que esté crujiente. El tomate triturado se puede servir a temperatura ambiente o ligeramente templado aparte."},{"appliance":"horno","time":15,"difficulty":"facil","prepSummary":"Precalentar el horno a 180°C. Tostar el pan rústico durante 8-10 minutos y, al mismo tiempo, calentar ligeramente el tomate triturado con aceite y orégano en un recipiente apto para horno."},{"appliance":"thermomix","time":10,"difficulty":"facil","prepSummary":"Preparar una base de tomate templada y emulsionada calentando el tomate triturado con aceite, orégano, sal y pimienta a 80°C, velocidad 2, durante 5 minutos. El pan se tuesta aparte."}]'::jsonb, '{}', NULL, true, NULL, '{"lacteo"}', NULL, '{}'::main_protein[], false, '[{"text":"Escurrir {{Tomate triturado de bote}} presionando con un colador para eliminar el exceso de líquido.","minutes":2,"kind":"prep"},{"text":"Repartir el tomate escurrido en el fondo de 2 platos formando una base uniforme.","minutes":1,"kind":"activo"},{"text":"Salpimentar el tomate con {{Sal|gusto}} y {{Pimienta negra|pizca}}.","minutes":1,"kind":"activo"},{"text":"Añadir {{Aceite de oliva virgen extra|chorrito}} sobre el tomate de cada plato.","minutes":1,"kind":"activo"},{"text":"Escurrir {{Burrata}} y colocarla en el centro de cada plato, entera o partida por la mitad.","minutes":1,"kind":"activo"},{"text":"Espolvorear {{Orégano seco|pizca}} sobre la burrata y el tomate.","minutes":1,"kind":"activo"},{"text":"Tostar {{Pan rústico}} en una tostadora o sartén a fuego medio hasta que esté crujiente.","minutes":3,"kind":"activo"},{"text":"Servir la ensalada con el pan tostado aparte para mojar.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'crudo', NULL)
