insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id, extra_proteins, freezable, steps_rich, estrella, occasion, kid_favourite, tecnica, cocina
) values
  ('ensaladas_verduras_035', 'Quesadilla de champiñones y queso', 'ensaladas_verduras', 'none', NULL, ARRAY['cena','primero']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 425, 18, 32, 25, 2, true, false, '{"gluten","lactosa"}', '[{"name":"Tortillas de trigo","amount":120,"unit":"g"},{"name":"Champiñones","amount":200,"unit":"g"},{"name":"Queso rallado para fundir","amount":120,"unit":"g"},{"name":"Cebolla","amount":40,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"},{"name":"Pimentón dulce","amount":2,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Laminar champiñones en láminas de unos 3 mm.","Picar cebolla y ajo lo más fino posible.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla y el ajo hasta que estén blandos y translúcidos.","Añadir los champiñones laminados y sal; subir a fuego fuerte.","Saltear los champiñones hasta que suelten el agua y se doren bien.","Añadir pimentón dulce, remover y retirar la sartén del fuego.","Extender el relleno de champiñones sobre la mitad de cada tortillas de trigo.","Repartir queso rallado para fundir sobre el relleno de cada tortilla.","Doblar cada tortilla por la mitad para cerrar la quesadilla.","Calentar sartén a fuego medio-fuerte sin añadir aceite.","Dorar la quesadilla por el primer lado hasta que esté crujiente y dorada.","Dar la vuelta y dorar por el otro lado hasta que el queso funda por completo.","Cortar cada quesadilla en triángulos y servir de inmediato."}', 'Quesadilla dorada y crujiente rellena de champiñones salteados y queso fundido.', '[{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Saltea el relleno de champiñones, cebolla y ajo. Monta la quesadilla y cocínala en la airfryer a 180°C durante 8-10 minutos, volteándola a mitad para un dorado uniforme y queso fundido."},{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Prepara el relleno salteando champiñones, cebolla y ajo. Monta las quesadillas y hornéalas en el horno precalentado a 200°C (con calor arriba y abajo) durante 10-12 minutos, hasta que estén doradas y el queso fundido."}]'::jsonb, '{}', NULL, true, NULL, '{"lacteo","seta"}', NULL, '{}'::main_protein[], false, '[{"text":"Laminar {{Champiñones}} en láminas de unos 3 mm.","minutes":3,"kind":"prep"},{"text":"Picar {{Cebolla}} y {{Ajo}} lo más fino posible.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla y el ajo hasta que estén blandos y translúcidos.","minutes":4,"kind":"activo"},{"text":"Añadir los champiñones laminados y {{Sal|gusto}}; subir a fuego fuerte.","minutes":1,"kind":"activo"},{"text":"Saltear los champiñones hasta que suelten el agua y se doren bien.","minutes":6,"kind":"activo"},{"text":"Añadir {{Pimentón dulce|pizca}}, remover y retirar la sartén del fuego.","minutes":1,"kind":"activo"},{"text":"Extender el relleno de champiñones sobre la mitad de cada {{Tortillas de trigo}}.","minutes":1,"kind":"prep"},{"text":"Repartir {{Queso rallado para fundir}} sobre el relleno de cada tortilla.","minutes":1,"kind":"prep"},{"text":"Doblar cada tortilla por la mitad para cerrar la quesadilla.","minutes":1,"kind":"prep"},{"text":"Calentar {{@Sartén}} a fuego medio-fuerte sin añadir aceite.","minutes":1,"kind":"activo"},{"text":"Dorar la quesadilla por el primer lado hasta que esté crujiente y dorada.","minutes":3,"kind":"activo"},{"text":"Dar la vuelta y dorar por el otro lado hasta que el queso funda por completo.","minutes":3,"kind":"activo"},{"text":"Cortar cada quesadilla en triángulos y servir de inmediato.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'crudo', 'mexicana'),
  ('ensaladas_verduras_036', 'Ensalada templada de espinacas y bacon exprés', 'ensaladas_verduras', 'cerdo', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 320, 16, 10, 24, 2, true, false, '{"gluten","huevo","mostaza","sulfitos"}', '[{"name":"Espinacas baby","amount":150,"unit":"g"},{"name":"Bacon en tiras","amount":80,"unit":"g"},{"name":"Huevo","amount":100,"unit":"g"},{"name":"Pan","amount":40,"unit":"g"},{"name":"Vinagre de Jerez","amount":15,"unit":"ml"},{"name":"Mostaza de Dijon","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"}]'::jsonb, '{"Llevar agua a ebullición en un cazo a fuego fuerte.","Introducir huevo con cuidado y cocer a fuego medio.","Cortar pan en dados pequeños para los picatostes.","Retirar los huevos del cazo y sumergir en agua fría hasta que estén templados.","Pelar los huevos y cortar en cuartos.","Calentar sartén a fuego medio sin aceite y añadir bacon en tiras.","Dorar el bacon hasta que quede crujiente, retirar y reservar sobre papel absorbente.","Freír los dados de pan en la misma sartén con la grasa del bacon hasta que se doren.","Retirar la sartén del fuego y añadir vinagre de jerez y mostaza de dijon.","Remover para ligar una vinagreta templada con los jugos de la sartén.","Repartir espinacas baby en una ensaladera.","Regar las espinacas con la vinagreta templada de la sartén.","Añadir el bacon crujiente, los picatostes y los huevos en cuartos.","Terminar con aceite de oliva y servir enseguida antes de que la hoja se ablande."}', 'Espinacas frescas con bacon crujiente, picatostes y huevo cocido, aliñadas templadas.', '[{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 180°C. Cocina el bacon en una capa durante 8-10 minutos hasta que esté crujiente. Luego, tuesta los picatostes con un poco de aceite durante 5-7 minutos. El huevo se puede cocer duro en la airfryer o de forma tradicional."},{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C. Hornea el bacon y los picatostes en bandejas separadas durante 15-20 minutos hasta que estén dorados y crujientes. El huevo se puede cocer duro en el horno o de forma tradicional."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], false, '[{"text":"Llevar agua a ebullición en un cazo a fuego fuerte.","minutes":3,"kind":"activo"},{"text":"Introducir {{Huevo}} con cuidado y cocer a fuego medio.","minutes":10,"kind":"pasivo"},{"text":"Cortar {{Pan}} en dados pequeños para los picatostes.","minutes":2,"kind":"paralelo","during":1},{"text":"Retirar los huevos del cazo y sumergir en agua fría hasta que estén templados.","minutes":2,"kind":"espera"},{"text":"Pelar los huevos y cortar en cuartos.","minutes":2,"kind":"prep"},{"text":"Calentar {{@Sartén}} a fuego medio sin aceite y añadir {{Bacon en tiras}}.","minutes":1,"kind":"activo"},{"text":"Dorar el bacon hasta que quede crujiente, retirar y reservar sobre papel absorbente.","minutes":4,"kind":"activo"},{"text":"Freír los dados de pan en la misma sartén con la grasa del bacon hasta que se doren.","minutes":3,"kind":"activo"},{"text":"Retirar la sartén del fuego y añadir {{Vinagre de Jerez}} y {{Mostaza de Dijon}}.","minutes":1,"kind":"activo"},{"text":"Remover para ligar una vinagreta templada con los jugos de la sartén.","minutes":1,"kind":"activo"},{"text":"Repartir {{Espinacas baby}} en una ensaladera.","minutes":1,"kind":"emplatado"},{"text":"Regar las espinacas con la vinagreta templada de la sartén.","minutes":1,"kind":"emplatado"},{"text":"Añadir el bacon crujiente, los picatostes y los huevos en cuartos.","minutes":1,"kind":"emplatado"},{"text":"Terminar con {{Aceite de oliva|chorrito}} y servir enseguida antes de que la hoja se ablande.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL),
  ('ensaladas_verduras_037', 'Tosta de burrata, miel y pistachos', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'all', 420, 13, 38, 24, 2, true, false, '{"gluten","lactosa","frutos_secos"}', '[{"name":"Pan rústico","amount":100,"unit":"g"},{"name":"Burrata","amount":125,"unit":"g"},{"name":"Miel","amount":20,"unit":"g"},{"name":"Pistachos pelados","amount":20,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":10,"unit":"ml"},{"name":"Sal en escamas","amount":2,"unit":"g"}]'::jsonb, '{"Picar pistachos pelados groseramente con un cuchillo.","Tostar pan rústico en una sartén o tostadora hasta que esté crujiente y dorado.","Repartir burrata en trozos sobre las tostadas.","Regar con miel por encima de la burrata.","Espolvorear los pistachos picados sobre la burrata.","Añadir aceite de oliva virgen extra y sal en escamas por encima."}', 'Tosta crujiente con burrata cremosa, un toque dulce de miel y el crujido de los pistachos.', '[{"appliance":"airfryer","time":10,"difficulty":"facil","prepSummary":"Para el pan, precalienta la airfryer a 180°C y tuesta las rebanadas durante 5-7 minutos hasta que estén doradas y crujientes. Luego, monta la tosta con la burrata, miel, pistachos, AOVE y sal."},{"appliance":"horno","time":12,"difficulty":"facil","prepSummary":"Tuesta el pan rústico en el horno precalentado a 190°C durante 5-8 minutos hasta obtener una base dorada. Retira, coloca la burrata y finaliza con la miel, los pistachos, un chorrito de AOVE y las escamas de sal."}]'::jsonb, '{}', NULL, true, NULL, '{"lacteo","frutos_secos"}', NULL, '{}'::main_protein[], false, '[{"text":"Picar {{Pistachos pelados}} groseramente con un cuchillo.","minutes":2,"kind":"prep"},{"text":"Tostar {{Pan rústico}} en una sartén o tostadora hasta que esté crujiente y dorado.","minutes":3,"kind":"activo"},{"text":"Repartir {{Burrata}} en trozos sobre las tostadas.","minutes":1,"kind":"activo"},{"text":"Regar con {{Miel}} por encima de la burrata.","minutes":1,"kind":"activo"},{"text":"Espolvorear los pistachos picados sobre la burrata.","minutes":1,"kind":"activo"},{"text":"Añadir {{Aceite de oliva virgen extra|chorrito}} y {{Sal en escamas|gusto}} por encima.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'crudo', NULL),
  ('ensaladas_verduras_038', 'Ensalada de burrata, melocotón y albahaca', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'verano', 302, 12, 14, 22, 2, true, true, '{"lactosa","sulfitos"}', '[{"name":"Burrata","amount":250,"unit":"g"},{"name":"Melocotón","amount":200,"unit":"g"},{"name":"Albahaca fresca","amount":10,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":15,"unit":"ml"},{"name":"Vinagre balsámico","amount":10,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Lavar melocotón bajo agua fría.","Cortar el melocotón en gajos finos, sin pelar.","Repartir los gajos de melocotón en la base de 2 platos.","Colocar burrata entera o partida en el centro de cada plato.","Salpimentar con sal y pimienta negra.","Regar con aceite de oliva virgen extra y vinagre balsámico.","Deshojar albahaca fresca por encima justo antes de servir."}', 'Burrata cremosa con melocotón jugoso y albahaca fresca, un contraste dulce y suave.', '[]'::jsonb, '{}', NULL, true, NULL, '{"lacteo","fruta"}', NULL, '{}'::main_protein[], false, '[{"text":"Lavar {{Melocotón}} bajo agua fría.","minutes":1,"kind":"prep"},{"text":"Cortar el melocotón en gajos finos, sin pelar.","minutes":2,"kind":"prep"},{"text":"Repartir los gajos de melocotón en la base de 2 platos.","minutes":1,"kind":"emplatado"},{"text":"Colocar {{Burrata}} entera o partida en el centro de cada plato.","minutes":1,"kind":"emplatado"},{"text":"Salpimentar con {{Sal|gusto}} y {{Pimienta negra|pizca}}.","minutes":1,"kind":"emplatado"},{"text":"Regar con {{Aceite de oliva virgen extra|chorrito}} y {{Vinagre balsámico}}.","minutes":1,"kind":"emplatado"},{"text":"Deshojar {{Albahaca fresca}} por encima justo antes de servir.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'crudo', NULL),
  ('ensaladas_verduras_039', 'Ensalada de remolacha, queso de cabra y nueces', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 346, 12, 16, 26, 2, true, false, '{"lactosa","frutos_secos","sulfitos"}', '[{"name":"Remolacha cocida","amount":200,"unit":"g"},{"name":"Queso de cabra","amount":100,"unit":"g"},{"name":"Nueces","amount":30,"unit":"g"},{"name":"Rúcula","amount":60,"unit":"g"},{"name":"Miel","amount":10,"unit":"g"},{"name":"Vinagre balsámico","amount":10,"unit":"ml"},{"name":"Aceite de oliva virgen extra","amount":15,"unit":"ml"}]'::jsonb, '{"Cortar remolacha cocida en dados de unos 2 cm.","Cortar queso de cabra en rodajas de aproximadamente 1 cm.","Trocear nueces groseramente con el cuchillo.","Mezclar aceite de oliva virgen extra, vinagre balsámico y miel en un bol pequeño hasta integrar.","Repartir rúcula en la base de 2 platos formando una cama uniforme.","Distribuir la remolacha en dados sobre la rúcula.","Colocar las rodajas de queso de cabra repartidas por encima.","Esparcir las nueces troceadas sobre la ensalada.","Regar con la vinagreta justo antes de servir."}', 'Remolacha dulce, queso de cabra cremoso y nueces crujientes con vinagreta de miel.', '[{"appliance":"airfryer","time":15,"difficulty":"facil","prepSummary":"Tuesta las nueces en la airfryer a 160°C durante 5-7 minutos hasta que estén ligeramente doradas. Para un toque gourmet, calienta el queso de cabra con un chorrito de miel unos minutos para que se dore ligeramente."},{"appliance":"horno","time":15,"difficulty":"facil","prepSummary":"Tuesta las nueces en el horno precalentado a 170°C durante 7-10 minutos, vigilando que no se quemen. Para realzar el sabor, hornea el queso de cabra con un hilo de miel hasta que esté templado y ligeramente dorado."}]'::jsonb, '{}', NULL, true, NULL, '{"verdura","lacteo","frutos_secos"}', NULL, '{}'::main_protein[], false, '[{"text":"Cortar {{Remolacha cocida}} en dados de unos 2 cm.","minutes":2,"kind":"prep"},{"text":"Cortar {{Queso de cabra}} en rodajas de aproximadamente 1 cm.","minutes":1,"kind":"prep"},{"text":"Trocear {{Nueces}} groseramente con el cuchillo.","minutes":1,"kind":"prep"},{"text":"Mezclar {{Aceite de oliva virgen extra}}, {{Vinagre balsámico}} y {{Miel}} en un bol pequeño hasta integrar.","minutes":1,"kind":"prep"},{"text":"Repartir {{Rúcula}} en la base de 2 platos formando una cama uniforme.","minutes":1,"kind":"emplatado"},{"text":"Distribuir la remolacha en dados sobre la rúcula.","minutes":1,"kind":"emplatado"},{"text":"Colocar las rodajas de queso de cabra repartidas por encima.","minutes":1,"kind":"emplatado"},{"text":"Esparcir las nueces troceadas sobre la ensalada.","minutes":1,"kind":"emplatado"},{"text":"Regar con la vinagreta justo antes de servir.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'crudo', NULL),
  ('ensaladas_verduras_040', 'Ensalada templada de pato y naranja', 'ensaladas_verduras', 'pollo', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'normal', 'all', 433, 34, 18, 25, 2, false, false, '{"sulfitos"}', '[{"name":"Magret de pato","amount":300,"unit":"g"},{"name":"Naranja","amount":200,"unit":"g"},{"name":"Canónigos","amount":80,"unit":"g"},{"name":"Cebolla morada","amount":30,"unit":"g"},{"name":"Vinagre de Jerez","amount":15,"unit":"ml"},{"name":"Miel","amount":10,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":15,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Laminar cebolla morada en aros muy finos y reservar.","Pelar naranja a vivo, separar los gajos y recoger el jugo que suelte en un bol.","Marcar la piel de magret de pato en forma de rejilla con un cuchillo, sin llegar a la carne.","Salpimentar magret de pato por ambos lados con sal.","Colocar el magret con la piel hacia abajo en sartén fría, sin aceite, y encender el fuego medio.","Cocinar sin mover hasta que la piel esté dorada y haya soltado su grasa, unos 7 min.","Retirar el exceso de grasa de la sartén con una cuchara.","Subir el fuego a fuerte y dorar el magret por el lado de la carne durante 2 min.","Retirar el magret a una tabla y dejar reposar 5 min antes de cortar.","Añadir el jugo de naranja reservado, vinagre de jerez y miel a la misma sartén.","Reducir a fuego medio hasta que la salsa espese ligeramente, unos 3 min. Retirar del fuego.","Cortar el magret reposado en láminas finas.","Disponer canónigos y la cebolla morada laminada en una fuente amplia.","Repartir los gajos de naranja y las láminas de magret sobre los canónigos.","Regar con aceite de oliva virgen extra y la reducción templada. Servir enseguida."}', 'Magret de pato dorado y jugoso sobre canónigos frescos, con naranja y una reducción agridulce.', '[{"appliance":"airfryer","time":25,"difficulty":"facil","prepSummary":"Marca la piel del magret, sazona y cocina en la airfryer a 190°C durante 15-20 minutos, con la piel hacia arriba, hasta que esté crujiente y dorado. Deja reposar antes de cortar."},{"appliance":"horno","time":40,"difficulty":"normal","prepSummary":"Sella el magret por el lado de la piel en una sartén apta para horno hasta dorar y renderizar la grasa. Termina en el horno precalentado a 180°C durante 10-12 minutos para el punto deseado. Reposa la carne antes de laminar."}]'::jsonb, '{}', true, NULL, NULL, '{"verdura","fruta"}', NULL, '{}'::main_protein[], false, '[{"text":"Laminar {{Cebolla morada}} en aros muy finos y reservar.","minutes":2,"kind":"prep"},{"text":"Pelar {{Naranja}} a vivo, separar los gajos y recoger el jugo que suelte en un bol.","minutes":3,"kind":"prep"},{"text":"Marcar la piel de {{Magret de pato}} en forma de rejilla con un cuchillo, sin llegar a la carne.","minutes":2,"kind":"prep"},{"text":"Salpimentar {{Magret de pato}} por ambos lados con {{Sal|gusto}}.","minutes":1,"kind":"prep"},{"text":"Colocar el magret con la piel hacia abajo en {{@Sartén}} fría, sin aceite, y encender el fuego medio.","minutes":1,"kind":"activo"},{"text":"Cocinar sin mover hasta que la piel esté dorada y haya soltado su grasa, unos 7 min.","minutes":7,"kind":"pasivo"},{"text":"Retirar el exceso de grasa de la sartén con una cuchara.","minutes":1,"kind":"activo"},{"text":"Subir el fuego a fuerte y dorar el magret por el lado de la carne durante 2 min.","minutes":2,"kind":"activo"},{"text":"Retirar el magret a una tabla y dejar reposar 5 min antes de cortar.","minutes":5,"kind":"espera"},{"text":"Añadir el jugo de naranja reservado, {{Vinagre de Jerez}} y {{Miel}} a la misma sartén.","minutes":1,"kind":"activo"},{"text":"Reducir a fuego medio hasta que la salsa espese ligeramente, unos 3 min. Retirar del fuego.","minutes":3,"kind":"activo"},{"text":"Cortar el magret reposado en láminas finas.","minutes":2,"kind":"prep"},{"text":"Disponer {{Canónigos}} y la cebolla morada laminada en una fuente amplia.","minutes":1,"kind":"emplatado"},{"text":"Repartir los gajos de naranja y las láminas de magret sobre los canónigos.","minutes":1,"kind":"emplatado"},{"text":"Regar con {{Aceite de oliva virgen extra|chorrito}} y la reducción templada. Servir enseguida.","minutes":1,"kind":"emplatado"}]'::jsonb, true, 'especial', NULL, 'sarten', NULL),
  ('ensaladas_verduras_041', 'Ensalada de langostinos y aguacate', 'ensaladas_verduras', 'marisco', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 290, 22, 10, 18, 2, true, false, '{"marisco"}', '[{"name":"Langostinos pelados","amount":200,"unit":"g"},{"name":"Aguacate","amount":200,"unit":"g"},{"name":"Tomate","amount":100,"unit":"g"},{"name":"Lechuga","amount":60,"unit":"g"},{"name":"Lima","amount":20,"unit":"ml"},{"name":"Cilantro fresco","amount":5,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":15,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Lavar lechuga y tomate bajo el grifo con agua fría.","Picar cilantro fresco fino y reservar.","Cortar el tomate en dados pequeños y reservar.","Cortar aguacate por la mitad, retirar el hueso y cortar la pulpa en dados.","Trocear la lechuga en piezas medianas y reservar.","Llevar a ebullición agua con sal en un cazo a fuego fuerte.","Cocer langostinos pelados en el agua hirviendo hasta que cambien de color, unos 2 min.","Escurrir los langostinos y enfriar en un bol con agua y hielo durante 2 min.","Escurrir los langostinos del agua con hielo y reservar.","Mezclar aceite de oliva virgen extra con lima y el cilantro picado en un bol pequeño.","Repartir la lechuga troceada en la base de 2 platos.","Distribuir los dados de aguacate y de tomate sobre la lechuga.","Colocar los langostinos encima y regar con el aliño de lima y cilantro justo antes de servir."}', 'Langostinos tiernos, aguacate cremoso y un aliño cítrico fresco con lima y cilantro.', '[{"appliance":"airfryer","time":15,"difficulty":"facil","prepSummary":"Para los langostinos, rocíalos con un poco de aceite y cocínalos en la airfryer a 190°C durante 8-10 minutos, agitándolos a mitad, hasta que estén dorados y cocidos. Luego, mezcla con el resto de ingredientes frescos."},{"appliance":"horno","time":20,"difficulty":"facil","prepSummary":"Extiende los langostinos en una bandeja de horno con un poco de aceite y sal. Ásalos a 200°C durante 10-12 minutos, volteándolos una vez, hasta que estén rosados y cocidos. Combina con el resto de la ensalada."},{"appliance":"thermomix","time":15,"difficulty":"facil","prepSummary":"Coloca los langostinos en el recipiente Varoma y cocínalos al vapor durante 5-7 minutos a temperatura Varoma, velocidad 1, con 500ml de agua en el vaso. Esto asegura langostinos jugosos para la ensalada."},{"appliance":"vaporera","time":15,"difficulty":"facil","prepSummary":"Cocina los langostinos en la vaporera durante 5-7 minutos hasta que estén rosados y tiernos. Este método los mantiene jugosos y es perfecto para una ensalada ligera."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], false, '[{"text":"Lavar {{Lechuga}} y {{Tomate}} bajo el grifo con agua fría.","minutes":2,"kind":"prep"},{"text":"Picar {{Cilantro fresco}} fino y reservar.","minutes":1,"kind":"prep"},{"text":"Cortar el tomate en dados pequeños y reservar.","minutes":2,"kind":"prep"},{"text":"Cortar {{Aguacate}} por la mitad, retirar el hueso y cortar la pulpa en dados.","minutes":2,"kind":"prep"},{"text":"Trocear la lechuga en piezas medianas y reservar.","minutes":1,"kind":"prep"},{"text":"Llevar a ebullición agua con {{Sal|gusto}} en un cazo a fuego fuerte.","minutes":3,"kind":"activo"},{"text":"Cocer {{Langostinos pelados}} en el agua hirviendo hasta que cambien de color, unos 2 min.","minutes":2,"kind":"activo"},{"text":"Escurrir los langostinos y enfriar en un bol con agua y hielo durante 2 min.","minutes":2,"kind":"espera"},{"text":"Escurrir los langostinos del agua con hielo y reservar.","minutes":1,"kind":"prep"},{"text":"Mezclar {{Aceite de oliva virgen extra}} con {{Lima}} y el cilantro picado en un bol pequeño.","minutes":1,"kind":"prep"},{"text":"Repartir la lechuga troceada en la base de 2 platos.","minutes":1,"kind":"emplatado"},{"text":"Distribuir los dados de aguacate y de tomate sobre la lechuga.","minutes":1,"kind":"emplatado"},{"text":"Colocar los langostinos encima y regar con el aliño de lima y cilantro justo antes de servir.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL),
  ('ensaladas_verduras_042', 'Ensalada de pera, nueces y roquefort', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'all', 352, 10, 24, 24, 2, false, false, '{"lactosa","frutos_secos","sulfitos"}', '[{"name":"Canónigos","amount":80,"unit":"g"},{"name":"Pera","amount":200,"unit":"g"},{"name":"Queso roquefort","amount":80,"unit":"g"},{"name":"Nueces","amount":30,"unit":"g"},{"name":"Miel","amount":10,"unit":"g"},{"name":"Vinagre balsámico","amount":10,"unit":"ml"},{"name":"Aceite de oliva virgen extra","amount":15,"unit":"ml"}]'::jsonb, '{"Lavar canónigos bajo agua fría y escurrir bien.","Laminar pera en rodajas finas sin pelar.","Mezclar aceite de oliva virgen extra, vinagre balsámico y miel en un bol pequeño hasta integrar.","Repartir los canónigos escurridos en la base de 2 platos.","Distribuir las láminas de pera sobre los canónigos.","Desmigar queso roquefort por encima de la pera.","Trocear nueces en trozos gruesos y esparcir sobre la ensalada.","Regar la ensalada con la vinagreta justo antes de servir."}', 'Pera crujiente, roquefort intenso y nueces tostadas, el clásico contraste dulce y salado.', '[{"appliance":"airfryer","time":15,"difficulty":"facil","prepSummary":"Para realzar el sabor, tuesta las nueces en la airfryer a 160°C durante 5 minutos. Si deseas, puedes asar ligeramente la pera en rodajas a 180°C durante 8-10 minutos hasta que esté tierna y ligeramente dorada, luego ensambla la ensalada con el resto de ingredientes y el aderezo."},{"appliance":"horno","time":20,"difficulty":"facil","prepSummary":"Precalienta el horno a 180°C. Tuesta las nueces en una bandeja durante 7 minutos hasta que estén aromáticas. Si prefieres la pera templada, ásala en rodajas junto a las nueces durante 10-15 minutos hasta que esté tierna, luego enfría ligeramente y monta la ensalada."}]'::jsonb, '{}', NULL, true, NULL, '{"verdura","lacteo","fruta","frutos_secos"}', NULL, '{}'::main_protein[], false, '[{"text":"Lavar {{Canónigos}} bajo agua fría y escurrir bien.","minutes":1,"kind":"prep"},{"text":"Laminar {{Pera}} en rodajas finas sin pelar.","minutes":2,"kind":"prep"},{"text":"Mezclar {{Aceite de oliva virgen extra}}, {{Vinagre balsámico}} y {{Miel}} en un bol pequeño hasta integrar.","minutes":1,"kind":"prep"},{"text":"Repartir los canónigos escurridos en la base de 2 platos.","minutes":1,"kind":"activo"},{"text":"Distribuir las láminas de pera sobre los canónigos.","minutes":1,"kind":"activo"},{"text":"Desmigar {{Queso roquefort}} por encima de la pera.","minutes":1,"kind":"activo"},{"text":"Trocear {{Nueces}} en trozos gruesos y esparcir sobre la ensalada.","minutes":1,"kind":"activo"},{"text":"Regar la ensalada con la vinagreta justo antes de servir.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'crudo', NULL),
  ('ensaladas_verduras_043', 'Ensalada de sandía, feta y menta', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'verano', 231, 8, 16, 15, 2, true, true, '{"lactosa","sulfitos"}', '[{"name":"Sandía","amount":300,"unit":"g"},{"name":"Queso feta","amount":100,"unit":"g"},{"name":"Menta fresca","amount":10,"unit":"g"},{"name":"Aceitunas negras","amount":20,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":15,"unit":"ml"},{"name":"Vinagre balsámico","amount":10,"unit":"ml"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Cortar sandía en dados grandes, retirando las pepitas.","Cortar queso feta en dados del mismo tamaño que la sandía.","Deshojar menta fresca y reservar las hojas enteras.","Repartir la sandía y el queso feta en una fuente.","Añadir aceitunas negras y las hojas de menta fresca por encima.","Regar con aceite de oliva virgen extra y vinagre balsámico.","Terminar con pimienta negra y servir bien fría."}', 'Sandía jugosa y feta salado con menta fresca, la ensalada más refrescante del verano.', '[]'::jsonb, '{}', NULL, true, NULL, '{"lacteo","fruta","encurtido"}', NULL, '{}'::main_protein[], false, '[{"text":"Cortar {{Sandía}} en dados grandes, retirando las pepitas.","minutes":3,"kind":"prep"},{"text":"Cortar {{Queso feta}} en dados del mismo tamaño que la sandía.","minutes":2,"kind":"prep"},{"text":"Deshojar {{Menta fresca}} y reservar las hojas enteras.","minutes":1,"kind":"prep"},{"text":"Repartir la sandía y el queso feta en una fuente.","minutes":1,"kind":"activo"},{"text":"Añadir {{Aceitunas negras}} y las hojas de menta fresca por encima.","minutes":1,"kind":"activo"},{"text":"Regar con {{Aceite de oliva virgen extra}} y {{Vinagre balsámico}}.","minutes":1,"kind":"activo"},{"text":"Terminar con {{Pimienta negra|pizca}} y servir bien fría.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'crudo', NULL),
  ('ensaladas_verduras_044', 'Ensalada de quinoa, granada y feta', 'ensaladas_verduras', 'none', 'quinoa', ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 343, 12, 40, 15, 2, true, true, '{"lactosa"}', '[{"name":"Quinoa","amount":100,"unit":"g"},{"name":"Granada","amount":100,"unit":"g"},{"name":"Queso feta","amount":80,"unit":"g"},{"name":"Pepino","amount":60,"unit":"g"},{"name":"Menta fresca","amount":5,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":15,"unit":"ml"},{"name":"Limón","amount":15,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Lavar quinoa bajo agua fría hasta que el agua salga clara.","Llevar a ebullición un cazo con agua y sal.","Cocer la quinoa a fuego medio hasta que esté tierna y haya absorbido el agua.","Desgranar granada y reservar los granos.","Cortar pepino en dados pequeños.","Picar menta fresca fina.","Escurrir la quinoa cocida y extenderla en una fuente hasta que esté fría.","Desmigar queso feta con los dedos en trozos irregulares.","Mezclar la quinoa fría con el pepino, los granos de granada y el queso feta desmigado.","Aliñar con aceite de oliva virgen extra y limón.","Añadir la menta picada y remover con suavidad hasta integrar.","Servir la ensalada templada o fría."}', 'Quinoa suelta con granada, feta y menta, fresca y ligera, para servir templada o fría.', '[{"appliance":"thermomix","time":20,"difficulty":"facil","prepSummary":"Cocina la quinoa en el cestillo con agua y sal durante 15-18 minutos a temperatura Varoma, velocidad 4. Una vez cocida y fría, mezcla con el resto de los ingredientes y el aliño en el vaso a velocidad cuchara."},{"appliance":"vaporera","time":25,"difficulty":"facil","prepSummary":"Cuece la quinoa en la vaporera hasta que esté tierna y esponjosa, aproximadamente 20-25 minutos. Deja enfriar completamente antes de mezclarla con la granada, el feta, el pepino, la menta y el aliño."},{"appliance":"olla_express","time":15,"difficulty":"facil","prepSummary":"Cocina la quinoa en la olla express con el doble de agua y una pizca de sal durante 5-7 minutos desde que sube la válvula. Deja despresurizar de forma natural, enfría y luego incorpora el resto de los ingredientes."},{"appliance":"microondas","time":20,"difficulty":"facil","prepSummary":"Prepara la quinoa en un recipiente apto para microondas con el doble de agua y sal, cocinándola durante 10-12 minutos a máxima potencia. Deja reposar, enfría y luego mezcla con los demás componentes de la ensalada."}]'::jsonb, '{}', NULL, NULL, NULL, '{"lacteo","fruta"}', NULL, '{}'::main_protein[], false, '[{"text":"Lavar {{Quinoa}} bajo agua fría hasta que el agua salga clara.","minutes":2,"kind":"prep"},{"text":"Llevar a ebullición un cazo con agua y {{Sal|gusto}}.","minutes":3,"kind":"activo"},{"text":"Cocer la quinoa a fuego medio hasta que esté tierna y haya absorbido el agua.","minutes":15,"kind":"pasivo"},{"text":"Desgranar {{Granada}} y reservar los granos.","minutes":3,"kind":"paralelo","during":2},{"text":"Cortar {{Pepino}} en dados pequeños.","minutes":2,"kind":"paralelo","during":2},{"text":"Picar {{Menta fresca}} fina.","minutes":1,"kind":"paralelo","during":2},{"text":"Escurrir la quinoa cocida y extenderla en una fuente hasta que esté fría.","minutes":5,"kind":"espera"},{"text":"Desmigar {{Queso feta}} con los dedos en trozos irregulares.","minutes":1,"kind":"prep"},{"text":"Mezclar la quinoa fría con el pepino, los granos de granada y el queso feta desmigado.","minutes":2,"kind":"activo"},{"text":"Aliñar con {{Aceite de oliva virgen extra|chorrito}} y {{Limón}}.","minutes":1,"kind":"activo"},{"text":"Añadir la menta picada y remover con suavidad hasta integrar.","minutes":1,"kind":"activo"},{"text":"Servir la ensalada templada o fría.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL)
