  cocina = excluded.cocina;

insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id, extra_proteins, freezable, steps_rich, estrella, occasion, kid_favourite, tecnica, cocina
) values
  ('ensaladas_verduras_045', 'Ensalada Waldorf de manzana, apio y nueces', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 326, 6, 26, 22, 2, true, false, '{"frutos_secos","apio","huevo","lactosa","sulfitos"}', '[{"name":"Manzana","amount":200,"unit":"g"},{"name":"Apio","amount":80,"unit":"g"},{"name":"Nueces","amount":40,"unit":"g"},{"name":"Uvas pasas","amount":30,"unit":"g"},{"name":"Mayonesa","amount":40,"unit":"g"},{"name":"Yogur natural","amount":30,"unit":"g"},{"name":"Limón","amount":10,"unit":"ml"},{"name":"Lechuga","amount":60,"unit":"g"}]'::jsonb, '{"Lavar lechuga y manzana bajo el grifo.","Cortar la manzana en dados medianos sin pelar.","Exprimir limón sobre los dados de manzana y remover para que no se oxiden.","Laminar apio en rodajas finas.","Trocear nueces en trozos gruesos.","Mezclar en un bol la manzana, el apio, las nueces y uvas pasas.","Añadir mayonesa y yogur natural al bol y remover hasta que todo quede bien integrado.","Repartir la lechuga como base en una fuente o en los platos.","Servir la mezcla Waldorf sobre la lechuga."}', 'Manzana crujiente, apio y nueces en una cremosa mezcla de mayonesa y yogur, el clásico americano.', '[]'::jsonb, '{}', NULL, true, NULL, '{"verdura","fruta","frutos_secos"}', NULL, '{}'::main_protein[], false, '[{"text":"Lavar {{Lechuga}} y {{Manzana}} bajo el grifo.","minutes":2,"kind":"prep"},{"text":"Cortar la manzana en dados medianos sin pelar.","minutes":2,"kind":"prep"},{"text":"Exprimir {{Limón}} sobre los dados de manzana y remover para que no se oxiden.","minutes":1,"kind":"prep"},{"text":"Laminar {{Apio}} en rodajas finas.","minutes":2,"kind":"prep"},{"text":"Trocear {{Nueces}} en trozos gruesos.","minutes":1,"kind":"prep"},{"text":"Mezclar en un bol la manzana, el apio, las nueces y {{Uvas pasas}}.","minutes":1,"kind":"activo"},{"text":"Añadir {{Mayonesa}} y {{Yogur natural}} al bol y remover hasta que todo quede bien integrado.","minutes":1,"kind":"activo"},{"text":"Repartir la lechuga como base en una fuente o en los platos.","minutes":1,"kind":"emplatado"},{"text":"Servir la mezcla Waldorf sobre la lechuga.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'crudo', NULL),
  ('ensaladas_verduras_046', 'Ensalada de pulpo y patata', 'ensaladas_verduras', 'marisco', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 50, 'normal', 'all', 333, 26, 28, 13, 2, false, true, '{"moluscos"}', '[{"name":"Pulpo cocido","amount":300,"unit":"g"},{"name":"Patata","amount":300,"unit":"g"},{"name":"Pimentón dulce","amount":5,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":30,"unit":"ml"},{"name":"Sal gorda","amount":3,"unit":"g"},{"name":"Laurel","amount":2,"unit":"g"}]'::jsonb, '{"Lavar patata y colocarlas enteras con piel en una olla.","Cubrir las patatas con agua fría, añadir laurel y sal gorda.","Llevar a ebullición a fuego fuerte y cocer a fuego medio hasta que estén tiernas, unos 25 min.","Cortar pulpo cocido en rodajas de 1 dedo de grosor.","Escurrir las patatas y dejarlas templar hasta que se puedan pelar sin quemarse, unos 10 min.","Pelar las patatas y cortarlas en rodajas gruesas de unos 2 cm.","Repartir las rodajas de patata en la base de una fuente.","Colocar las rodajas de pulpo cocido sobre las patatas.","Espolvorear pimentón dulce de manera uniforme sobre el pulpo y las patatas.","Regar con aceite de oliva virgen extra generoso y servir templado."}', 'Pulpo tierno en rodajas sobre patata cocida, con pimentón y un buen chorro de aceite de oliva.', '[{"appliance":"airfryer","time":30,"difficulty":"normal","prepSummary":"Corta las patatas en dados y cocínalas en la airfryer a 190°C durante 20-25 minutos, removiendo a mitad. Añade el pulpo cocido troceado los últimos 5 minutos para que se caliente y dore ligeramente."},{"appliance":"horno","time":45,"difficulty":"normal","prepSummary":"Asa las patatas troceadas con un chorrito de aceite a 200°C durante 30-40 minutos hasta que estén tiernas. Incorpora el pulpo cocido troceado los últimos 10 minutos para que se temple."},{"appliance":"thermomix","time":35,"difficulty":"facil","prepSummary":"Cocina las patatas troceadas al vapor en el Varoma durante 25-30 minutos, velocidad 1, temperatura Varoma. Añade el pulpo cocido troceado los últimos 5 minutos para que se caliente suavemente."},{"appliance":"vaporera","time":35,"difficulty":"facil","prepSummary":"Cuece las patatas troceadas al vapor hasta que estén tiernas, unos 25-30 minutos. Incorpora el pulpo cocido troceado los últimos 5 minutos de cocción para que se temple sin resecarse."},{"appliance":"olla_express","time":20,"difficulty":"facil","prepSummary":"Cocina las patatas troceadas en la olla express con un vaso de agua y una hoja de laurel durante 8-10 minutos desde que sube la válvula. Despresuriza, añade el pulpo troceado y calienta 2 minutos más."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Lavar {{Patata}} y colocarlas enteras con piel en una olla.","minutes":2,"kind":"prep"},{"text":"Cubrir las patatas con agua fría, añadir {{Laurel}} y {{Sal gorda|gusto}}.","minutes":1,"kind":"prep"},{"text":"Llevar a ebullición a fuego fuerte y cocer a fuego medio hasta que estén tiernas, unos 25 min.","minutes":27,"kind":"pasivo"},{"text":"Cortar {{Pulpo cocido}} en rodajas de 1 dedo de grosor.","minutes":3,"kind":"paralelo","during":2},{"text":"Escurrir las patatas y dejarlas templar hasta que se puedan pelar sin quemarse, unos 10 min.","minutes":10,"kind":"espera"},{"text":"Pelar las patatas y cortarlas en rodajas gruesas de unos 2 cm.","minutes":3,"kind":"prep"},{"text":"Repartir las rodajas de patata en la base de una fuente.","minutes":1,"kind":"emplatado"},{"text":"Colocar las rodajas de pulpo cocido sobre las patatas.","minutes":1,"kind":"emplatado"},{"text":"Espolvorear {{Pimentón dulce|pizca}} de manera uniforme sobre el pulpo y las patatas.","minutes":1,"kind":"emplatado"},{"text":"Regar con {{Aceite de oliva virgen extra|chorrito}} generoso y servir templado.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'olla', NULL),
  ('ensaladas_verduras_047', 'Ensalada de garbanzos especiados con comino', 'ensaladas_verduras', 'legumbre', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 300, 12, 36, 12, 2, true, true, '{}', '[{"name":"Garbanzos cocidos","amount":300,"unit":"g"},{"name":"Comino molido","amount":4,"unit":"g"},{"name":"Pimentón dulce","amount":2,"unit":"g"},{"name":"Cebolla morada","amount":40,"unit":"g"},{"name":"Pimiento rojo","amount":60,"unit":"g"},{"name":"Perejil fresco","amount":10,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":20,"unit":"ml"},{"name":"Limón","amount":15,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Escurrir garbanzos cocidos con un colador y enjuagarlos bajo el grifo hasta que el agua salga limpia.","Pelar cebolla morada y cortar en dados pequeños.","Cortar pimiento rojo en dados pequeños del mismo tamaño que la cebolla morada.","Picar perejil fresco fino y reservar aparte.","Mezclar en un bol los garbanzos escurridos, la cebolla morada y el pimiento rojo.","Añadir comino molido, pimentón dulce y sal sobre la mezcla y remover hasta integrar bien.","Aliñar con aceite de oliva virgen extra y limón, y remover para que el aliño cubra todos los garbanzos.","Esperar 5 min para que los garbanzos absorban el aliño y los aromas de las especias.","Repartir la ensalada en los platos y dispersar el perejil picado por encima antes de servir."}', 'Garbanzos especiados con comino y pimentón, coloridos y listos para servir templados o fríos.', '[{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Mezcla los garbanzos, pimiento y cebolla con aceite, comino, pimentón y sal. Cocina en la airfryer a 190°C durante 15-18 minutos, agitando a mitad, hasta que estén ligeramente dorados y tiernos. Añade perejil y limón al final."},{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Extiende los garbanzos, pimiento y cebolla mezclados con aceite, comino, pimentón y sal en una bandeja. Hornea a 200°C durante 20-25 minutos, removiendo una vez, hasta que estén crujientes y las verduras tiernas. Incorpora perejil y limón al servir."}]'::jsonb, '{}', NULL, true, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Escurrir {{Garbanzos cocidos}} con un colador y enjuagarlos bajo el grifo hasta que el agua salga limpia.","minutes":2,"kind":"prep"},{"text":"Pelar {{Cebolla morada}} y cortar en dados pequeños.","minutes":2,"kind":"prep"},{"text":"Cortar {{Pimiento rojo}} en dados pequeños del mismo tamaño que la cebolla morada.","minutes":2,"kind":"prep"},{"text":"Picar {{Perejil fresco}} fino y reservar aparte.","minutes":1,"kind":"prep"},{"text":"Mezclar en un bol los garbanzos escurridos, la cebolla morada y el pimiento rojo.","minutes":1,"kind":"activo"},{"text":"Añadir {{Comino molido}}, {{Pimentón dulce}} y {{Sal|gusto}} sobre la mezcla y remover hasta integrar bien.","minutes":1,"kind":"activo"},{"text":"Aliñar con {{Aceite de oliva virgen extra|chorrito}} y {{Limón}}, y remover para que el aliño cubra todos los garbanzos.","minutes":1,"kind":"activo"},{"text":"Esperar 5 min para que los garbanzos absorban el aliño y los aromas de las especias.","minutes":5,"kind":"espera"},{"text":"Repartir la ensalada en los platos y dispersar el perejil picado por encima antes de servir.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'crudo', NULL),
  ('ensaladas_verduras_048', 'Ensalada de espárragos trigueros y jamón', 'ensaladas_verduras', 'cerdo', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 233, 12, 8, 17, 2, true, true, '{"sulfitos"}', '[{"name":"Espárragos trigueros","amount":250,"unit":"g"},{"name":"Jamón serrano","amount":60,"unit":"g"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":20,"unit":"ml"},{"name":"Vinagre de Jerez","amount":10,"unit":"ml"},{"name":"Sal","amount":1,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Lavar espárragos trigueros y retirar la parte leñosa del tallo rompiéndolo por donde ceda de forma natural.","Laminar ajo.","Calentar plancha a fuego fuerte con aceite de oliva virgen extra.","Asar los espárragos trigueros hasta que estén tiernos y con puntos dorados.","Retirar los espárragos y reservar en la fuente de servicio.","Añadir jamón serrano en tiras a la plancha caliente y dorar hasta que quede crujiente.","Añadir el ajo laminado junto al jamón y saltear hasta que esté dorado.","Repartir el jamón crujiente y el ajo sobre los espárragos reservados.","Aliñar con el resto del aceite de oliva virgen extra, vinagre de jerez, sal y pimienta negra.","Servir templado."}', 'Espárragos trigueros a la plancha con jamón crujiente, un aliño sencillo que no tapa el sabor.', '[{"appliance":"airfryer","time":15,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190°C. Rocía los espárragos con aceite, sal, pimienta y ajo picado, y cocina 8-10 min. Añade el jamón en los últimos 2-3 min para que quede crujiente."},{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C. Extiende los espárragos en una bandeja con aceite, sal, pimienta y ajo picado. Hornea 10-12 min hasta que estén tiernos y ligeramente dorados, añadiendo el jamón los últimos 5 min para que se dore."},{"appliance":"vaporera","time":15,"difficulty":"facil","prepSummary":"Cocina los espárragos al vapor 5-7 minutos hasta que estén tiernos pero firmes. Para el jamón, saltéalo en una sartén aparte o caliéntalo brevemente en el microondas hasta que esté crujiente."},{"appliance":"microondas","time":10,"difficulty":"facil","prepSummary":"Coloca los espárragos con una cucharada de agua en un recipiente apto para microondas y cocina 3-4 minutos a máxima potencia. Cocina el jamón entre papel de cocina 1-2 minutos para que quede crujiente."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], false, '[{"text":"Lavar {{Espárragos trigueros}} y retirar la parte leñosa del tallo rompiéndolo por donde ceda de forma natural.","minutes":2,"kind":"prep"},{"text":"Laminar {{Ajo}}.","minutes":1,"kind":"prep"},{"text":"Calentar {{@Plancha}} a fuego fuerte con {{Aceite de oliva virgen extra|chorrito}}.","minutes":1,"kind":"activo"},{"text":"Asar los espárragos trigueros hasta que estén tiernos y con puntos dorados.","minutes":6,"kind":"activo"},{"text":"Retirar los espárragos y reservar en la fuente de servicio.","minutes":1,"kind":"activo"},{"text":"Añadir {{Jamón serrano}} en tiras a la plancha caliente y dorar hasta que quede crujiente.","minutes":2,"kind":"activo"},{"text":"Añadir el ajo laminado junto al jamón y saltear hasta que esté dorado.","minutes":1,"kind":"activo"},{"text":"Repartir el jamón crujiente y el ajo sobre los espárragos reservados.","minutes":1,"kind":"emplatado"},{"text":"Aliñar con el resto del aceite de oliva virgen extra, {{Vinagre de Jerez}}, {{Sal|gusto}} y {{Pimienta negra|pizca}}.","minutes":1,"kind":"emplatado"},{"text":"Servir templado.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'plancha', NULL),
  ('ensaladas_verduras_049', 'Ensalada de tomate raf con ventresca de atún', 'ensaladas_verduras', 'pescado_azul', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'verano', 310, 20, 8, 22, 2, true, true, '{"pescado","sulfitos"}', '[{"name":"Tomate raf","amount":300,"unit":"g"},{"name":"Ventresca de atún en aceite","amount":120,"unit":"g"},{"name":"Cebolleta","amount":20,"unit":"g"},{"name":"Aceitunas negras","amount":20,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":20,"unit":"ml"},{"name":"Sal en escamas","amount":3,"unit":"g"}]'::jsonb, '{"Lavar tomate raf bajo el grifo y secar con papel de cocina.","Cortar el tomate raf a mano en trozos irregulares, conservando todo el jugo que suelte.","Laminar cebolleta en aros muy finos.","Repartir el tomate raf en una fuente honda, vertiendo también el jugo acumulado.","Esparcir la cebolleta laminada sobre el tomate de forma uniforme.","Añadir aceitunas negras distribuidas por toda la fuente.","Escurrir ventresca de atún en aceite y colocarla entera encima del tomate, sin desmigar.","Regar con aceite de oliva virgen extra por encima de todos los ingredientes.","Terminar con sal en escamas y servir a temperatura ambiente."}', 'Tomate raf maduro partido a mano con ventresca de atún brillante y aceite de oliva.', '[]'::jsonb, '{}', NULL, true, NULL, '{"verdura","encurtido"}', NULL, '{}'::main_protein[], false, '[{"text":"Lavar {{Tomate raf}} bajo el grifo y secar con papel de cocina.","minutes":1,"kind":"prep"},{"text":"Cortar el tomate raf a mano en trozos irregulares, conservando todo el jugo que suelte.","minutes":2,"kind":"prep"},{"text":"Laminar {{Cebolleta}} en aros muy finos.","minutes":1,"kind":"prep"},{"text":"Repartir el tomate raf en una fuente honda, vertiendo también el jugo acumulado.","minutes":1,"kind":"activo"},{"text":"Esparcir la cebolleta laminada sobre el tomate de forma uniforme.","minutes":1,"kind":"activo"},{"text":"Añadir {{Aceitunas negras}} distribuidas por toda la fuente.","minutes":1,"kind":"activo"},{"text":"Escurrir {{Ventresca de atún en aceite}} y colocarla entera encima del tomate, sin desmigar.","minutes":1,"kind":"activo"},{"text":"Regar con {{Aceite de oliva virgen extra|chorrito}} por encima de todos los ingredientes.","minutes":1,"kind":"activo"},{"text":"Terminar con {{Sal en escamas|pizca}} y servir a temperatura ambiente.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'crudo', NULL),
  ('ensaladas_verduras_050', 'Ensalada de higos, jamón y queso de cabra', 'ensaladas_verduras', 'cerdo', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'verano', 341, 14, 24, 21, 2, true, false, '{"lactosa","sulfitos"}', '[{"name":"Higos","amount":200,"unit":"g"},{"name":"Jamón serrano","amount":60,"unit":"g"},{"name":"Queso de cabra","amount":80,"unit":"g"},{"name":"Rúcula","amount":50,"unit":"g"},{"name":"Miel","amount":10,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":15,"unit":"ml"},{"name":"Vinagre balsámico","amount":10,"unit":"ml"}]'::jsonb, '{"Lavar higos bajo agua fría y secarlos con papel de cocina.","Cortar los higos en cuartos.","Cortar queso de cabra en rodajas de aproximadamente 1 cm.","Cortar jamón serrano en tiras finas.","Repartir rúcula en la base de 2 platos formando una cama uniforme.","Distribuir los higos en cuartos sobre la rúcula.","Repartir las tiras de jamón serrano por encima de los higos.","Colocar las rodajas de queso de cabra repartidas por toda la ensalada.","Aliñar con miel, aceite de oliva virgen extra y vinagre balsámico en hilo fino."}', 'Higos maduros, jamón serrano y queso de cabra sobre rúcula, con un toque de miel.', '[{"appliance":"airfryer","time":12,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 180°C. Coloca los higos partidos por la mitad y las rodajas de queso de cabra. Cocina durante 6-8 minutos hasta que los higos estén tiernos y el queso ligeramente dorado y cremoso. Monta la ensalada con el resto de ingredientes."},{"appliance":"horno","time":15,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C con función grill. Dispón los higos partidos y las rodajas de queso de cabra en una bandeja de horno. Gratina durante 5-7 minutos hasta que el queso esté dorado y los higos ligeramente caramelizados. Monta la ensalada."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura","lacteo","fruta"}', NULL, '{}'::main_protein[], false, '[{"text":"Lavar {{Higos}} bajo agua fría y secarlos con papel de cocina.","minutes":1,"kind":"prep"},{"text":"Cortar los higos en cuartos.","minutes":1,"kind":"prep"},{"text":"Cortar {{Queso de cabra}} en rodajas de aproximadamente 1 cm.","minutes":1,"kind":"prep"},{"text":"Cortar {{Jamón serrano}} en tiras finas.","minutes":1,"kind":"prep"},{"text":"Repartir {{Rúcula}} en la base de 2 platos formando una cama uniforme.","minutes":1,"kind":"activo"},{"text":"Distribuir los higos en cuartos sobre la rúcula.","minutes":1,"kind":"activo"},{"text":"Repartir las tiras de jamón serrano por encima de los higos.","minutes":1,"kind":"activo"},{"text":"Colocar las rodajas de queso de cabra repartidas por toda la ensalada.","minutes":1,"kind":"activo"},{"text":"Aliñar con {{Miel}}, {{Aceite de oliva virgen extra}} y {{Vinagre balsámico}} en hilo fino.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL),
  ('ensaladas_verduras_051', 'Ensalada de rúcula, parmesano y piñones', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'all', 280, 10, 6, 24, 2, true, false, '{"lactosa","frutos_secos","sulfitos"}', '[{"name":"Rúcula","amount":100,"unit":"g"},{"name":"Queso parmesano","amount":50,"unit":"g"},{"name":"Piñones","amount":25,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":20,"unit":"ml"},{"name":"Vinagre balsámico","amount":10,"unit":"ml"},{"name":"Sal","amount":1,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Tostar piñones en una sartén sin aceite a fuego medio, removiendo hasta que se doren ligeramente.","Retirar los piñones de la sartén y reservar en un plato.","Lavar rúcula bajo agua fría y escurrir bien.","Hacer virutas de queso parmesano con un pelador.","Repartir la rúcula escurrida en una fuente o en 2 platos.","Distribuir las virutas de queso parmesano sobre la rúcula.","Esparcir los piñones tostados por encima.","Aliñar con aceite de oliva virgen extra y vinagre balsámico.","Añadir sal y pimienta negra, y servir de inmediato."}', 'Rúcula intensa con virutas de parmesano y piñones tostados, sencilla y llena de sabor.', '[{"appliance":"thermomix","time":7,"difficulty":"facil","prepSummary":"La Thermomix es ideal para rallar el queso parmesano en segundos y emulsionar el aderezo de aceite, vinagre, sal y pimienta, logrando una textura perfecta para la ensalada."},{"appliance":"airfryer","time":5,"difficulty":"facil","prepSummary":"Tuesta los piñones en la airfryer a 160°C durante 3-4 minutos, agitándolos a mitad, para realzar su sabor y aportar un toque crujiente a la ensalada."},{"appliance":"horno","time":7,"difficulty":"facil","prepSummary":"Para un sabor más intenso, tuesta los piñones en el horno a 180°C durante 5-7 minutos, extendidos en una bandeja, vigilando para que no se quemen y queden dorados."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura","lacteo","frutos_secos"}', NULL, '{}'::main_protein[], false, '[{"text":"Tostar {{Piñones}} en una sartén sin aceite a fuego medio, removiendo hasta que se doren ligeramente.","minutes":3,"kind":"activo"},{"text":"Retirar los piñones de la sartén y reservar en un plato.","minutes":1,"kind":"prep"},{"text":"Lavar {{Rúcula}} bajo agua fría y escurrir bien.","minutes":2,"kind":"prep"},{"text":"Hacer virutas de {{Queso parmesano}} con un pelador.","minutes":1,"kind":"prep"},{"text":"Repartir la rúcula escurrida en una fuente o en 2 platos.","minutes":1,"kind":"emplatado"},{"text":"Distribuir las virutas de queso parmesano sobre la rúcula.","minutes":1,"kind":"emplatado"},{"text":"Esparcir los piñones tostados por encima.","minutes":1,"kind":"emplatado"},{"text":"Aliñar con {{Aceite de oliva virgen extra|chorrito}} y {{Vinagre balsámico}}.","minutes":1,"kind":"emplatado"},{"text":"Añadir {{Sal|gusto}} y {{Pimienta negra|pizca}}, y servir de inmediato.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL),
  ('ensaladas_verduras_052', 'Ensalada thai de pollo con cacahuete', 'ensaladas_verduras', 'pollo', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 30, 'normal', 'all', 380, 30, 20, 20, 2, false, true, '{"cacahuetes","soja","pescado","sesamo","gluten"}', '[{"name":"Pechuga de pollo","amount":250,"unit":"g"},{"name":"Col china","amount":150,"unit":"g"},{"name":"Zanahoria","amount":60,"unit":"g"},{"name":"Pepino","amount":80,"unit":"g"},{"name":"Cacahuetes tostados","amount":30,"unit":"g"},{"name":"Cilantro fresco","amount":10,"unit":"g"},{"name":"Lima","amount":20,"unit":"ml"},{"name":"Salsa de soja","amount":15,"unit":"ml"},{"name":"Salsa de pescado","amount":10,"unit":"ml"},{"name":"Azúcar moreno","amount":10,"unit":"g"},{"name":"Guindilla roja","amount":5,"unit":"g"},{"name":"Aceite de sésamo","amount":5,"unit":"ml"}]'::jsonb, '{"Calentar plancha a fuego fuerte.","Cocinar pechuga de pollo hasta que esté hecha por dentro, unos 6 min por cada lado.","Cortar col china en juliana fina.","Cortar zanahoria en bastones finos.","Cortar pepino en bastones finos.","Picar guindilla roja en rodajas finas.","Picar cilantro fresco fino.","Picar cacahuetes tostados groseramente.","Mezclar en un bol lima, salsa de soja, salsa de pescado, azúcar moreno y aceite de sésamo hasta disolver el azúcar.","Retirar la pechuga de pollo de la plancha y dejar templar 5 min.","Cortar la pechuga de pollo en tiras finas.","Disponer en una fuente grande la col china, la zanahoria, el pepino y las tiras de pollo.","Añadir el aliño sobre la fuente y remover bien hasta que todo quede impregnado.","Servir con los cacahuetes picados, el cilantro fresco y la guindilla roja por encima."}', 'Pollo, col y verduras crujientes con un aliño agridulce de lima y salsa de pescado.', '[{"appliance":"airfryer","time":25,"difficulty":"facil","prepSummary":"Corta el pollo en tiras, rocía con un poco de aceite y cocina en la airfryer a 190°C durante 15-18 minutos, volteando a mitad, hasta que esté dorado y jugoso. Mientras, prepara las verduras y el aliño."},{"appliance":"horno","time":30,"difficulty":"normal","prepSummary":"Hornea la pechuga de pollo entera o en tiras a 190°C durante 20-25 minutos, hasta que esté cocida y ligeramente dorada. Para un toque extra, puedes marinarla previamente con un poco de salsa de soja."},{"appliance":"thermomix","time":25,"difficulty":"normal","prepSummary":"Cocina la pechuga de pollo al vapor en el Varoma durante 15-20 minutos a temperatura Varoma, velocidad 1, para que quede tierna. Utiliza el vaso para picar las verduras y emulsionar el aliño a velocidad media."},{"appliance":"vaporera","time":25,"difficulty":"facil","prepSummary":"Cocina la pechuga de pollo entera o en trozos en la vaporera durante 15-20 minutos, hasta que esté completamente cocida y muy jugosa. Este método es ideal para una ensalada ligera y saludable."},{"appliance":"olla_express","time":25,"difficulty":"normal","prepSummary":"Cocina la pechuga de pollo entera en la olla express con un poco de agua o caldo durante 5-7 minutos desde que sube la válvula. Deja despresurizar naturalmente para obtener un pollo muy tierno, ideal para desmenuzar."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], false, '[{"text":"Calentar {{@Plancha}} a fuego fuerte.","minutes":2,"kind":"activo"},{"text":"Cocinar {{Pechuga de pollo}} hasta que esté hecha por dentro, unos 6 min por cada lado.","minutes":12,"kind":"pasivo"},{"text":"Cortar {{Col china}} en juliana fina.","minutes":3,"kind":"paralelo","during":1},{"text":"Cortar {{Zanahoria}} en bastones finos.","minutes":2,"kind":"paralelo","during":1},{"text":"Cortar {{Pepino}} en bastones finos.","minutes":2,"kind":"paralelo","during":1},{"text":"Picar {{Guindilla roja}} en rodajas finas.","minutes":1,"kind":"paralelo","during":1},{"text":"Picar {{Cilantro fresco}} fino.","minutes":1,"kind":"paralelo","during":1},{"text":"Picar {{Cacahuetes tostados}} groseramente.","minutes":1,"kind":"paralelo","during":1},{"text":"Mezclar en un bol {{Lima}}, {{Salsa de soja}}, {{Salsa de pescado}}, {{Azúcar moreno}} y {{Aceite de sésamo}} hasta disolver el azúcar.","minutes":2,"kind":"paralelo","during":1},{"text":"Retirar la pechuga de pollo de la plancha y dejar templar 5 min.","minutes":5,"kind":"espera"},{"text":"Cortar la pechuga de pollo en tiras finas.","minutes":2,"kind":"prep"},{"text":"Disponer en una fuente grande la col china, la zanahoria, el pepino y las tiras de pollo.","minutes":1,"kind":"activo"},{"text":"Añadir el aliño sobre la fuente y remover bien hasta que todo quede impregnado.","minutes":1,"kind":"activo"},{"text":"Servir con los cacahuetes picados, el cilantro fresco y la guindilla roja por encima.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'plancha', NULL),
  ('ensaladas_verduras_053', 'Ensalada de bogavante', 'ensaladas_verduras', 'marisco', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 60, 'elaborada', 'all', 376, 32, 8, 24, 2, true, false, '{"marisco","huevo"}', '[{"name":"Bogavante","amount":600,"unit":"g"},{"name":"Lechugas variadas","amount":60,"unit":"g"},{"name":"Tomate cherry","amount":100,"unit":"g"},{"name":"Aguacate","amount":150,"unit":"g"},{"name":"Huevo","amount":50,"unit":"g"},{"name":"Aceite de oliva suave","amount":100,"unit":"ml"},{"name":"Limón","amount":15,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Llevar a ebullición una olla grande con agua abundante y sal.","Sumergir bogavante en el agua hirviendo y cocer 9 min.","Retirar el bogavante y sumergirlo en agua con hielo hasta que esté frío para cortar la cocción.","Extraer la carne de la cola y las pinzas con cuidado hasta que quede entera.","Cortar la carne del bogavante en medallones.","Verter huevo en un vaso de batidora junto con sal.","Añadir aceite de oliva suave en hilo fino mientras se bate hasta que emulsione.","Añadir limón a la mayonesa y remover hasta integrar.","Lavar lechugas variadas y escurrirlas bien.","Cortar aguacate en láminas.","Cortar tomate cherry por la mitad.","Repartir las lechugas variadas en la base de 2 platos.","Distribuir las láminas de aguacate y los tomates cherry sobre las lechugas.","Colocar los medallones de bogavante encima.","Servir con la mayonesa en un cordón fino sobre la ensalada o aparte."}', 'Bogavante recién cocido sobre hojas frescas, aguacate y tomate, para una ocasión especial.', '[{"appliance":"airfryer","time":45,"difficulty":"normal","prepSummary":"Precalienta la airfryer a 190°C. Cocina el bogavante (partido por la mitad) durante 12-15 minutos, hasta que la carne esté opaca. Los huevos se pueden hacer a 130°C durante 13-15 min para que queden duros y fáciles de pelar."},{"appliance":"horno","time":50,"difficulty":"normal","prepSummary":"Precalienta el horno a 200°C. Asa el bogavante (partido por la mitad con un poco de aceite) durante 15-20 minutos. Hierve los huevos por separado hasta que estén duros y enfríalos para pelar fácilmente."},{"appliance":"thermomix","time":50,"difficulty":"normal","prepSummary":"Cocina el bogavante entero o partido en el recipiente Varoma durante 20-25 minutos a velocidad Varoma. Aprovecha para cocer los huevos en el mismo Varoma o en el cestillo, programando 13-15 minutos."},{"appliance":"vaporera","time":45,"difficulty":"normal","prepSummary":"Cuece el bogavante entero o partido al vapor durante 15-20 minutos hasta que esté rojo y la carne opaca. Puedes cocer los huevos duros en la misma vaporera durante 12-15 minutos para un resultado perfecto."},{"appliance":"olla_express","time":40,"difficulty":"elaborada","prepSummary":"Introduce el bogavante entero o partido en la olla express con un poco de agua y cocina 5-7 minutos desde que sube la válvula. Los huevos se pueden cocinar 5-6 minutos a presión para pelarlos fácilmente, pero ten cuidado de no sobrecocer el bogavante."}]'::jsonb, '{}', true, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], false, '[{"text":"Llevar a ebullición una olla grande con agua abundante y {{Sal|gusto}}.","minutes":10,"kind":"activo"},{"text":"Sumergir {{Bogavante}} en el agua hirviendo y cocer 9 min.","minutes":9,"kind":"pasivo"},{"text":"Retirar el bogavante y sumergirlo en agua con hielo hasta que esté frío para cortar la cocción.","minutes":5,"kind":"espera"},{"text":"Extraer la carne de la cola y las pinzas con cuidado hasta que quede entera.","minutes":5,"kind":"prep"},{"text":"Cortar la carne del bogavante en medallones.","minutes":2,"kind":"prep"},{"text":"Verter {{Huevo}} en un vaso de batidora junto con {{Sal|gusto}}.","minutes":1,"kind":"prep","part":"salsa"},{"text":"Añadir {{Aceite de oliva suave}} en hilo fino mientras se bate hasta que emulsione.","minutes":3,"kind":"activo","part":"salsa"},{"text":"Añadir {{Limón}} a la mayonesa y remover hasta integrar.","minutes":1,"kind":"activo","part":"salsa"},{"text":"Lavar {{Lechugas variadas}} y escurrirlas bien.","minutes":2,"kind":"prep","part":"principal"},{"text":"Cortar {{Aguacate}} en láminas.","minutes":2,"kind":"prep","part":"principal"},{"text":"Cortar {{Tomate cherry}} por la mitad.","minutes":1,"kind":"prep","part":"principal"},{"text":"Repartir las lechugas variadas en la base de 2 platos.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Distribuir las láminas de aguacate y los tomates cherry sobre las lechugas.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Colocar los medallones de bogavante encima.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Servir con la mayonesa en un cordón fino sobre la ensalada o aparte.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true, 'especial', NULL, 'olla', NULL),
  ('ensaladas_verduras_054', 'Ensalada niçoise', 'ensaladas_verduras', 'pescado_azul', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'normal', 'all', 452, 30, 20, 28, 2, false, false, '{"huevo","pescado","sulfitos","mostaza"}', '[{"name":"Lechuga o mezclum","amount":100,"unit":"g"},{"name":"Tomate","amount":150,"unit":"g"},{"name":"Judías verdes","amount":150,"unit":"g"},{"name":"Patata","amount":200,"unit":"g"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Atún en aceite","amount":120,"unit":"g"},{"name":"Anchoas","amount":20,"unit":"g"},{"name":"Aceitunas negras","amount":40,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Vinagre de vino","amount":10,"unit":"ml"},{"name":"Mostaza de Dijon","amount":10,"unit":"g"}]'::jsonb, '{"Llevar a ebullición una olla con agua y sal a fuego fuerte.","Cocer patata con piel en el agua hirviendo a fuego medio hasta que estén tiernas.","Llevar a ebullición un cazo con agua a fuego fuerte para cocer los huevos.","Cocer huevo en el agua hirviendo a fuego medio durante 10 min.","Escurrir los huevos y sumergirlos en agua fría hasta que estén templados.","Llevar a ebullición otro cazo con agua y sal a fuego fuerte para las judías.","Escaldar judías verdes en el agua hirviendo a fuego medio.","Escurrir las judías verdes y pasar por agua fría hasta que estén frías para cortar la cocción.","Escurrir las patatas y dejar templar hasta que se puedan manipular.","Pelar las patatas y cortar en rodajas.","Pelar los huevos y cortar en cuartos.","Cortar tomate en gajos.","Mezclar aceite de oliva, vinagre de vino y mostaza de dijon en un bol pequeño hasta emulsionar.","Lavar lechuga o mezclum y repartir en la base de 2 platos o una fuente.","Distribuir encima las rodajas de patata, las judías verdes y los gajos de tomate.","Añadir atún en aceite desmigado, anchoas y aceitunas negras repartidos por la ensalada.","Colocar los cuartos de huevo por encima.","Aliñar la ensalada con la vinagreta justo antes de servir."}', 'Ensalada niçoise clásica con atún, huevo cocido, anchoas, patata y judías verdes.', '[{"appliance":"thermomix","time":35,"difficulty":"normal","prepSummary":"Cocina las patatas y judías verdes en el recipiente Varoma y los huevos en el cestillo, todo a la vez durante unos 20-25 minutos a temperatura Varoma. El truco es aprovechar la cocción simultánea para optimizar el tiempo y lograr la textura perfecta."},{"appliance":"vaporera","time":35,"difficulty":"facil","prepSummary":"Cuece las patatas y judías verdes al vapor hasta que estén tiernas (unos 15-20 minutos para las patatas, 8-10 para las judías). Hierve los huevos por separado o en la misma vaporera si tiene esa función. La cocción suave al vapor mantiene la textura ideal de los ingredientes."},{"appliance":"olla_express","time":30,"difficulty":"normal","prepSummary":"Cocina las patatas, judías verdes y huevos en la olla express con la rejilla y un poco de agua, durante 5-7 minutos desde que sube la válvula. El truco es despresurizar rápidamente para evitar que las verduras se pasen y queden perfectas."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura","encurtido"}', NULL, '{}'::main_protein[], false, '[{"text":"Llevar a ebullición una olla con agua y sal a fuego fuerte.","minutes":3,"kind":"activo"},{"text":"Cocer {{Patata}} con piel en el agua hirviendo a fuego medio hasta que estén tiernas.","minutes":20,"kind":"pasivo"},{"text":"Llevar a ebullición un cazo con agua a fuego fuerte para cocer los huevos.","minutes":2,"kind":"paralelo","during":1},{"text":"Cocer {{Huevo}} en el agua hirviendo a fuego medio durante 10 min.","minutes":10,"kind":"pasivo"},{"text":"Escurrir los huevos y sumergirlos en agua fría hasta que estén templados.","minutes":5,"kind":"espera"},{"text":"Llevar a ebullición otro cazo con agua y sal a fuego fuerte para las judías.","minutes":2,"kind":"paralelo","during":1},{"text":"Escaldar {{Judías verdes}} en el agua hirviendo a fuego medio.","minutes":5,"kind":"pasivo"},{"text":"Escurrir las judías verdes y pasar por agua fría hasta que estén frías para cortar la cocción.","minutes":2,"kind":"activo"},{"text":"Escurrir las patatas y dejar templar hasta que se puedan manipular.","minutes":5,"kind":"espera"},{"text":"Pelar las patatas y cortar en rodajas.","minutes":3,"kind":"prep"},{"text":"Pelar los huevos y cortar en cuartos.","minutes":2,"kind":"prep"},{"text":"Cortar {{Tomate}} en gajos.","minutes":2,"kind":"prep"},{"text":"Mezclar {{Aceite de oliva}}, {{Vinagre de vino}} y {{Mostaza de Dijon}} en un bol pequeño hasta emulsionar.","minutes":2,"kind":"prep"},{"text":"Lavar {{Lechuga o mezclum}} y repartir en la base de 2 platos o una fuente.","minutes":2,"kind":"emplatado"},{"text":"Distribuir encima las rodajas de patata, las judías verdes y los gajos de tomate.","minutes":2,"kind":"emplatado"},{"text":"Añadir {{Atún en aceite}} desmigado, {{Anchoas}} y {{Aceitunas negras}} repartidos por la ensalada.","minutes":1,"kind":"emplatado"},{"text":"Colocar los cuartos de huevo por encima.","minutes":1,"kind":"emplatado"},{"text":"Aliñar la ensalada con la vinagreta justo antes de servir.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'olla', NULL)
