insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id, extra_proteins, freezable, steps_rich, estrella, occasion, kid_favourite, tecnica, cocina
) values
  ('ensaladas_verduras_055', 'Ensalada de aguacate y gambas con salsa rosa', 'ensaladas_verduras', 'marisco', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 426, 20, 10, 34, 2, true, false, '{"marisco","huevo"}', '[{"name":"Canónigos","amount":100,"unit":"g"},{"name":"Aguacate","amount":200,"unit":"g"},{"name":"Gambas cocidas peladas","amount":200,"unit":"g"},{"name":"Tomate cherry","amount":100,"unit":"g"},{"name":"Mayonesa","amount":60,"unit":"g"},{"name":"Ketchup","amount":20,"unit":"g"},{"name":"Limón","amount":10,"unit":"ml"}]'::jsonb, '{"Mezclar mayonesa, ketchup y limón en un bol pequeño hasta obtener una salsa rosa homogénea.","Lavar canónigos bajo el grifo y escurrir bien.","Cortar tomate cherry por la mitad.","Cortar aguacate por la mitad, retirar el hueso y laminar la pulpa.","Repartir los canónigos escurridos en la base de 2 platos.","Distribuir las láminas de aguacate, gambas cocidas peladas y los tomates cherry sobre los canónigos.","Napar con la salsa rosa y servir enseguida."}', 'Ensalada fresca de aguacate y gambas cocidas con una cremosa salsa rosa casera.', '[]'::jsonb, '{}', NULL, true, NULL, '{"verdura"}', NULL, '{}'::main_protein[], false, '[{"text":"Mezclar {{Mayonesa}}, {{Ketchup}} y {{Limón}} en un bol pequeño hasta obtener una salsa rosa homogénea.","minutes":2,"kind":"prep"},{"text":"Lavar {{Canónigos}} bajo el grifo y escurrir bien.","minutes":1,"kind":"prep"},{"text":"Cortar {{Tomate cherry}} por la mitad.","minutes":1,"kind":"prep"},{"text":"Cortar {{Aguacate}} por la mitad, retirar el hueso y laminar la pulpa.","minutes":2,"kind":"prep"},{"text":"Repartir los canónigos escurridos en la base de 2 platos.","minutes":1,"kind":"emplatado"},{"text":"Distribuir las láminas de aguacate, {{Gambas cocidas peladas}} y los tomates cherry sobre los canónigos.","minutes":2,"kind":"emplatado"},{"text":"Napar con la salsa rosa y servir enseguida.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'crudo', NULL),
  ('ensaladas_verduras_056', 'Ensalada de manzana, nueces y queso azul', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 331, 8, 14, 27, 2, false, false, '{"frutos_secos","lactosa","sulfitos"}', '[{"name":"Canónigos","amount":100,"unit":"g"},{"name":"Manzana","amount":150,"unit":"g"},{"name":"Nueces","amount":40,"unit":"g"},{"name":"Queso azul","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Vinagre de Módena","amount":15,"unit":"ml"},{"name":"Miel","amount":10,"unit":"g"}]'::jsonb, '{"Lavar canónigos bajo agua fría y escurrir bien.","Repartir los canónigos escurridos en una ensaladera o en 2 platos.","Descorazonar manzana y cortar en láminas finas.","Calentar sartén a fuego medio sin aceite y tostar nueces hasta que desprendan aroma tostado.","Retirar las nueces de la sartén y reservar.","Desmenuzar queso azul en trozos irregulares.","Mezclar aceite de oliva, vinagre de módena y miel en un bol hasta emulsionar.","Repartir las láminas de manzana, las nueces y el queso azul sobre la base de canónigos.","Aliñar la ensalada con el aliño justo antes de servir."}', 'Ensalada dulce y crujiente de manzana, nueces tostadas y queso azul.', '[{"appliance":"thermomix","time":15,"difficulty":"facil","prepSummary":"Utiliza la Thermomix para pesar con precisión todos los ingredientes y emulsionar la vinagreta de aceite, vinagre y miel, logrando una mezcla homogénea y perfecta para aderezar la ensalada."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura","lacteo","fruta","frutos_secos"}', NULL, '{}'::main_protein[], false, '[{"text":"Lavar {{Canónigos}} bajo agua fría y escurrir bien.","minutes":2,"kind":"prep"},{"text":"Repartir los canónigos escurridos en una ensaladera o en 2 platos.","minutes":1,"kind":"prep"},{"text":"Descorazonar {{Manzana}} y cortar en láminas finas.","minutes":2,"kind":"prep"},{"text":"Calentar {{@Sartén}} a fuego medio sin aceite y tostar {{Nueces}} hasta que desprendan aroma tostado.","minutes":3,"kind":"activo"},{"text":"Retirar las nueces de la sartén y reservar.","minutes":1,"kind":"prep"},{"text":"Desmenuzar {{Queso azul}} en trozos irregulares.","minutes":1,"kind":"prep"},{"text":"Mezclar {{Aceite de oliva|chorrito}}, {{Vinagre de Módena}} y {{Miel}} en un bol hasta emulsionar.","minutes":1,"kind":"activo"},{"text":"Repartir las láminas de manzana, las nueces y el queso azul sobre la base de canónigos.","minutes":1,"kind":"emplatado"},{"text":"Aliñar la ensalada con el aliño justo antes de servir.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL),
  ('ensaladas_verduras_057', 'Tabulé de cuscús con menta y limón', 'ensaladas_verduras', 'none', 'cuscus', ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 300, 7, 38, 13, 2, true, true, '{"gluten"}', '[{"name":"Cuscús","amount":100,"unit":"g"},{"name":"Tomate","amount":150,"unit":"g"},{"name":"Pepino","amount":100,"unit":"g"},{"name":"Cebolleta","amount":30,"unit":"g"},{"name":"Perejil fresco","amount":20,"unit":"g"},{"name":"Menta fresca","amount":10,"unit":"g"},{"name":"Limón","amount":30,"unit":"ml"},{"name":"Aceite de oliva","amount":30,"unit":"ml"}]'::jsonb, '{"Hervir agua con sal en un cazo pequeño.","Colocar cuscús en un bol amplio y cubrir con el agua hirviendo recién lista.","Añadir aceite de oliva al bol, tapar con un plato y dejar reposar 5 min.","Cortar tomate en dados pequeños.","Cortar pepino en dados pequeños.","Picar cebolleta muy fina.","Picar perejil fresco muy fino.","Picar menta fresca muy fina.","Soltar los granos de cuscús con un tenedor hasta que queden sueltos y esponjosos.","Añadir el tomate, el pepino, la cebolleta, el perejil y la menta al bol con el cuscús.","Aliñar con limón y el resto del aceite de oliva.","Salpimentar al gusto y remover bien hasta integrar todos los ingredientes.","Tapar el bol y refrigerar en la nevera al menos 15 min para que los sabores se asienten.","Servir el tabulé frío directamente del bol."}', 'Tabulé de cuscús con menta, perejil y limón, ligero y muy aromático.', '[{"appliance":"thermomix","time":15,"difficulty":"facil","prepSummary":"La Thermomix es excelente para picar finamente las verduras y hierbas en segundos. Luego, puedes hidratar el cuscús con agua caliente en el vaso y mezclar todos los ingredientes con el aceite y limón, logrando una textura homogénea."},{"appliance":"vaporera","time":20,"difficulty":"facil","prepSummary":"La vaporera es perfecta para cocinar el cuscús, dejándolo suelto y esponjoso. Hidrata el cuscús al vapor durante unos 10-12 minutos y luego mézclalo con las verduras frescas picadas y el aliño para un resultado auténtico."},{"appliance":"microondas","time":15,"difficulty":"facil","prepSummary":"El microondas es ideal para calentar rápidamente el agua o caldo para hidratar el cuscús en pocos minutos. Simplemente calienta el líquido, añade el cuscús, deja reposar y luego mezcla con el resto de ingredientes frescos para un tabulé rápido."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], false, '[{"text":"Hervir agua con sal en un cazo pequeño.","minutes":3,"kind":"activo"},{"text":"Colocar {{Cuscús}} en un bol amplio y cubrir con el agua hirviendo recién lista.","minutes":1,"kind":"activo"},{"text":"Añadir {{Aceite de oliva|chorrito}} al bol, tapar con un plato y dejar reposar 5 min.","minutes":5,"kind":"espera"},{"text":"Cortar {{Tomate}} en dados pequeños.","minutes":2,"kind":"paralelo","during":2},{"text":"Cortar {{Pepino}} en dados pequeños.","minutes":1,"kind":"paralelo","during":2},{"text":"Picar {{Cebolleta}} muy fina.","minutes":1,"kind":"paralelo","during":2},{"text":"Picar {{Perejil fresco}} muy fino.","minutes":1,"kind":"paralelo","during":2},{"text":"Picar {{Menta fresca}} muy fina.","minutes":1,"kind":"paralelo","during":2},{"text":"Soltar los granos de cuscús con un tenedor hasta que queden sueltos y esponjosos.","minutes":1,"kind":"activo"},{"text":"Añadir el tomate, el pepino, la cebolleta, el perejil y la menta al bol con el cuscús.","minutes":1,"kind":"activo"},{"text":"Aliñar con {{Limón}} y el resto del aceite de oliva.","minutes":1,"kind":"activo"},{"text":"Salpimentar al gusto y remover bien hasta integrar todos los ingredientes.","minutes":1,"kind":"activo"},{"text":"Tapar el bol y refrigerar en la nevera al menos 15 min para que los sabores se asienten.","minutes":15,"kind":"espera"},{"text":"Servir el tabulé frío directamente del bol.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'sarten', 'mediterranea'),
  ('ensaladas_verduras_058', 'Ensalada de cuscús con verduras asadas', 'ensaladas_verduras', 'none', 'cuscus', ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'horno', 40, 'facil', 'all', 355, 8, 42, 17, 2, true, true, '{"gluten"}', '[{"name":"Cuscús","amount":100,"unit":"g"},{"name":"Calabacín","amount":150,"unit":"g"},{"name":"Pimiento rojo","amount":100,"unit":"g"},{"name":"Berenjena","amount":150,"unit":"g"},{"name":"Cebolla roja","amount":50,"unit":"g"},{"name":"Aceite de oliva","amount":35,"unit":"ml"},{"name":"Limón","amount":15,"unit":"ml"},{"name":"Perejil fresco","amount":10,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C.","Cortar calabacín, pimiento rojo, berenjena y cebolla roja en trozos regulares de unos 2 cm.","Disponer las verduras cortadas en una bandeja de horno en una sola capa.","Rociar las verduras con aceite de oliva y salpimentar.","Hornear las verduras a 200 °C durante 25 min, hasta que estén tiernas y doradas.","Llevar agua con sal a ebullición y verterla sobre cuscús en un bol hasta cubrirlo justo.","Tapar el bol y dejar reposar el cuscús 5 min hasta que absorba toda el agua.","Soltar los granos de cuscús con un tenedor hasta que queden sueltos y esponjosos.","Picar perejil fresco fino y reservar.","Mezclar el cuscús con las verduras asadas templadas en el bol grande.","Aliñar con el resto del aceite de oliva y limón, y remover para integrar.","Espolvorear el perejil picado por encima y servir templado o frío."}', 'Ensalada de cuscús con verduras de temporada asadas al horno.', '[{"appliance":"horno","time":40,"difficulty":"facil","prepSummary":"Cortar las verduras, mezclarlas con aceite de oliva, sal y pimienta. Asarlas en el horno precalentado a 200°C durante 25-30 minutos hasta que estén tiernas y ligeramente doradas. Preparar el cuscús con agua caliente y mezclar todo."},{"appliance":"airfryer","time":25,"difficulty":"facil","prepSummary":"Trocear las verduras, aderezar con aceite de oliva. Cocinarlas en la airfryer a 190°C en tandas durante 15-20 minutos, removiendo a mitad, hasta que estén tiernas y con un ligero tostado. Hidratar el cuscús y combinar."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], false, '[{"text":"Precalentar el horno a 200 °C.","minutes":10,"kind":"pasivo"},{"text":"Cortar {{Calabacín}}, {{Pimiento rojo}}, {{Berenjena}} y {{Cebolla roja}} en trozos regulares de unos 2 cm.","minutes":8,"kind":"prep"},{"text":"Disponer las verduras cortadas en una bandeja de horno en una sola capa.","minutes":1,"kind":"prep"},{"text":"Rociar las verduras con {{Aceite de oliva|chorrito}} y salpimentar.","minutes":1,"kind":"prep"},{"text":"Hornear las verduras a 200 °C durante 25 min, hasta que estén tiernas y doradas.","minutes":25,"kind":"pasivo"},{"text":"Llevar agua con sal a ebullición y verterla sobre {{Cuscús}} en un bol hasta cubrirlo justo.","minutes":3,"kind":"activo"},{"text":"Tapar el bol y dejar reposar el cuscús 5 min hasta que absorba toda el agua.","minutes":5,"kind":"espera"},{"text":"Soltar los granos de cuscús con un tenedor hasta que queden sueltos y esponjosos.","minutes":2,"kind":"activo"},{"text":"Picar {{Perejil fresco}} fino y reservar.","minutes":2,"kind":"prep"},{"text":"Mezclar el cuscús con las verduras asadas templadas en el bol grande.","minutes":2,"kind":"activo"},{"text":"Aliñar con el resto del aceite de oliva y {{Limón}}, y remover para integrar.","minutes":1,"kind":"activo"},{"text":"Espolvorear el perejil picado por encima y servir templado o frío.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'horno', 'mediterranea'),
  ('ensaladas_verduras_059', 'Ensalada campera con ventresca', 'ensaladas_verduras', 'pescado_azul', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'facil', 'all', 404, 22, 25, 24, 2, true, true, '{"pescado","huevo","sulfitos"}', '[{"name":"Patata","amount":300,"unit":"g"},{"name":"Tomate","amount":150,"unit":"g"},{"name":"Pimiento verde","amount":60,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Ventresca de atún en aceite","amount":120,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Aceitunas","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Vinagre de vino","amount":10,"unit":"ml"}]'::jsonb, '{"Llevar a ebullición agua con sal en un cazo y cocer patata con piel hasta que estén tiernas.","Cocer huevo en agua hirviendo durante 10 min.","Enfriar el huevo bajo agua fría, pelar y cortar en cuartos.","Escurrir las patatas, dejar templar y pelar.","Cortar las patatas en rodajas y disponer en una fuente.","Cortar tomate en dados pequeños y repartir sobre las patatas.","Cortar pimiento verde en dados pequeños y añadir a la fuente.","Cortar cebolla en dados pequeños y añadir a la fuente.","Desmigar ventresca de atún en aceite sobre la fuente.","Añadir aceitunas y los cuartos de huevo sobre la ensalada.","Aliñar con aceite de oliva y vinagre de vino.","Reposar la ensalada 5 min antes de servir para que se integren los sabores.","Servir la ensalada campera directamente desde la fuente."}', 'Ensalada campera de patata con ventresca de atún, huevo y pimiento.', '[{"appliance":"thermomix","time":30,"difficulty":"facil","prepSummary":"Cocina las patatas y el huevo al vapor en el recipiente Varoma simultáneamente durante unos 25-30 minutos, asegurando que queden tiernos y cocidos a la perfección."},{"appliance":"vaporera","time":30,"difficulty":"facil","prepSummary":"Cuece las patatas y el huevo al vapor en la vaporera durante unos 25-30 minutos hasta que estén tiernos, manteniendo su textura y nutrientes."},{"appliance":"olla_express","time":20,"difficulty":"facil","prepSummary":"Cocina las patatas y el huevo en la olla express con un poco de agua durante 5-7 minutos desde que sube la válvula, reduciendo significativamente el tiempo de cocción."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura","encurtido"}', NULL, '{}'::main_protein[], false, '[{"text":"Llevar a ebullición agua con sal en un cazo y cocer {{Patata}} con piel hasta que estén tiernas.","minutes":25,"kind":"pasivo"},{"text":"Cocer {{Huevo}} en agua hirviendo durante 10 min.","minutes":10,"kind":"paralelo","during":0},{"text":"Enfriar el huevo bajo agua fría, pelar y cortar en cuartos.","minutes":3,"kind":"prep"},{"text":"Escurrir las patatas, dejar templar y pelar.","minutes":5,"kind":"prep"},{"text":"Cortar las patatas en rodajas y disponer en una fuente.","minutes":2,"kind":"prep"},{"text":"Cortar {{Tomate}} en dados pequeños y repartir sobre las patatas.","minutes":2,"kind":"prep"},{"text":"Cortar {{Pimiento verde}} en dados pequeños y añadir a la fuente.","minutes":1,"kind":"prep"},{"text":"Cortar {{Cebolla}} en dados pequeños y añadir a la fuente.","minutes":1,"kind":"prep"},{"text":"Desmigar {{Ventresca de atún en aceite}} sobre la fuente.","minutes":1,"kind":"activo"},{"text":"Añadir {{Aceitunas}} y los cuartos de huevo sobre la ensalada.","minutes":1,"kind":"activo"},{"text":"Aliñar con {{Aceite de oliva|chorrito}} y {{Vinagre de vino|chorrito}}.","minutes":1,"kind":"activo"},{"text":"Reposar la ensalada 5 min antes de servir para que se integren los sabores.","minutes":5,"kind":"espera"},{"text":"Servir la ensalada campera directamente desde la fuente.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL),
  ('ensaladas_verduras_060', 'Ensalada tibia de setas y jamón', 'ensaladas_verduras', 'cerdo', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 215, 13, 5, 17, 2, true, false, '{"sulfitos"}', '[{"name":"Mezclum de hojas","amount":80,"unit":"g"},{"name":"Setas variadas","amount":250,"unit":"g"},{"name":"Jamón serrano en taquitos","amount":60,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Vinagre de Jerez","amount":10,"unit":"ml"},{"name":"Perejil fresco","amount":5,"unit":"g"}]'::jsonb, '{"Limpiar setas variadas con un paño húmedo para retirar la tierra.","Laminar las setas limpias.","Picar ajo fino.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír el ajo picado hasta que aromatice sin que se dore.","Añadir las setas laminadas y subir a fuego fuerte.","Saltear las setas hasta que se doren y suelten el agua, removiendo a menudo.","Añadir jamón serrano en taquitos y saltear 1 min más hasta que esté caliente.","Picar perejil fresco fino y reservar.","Repartir mezclum de hojas en los platos como base.","Distribuir las setas y el jamón templados sobre las hojas.","Aliñar con aceite de oliva y vinagre de jerez.","Espolvorear el perejil picado y servir enseguida."}', 'Ensalada tibia de setas salteadas y jamón serrano sobre un fondo de hojas frescas.', '[{"appliance":"airfryer","time":15,"difficulty":"facil","prepSummary":"Para unas setas tiernas y jamón crujiente, cocina las setas con ajo y un chorrito de aceite en la airfryer a 180°C durante 10-12 minutos. Añade el jamón en taquitos los últimos 3-5 minutos para que se dore bien."},{"appliance":"horno","time":20,"difficulty":"facil","prepSummary":"Asa las setas con ajo y un poco de aceite en una bandeja de horno a 200°C durante 15-20 minutos, removiendo a mitad. Incorpora el jamón en taquitos los últimos 5-7 minutos para que quede dorado y crujiente."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura","seta"}', NULL, '{}'::main_protein[], false, '[{"text":"Limpiar {{Setas variadas}} con un paño húmedo para retirar la tierra.","minutes":2,"kind":"prep"},{"text":"Laminar las setas limpias.","minutes":2,"kind":"prep"},{"text":"Picar {{Ajo}} fino.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír el ajo picado hasta que aromatice sin que se dore.","minutes":1,"kind":"activo"},{"text":"Añadir las setas laminadas y subir a fuego fuerte.","minutes":1,"kind":"activo"},{"text":"Saltear las setas hasta que se doren y suelten el agua, removiendo a menudo.","minutes":6,"kind":"activo"},{"text":"Añadir {{Jamón serrano en taquitos}} y saltear 1 min más hasta que esté caliente.","minutes":1,"kind":"activo"},{"text":"Picar {{Perejil fresco}} fino y reservar.","minutes":1,"kind":"prep"},{"text":"Repartir {{Mezclum de hojas}} en los platos como base.","minutes":1,"kind":"emplatado"},{"text":"Distribuir las setas y el jamón templados sobre las hojas.","minutes":1,"kind":"emplatado"},{"text":"Aliñar con {{Aceite de oliva|chorrito}} y {{Vinagre de Jerez}}.","minutes":1,"kind":"emplatado"},{"text":"Espolvorear el perejil picado y servir enseguida.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL),
  ('ensaladas_verduras_061', 'Ensalada de espinacas, fresas y almendras', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 220, 5, 11, 17, 2, true, false, '{"frutos_secos"}', '[{"name":"Espinacas baby","amount":100,"unit":"g"},{"name":"Fresas","amount":150,"unit":"g"},{"name":"Almendras laminadas","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Vinagre balsámico","amount":15,"unit":"ml"},{"name":"Miel","amount":10,"unit":"g"}]'::jsonb, '{"Lavar espinacas baby bajo el grifo con agua fría y escurrir bien.","Lavar fresas, retirar el rabito y cortar cada una en láminas.","Calentar sartén a fuego medio sin aceite hasta que esté bien caliente.","Tostar almendras laminadas en la sartén hasta que estén doradas, removiendo con frecuencia.","Retirar las almendras laminadas de la sartén y reservar sobre un plato para que enfríen.","Mezclar aceite de oliva con vinagre balsámico y miel en un bol pequeño hasta emulsionar.","Repartir las espinacas baby en la base de los platos.","Distribuir las fresas laminadas y las almendras laminadas tostadas por encima de las espinacas.","Aliñar con el aceite de oliva, el vinagre balsámico y la miel justo antes de servir."}', 'Ensalada de espinacas baby con fresas y almendras tostadas.', '[{"appliance":"airfryer","time":15,"difficulty":"facil","prepSummary":"Tuesta las almendras laminadas en la airfryer a 170°C durante 4-5 minutos, agitándolas a mitad para un dorado uniforme. Luego, mezcla todos los ingredientes y aliña con la vinagreta."},{"appliance":"horno","time":20,"difficulty":"facil","prepSummary":"Precalienta el horno a 170°C. Tuesta las almendras laminadas en una bandeja durante 5-7 minutos hasta que estén ligeramente doradas. Deja enfriar y luego combina con el resto de ingredientes y el aderezo."},{"appliance":"thermomix","time":15,"difficulty":"facil","prepSummary":"Prepara el aderezo emulsionando el aceite, vinagre y miel en la Thermomix durante 30 segundos a velocidad 4-5. Luego, vierte sobre las espinacas, fresas y almendras, y mezcla suavemente."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura","fruta","frutos_secos"}', NULL, '{}'::main_protein[], false, '[{"text":"Lavar {{Espinacas baby}} bajo el grifo con agua fría y escurrir bien.","minutes":2,"kind":"prep"},{"text":"Lavar {{Fresas}}, retirar el rabito y cortar cada una en láminas.","minutes":3,"kind":"prep"},{"text":"Calentar {{@Sartén}} a fuego medio sin aceite hasta que esté bien caliente.","minutes":1,"kind":"activo"},{"text":"Tostar {{Almendras laminadas}} en la sartén hasta que estén doradas, removiendo con frecuencia.","minutes":3,"kind":"activo"},{"text":"Retirar las almendras laminadas de la sartén y reservar sobre un plato para que enfríen.","minutes":1,"kind":"espera"},{"text":"Mezclar {{Aceite de oliva}} con {{Vinagre balsámico}} y {{Miel|gusto}} en un bol pequeño hasta emulsionar.","minutes":1,"kind":"prep"},{"text":"Repartir las espinacas baby en la base de los platos.","minutes":1,"kind":"emplatado"},{"text":"Distribuir las fresas laminadas y las almendras laminadas tostadas por encima de las espinacas.","minutes":1,"kind":"emplatado"},{"text":"Aliñar con el aceite de oliva, el vinagre balsámico y la miel justo antes de servir.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL),
  ('ensaladas_verduras_062', 'Ensalada de canónigos con granada y queso de cabra', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 316, 10, 15, 24, 2, true, false, '{"lactosa","frutos_secos"}', '[{"name":"Canónigos","amount":100,"unit":"g"},{"name":"Granada (arilos)","amount":100,"unit":"g"},{"name":"Queso de cabra","amount":80,"unit":"g"},{"name":"Nueces","amount":20,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Vinagre de Módena","amount":15,"unit":"ml"},{"name":"Miel","amount":10,"unit":"g"}]'::jsonb, '{"Lavar canónigos bajo agua fría y escurrir bien.","Desgranar granada (arilos) retirando toda la piel blanca.","Cortar queso de cabra en rodajas.","Mezclar aceite de oliva, vinagre de módena y miel en un bol hasta emulsionar.","Repartir los canónigos escurridos en una fuente.","Disponer sobre los canónigos los arilos de granada, las rodajas de queso de cabra y nueces.","Aliñar con el vinagre de Módena emulsionado justo antes de servir."}', 'Ensalada de canónigos con granada, queso de cabra y nueces.', '[{"appliance":"airfryer","time":10,"difficulty":"facil","prepSummary":"Para realzar el queso de cabra, caliéntalo en la airfryer a 180°C durante 4-5 minutos hasta que esté ligeramente dorado y cremoso. Luego, monta la ensalada con el resto de ingredientes frescos y el queso templado."},{"appliance":"horno","time":12,"difficulty":"facil","prepSummary":"Gratina el queso de cabra en el horno precalentado a 200°C durante 5-7 minutos, hasta que esté fundente y con una ligera costra dorada. Sirve el queso templado sobre la ensalada ya montada."}]'::jsonb, '{}', NULL, true, NULL, '{"verdura","lacteo","fruta","frutos_secos"}', NULL, '{}'::main_protein[], false, '[{"text":"Lavar {{Canónigos}} bajo agua fría y escurrir bien.","minutes":2,"kind":"prep"},{"text":"Desgranar {{Granada (arilos)}} retirando toda la piel blanca.","minutes":3,"kind":"prep"},{"text":"Cortar {{Queso de cabra}} en rodajas.","minutes":1,"kind":"prep"},{"text":"Mezclar {{Aceite de oliva|chorrito}}, {{Vinagre de Módena}} y {{Miel}} en un bol hasta emulsionar.","minutes":2,"kind":"activo"},{"text":"Repartir los canónigos escurridos en una fuente.","minutes":1,"kind":"emplatado"},{"text":"Disponer sobre los canónigos los arilos de granada, las rodajas de queso de cabra y {{Nueces}}.","minutes":1,"kind":"emplatado"},{"text":"Aliñar con el vinagre de Módena emulsionado justo antes de servir.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'crudo', NULL),
  ('ensaladas_verduras_063', 'Ensalada de tomate, mozzarella y pesto', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'verano', 323, 14, 6, 27, 2, true, true, '{"lactosa","frutos_secos"}', '[{"name":"Tomate","amount":250,"unit":"g"},{"name":"Mozzarella fresca","amount":150,"unit":"g"},{"name":"Pesto","amount":40,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"},{"name":"Albahaca fresca","amount":5,"unit":"g"}]'::jsonb, '{"Cortar tomate en rodajas gruesas de unos 8 mm.","Cortar mozzarella fresca en rodajas del mismo grosor que el tomate.","Alternar en el plato las rodajas de tomate y mozzarella, superponiéndolas ligeramente.","Repartir pesto por encima con una cuchara, en hilo fino y uniforme.","Rociar con aceite de oliva sobre el conjunto.","Distribuir albahaca fresca en hojas enteras por encima y servir a temperatura ambiente."}', 'Ensalada caprese de tomate y mozzarella con pesto casero.', '[]'::jsonb, '{}', NULL, true, NULL, '{"verdura","lacteo"}', NULL, '{}'::main_protein[], false, '[{"text":"Cortar {{Tomate}} en rodajas gruesas de unos 8 mm.","minutes":2,"kind":"prep"},{"text":"Cortar {{Mozzarella fresca}} en rodajas del mismo grosor que el tomate.","minutes":2,"kind":"prep"},{"text":"Alternar en el plato las rodajas de tomate y mozzarella, superponiéndolas ligeramente.","minutes":1,"kind":"emplatado"},{"text":"Repartir {{Pesto}} por encima con una cuchara, en hilo fino y uniforme.","minutes":1,"kind":"emplatado"},{"text":"Rociar con {{Aceite de oliva|chorrito}} sobre el conjunto.","minutes":1,"kind":"emplatado"},{"text":"Distribuir {{Albahaca fresca|gusto}} en hojas enteras por encima y servir a temperatura ambiente.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'crudo', 'italiana'),
  ('ensaladas_verduras_064', 'Ensalada de lentejas templadas con feta', 'ensaladas_verduras', 'legumbre', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 400, 20, 35, 20, 2, true, true, '{"lactosa","sulfitos"}', '[{"name":"Lentejas cocidas","amount":300,"unit":"g"},{"name":"Queso feta","amount":100,"unit":"g"},{"name":"Tomate cherry","amount":120,"unit":"g"},{"name":"Cebolla roja","amount":40,"unit":"g"},{"name":"Pepino","amount":80,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Vinagre de vino","amount":10,"unit":"ml"},{"name":"Perejil fresco","amount":10,"unit":"g"}]'::jsonb, '{"Cortar tomate cherry por la mitad.","Picar cebolla roja muy fina.","Cortar pepino en dados pequeños.","Picar perejil fresco fino.","Calentar lentejas cocidas en un cazo a fuego suave hasta que estén templadas.","Mezclar las lentejas templadas con el tomate cherry, la cebolla roja y el pepino en un bol.","Aliñar con aceite de oliva y vinagre de vino.","Añadir el perejil picado y remover con cuidado.","Desmenuzar queso feta por encima y servir templado."}', 'Ensalada templada de lentejas con feta desmenuzado y verduras frescas.', '[{"appliance":"thermomix","time":20,"difficulty":"facil","prepSummary":"Pica la cebolla, el pepino y el perejil en segundos. Calienta las lentejas cocidas a 90°C, velocidad cuchara, giro inverso durante 5-7 minutos y emulsiona el aliño en el vaso."},{"appliance":"microondas","time":15,"difficulty":"facil","prepSummary":"Calienta las lentejas cocidas en un recipiente apto para microondas durante 2-3 minutos a máxima potencia hasta que estén templadas. Luego, mezcla con el resto de ingredientes frescos."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura","lacteo"}', NULL, '{}'::main_protein[], false, '[{"text":"Cortar {{Tomate cherry}} por la mitad.","minutes":2,"kind":"prep"},{"text":"Picar {{Cebolla roja}} muy fina.","minutes":2,"kind":"prep"},{"text":"Cortar {{Pepino}} en dados pequeños.","minutes":2,"kind":"prep"},{"text":"Picar {{Perejil fresco}} fino.","minutes":1,"kind":"prep"},{"text":"Calentar {{Lentejas cocidas}} en un cazo a fuego suave hasta que estén templadas.","minutes":3,"kind":"activo"},{"text":"Mezclar las lentejas templadas con el tomate cherry, la cebolla roja y el pepino en un bol.","minutes":1,"kind":"activo"},{"text":"Aliñar con {{Aceite de oliva|chorrito}} y {{Vinagre de vino}}.","minutes":1,"kind":"activo"},{"text":"Añadir el perejil picado y remover con cuidado.","minutes":1,"kind":"activo"},{"text":"Desmenuzar {{Queso feta}} por encima y servir templado.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL)
