insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id, extra_proteins, freezable, steps_rich, estrella, occasion, kid_favourite, tecnica, cocina
) values
  ('ensaladas_verduras_065', 'Ensalada de pollo crujiente y aguacate', 'ensaladas_verduras', 'pollo', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 30, 'facil', 'all', 579, 36, 30, 35, 2, true, false, '{"gluten","huevo"}', '[{"name":"Pechuga de pollo","amount":260,"unit":"g"},{"name":"Harina","amount":40,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Pan rallado","amount":60,"unit":"g"},{"name":"Aceite de oliva suave para freír","amount":200,"unit":"ml"},{"name":"Aguacate","amount":200,"unit":"g"},{"name":"Mezclum de hojas","amount":100,"unit":"g"},{"name":"Tomate cherry","amount":100,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Vinagre de vino","amount":10,"unit":"ml"}]'::jsonb, '{"Cortar pechuga de pollo en tiras finas y salpimentar.","Batir huevo en un bol hasta que esté homogéneo.","Pasar cada tira de pollo por harina, luego por el huevo batido y por último por pan rallado, presionando bien.","Calentar aceite de oliva suave para freír en sartén a fuego medio-fuerte hasta que esté caliente.","Freír las tiras de pollo empanadas hasta que estén doradas y crujientes, unos 3 min por cada lado.","Escurrir el pollo frito sobre papel absorbente y reservar.","Lavar y escurrir mezclum de hojas y repartir sobre los platos.","Cortar tomate cherry por la mitad.","Laminar aguacate y repartir sobre las hojas junto con los tomates cherry.","Mezclar aceite de oliva con vinagre de vino en un bol pequeño hasta integrar.","Colocar las tiras de pollo crujiente sobre la ensalada.","Aliñar con el vinagre y el aceite de oliva y servir enseguida para que el pollo conserve el crujiente."}', 'Ensalada de pollo crujiente empanado con aguacate y tomate cherry.', '[{"appliance":"airfryer","time":25,"difficulty":"facil","prepSummary":"Prepara el pollo empanado y cocínalo en la airfryer a 190-200°C durante 15-18 minutos, dándole la vuelta a mitad, hasta que esté dorado y crujiente. Luego, monta la ensalada."},{"appliance":"horno","time":35,"difficulty":"facil","prepSummary":"Empana el pollo y hornéalo en un horno precalentado a 200°C durante 20-25 minutos, o hasta que esté bien dorado y crujiente. Voltea a mitad de cocción para un resultado uniforme."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], false, '[{"text":"Cortar {{Pechuga de pollo}} en tiras finas y salpimentar.","minutes":3,"kind":"prep","part":"principal"},{"text":"Batir {{Huevo}} en un bol hasta que esté homogéneo.","minutes":1,"kind":"prep","part":"principal"},{"text":"Pasar cada tira de pollo por {{Harina}}, luego por el huevo batido y por último por {{Pan rallado}}, presionando bien.","minutes":4,"kind":"prep","part":"principal"},{"text":"Calentar {{Aceite de oliva suave para freír|abundante}} en {{@Sartén}} a fuego medio-fuerte hasta que esté caliente.","minutes":2,"kind":"activo","part":"principal"},{"text":"Freír las tiras de pollo empanadas hasta que estén doradas y crujientes, unos 3 min por cada lado.","minutes":6,"kind":"activo","part":"principal"},{"text":"Escurrir el pollo frito sobre papel absorbente y reservar.","minutes":2,"kind":"prep","part":"principal"},{"text":"Lavar y escurrir {{Mezclum de hojas}} y repartir sobre los platos.","minutes":2,"kind":"prep","part":"guarnicion"},{"text":"Cortar {{Tomate cherry}} por la mitad.","minutes":1,"kind":"prep","part":"guarnicion"},{"text":"Laminar {{Aguacate}} y repartir sobre las hojas junto con los tomates cherry.","minutes":2,"kind":"prep","part":"guarnicion"},{"text":"Mezclar {{Aceite de oliva}} con {{Vinagre de vino}} en un bol pequeño hasta integrar.","minutes":1,"kind":"prep","part":"salsa"},{"text":"Colocar las tiras de pollo crujiente sobre la ensalada.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Aliñar con el vinagre y el aceite de oliva y servir enseguida para que el pollo conserve el crujiente.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true, NULL, NULL, 'horno', NULL),
  ('ensaladas_verduras_066', 'Ensalada de calabaza asada y queso de cabra', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'horno', 35, 'facil', 'all', 365, 13, 22, 25, 2, true, false, '{"lactosa","frutos_secos"}', '[{"name":"Calabaza","amount":400,"unit":"g"},{"name":"Rúcula","amount":80,"unit":"g"},{"name":"Queso de cabra","amount":100,"unit":"g"},{"name":"Nueces","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Miel","amount":20,"unit":"g"},{"name":"Vinagre balsámico","amount":10,"unit":"ml"}]'::jsonb, '{"Precalentar el horno a 200 °C.","Pelar calabaza y cortar en dados de 2 cm.","Disponer los dados de calabaza en una bandeja y rociar con aceite de oliva.","Salpimentar los dados de calabaza y hornear a 200 °C hasta que estén tiernos y dorados.","Mezclar miel y vinagre balsámico con el resto del aceite de oliva en un bol hasta emulsionar.","Trocear nueces en trozos gruesos.","Retirar la calabaza del horno y dejar templar.","Repartir rúcula en los platos.","Disponer los dados de calabaza templada sobre la rúcula.","Desmenuzar queso de cabra por encima de la calabaza.","Repartir las nueces troceadas sobre la ensalada.","Aliñar la ensalada con la vinagreta de miel y vinagre balsámico justo antes de servir."}', 'Ensalada de calabaza asada con queso de cabra y nueces sobre rúcula.', '[{"appliance":"horno","time":35,"difficulty":"facil","prepSummary":"Corta la calabaza en cubos, mézclala con aceite, sal y pimienta. Ásala en el horno precalentado a 200°C durante 30-35 minutos, hasta que esté tierna y ligeramente caramelizada."},{"appliance":"airfryer","time":20,"difficulty":"facil","prepSummary":"Corta la calabaza en cubos, mézclala con aceite, sal y pimienta. Cocínala en la airfryer a 190°C durante 18-20 minutos, agitando la cesta a mitad de cocción, hasta que esté tierna y dorada."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura","lacteo","frutos_secos"}', NULL, '{}'::main_protein[], false, '[{"text":"Precalentar el horno a 200 °C.","minutes":10,"kind":"pasivo"},{"text":"Pelar {{Calabaza}} y cortar en dados de 2 cm.","minutes":5,"kind":"prep"},{"text":"Disponer los dados de calabaza en una bandeja y rociar con {{Aceite de oliva|chorrito}}.","minutes":1,"kind":"prep"},{"text":"Salpimentar los dados de calabaza y hornear a 200 °C hasta que estén tiernos y dorados.","minutes":25,"kind":"pasivo"},{"text":"Mezclar {{Miel}} y {{Vinagre balsámico}} con el resto del aceite de oliva en un bol hasta emulsionar.","minutes":2,"kind":"prep"},{"text":"Trocear {{Nueces}} en trozos gruesos.","minutes":1,"kind":"prep"},{"text":"Retirar la calabaza del horno y dejar templar.","minutes":5,"kind":"espera"},{"text":"Repartir {{Rúcula}} en los platos.","minutes":1,"kind":"emplatado"},{"text":"Disponer los dados de calabaza templada sobre la rúcula.","minutes":1,"kind":"emplatado"},{"text":"Desmenuzar {{Queso de cabra}} por encima de la calabaza.","minutes":1,"kind":"emplatado"},{"text":"Repartir las nueces troceadas sobre la ensalada.","minutes":1,"kind":"emplatado"},{"text":"Aliñar la ensalada con la vinagreta de miel y vinagre balsámico justo antes de servir.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'horno', NULL),
  ('ensaladas_verduras_067', 'Ensalada César con pollo crujiente', 'ensaladas_verduras', 'pollo', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'facil', 'all', 540, 38, 25, 32, 2, true, false, '{"gluten","huevo","lactosa","pescado","mostaza"}', '[{"name":"Lechuga romana","amount":200,"unit":"g"},{"name":"Pechuga de pollo","amount":260,"unit":"g"},{"name":"Harina","amount":30,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Pan rallado","amount":50,"unit":"g"},{"name":"Pan de molde para picatostes","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Queso parmesano","amount":40,"unit":"g"},{"name":"Mayonesa","amount":40,"unit":"g"},{"name":"Anchoas","amount":10,"unit":"g"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Limón","amount":15,"unit":"ml"},{"name":"Mostaza de Dijon","amount":5,"unit":"g"}]'::jsonb, '{"Cortar pechuga de pollo en tiras de tamaño uniforme y salpimentar.","Batir huevo en un bol hondo hasta que esté homogéneo.","Pasar cada tira de pollo por harina, luego por el huevo batido y después por pan rallado.","Calentar aceite de oliva en sartén a fuego fuerte hasta que esté bien caliente.","Freír las tiras de pollo empanadas 3 min por cada lado hasta que estén doradas.","Retirar el pollo y escurrir sobre papel absorbente. Reservar.","Cortar pan de molde para picatostes en dados pequeños y uniformes.","Calentar un chorrito de aceite de oliva en sartén a fuego medio.","Dorar los dados de pan de molde en la sartén, removiendo, hasta que estén crujientes y dorados.","Retirar los picatostes y reservar sobre papel absorbente.","Picar ajo fino y colocar en el vaso de la batidora junto con anchoas.","Rallar la mitad de queso parmesano e incorporar al vaso con mayonesa, limón y mostaza de dijon.","Triturar todos los ingredientes de la salsa hasta obtener una mezcla lisa y homogénea.","Lavar y trocear lechuga romana en trozos grandes y repartir en los platos.","Aliñar la lechuga con la salsa César y remover hasta que quede bien cubierta.","Repartir las tiras de pollo crujiente y los picatostes sobre la lechuga aliñada.","Rallar el resto del queso parmesano por encima y servir de inmediato."}', 'Ensalada César completa con pollo crujiente, picatostes y parmesano.', '[{"appliance":"airfryer","time":30,"difficulty":"facil","prepSummary":"Para el pollo crujiente y los picatostes, precalienta la airfryer a 190°C. Cocina el pollo empanado durante 15-18 minutos, dándole la vuelta a mitad, y los picatostes unos 5-7 minutos hasta que estén dorados y crujientes."},{"appliance":"horno","time":35,"difficulty":"facil","prepSummary":"Hornea el pollo empanado y los picatostes simultáneamente en bandejas separadas. Precalienta el horno a 200°C y cocina el pollo durante 20-25 minutos y los picatostes unos 10-15 minutos, hasta que ambos estén dorados y crujientes."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura","lacteo"}', NULL, ARRAY['pescado_azul']::main_protein[], false, '[{"text":"Cortar {{Pechuga de pollo}} en tiras de tamaño uniforme y salpimentar.","minutes":3,"kind":"prep","part":"principal"},{"text":"Batir {{Huevo}} en un bol hondo hasta que esté homogéneo.","minutes":1,"kind":"prep","part":"principal"},{"text":"Pasar cada tira de pollo por {{Harina}}, luego por el huevo batido y después por {{Pan rallado}}.","minutes":4,"kind":"prep","part":"principal"},{"text":"Calentar {{Aceite de oliva|abundante}} en {{@Sartén}} a fuego fuerte hasta que esté bien caliente.","minutes":2,"kind":"activo","part":"principal"},{"text":"Freír las tiras de pollo empanadas 3 min por cada lado hasta que estén doradas.","minutes":6,"kind":"activo","part":"principal"},{"text":"Retirar el pollo y escurrir sobre papel absorbente. Reservar.","minutes":2,"kind":"activo","part":"principal"},{"text":"Cortar {{Pan de molde para picatostes}} en dados pequeños y uniformes.","minutes":2,"kind":"prep","part":"guarnicion"},{"text":"Calentar un chorrito de aceite de oliva en {{@Sartén}} a fuego medio.","minutes":1,"kind":"activo","part":"guarnicion"},{"text":"Dorar los dados de pan de molde en la sartén, removiendo, hasta que estén crujientes y dorados.","minutes":4,"kind":"activo","part":"guarnicion"},{"text":"Retirar los picatostes y reservar sobre papel absorbente.","minutes":1,"kind":"activo","part":"guarnicion"},{"text":"Picar {{Ajo}} fino y colocar en el vaso de la batidora junto con {{Anchoas}}.","minutes":2,"kind":"prep","part":"salsa"},{"text":"Rallar la mitad de {{Queso parmesano}} e incorporar al vaso con {{Mayonesa}}, {{Limón}} y {{Mostaza de Dijon}}.","minutes":2,"kind":"prep","part":"salsa"},{"text":"Triturar todos los ingredientes de la salsa hasta obtener una mezcla lisa y homogénea.","minutes":1,"kind":"activo","part":"salsa"},{"text":"Lavar y trocear {{Lechuga romana}} en trozos grandes y repartir en los platos.","minutes":3,"kind":"prep","part":"combinado"},{"text":"Aliñar la lechuga con la salsa César y remover hasta que quede bien cubierta.","minutes":1,"kind":"activo","part":"combinado"},{"text":"Repartir las tiras de pollo crujiente y los picatostes sobre la lechuga aliñada.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Rallar el resto del queso parmesano por encima y servir de inmediato.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true, NULL, NULL, 'horno', NULL),
  ('ensaladas_verduras_068', 'Ensalada de zanahoria rallada, pasas y comino', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 213, 2, 31, 9, 2, true, true, '{"sulfitos"}', '[{"name":"Zanahoria","amount":300,"unit":"g"},{"name":"Pasas","amount":40,"unit":"g"},{"name":"Comino molido","amount":2,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Limón","amount":20,"unit":"ml"},{"name":"Perejil fresco","amount":10,"unit":"g"}]'::jsonb, '{"Pelar zanahoria y rallarla con un rallador grueso en tiras finas.","Sumergir pasas en un bol con agua templada hasta que se hidraten.","Picar perejil fresco fino.","Escurrir las pasas y reservar.","Mezclar la zanahoria rallada con las pasas escurridas en un bol grande.","Añadir comino molido y remover para distribuirlo.","Aliñar con aceite de oliva y limón.","Espolvorear el perejil picado y remover bien hasta integrar todos los ingredientes.","Tapar el bol y refrigerar hasta que los sabores se integren.","Servir la ensalada fría directamente del bol."}', 'Ensalada marroquí de zanahoria rallada con pasas, comino y limón.', '[{"appliance":"thermomix","time":15,"difficulty":"facil","prepSummary":"Ralla las zanahorias en el vaso a velocidad 5-7 durante unos segundos. Añade las pasas, comino, aceite, limón y perejil, y mezcla a velocidad 3-4 en sentido inverso durante 10-15 segundos para integrar todos los ingredientes sin triturar."}]'::jsonb, '{}', NULL, true, NULL, '{"verdura"}', NULL, '{}'::main_protein[], false, '[{"text":"Pelar {{Zanahoria}} y rallarla con un rallador grueso en tiras finas.","minutes":5,"kind":"prep"},{"text":"Sumergir {{Pasas}} en un bol con agua templada hasta que se hidraten.","minutes":10,"kind":"pasivo"},{"text":"Picar {{Perejil fresco}} fino.","minutes":2,"kind":"paralelo","during":1},{"text":"Escurrir las pasas y reservar.","minutes":1,"kind":"prep"},{"text":"Mezclar la zanahoria rallada con las pasas escurridas en un bol grande.","minutes":1,"kind":"activo"},{"text":"Añadir {{Comino molido|pizca}} y remover para distribuirlo.","minutes":1,"kind":"activo"},{"text":"Aliñar con {{Aceite de oliva|chorrito}} y {{Limón}}.","minutes":1,"kind":"activo"},{"text":"Espolvorear el perejil picado y remover bien hasta integrar todos los ingredientes.","minutes":1,"kind":"activo"},{"text":"Tapar el bol y refrigerar hasta que los sabores se integren.","minutes":10,"kind":"espera"},{"text":"Servir la ensalada fría directamente del bol.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'crudo', NULL),
  ('ensaladas_verduras_069', 'Ensalada de brotes tiernos con miel y mostaza', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'all', 172, 2, 11, 14, 2, true, false, '{"mostaza","sulfitos"}', '[{"name":"Brotes tiernos","amount":160,"unit":"g"},{"name":"Tomate cherry","amount":120,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Miel","amount":20,"unit":"g"},{"name":"Mostaza de Dijon","amount":15,"unit":"g"},{"name":"Vinagre de vino","amount":10,"unit":"ml"}]'::jsonb, '{"Lavar brotes tiernos bajo agua fría y escurrir bien.","Cortar tomate cherry por la mitad.","Mezclar aceite de oliva, miel, mostaza de dijon y vinagre de vino en un bol hasta emulsionar.","Repartir los brotes tiernos en los platos y distribuir los tomates cherry por encima.","Aliñar con la vinagreta justo antes de servir y remover con suavidad hasta que las hojas queden bien cubiertas."}', 'Ensalada de brotes tiernos con tomate cherry y aliño de miel y mostaza.', '[{"appliance":"thermomix","time":8,"difficulty":"facil","prepSummary":"La Thermomix es ideal para emulsionar la vinagreta de miel y mostaza en segundos, garantizando una mezcla homogénea y perfecta. Simplemente añade todos los ingredientes de la vinagreta y mezcla a velocidad media-alta."}]'::jsonb, '{}', NULL, true, NULL, '{"verdura"}', NULL, '{}'::main_protein[], false, '[{"text":"Lavar {{Brotes tiernos}} bajo agua fría y escurrir bien.","minutes":2,"kind":"prep"},{"text":"Cortar {{Tomate cherry}} por la mitad.","minutes":1,"kind":"prep"},{"text":"Mezclar {{Aceite de oliva|chorrito}}, {{Miel}}, {{Mostaza de Dijon}} y {{Vinagre de vino}} en un bol hasta emulsionar.","minutes":2,"kind":"activo"},{"text":"Repartir los brotes tiernos en los platos y distribuir los tomates cherry por encima.","minutes":1,"kind":"emplatado"},{"text":"Aliñar con la vinagreta justo antes de servir y remover con suavidad hasta que las hojas queden bien cubiertas.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'crudo', NULL),
  ('ensaladas_verduras_070', 'Ensalada de arroz salvaje con verduras', 'ensaladas_verduras', 'none', 'arroz', ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 45, 'facil', 'all', 346, 5, 50, 14, 2, true, true, '{"sulfitos"}', '[{"name":"Arroz salvaje","amount":120,"unit":"g"},{"name":"Pimiento rojo","amount":100,"unit":"g"},{"name":"Calabacín","amount":100,"unit":"g"},{"name":"Zanahoria","amount":100,"unit":"g"},{"name":"Cebolleta","amount":40,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Vinagre de vino","amount":10,"unit":"ml"},{"name":"Perejil fresco","amount":10,"unit":"g"}]'::jsonb, '{"Llevar a ebullición una olla con abundante agua y una pizca de sal a fuego fuerte.","Añadir arroz salvaje cuando el agua hierva y cocer a fuego medio durante 35-40 min, hasta que esté tierno.","Cortar pimiento rojo en dados pequeños.","Cortar calabacín en dados pequeños.","Cortar zanahoria en dados pequeños.","Picar cebolleta finamente.","Picar perejil fresco finamente.","Escurrir el arroz cuando esté tierno y extenderlo en un bol para que temple.","Calentar aceite de oliva en sartén a fuego fuerte.","Saltear el pimiento rojo, el calabacín y la zanahoria en la sartén 5-6 min, hasta que estén tiernos con un punto crujiente.","Retirar las verduras del fuego y dejar templar 5 min.","Mezclar el arroz templado con las verduras salteadas y la cebolleta picada en el bol.","Aliñar con el resto del aceite de oliva y vinagre de vino y remover bien para integrar.","Espolvorear el perejil picado por encima y servir templado o frío."}', 'Ensalada de arroz salvaje con verduras salteadas, fresca y con textura.', '[{"appliance":"thermomix","time":50,"difficulty":"facil","prepSummary":"Cocina el arroz salvaje en el cestillo mientras las verduras troceadas se cocinan al vapor en el Varoma. Luego, mezcla todo con el aderezo en el vaso."},{"appliance":"vaporera","time":55,"difficulty":"facil","prepSummary":"Cocina el arroz salvaje en la base o en un cuenco adecuado, y las verduras troceadas en la bandeja superior al vapor hasta que estén tiernas. Combina y adereza."},{"appliance":"olla_express","time":35,"difficulty":"facil","prepSummary":"Cocina el arroz salvaje a presión para reducir el tiempo. Luego, cocina las verduras troceadas muy brevemente al vapor dentro de la misma olla o en una cesta para mantener su textura y color."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], false, '[{"text":"Llevar a ebullición una olla con abundante agua y una pizca de sal a fuego fuerte.","minutes":5,"kind":"activo"},{"text":"Añadir {{Arroz salvaje}} cuando el agua hierva y cocer a fuego medio durante 35-40 min, hasta que esté tierno.","minutes":38,"kind":"pasivo"},{"text":"Cortar {{Pimiento rojo}} en dados pequeños.","minutes":3,"kind":"paralelo","during":1},{"text":"Cortar {{Calabacín}} en dados pequeños.","minutes":2,"kind":"paralelo","during":1},{"text":"Cortar {{Zanahoria}} en dados pequeños.","minutes":2,"kind":"paralelo","during":1},{"text":"Picar {{Cebolleta}} finamente.","minutes":2,"kind":"paralelo","during":1},{"text":"Picar {{Perejil fresco}} finamente.","minutes":1,"kind":"paralelo","during":1},{"text":"Escurrir el arroz cuando esté tierno y extenderlo en un bol para que temple.","minutes":2,"kind":"activo"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego fuerte.","minutes":1,"kind":"activo"},{"text":"Saltear el pimiento rojo, el calabacín y la zanahoria en la sartén 5-6 min, hasta que estén tiernos con un punto crujiente.","minutes":6,"kind":"activo"},{"text":"Retirar las verduras del fuego y dejar templar 5 min.","minutes":5,"kind":"espera"},{"text":"Mezclar el arroz templado con las verduras salteadas y la cebolleta picada en el bol.","minutes":2,"kind":"activo"},{"text":"Aliñar con el resto del aceite de oliva y {{Vinagre de vino|chorrito}} y remover bien para integrar.","minutes":1,"kind":"activo"},{"text":"Espolvorear el perejil picado por encima y servir templado o frío.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'olla', NULL),
  ('ensaladas_verduras_071', 'Ensalada de judías verdes, tomate y huevo', 'ensaladas_verduras', 'huevo', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 227, 9, 14, 15, 2, true, true, '{"huevo","sulfitos"}', '[{"name":"Judías verdes","amount":300,"unit":"g"},{"name":"Tomate","amount":200,"unit":"g"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Cebolla","amount":40,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Vinagre de vino","amount":10,"unit":"ml"}]'::jsonb, '{"Limpiar judías verdes, retirar las puntas y cortar en mitades si son muy largas.","Llevar a ebullición una olla con agua y sal a fuego fuerte.","Cocer las judías verdes 9 min hasta que estén tiernas pero firmes.","Cocer huevo en otro cazo con agua a ebullición durante 10 min.","Cortar tomate en gajos.","Laminar cebolla en juliana fina.","Escurrir las judías verdes y enfriar de inmediato en un bol con agua fría para conservar el color.","Escurrir los huevos, enfriar bajo el grifo, pelar y cortar en cuartos.","Colocar las judías verdes escurridas, el tomate y la cebolla en una fuente.","Repartir los cuartos de huevo por encima.","Aliñar con aceite de oliva, vinagre de vino y servir templado o frío."}', 'Ensalada de judías verdes, tomate y huevo cocido, sencilla y equilibrada.', '[{"appliance":"airfryer","time":20,"difficulty":"facil","prepSummary":"Cocina las judías verdes a 190°C durante 12-15 minutos hasta que estén tiernas y ligeramente doradas. Hierve los huevos en la airfryer a 130°C durante 13-15 minutos para que queden duros."},{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Asa las judías verdes con un poco de aceite a 190°C durante 15-20 minutos. Hornea los huevos en un molde apto para horno a 180°C durante 15-18 minutos hasta que estén cocidos."},{"appliance":"thermomix","time":20,"difficulty":"facil","prepSummary":"Cuece las judías verdes y los huevos en el recipiente Varoma durante 15-20 minutos a temperatura Varoma, velocidad 1, con 500ml de agua en el vaso. Los huevos quedarán perfectos y las judías al dente."},{"appliance":"vaporera","time":20,"difficulty":"facil","prepSummary":"Cocina al vapor las judías verdes durante 15-20 minutos hasta que estén tiernas. Añade los huevos a la vaporera y cuécelos durante 12-15 minutos para obtener huevos duros perfectos."},{"appliance":"olla_express","time":15,"difficulty":"facil","prepSummary":"Cuece las judías verdes en la olla express con un poco de agua durante 3-4 minutos desde que sube la válvula. Los huevos se pueden cocer en el mismo tiempo o por separado durante 5-6 minutos a presión."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], false, '[{"text":"Limpiar {{Judías verdes}}, retirar las puntas y cortar en mitades si son muy largas.","minutes":3,"kind":"prep"},{"text":"Llevar a ebullición una olla con agua y sal a fuego fuerte.","minutes":4,"kind":"activo"},{"text":"Cocer las judías verdes 9 min hasta que estén tiernas pero firmes.","minutes":9,"kind":"pasivo"},{"text":"Cocer {{Huevo}} en otro cazo con agua a ebullición durante 10 min.","minutes":10,"kind":"pasivo"},{"text":"Cortar {{Tomate}} en gajos.","minutes":2,"kind":"paralelo","during":2},{"text":"Laminar {{Cebolla}} en juliana fina.","minutes":2,"kind":"paralelo","during":2},{"text":"Escurrir las judías verdes y enfriar de inmediato en un bol con agua fría para conservar el color.","minutes":2,"kind":"activo"},{"text":"Escurrir los huevos, enfriar bajo el grifo, pelar y cortar en cuartos.","minutes":3,"kind":"prep"},{"text":"Colocar las judías verdes escurridas, el tomate y la cebolla en una fuente.","minutes":1,"kind":"emplatado"},{"text":"Repartir los cuartos de huevo por encima.","minutes":1,"kind":"emplatado"},{"text":"Aliñar con {{Aceite de oliva|chorrito}}, {{Vinagre de vino|chorrito}} y servir templado o frío.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'olla', NULL),
  ('ensaladas_verduras_072', 'Ensalada de patata, huevo y atún', 'ensaladas_verduras', 'pescado_azul', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 30, 'facil', 'all', 440, 30, 35, 20, 2, true, true, '{"huevo","pescado","sulfitos"}', '[{"name":"Patata","amount":400,"unit":"g"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Atún en conserva","amount":160,"unit":"g"},{"name":"Cebolla","amount":40,"unit":"g"},{"name":"Aceitunas","amount":40,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Vinagre de vino","amount":10,"unit":"ml"}]'::jsonb, '{"Lavar patata y colocarlas enteras con piel en un cazo. Cubrir con agua fría y llevar a ebullición a fuego fuerte.","Cocer las patatas a fuego medio hasta que estén tiernas al pincharlas con un cuchillo, aproximadamente 22 min.","Cocer huevo en un cazo aparte con agua hirviendo a fuego medio durante 10 min.","Escurrir los huevos y sumergirlos en agua fría hasta que estén fríos.","Escurrir las patatas y dejarlas templar hasta que se puedan manipular sin quemarse.","Pelar y cortar las patatas en rodajas gruesas de unos 1,5 cm.","Pelar los huevos y cortarlos en cuartos.","Picar cebolla muy fina.","Escurrir atún en conserva y desmigar con un tenedor.","Disponer las rodajas de patata en una fuente formando una capa uniforme.","Repartir la cebolla picada sobre las patatas.","Distribuir el atún desmigado sobre las patatas y la cebolla.","Colocar los cuartos de huevo y aceitunas sobre la ensalada.","Aliñar con aceite de oliva y vinagre de vino por encima.","Dejar reposar la ensalada 5 min antes de servir para que los sabores se integren."}', 'Ensalada de patata, huevo y atún, variante clásica de la ensalada campera.', '[{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Cocina las patatas troceadas y los huevos en el cestillo o Varoma simultáneamente durante unos 25-30 minutos a temperatura Varoma, velocidad 1. Luego pica la cebolla y mezcla todos los ingredientes."},{"appliance":"vaporera","time":25,"difficulty":"facil","prepSummary":"Cuece las patatas troceadas y los huevos en la vaporera durante 25-30 minutos hasta que estén tiernas y duros, respectivamente. Luego enfría, pica la cebolla y mezcla el resto de ingredientes."},{"appliance":"olla_express","time":15,"difficulty":"facil","prepSummary":"Cocina las patatas troceadas y los huevos en la olla a presión con un poco de agua durante 5-7 minutos desde que sube la válvula. Despresuriza, enfría y mezcla con el resto de ingredientes."}]'::jsonb, '{}', NULL, NULL, NULL, '{"encurtido"}', NULL, '{}'::main_protein[], false, '[{"text":"Lavar {{Patata}} y colocarlas enteras con piel en un cazo. Cubrir con agua fría y llevar a ebullición a fuego fuerte.","minutes":3,"kind":"activo"},{"text":"Cocer las patatas a fuego medio hasta que estén tiernas al pincharlas con un cuchillo, aproximadamente 22 min.","minutes":22,"kind":"pasivo"},{"text":"Cocer {{Huevo}} en un cazo aparte con agua hirviendo a fuego medio durante 10 min.","minutes":10,"kind":"paralelo","during":1},{"text":"Escurrir los huevos y sumergirlos en agua fría hasta que estén fríos.","minutes":3,"kind":"espera"},{"text":"Escurrir las patatas y dejarlas templar hasta que se puedan manipular sin quemarse.","minutes":5,"kind":"espera"},{"text":"Pelar y cortar las patatas en rodajas gruesas de unos 1,5 cm.","minutes":3,"kind":"prep"},{"text":"Pelar los huevos y cortarlos en cuartos.","minutes":2,"kind":"prep"},{"text":"Picar {{Cebolla}} muy fina.","minutes":2,"kind":"prep"},{"text":"Escurrir {{Atún en conserva}} y desmigar con un tenedor.","minutes":1,"kind":"prep"},{"text":"Disponer las rodajas de patata en una fuente formando una capa uniforme.","minutes":1,"kind":"emplatado"},{"text":"Repartir la cebolla picada sobre las patatas.","minutes":1,"kind":"emplatado"},{"text":"Distribuir el atún desmigado sobre las patatas y la cebolla.","minutes":1,"kind":"emplatado"},{"text":"Colocar los cuartos de huevo y {{Aceitunas}} sobre la ensalada.","minutes":1,"kind":"emplatado"},{"text":"Aliñar con {{Aceite de oliva|chorrito}} y {{Vinagre de vino|chorrito}} por encima.","minutes":1,"kind":"emplatado"},{"text":"Dejar reposar la ensalada 5 min antes de servir para que los sabores se integren.","minutes":5,"kind":"espera"}]'::jsonb, true, NULL, NULL, 'sarten', NULL),
  ('ensaladas_verduras_073', 'Ensalada de pepino, yogur y menta', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'verano', 210, 10, 11, 14, 2, true, true, '{"lactosa"}', '[{"name":"Pepino","amount":400,"unit":"g"},{"name":"Yogur griego natural","amount":200,"unit":"g"},{"name":"Menta fresca","amount":10,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"}]'::jsonb, '{"Pelar pepino y cortarlo por la mitad a lo largo.","Retirar las semillas del pepino con una cuchara y rallarlo en trozos gruesos.","Colocar el pepino rallado en un colador, añadir sal y dejar reposar 10 min para que suelte el agua.","Picar ajo muy fino.","Picar menta fresca fina.","Escurrir el pepino con las manos para eliminar el máximo de agua posible.","Mezclar yogur griego natural con el pepino escurrido, el ajo picado y la menta picada en un bol.","Añadir aceite de oliva y remover hasta integrar.","Tapar el bol y refrigerar al menos 20 min hasta que esté bien fría.","Servir la ensalada fría directamente del bol."}', 'Ensalada fría de pepino con yogur y menta, ideal para el calor.', '[{"appliance":"thermomix","time":10,"difficulty":"facil","prepSummary":"La Thermomix es perfecta para picar finamente el ajo y la menta. Luego, trocea el pepino y mezcla todos los ingredientes con el yogur y el aceite a velocidad baja hasta obtener una ensalada homogénea y lista para servir."}]'::jsonb, '{}', NULL, true, NULL, '{"verdura","lacteo"}', NULL, '{}'::main_protein[], false, '[{"text":"Pelar {{Pepino}} y cortarlo por la mitad a lo largo.","minutes":2,"kind":"prep"},{"text":"Retirar las semillas del pepino con una cuchara y rallarlo en trozos gruesos.","minutes":2,"kind":"prep"},{"text":"Colocar el pepino rallado en un colador, añadir {{Sal|gusto}} y dejar reposar 10 min para que suelte el agua.","minutes":10,"kind":"espera"},{"text":"Picar {{Ajo}} muy fino.","minutes":1,"kind":"paralelo","during":2},{"text":"Picar {{Menta fresca}} fina.","minutes":1,"kind":"paralelo","during":2},{"text":"Escurrir el pepino con las manos para eliminar el máximo de agua posible.","minutes":1,"kind":"activo"},{"text":"Mezclar {{Yogur griego natural}} con el pepino escurrido, el ajo picado y la menta picada en un bol.","minutes":2,"kind":"activo"},{"text":"Añadir {{Aceite de oliva|chorrito}} y remover hasta integrar.","minutes":1,"kind":"activo"},{"text":"Tapar el bol y refrigerar al menos 20 min hasta que esté bien fría.","minutes":20,"kind":"espera"},{"text":"Servir la ensalada fría directamente del bol.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'crudo', NULL),
  ('ensaladas_verduras_074', 'Ensalada de naranja, hinojo y aceitunas negras', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'invierno', 232, 2, 25, 14, 2, true, true, '{"sulfitos"}', '[{"name":"Naranja","amount":300,"unit":"g"},{"name":"Hinojo","amount":200,"unit":"g"},{"name":"Aceitunas negras","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"}]'::jsonb, '{"Pelar naranja retirando también la piel blanca.","Cortar la naranja pelada en rodajas finas.","Limpiar hinojo y retirar la parte más dura de la base.","Laminar el hinojo en láminas muy finas, preferiblemente con mandolina.","Disponer las rodajas de naranja y las láminas de hinojo alternadas en una fuente.","Repartir aceitunas negras por encima de la naranja y el hinojo.","Aliñar con aceite de oliva y sal.","Dejar reposar en la nevera hasta que los sabores se mezclen.","Servir la ensalada fría directamente de la nevera."}', 'Ensalada de naranja, hinojo y aceitunas negras, fresca y de inspiración mediterránea.', '[{"appliance":"airfryer","time":20,"difficulty":"facil","prepSummary":"Para una versión templada y con un toque dulce, corta el hinojo en láminas finas, rocíalas con aceite de oliva y cocínalas en la airfryer a 180°C durante 12-15 minutos, hasta que estén tiernas y ligeramente doradas. Luego, mezcla con la naranja fresca y las aceitunas para un cont"},{"appliance":"horno","time":30,"difficulty":"facil","prepSummary":"Para realzar el sabor del hinojo y darle una textura más suave y caramelizada, ásalo cortado en láminas finas con un chorrito de aceite de oliva en el horno precalentado a 200°C durante 20-25 minutos. Combina el hinojo asado tibio con la naranja y las aceitunas para una ensalada "}]'::jsonb, '{}', NULL, true, NULL, '{"fruta","encurtido"}', NULL, '{}'::main_protein[], false, '[{"text":"Pelar {{Naranja}} retirando también la piel blanca.","minutes":2,"kind":"prep"},{"text":"Cortar la naranja pelada en rodajas finas.","minutes":2,"kind":"prep"},{"text":"Limpiar {{Hinojo}} y retirar la parte más dura de la base.","minutes":1,"kind":"prep"},{"text":"Laminar el hinojo en láminas muy finas, preferiblemente con mandolina.","minutes":2,"kind":"prep"},{"text":"Disponer las rodajas de naranja y las láminas de hinojo alternadas en una fuente.","minutes":1,"kind":"activo"},{"text":"Repartir {{Aceitunas negras}} por encima de la naranja y el hinojo.","minutes":1,"kind":"activo"},{"text":"Aliñar con {{Aceite de oliva|chorrito}} y {{Sal|gusto}}.","minutes":1,"kind":"activo"},{"text":"Dejar reposar en la nevera hasta que los sabores se mezclen.","minutes":10,"kind":"espera"},{"text":"Servir la ensalada fría directamente de la nevera.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'crudo', NULL)
