insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id, extra_proteins, freezable, steps_rich, estrella, occasion, kid_favourite, tecnica, cocina
) values
  ('ensaladas_verduras_075', 'Ensalada de alcachofas confitadas y jamón', 'ensaladas_verduras', 'cerdo', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 35, 'normal', 'invierno', 271, 16, 9, 19, 2, true, false, '{"sulfitos"}', '[{"name":"Corazones de alcachofa","amount":300,"unit":"g"},{"name":"Jamón serrano en virutas","amount":80,"unit":"g"},{"name":"Aceite de oliva","amount":120,"unit":"ml"},{"name":"Ajo","amount":20,"unit":"g"},{"name":"Tomillo fresco","amount":5,"unit":"g"},{"name":"Limón","amount":15,"unit":"ml"}]'::jsonb, '{"Laminar ajo.","Escurrir corazones de alcachofa y secarlos con papel de cocina.","Colocar los corazones de alcachofa en un cazo pequeño junto con aceite de oliva, el ajo laminado y tomillo fresco.","Confitar a fuego suave hasta que los corazones de alcachofa estén muy tiernos y el aceite no llegue a hervir.","Escurrir los corazones de alcachofa del aceite y reservar un chorrito del aceite de confitar.","Dejar templar los corazones de alcachofa escurridos.","Repartir los corazones de alcachofa en una fuente.","Distribuir jamón serrano en virutas por encima de las alcachofas.","Rociar con el aceite de confitar reservado y limón."}', 'Ensalada de alcachofas confitadas con virutas de jamón serrano.', '[{"appliance":"horno","time":40,"difficulty":"normal","prepSummary":"Coloca los corazones de alcachofa, ajo y tomillo en una fuente apta para horno, cúbrelos con el aceite de oliva. Hornea a 160°C durante 40 minutos hasta que estén tiernos y confitados."},{"appliance":"thermomix","time":35,"difficulty":"normal","prepSummary":"Introduce los corazones de alcachofa, ajo, tomillo y aceite en el vaso. Cocina a 90°C, velocidad cuchara, giro inverso, durante 35 minutos para confitar las alcachofas suavemente."}]'::jsonb, '{}', true, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], false, '[{"text":"Laminar {{Ajo}}.","minutes":2,"kind":"prep"},{"text":"Escurrir {{Corazones de alcachofa}} y secarlos con papel de cocina.","minutes":2,"kind":"prep"},{"text":"Colocar los corazones de alcachofa en un cazo pequeño junto con {{Aceite de oliva}}, el ajo laminado y {{Tomillo fresco}}.","minutes":2,"kind":"activo"},{"text":"Confitar a fuego suave hasta que los corazones de alcachofa estén muy tiernos y el aceite no llegue a hervir.","minutes":25,"kind":"pasivo"},{"text":"Escurrir los corazones de alcachofa del aceite y reservar un chorrito del aceite de confitar.","minutes":2,"kind":"activo"},{"text":"Dejar templar los corazones de alcachofa escurridos.","minutes":5,"kind":"espera"},{"text":"Repartir los corazones de alcachofa en una fuente.","minutes":1,"kind":"emplatado"},{"text":"Distribuir {{Jamón serrano en virutas}} por encima de las alcachofas.","minutes":1,"kind":"emplatado"},{"text":"Rociar con el aceite de confitar reservado y {{Limón|chorrito}}.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL),
  ('ensaladas_verduras_076', 'Ensalada de aguacate, tomate y maíz con lima', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 344, 5, 27, 24, 2, true, true, '{}', '[{"name":"Aguacate","amount":200,"unit":"g"},{"name":"Tomate","amount":200,"unit":"g"},{"name":"Maíz dulce cocido","amount":160,"unit":"g"},{"name":"Cebolla roja","amount":40,"unit":"g"},{"name":"Cilantro fresco","amount":10,"unit":"g"},{"name":"Lima","amount":30,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"}]'::jsonb, '{"Cortar aguacate por la mitad, retirar el hueso y cortarlo en dados de tamaño uniforme.","Cortar tomate en dados del mismo tamaño que el aguacate.","Escurrir maíz dulce cocido y reservar.","Picar cebolla roja muy fina.","Picar cilantro fresco fino.","Mezclar en un bol el aguacate, el tomate, el maíz, la cebolla roja y el cilantro picado.","Aliñar con lima, aceite de oliva y sal.","Remover con cuidado hasta que el aliño cubra todos los ingredientes sin deshacer el aguacate.","Servir enseguida para que el aguacate no se oxide."}', 'Ensalada fresca de aguacate, tomate y maíz con un toque de lima.', '[]'::jsonb, '{}', NULL, true, NULL, '{"verdura"}', NULL, '{}'::main_protein[], false, '[{"text":"Cortar {{Aguacate}} por la mitad, retirar el hueso y cortarlo en dados de tamaño uniforme.","minutes":3,"kind":"prep"},{"text":"Cortar {{Tomate}} en dados del mismo tamaño que el aguacate.","minutes":2,"kind":"prep"},{"text":"Escurrir {{Maíz dulce cocido}} y reservar.","minutes":1,"kind":"prep"},{"text":"Picar {{Cebolla roja}} muy fina.","minutes":2,"kind":"prep"},{"text":"Picar {{Cilantro fresco}} fino.","minutes":1,"kind":"prep"},{"text":"Mezclar en un bol el aguacate, el tomate, el maíz, la cebolla roja y el cilantro picado.","minutes":1,"kind":"activo"},{"text":"Aliñar con {{Lima}}, {{Aceite de oliva|chorrito}} y {{Sal|gusto}}.","minutes":1,"kind":"activo"},{"text":"Remover con cuidado hasta que el aliño cubra todos los ingredientes sin deshacer el aguacate.","minutes":1,"kind":"activo"},{"text":"Servir enseguida para que el aguacate no se oxide.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'crudo', NULL),
  ('ensaladas_verduras_077', 'Ensalada de col kale con manzana y nueces', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 330, 8, 19, 25, 2, true, true, '{"lactosa","frutos_secos"}', '[{"name":"Col kale","amount":150,"unit":"g"},{"name":"Manzana","amount":150,"unit":"g"},{"name":"Nueces","amount":30,"unit":"g"},{"name":"Queso parmesano","amount":20,"unit":"g"},{"name":"Zumo de limón","amount":20,"unit":"ml"},{"name":"Aceite de oliva virgen extra","amount":25,"unit":"ml"},{"name":"Miel","amount":10,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Lavar col kale, retirar el tallo central duro y cortar en tiras finas.","Masajear el kale con sal y un chorrito de aceite de oliva virgen extra durante 1-2 min hasta que se ablande y oscurezca ligeramente.","Lavar manzana, descorazonar y laminar en láminas finas.","Rociar la manzana laminada con zumo de limón para evitar la oxidación.","Calentar sartén a fuego medio sin aceite y tostar nueces 2-3 min, removiendo, hasta que estén doradas y aromáticas.","Retirar las nueces de la sartén y dejar enfriar sobre una superficie plana.","Mezclar en un bol el aceite de oliva virgen extra restante, el zumo de limón restante y miel hasta obtener el aliño.","Rallar queso parmesano en virutas finas con un pelador o rallador.","Disponer el kale masajeado en un bol grande y añadir la manzana laminada.","Verter el aliño sobre la ensalada y remover con cuidado hasta cubrir bien.","Repartir las nueces tostadas y el queso parmesano en virutas por encima y servir."}', 'Ensalada de col kale masajeada con manzana crujiente, nueces tostadas y virutas de parmesano.', '[{"appliance":"thermomix","time":12,"difficulty":"facil","prepSummary":"La Thermomix es perfecta para esta ensalada, ya que pica el kale, la manzana y las nueces de forma rápida y homogénea. Además, emulsiona el aliño a la perfección, garantizando una mezcla uniforme de todos los ingredientes."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura","fruta","frutos_secos"}', NULL, '{}'::main_protein[], false, '[{"text":"Lavar {{Col kale}}, retirar el tallo central duro y cortar en tiras finas.","minutes":3,"kind":"prep"},{"text":"Masajear el kale con {{Sal|gusto}} y un chorrito de {{Aceite de oliva virgen extra|chorrito}} durante 1-2 min hasta que se ablande y oscurezca ligeramente.","minutes":2,"kind":"activo"},{"text":"Lavar {{Manzana}}, descorazonar y laminar en láminas finas.","minutes":2,"kind":"prep"},{"text":"Rociar la manzana laminada con {{Zumo de limón}} para evitar la oxidación.","minutes":1,"kind":"prep"},{"text":"Calentar {{@Sartén}} a fuego medio sin aceite y tostar {{Nueces}} 2-3 min, removiendo, hasta que estén doradas y aromáticas.","minutes":3,"kind":"activo"},{"text":"Retirar las nueces de la sartén y dejar enfriar sobre una superficie plana.","minutes":2,"kind":"espera"},{"text":"Mezclar en un bol el aceite de oliva virgen extra restante, el zumo de limón restante y {{Miel}} hasta obtener el aliño.","minutes":1,"kind":"prep"},{"text":"Rallar {{Queso parmesano}} en virutas finas con un pelador o rallador.","minutes":1,"kind":"prep"},{"text":"Disponer el kale masajeado en un bol grande y añadir la manzana laminada.","minutes":1,"kind":"emplatado"},{"text":"Verter el aliño sobre la ensalada y remover con cuidado hasta cubrir bien.","minutes":1,"kind":"emplatado"},{"text":"Repartir las nueces tostadas y el queso parmesano en virutas por encima y servir.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL),
  ('ensaladas_verduras_078', 'Ensalada de espárragos blancos y salmón ahumado', 'ensaladas_verduras', 'pescado_azul', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 210, 15, 7, 14, 2, true, false, '{"pescado","mostaza"}', '[{"name":"Espárragos blancos en conserva","amount":300,"unit":"g"},{"name":"Salmón ahumado","amount":100,"unit":"g"},{"name":"Rúcula","amount":40,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":20,"unit":"ml"},{"name":"Zumo de limón","amount":15,"unit":"ml"},{"name":"Mostaza de Dijon","amount":5,"unit":"g"},{"name":"Eneldo fresco","amount":5,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Escurrir espárragos blancos en conserva y secarlos con papel de cocina.","Lavar rúcula y secarla con papel de cocina.","Mezclar aceite de oliva virgen extra, zumo de limón, mostaza de dijon y sal en un bol pequeño hasta emulsionar.","Cortar salmón ahumado en lonchas del tamaño de un bocado.","Picar eneldo fresco finamente.","Repartir la rúcula como base en 2 platos.","Colocar los espárragos sobre la rúcula, distribuyéndolos de forma uniforme entre los 2 platos.","Disponer el salmón entre los espárragos en cada plato.","Rociar cada plato con el aliño justo antes de servir.","Espolvorear el eneldo picado sobre cada plato y servir de inmediato."}', 'Espárragos blancos tiernos con salmón ahumado, rúcula y un aliño ligero de mostaza y eneldo.', '[]'::jsonb, '{}', true, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], false, '[{"text":"Escurrir {{Espárragos blancos en conserva}} y secarlos con papel de cocina.","minutes":2,"kind":"prep"},{"text":"Lavar {{Rúcula}} y secarla con papel de cocina.","minutes":1,"kind":"prep"},{"text":"Mezclar {{Aceite de oliva virgen extra}}, {{Zumo de limón}}, {{Mostaza de Dijon}} y {{Sal|gusto}} en un bol pequeño hasta emulsionar.","minutes":2,"kind":"prep"},{"text":"Cortar {{Salmón ahumado}} en lonchas del tamaño de un bocado.","minutes":1,"kind":"prep"},{"text":"Picar {{Eneldo fresco}} finamente.","minutes":1,"kind":"prep"},{"text":"Repartir la rúcula como base en 2 platos.","minutes":1,"kind":"emplatado"},{"text":"Colocar los espárragos sobre la rúcula, distribuyéndolos de forma uniforme entre los 2 platos.","minutes":1,"kind":"emplatado"},{"text":"Disponer el salmón entre los espárragos en cada plato.","minutes":1,"kind":"emplatado"},{"text":"Rociar cada plato con el aliño justo antes de servir.","minutes":1,"kind":"emplatado"},{"text":"Espolvorear el eneldo picado sobre cada plato y servir de inmediato.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL),
  ('ensaladas_verduras_079', 'Ensalada tibia de coliflor asada y tahini', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'horno', 40, 'facil', 'all', 290, 9, 17, 21, 2, true, true, '{"sesamo"}', '[{"name":"Coliflor","amount":500,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Comino molido","amount":3,"unit":"g"},{"name":"Pimentón dulce","amount":3,"unit":"g"},{"name":"Tahini","amount":40,"unit":"g"},{"name":"Zumo de limón","amount":20,"unit":"ml"},{"name":"Agua","amount":20,"unit":"ml"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Perejil fresco","amount":5,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C.","Cortar coliflor en ramilletes de tamaño similar para que se asen de manera uniforme.","Picar ajo muy fino.","Picar perejil fresco fino y reservar.","Disponer los ramilletes en una bandeja de horno en una sola capa.","Mezclar los ramilletes con aceite de oliva, comino molido, pimentón dulce y sal hasta cubrirlos bien.","Hornear 25 min hasta que los bordes estén dorados y la coliflor tierna, removiendo a mitad de cocción.","Mezclar tahini, zumo de limón, el ajo picado y agua hasta obtener una salsa cremosa y homogénea.","Retirar la coliflor del horno y disponer en una fuente.","Rociar la salsa de tahini sobre la coliflor asada.","Terminar con el perejil fresco picado y servir templada."}', 'Arbolitos de coliflor asados hasta dorarse, bañados en una salsa cremosa de tahini y limón.', '[{"appliance":"horno","time":40,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C. Mezcla la coliflor con aceite, comino y pimentón, y ásala en una bandeja durante 30-35 minutos, removiendo a mitad para un dorado uniforme y tierno."},{"appliance":"airfryer","time":25,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190°C. Cubre la coliflor con aceite y especias, y cocina en la cesta durante 18-22 minutos, agitando a mitad para lograr un asado crujiente y bien dorado."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], false, '[{"text":"Precalentar el horno a 200 °C.","minutes":10,"kind":"pasivo"},{"text":"Cortar {{Coliflor}} en ramilletes de tamaño similar para que se asen de manera uniforme.","minutes":5,"kind":"prep","part":"principal"},{"text":"Picar {{Ajo}} muy fino.","minutes":2,"kind":"prep","part":"salsa"},{"text":"Picar {{Perejil fresco}} fino y reservar.","minutes":1,"kind":"prep","part":"salsa"},{"text":"Disponer los ramilletes en una bandeja de horno en una sola capa.","minutes":1,"kind":"prep","part":"principal"},{"text":"Mezclar los ramilletes con {{Aceite de oliva}}, {{Comino molido}}, {{Pimentón dulce}} y {{Sal|gusto}} hasta cubrirlos bien.","minutes":2,"kind":"activo","part":"principal"},{"text":"Hornear 25 min hasta que los bordes estén dorados y la coliflor tierna, removiendo a mitad de cocción.","minutes":25,"kind":"pasivo","part":"principal"},{"text":"Mezclar {{Tahini}}, {{Zumo de limón}}, el ajo picado y {{Agua}} hasta obtener una salsa cremosa y homogénea.","minutes":3,"kind":"paralelo","part":"salsa","during":6},{"text":"Retirar la coliflor del horno y disponer en una fuente.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Rociar la salsa de tahini sobre la coliflor asada.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Terminar con el perejil fresco picado y servir templada.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true, NULL, NULL, 'horno', 'mediterranea'),
  ('ensaladas_verduras_080', 'Ensalada de garbanzos, atún y pimientos', 'ensaladas_verduras', 'legumbre', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 520, 35, 47, 22, 2, true, true, '{"pescado","sulfitos"}', '[{"name":"Garbanzos cocidos","amount":300,"unit":"g"},{"name":"Atún en conserva","amount":160,"unit":"g"},{"name":"Pimiento rojo","amount":80,"unit":"g"},{"name":"Pimiento verde","amount":60,"unit":"g"},{"name":"Cebolla morada","amount":40,"unit":"g"},{"name":"Tomate","amount":100,"unit":"g"},{"name":"Aceitunas negras","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Vinagre de jerez","amount":10,"unit":"ml"},{"name":"Perejil fresco","amount":5,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Escurrir garbanzos cocidos y reservar en un bol grande.","Escurrir atún en conserva y desmigar con un tenedor hasta obtener lascas sueltas.","Cortar pimiento rojo y pimiento verde en dados pequeños.","Picar cebolla morada muy fina.","Cortar tomate en dados medianos.","Picar perejil fresco fino y reservar.","Añadir el atún desmigado, los pimientos, la cebolla morada, el tomate y aceitunas negras al bol con los garbanzos.","Aliñar con aceite de oliva, vinagre de jerez y sal.","Remover con cuidado hasta que el aliño se distribuya sin romper los garbanzos.","Tapar el bol y reposar en la nevera hasta que los sabores se integren.","Espolvorear el perejil picado por encima y servir frío."}', 'Ensalada contundente de garbanzos con atún, pimientos y aceitunas, perfecta para llevar de tupper.', '[{"appliance":"thermomix","time":15,"difficulty":"facil","prepSummary":"Utiliza el Thermomix para picar finamente los pimientos, cebolla y tomate en segundos. Luego, mezcla todos los ingredientes en el vaso o en un bol aparte y emulsiona el aliño con aceite, vinagre y sal para añadirlo al final."}]'::jsonb, '{}', NULL, true, NULL, '{"verdura","encurtido"}', NULL, ARRAY['pescado_azul']::main_protein[], false, '[{"text":"Escurrir {{Garbanzos cocidos}} y reservar en un bol grande.","minutes":1,"kind":"prep"},{"text":"Escurrir {{Atún en conserva}} y desmigar con un tenedor hasta obtener lascas sueltas.","minutes":2,"kind":"prep"},{"text":"Cortar {{Pimiento rojo}} y {{Pimiento verde}} en dados pequeños.","minutes":3,"kind":"prep"},{"text":"Picar {{Cebolla morada}} muy fina.","minutes":2,"kind":"prep"},{"text":"Cortar {{Tomate}} en dados medianos.","minutes":1,"kind":"prep"},{"text":"Picar {{Perejil fresco}} fino y reservar.","minutes":1,"kind":"prep"},{"text":"Añadir el atún desmigado, los pimientos, la cebolla morada, el tomate y {{Aceitunas negras}} al bol con los garbanzos.","minutes":2,"kind":"activo"},{"text":"Aliñar con {{Aceite de oliva}}, {{Vinagre de jerez}} y {{Sal|gusto}}.","minutes":1,"kind":"activo"},{"text":"Remover con cuidado hasta que el aliño se distribuya sin romper los garbanzos.","minutes":1,"kind":"activo"},{"text":"Tapar el bol y reposar en la nevera hasta que los sabores se integren.","minutes":10,"kind":"espera"},{"text":"Espolvorear el perejil picado por encima y servir frío.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'crudo', NULL),
  ('ensaladas_verduras_081', 'Ensalada de pasta fría mediterránea', 'ensaladas_verduras', 'none', 'pasta', ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'verano', 520, 18, 55, 26, 2, true, true, '{"gluten","lactosa","sulfitos"}', '[{"name":"Fusilli","amount":140,"unit":"g"},{"name":"Tomate cherry","amount":150,"unit":"g"},{"name":"Pepino","amount":100,"unit":"g"},{"name":"Pimiento rojo","amount":60,"unit":"g"},{"name":"Aceitunas negras","amount":30,"unit":"g"},{"name":"Mozzarella (bocconcini)","amount":80,"unit":"g"},{"name":"Albahaca fresca","amount":10,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":25,"unit":"ml"},{"name":"Vinagre balsámico","amount":10,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Llevar a ebullición una olla con abundante agua y sal.","Cocer fusilli en el agua hirviendo hasta que estén al dente, siguiendo el tiempo del envase.","Cortar tomate cherry por la mitad.","Cortar pepino en dados.","Cortar pimiento rojo en tiras finas.","Cortar mozzarella (bocconcini) en dados.","Escurrir los fusilli y refrescar bajo agua fría hasta que estén completamente fríos.","Escurrir bien los fusilli y reservar en un bol grande.","Añadir el tomate cherry, el pepino, el pimiento rojo, aceitunas negras y la mozzarella al bol.","Aliñar con aceite de oliva virgen extra y vinagre balsámico.","Deshojar albahaca fresca con las manos y añadir al bol.","Remover con suavidad hasta integrar todos los ingredientes.","Tapar el bol y refrigerar en la nevera hasta que la ensalada esté bien fría.","Servir la ensalada fría directamente del bol o repartir en platos."}', 'Pasta fría con tomate cherry, mozzarella, pimiento y albahaca, ideal para el calor del verano.', '[{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"La Thermomix es ideal para cocer la pasta de forma controlada. Añade agua y sal al vaso, calienta, y luego incorpora los fusilli cociéndolos a la temperatura y tiempo indicados en el paquete, a velocidad cuchara y giro inverso. El resto de ingredientes se pican y mezclan manualme"},{"appliance":"olla_express","time":15,"difficulty":"facil","prepSummary":"La olla express es excelente para cocer la pasta en mucho menos tiempo. Añade el agua y la sal, lleva a ebullición, incorpora la pasta y cocina a presión por la mitad del tiempo indicado en el paquete, o incluso menos, liberando la presión rápidamente para evitar que se pase. Lue"},{"appliance":"microondas","time":20,"difficulty":"facil","prepSummary":"Puedes cocer la pasta en el microondas usando un recipiente apto con agua y sal, calentando a máxima potencia hasta que hierva y luego cocinando según las instrucciones del paquete, removiendo ocasionalmente. Es una opción rápida para la cocción, luego solo tienes que añadir los "}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura","lacteo","encurtido"}', NULL, '{}'::main_protein[], false, '[{"text":"Llevar a ebullición una olla con abundante agua y {{Sal|gusto}}.","minutes":5,"kind":"activo"},{"text":"Cocer {{Fusilli}} en el agua hirviendo hasta que estén al dente, siguiendo el tiempo del envase.","minutes":10,"kind":"pasivo"},{"text":"Cortar {{Tomate cherry}} por la mitad.","minutes":2,"kind":"paralelo","during":1},{"text":"Cortar {{Pepino}} en dados.","minutes":2,"kind":"paralelo","during":1},{"text":"Cortar {{Pimiento rojo}} en tiras finas.","minutes":2,"kind":"paralelo","during":1},{"text":"Cortar {{Mozzarella (bocconcini)}} en dados.","minutes":1,"kind":"paralelo","during":1},{"text":"Escurrir los fusilli y refrescar bajo agua fría hasta que estén completamente fríos.","minutes":2,"kind":"activo"},{"text":"Escurrir bien los fusilli y reservar en un bol grande.","minutes":1,"kind":"prep"},{"text":"Añadir el tomate cherry, el pepino, el pimiento rojo, {{Aceitunas negras}} y la mozzarella al bol.","minutes":1,"kind":"activo"},{"text":"Aliñar con {{Aceite de oliva virgen extra}} y {{Vinagre balsámico}}.","minutes":1,"kind":"activo"},{"text":"Deshojar {{Albahaca fresca}} con las manos y añadir al bol.","minutes":1,"kind":"activo"},{"text":"Remover con suavidad hasta integrar todos los ingredientes.","minutes":1,"kind":"activo"},{"text":"Tapar el bol y refrigerar en la nevera hasta que la ensalada esté bien fría.","minutes":20,"kind":"espera"},{"text":"Servir la ensalada fría directamente del bol o repartir en platos.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'olla', 'italiana'),
  ('ensaladas_verduras_082', 'Ensalada de melón y jamón', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'verano', 265, 18, 20, 13, 2, true, false, '{"lactosa","sulfitos"}', '[{"name":"Melón","amount":400,"unit":"g"},{"name":"Jamón serrano","amount":80,"unit":"g"},{"name":"Rúcula","amount":40,"unit":"g"},{"name":"Queso parmesano","amount":20,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":15,"unit":"ml"},{"name":"Reducción de vinagre balsámico","amount":10,"unit":"ml"}]'::jsonb, '{"Cortar melón en dados de unos 2 cm, retirando antes la piel y las semillas.","Rallar queso parmesano en virutas finas con un pelador o rallador grueso.","Lavar rúcula bajo agua fría y secar bien con papel de cocina.","Repartir la rúcula seca en la base de 2 platos.","Colocar los dados de melón sobre la rúcula, distribuyéndolos de forma uniforme.","Enrollar jamón serrano en cilindros y disponerlos entre los dados de melón.","Añadir las virutas de queso parmesano por encima.","Rociar con aceite de oliva virgen extra y reducción de vinagre balsámico.","Servir de inmediato, bien frío."}', 'El clásico contraste dulce y salado de melón fresco con jamón serrano y virutas de parmesano.', '[]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura","fruta"}', NULL, ARRAY['cerdo']::main_protein[], false, '[{"text":"Cortar {{Melón}} en dados de unos 2 cm, retirando antes la piel y las semillas.","minutes":3,"kind":"prep"},{"text":"Rallar {{Queso parmesano}} en virutas finas con un pelador o rallador grueso.","minutes":1,"kind":"prep"},{"text":"Lavar {{Rúcula}} bajo agua fría y secar bien con papel de cocina.","minutes":1,"kind":"prep"},{"text":"Repartir la rúcula seca en la base de 2 platos.","minutes":1,"kind":"emplatado"},{"text":"Colocar los dados de melón sobre la rúcula, distribuyéndolos de forma uniforme.","minutes":1,"kind":"emplatado"},{"text":"Enrollar {{Jamón serrano}} en cilindros y disponerlos entre los dados de melón.","minutes":1,"kind":"emplatado"},{"text":"Añadir las virutas de queso parmesano por encima.","minutes":1,"kind":"emplatado"},{"text":"Rociar con {{Aceite de oliva virgen extra|chorrito}} y {{Reducción de vinagre balsámico|chorrito}}.","minutes":1,"kind":"emplatado"},{"text":"Servir de inmediato, bien frío.","kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL),
  ('ensaladas_verduras_083', 'Ensalada de endivias, roquefort y nueces', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 385, 12, 14, 32, 2, false, false, '{"lactosa","frutos_secos","sulfitos"}', '[{"name":"Endivias","amount":300,"unit":"g"},{"name":"Queso roquefort","amount":60,"unit":"g"},{"name":"Nueces","amount":40,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Vinagre de jerez","amount":10,"unit":"ml"},{"name":"Miel","amount":10,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Separar las hojas de endivias, lavarlas bajo agua fría y secarlas bien con papel de cocina.","Calentar sartén a fuego medio sin aceite y tostar nueces hasta que estén doradas, sin dejar de remover.","Retirar las nueces de la sartén y trocearlas groseramente con un cuchillo.","Mezclar aceite de oliva, vinagre de jerez, miel y sal en un bol pequeño hasta emulsionar.","Disponer las hojas de endivias en forma de barco en una fuente o plato.","Desmenuzar queso roquefort en trozos irregulares sobre las hojas de endivias.","Repartir las nueces troceadas sobre la ensalada.","Rociar la ensalada con el aliño justo antes de servir y servir enseguida para conservar la textura crujiente."}', 'Hojas de endivia en barco con queso roquefort desmenuzado, nueces tostadas y un aliño de miel y mostaza.', '[]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura","lacteo","frutos_secos"}', NULL, '{}'::main_protein[], false, '[{"text":"Separar las hojas de {{Endivias}}, lavarlas bajo agua fría y secarlas bien con papel de cocina.","minutes":3,"kind":"prep"},{"text":"Calentar {{@Sartén}} a fuego medio sin aceite y tostar {{Nueces}} hasta que estén doradas, sin dejar de remover.","minutes":3,"kind":"activo"},{"text":"Retirar las nueces de la sartén y trocearlas groseramente con un cuchillo.","minutes":1,"kind":"prep"},{"text":"Mezclar {{Aceite de oliva}}, {{Vinagre de jerez}}, {{Miel}} y {{Sal|gusto}} en un bol pequeño hasta emulsionar.","minutes":1,"kind":"prep"},{"text":"Disponer las hojas de endivias en forma de barco en una fuente o plato.","minutes":2,"kind":"emplatado"},{"text":"Desmenuzar {{Queso roquefort}} en trozos irregulares sobre las hojas de endivias.","minutes":1,"kind":"emplatado"},{"text":"Repartir las nueces troceadas sobre la ensalada.","minutes":1,"kind":"emplatado"},{"text":"Rociar la ensalada con el aliño justo antes de servir y servir enseguida para conservar la textura crujiente.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL),
  ('ensaladas_verduras_084', 'Ensalada de aguacate y langostinos al curry', 'ensaladas_verduras', 'marisco', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 455, 25, 11, 36, 2, true, false, '{"marisco","huevo"}', '[{"name":"Langostinos pelados","amount":200,"unit":"g"},{"name":"Aguacate","amount":200,"unit":"g"},{"name":"Mayonesa","amount":40,"unit":"g"},{"name":"Curry en polvo","amount":5,"unit":"g"},{"name":"Zumo de limón","amount":15,"unit":"ml"},{"name":"Canónigos","amount":60,"unit":"g"},{"name":"Tomate cherry","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Salpimentar langostinos pelados con sal.","Calentar sartén con aceite de oliva a fuego fuerte.","Saltear los langostinos 2-3 min hasta que estén rosados y reservar para que enfríen.","Mezclar mayonesa con curry en polvo y zumo de limón hasta obtener una salsa homogénea.","Cortar aguacate por la mitad, deshuesar y cortar en dados.","Rociar los dados de aguacate con el zumo de limón restante para que no se oxiden.","Cortar tomate cherry por la mitad.","Repartir canónigos como base en los platos.","Colocar encima los dados de aguacate y los langostinos fríos.","Añadir los tomates cherry sobre la ensalada.","Napar con la salsa de curry o servirla aparte en un cuenco."}', 'Langostinos salteados con aguacate cremoso y una suave salsa de curry, fresca y elegante.', '[{"appliance":"airfryer","time":15,"difficulty":"facil","prepSummary":"Los langostinos, marinados con curry, aceite y sal, se cocinan en la airfryer a 190°C durante 6-8 minutos, agitándolos a mitad. Esto les da una textura crujiente por fuera y jugosa por dentro, ideal para la ensalada."},{"appliance":"horno","time":20,"difficulty":"facil","prepSummary":"Marinar los langostinos con curry, aceite y sal, y asarlos en el horno precalentado a 200°C durante 8-10 minutos hasta que estén rosados y cocidos. Esta cocción al horno realza el sabor del curry de forma suave."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], false, '[{"text":"Salpimentar {{Langostinos pelados}} con {{Sal|gusto}}.","minutes":1,"kind":"prep"},{"text":"Calentar {{@Sartén}} con {{Aceite de oliva|chorrito}} a fuego fuerte.","minutes":1,"kind":"activo"},{"text":"Saltear los langostinos 2-3 min hasta que estén rosados y reservar para que enfríen.","minutes":3,"kind":"activo"},{"text":"Mezclar {{Mayonesa}} con {{Curry en polvo}} y {{Zumo de limón}} hasta obtener una salsa homogénea.","minutes":2,"kind":"prep"},{"text":"Cortar {{Aguacate}} por la mitad, deshuesar y cortar en dados.","minutes":2,"kind":"prep"},{"text":"Rociar los dados de aguacate con el zumo de limón restante para que no se oxiden.","minutes":1,"kind":"prep"},{"text":"Cortar {{Tomate cherry}} por la mitad.","minutes":1,"kind":"prep"},{"text":"Repartir {{Canónigos}} como base en los platos.","minutes":1,"kind":"emplatado"},{"text":"Colocar encima los dados de aguacate y los langostinos fríos.","minutes":1,"kind":"emplatado"},{"text":"Añadir los tomates cherry sobre la ensalada.","minutes":1,"kind":"emplatado"},{"text":"Napar con la salsa de curry o servirla aparte en un cuenco.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL)
