  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id, extra_proteins, freezable, steps_rich, estrella, occasion, kid_favourite, tecnica, cocina
) values
  ('ensaladas_verduras_085', 'Ensalada de remolacha, naranja y aceitunas negras', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'invierno', 258, 4, 32, 13, 2, true, true, '{"sulfitos"}', '[{"name":"Remolacha cocida","amount":250,"unit":"g"},{"name":"Naranja","amount":300,"unit":"g"},{"name":"Aceitunas negras","amount":40,"unit":"g"},{"name":"Cebolla morada","amount":30,"unit":"g"},{"name":"Rúcula","amount":40,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":20,"unit":"ml"},{"name":"Vinagre de jerez","amount":10,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Laminar cebolla morada en aros muy finos.","Cortar remolacha cocida en dados o láminas uniformes.","Pelar naranja a lo vivo, retirando toda la piel blanca.","Cortar las naranjas en rodajas o gajos.","Repartir rúcula como base en una fuente amplia.","Disponer la remolacha y los gajos de naranja sobre la rúcula.","Repartir la cebolla morada laminada por encima.","Distribuir aceitunas negras por toda la ensalada.","Mezclar aceite de oliva virgen extra, vinagre de jerez y sal en un bol pequeño.","Aliñar la ensalada con la mezcla y servir de inmediato."}', 'Remolacha y naranja en una combinación muy vistosa, con aceitunas negras y un aliño sencillo.', '[{"appliance":"thermomix","time":15,"difficulty":"facil","prepSummary":"Utiliza la Thermomix para picar la cebolla morada y la remolacha cocida en trozos uniformes (velocidad 4, 3-4 segundos). Emulsiona el aceite, vinagre y sal para el aliño (velocidad 5, 30 segundos). Luego, mezcla todo suavemente en un bol con el resto de ingredientes."}]'::jsonb, '{}', NULL, true, NULL, '{"verdura","fruta","encurtido"}', NULL, '{}'::main_protein[], false, '[{"text":"Laminar {{Cebolla morada}} en aros muy finos.","minutes":2,"kind":"prep"},{"text":"Cortar {{Remolacha cocida}} en dados o láminas uniformes.","minutes":2,"kind":"prep"},{"text":"Pelar {{Naranja}} a lo vivo, retirando toda la piel blanca.","minutes":2,"kind":"prep"},{"text":"Cortar las naranjas en rodajas o gajos.","minutes":1,"kind":"prep"},{"text":"Repartir {{Rúcula}} como base en una fuente amplia.","minutes":1,"kind":"emplatado"},{"text":"Disponer la remolacha y los gajos de naranja sobre la rúcula.","minutes":1,"kind":"emplatado"},{"text":"Repartir la cebolla morada laminada por encima.","minutes":1,"kind":"emplatado"},{"text":"Distribuir {{Aceitunas negras}} por toda la ensalada.","minutes":1,"kind":"emplatado"},{"text":"Mezclar {{Aceite de oliva virgen extra}}, {{Vinagre de jerez}} y {{Sal|gusto}} en un bol pequeño.","minutes":1,"kind":"prep"},{"text":"Aliñar la ensalada con la mezcla y servir de inmediato.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'crudo', NULL),
  ('ensaladas_verduras_086', 'Ensalada de tomate cherry, mozzarella y albahaca', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'verano', 355, 16, 9, 28, 2, true, false, '{"lactosa","sulfitos"}', '[{"name":"Tomate cherry","amount":300,"unit":"g"},{"name":"Mozzarella fresca","amount":150,"unit":"g"},{"name":"Albahaca fresca","amount":10,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":25,"unit":"ml"},{"name":"Vinagre balsámico","amount":10,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Lavar tomate cherry bajo el grifo y escurrir bien.","Cortar cada tomate cherry por la mitad y reservar.","Escurrir mozzarella fresca y cortar en dados de unos 2 cm.","Lavar albahaca fresca, secar con papel de cocina y reservar las hojas enteras.","Disponer los tomates cherry y la mozzarella en una fuente, alternando los trozos.","Repartir las hojas de albahaca por encima.","Aliñar con aceite de oliva virgen extra y vinagre balsámico.","Añadir sal y servir de inmediato a temperatura ambiente."}', 'Bocados de tomate cherry y mozzarella fresca con albahaca, sencilla y llena de color.', '[{"appliance":"horno","time":20,"difficulty":"facil","prepSummary":"Asa los tomates cherry partidos por la mitad con un chorrito de aceite y sal en el horno precalentado a 180°C durante 15 minutos, hasta que estén tiernos y ligeramente caramelizados. Combínalos tibios con la mozzarella, albahaca, aceite y vinagre."},{"appliance":"airfryer","time":15,"difficulty":"facil","prepSummary":"Para intensificar su sabor, asa los tomates cherry partidos por la mitad con un poco de aceite y sal en la airfryer a 180°C durante 10-12 minutos, agitándolos a mitad. Luego, mezcla con la mozzarella fresca, albahaca, aceite y vinagre."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura","lacteo"}', NULL, '{}'::main_protein[], false, '[{"text":"Lavar {{Tomate cherry}} bajo el grifo y escurrir bien.","minutes":1,"kind":"prep"},{"text":"Cortar cada tomate cherry por la mitad y reservar.","minutes":2,"kind":"prep"},{"text":"Escurrir {{Mozzarella fresca}} y cortar en dados de unos 2 cm.","minutes":1,"kind":"prep"},{"text":"Lavar {{Albahaca fresca}}, secar con papel de cocina y reservar las hojas enteras.","minutes":1,"kind":"prep"},{"text":"Disponer los tomates cherry y la mozzarella en una fuente, alternando los trozos.","minutes":1,"kind":"activo"},{"text":"Repartir las hojas de albahaca por encima.","minutes":1,"kind":"activo"},{"text":"Aliñar con {{Aceite de oliva virgen extra|chorrito}} y {{Vinagre balsámico|chorrito}}.","minutes":1,"kind":"activo"},{"text":"Añadir {{Sal|gusto}} y servir de inmediato a temperatura ambiente.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL),
  ('ensaladas_verduras_087', 'Ensalada de pollo, mango y aguacate', 'ensaladas_verduras', 'pollo', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 470, 42, 28, 24, 2, true, false, '{"soja","gluten"}', '[{"name":"Pechuga de pollo","amount":250,"unit":"g"},{"name":"Mango","amount":200,"unit":"g"},{"name":"Aguacate","amount":150,"unit":"g"},{"name":"Mezclum de lechugas","amount":80,"unit":"g"},{"name":"Cebolla morada","amount":30,"unit":"g"},{"name":"Zumo de lima","amount":20,"unit":"ml"},{"name":"Salsa de soja","amount":15,"unit":"ml"},{"name":"Miel","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Salpimentar pechuga de pollo por ambas caras con sal.","Calentar plancha a fuego fuerte con aceite de oliva.","Cocinar la pechuga de pollo 6 min por cada lado hasta que esté bien hecha.","Pelar mango y cortarlo en dados.","Laminar cebolla morada muy fina.","Mezclar zumo de lima, salsa de soja, miel y el aceite de oliva restante en un bol hasta integrar.","Retirar la pechuga de la plancha y dejar reposar 3 min.","Cortar la pechuga en tiras.","Cortar aguacate por la mitad, deshuesar y laminar.","Rociar las láminas de aguacate con un poco del zumo de lima del aliño para evitar que se oxide.","Repartir mezclum de lechugas como base en 2 platos.","Disponer sobre la base las tiras de pollo, el mango y el aguacate.","Añadir la cebolla morada laminada sobre la ensalada.","Rociar con el aliño justo antes de servir."}', 'Ensalada contundente de pollo a la plancha con mango dulce y aguacate cremoso.', '[{"appliance":"airfryer","time":20,"difficulty":"facil","prepSummary":"Cocina el pollo marinado en la airfryer a 190-200°C durante 15-18 minutos, dándole la vuelta a mitad para un exterior dorado y jugoso."},{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Hornea la pechuga de pollo a 200°C durante 20-25 minutos en una bandeja, asegurando que quede cocida pero jugosa por dentro."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura","fruta"}', NULL, '{}'::main_protein[], false, '[{"text":"Salpimentar {{Pechuga de pollo}} por ambas caras con {{Sal|gusto}}.","minutes":1,"kind":"prep"},{"text":"Calentar {{@Plancha}} a fuego fuerte con {{Aceite de oliva|chorrito}}.","minutes":2,"kind":"activo"},{"text":"Cocinar la pechuga de pollo 6 min por cada lado hasta que esté bien hecha.","minutes":12,"kind":"activo"},{"text":"Pelar {{Mango}} y cortarlo en dados.","minutes":2,"kind":"paralelo","during":2},{"text":"Laminar {{Cebolla morada}} muy fina.","minutes":2,"kind":"paralelo","during":2},{"text":"Mezclar {{Zumo de lima}}, {{Salsa de soja}}, {{Miel}} y el aceite de oliva restante en un bol hasta integrar.","minutes":2,"kind":"paralelo","during":2},{"text":"Retirar la pechuga de la plancha y dejar reposar 3 min.","minutes":3,"kind":"espera"},{"text":"Cortar la pechuga en tiras.","minutes":1,"kind":"prep"},{"text":"Cortar {{Aguacate}} por la mitad, deshuesar y laminar.","minutes":2,"kind":"prep"},{"text":"Rociar las láminas de aguacate con un poco del zumo de lima del aliño para evitar que se oxide.","minutes":1,"kind":"prep"},{"text":"Repartir {{Mezclum de lechugas}} como base en 2 platos.","minutes":1,"kind":"emplatado"},{"text":"Disponer sobre la base las tiras de pollo, el mango y el aguacate.","minutes":1,"kind":"emplatado"},{"text":"Añadir la cebolla morada laminada sobre la ensalada.","minutes":1,"kind":"emplatado"},{"text":"Rociar con el aliño justo antes de servir.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'plancha', NULL),
  ('ensaladas_verduras_088', 'Ensalada de burrata con miel, pistachos y guindilla', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'all', 448, 19, 13, 36, 2, false, false, '{"lactosa","frutos_secos"}', '[{"name":"Burrata","amount":200,"unit":"g"},{"name":"Rúcula","amount":40,"unit":"g"},{"name":"Miel","amount":20,"unit":"g"},{"name":"Pistachos","amount":30,"unit":"g"},{"name":"Guindilla fresca","amount":2,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":15,"unit":"ml"},{"name":"Sal en escamas","amount":2,"unit":"g"}]'::jsonb, '{"Retirar burrata de la nevera y dejar reposar a temperatura ambiente.","Picar guindilla fresca en rodajas muy finas y reservar.","Cortar pistachos groseramente con un cuchillo y reservar.","Repartir rúcula en una fuente o en 2 platos individuales.","Colocar la burrata entera o partida por la mitad sobre la rúcula.","Rociar miel sobre la burrata.","Repartir los pistachos y la guindilla picada por encima.","Terminar con aceite de oliva virgen extra y sal en escamas, y servir enseguida."}', 'Burrata cremosa con miel, pistachos crujientes y un toque picante de guindilla fresca.', '[]'::jsonb, '{}', NULL, true, NULL, '{"verdura","lacteo","frutos_secos"}', NULL, '{}'::main_protein[], false, '[{"text":"Retirar {{Burrata}} de la nevera y dejar reposar a temperatura ambiente.","minutes":15,"kind":"espera"},{"text":"Picar {{Guindilla fresca}} en rodajas muy finas y reservar.","minutes":2,"kind":"prep"},{"text":"Cortar {{Pistachos}} groseramente con un cuchillo y reservar.","minutes":1,"kind":"prep"},{"text":"Repartir {{Rúcula}} en una fuente o en 2 platos individuales.","minutes":1,"kind":"emplatado"},{"text":"Colocar la burrata entera o partida por la mitad sobre la rúcula.","minutes":1,"kind":"emplatado"},{"text":"Rociar {{Miel}} sobre la burrata.","minutes":1,"kind":"emplatado"},{"text":"Repartir los pistachos y la guindilla picada por encima.","minutes":1,"kind":"emplatado"},{"text":"Terminar con {{Aceite de oliva virgen extra|chorrito}} y {{Sal en escamas|gusto}}, y servir enseguida.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'crudo', NULL),
  ('ensaladas_verduras_089', 'Ensalada de orzo con feta, pepino y aceitunas', 'ensaladas_verduras', 'none', 'pasta', ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 515, 18, 51, 28, 2, true, true, '{"gluten","lactosa","sulfitos"}', '[{"name":"Orzo","amount":130,"unit":"g"},{"name":"Queso feta","amount":80,"unit":"g"},{"name":"Pepino","amount":150,"unit":"g"},{"name":"Tomate cherry","amount":100,"unit":"g"},{"name":"Aceitunas negras (kalamata)","amount":40,"unit":"g"},{"name":"Cebolla morada","amount":30,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":25,"unit":"ml"},{"name":"Zumo de limón","amount":15,"unit":"ml"},{"name":"Orégano seco","amount":2,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Llevar a ebullición una olla con agua abundante y sal.","Cocer orzo en el agua hirviendo hasta que esté al dente, siguiendo el tiempo del envase.","Cortar pepino en dados pequeños.","Cortar tomate cherry por la mitad.","Picar cebolla morada muy fina.","Desmenuzar queso feta en trozos irregulares.","Escurrir el orzo cocido y refrescar bajo agua fría hasta que esté completamente frío.","Escurrir bien el orzo y trasladar a un bol grande.","Añadir el pepino, el tomate cherry, la cebolla morada y aceitunas negras (kalamata) al bol.","Añadir aceite de oliva virgen extra, zumo de limón y orégano seco.","Remover con suavidad hasta que todo quede bien aliñado.","Añadir el queso feta desmenuzado y remover con cuidado para no romperlo demasiado.","Tapar el bol y refrigerar hasta que la ensalada esté bien fría y los sabores integrados.","Servir la ensalada fría directamente del bol."}', 'Orzo frío con queso feta, pepino y aceitunas, brillante de aceite de oliva.', '[{"appliance":"thermomix","time":15,"difficulty":"facil","prepSummary":"Cocina el orzo en el vaso de la Thermomix siguiendo las instrucciones para pasta. Una vez cocido y escurrido, añade el resto de los ingredientes frescos y el aliño, mezclando suavemente para integrar."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura","lacteo","encurtido"}', NULL, '{}'::main_protein[], false, '[{"text":"Llevar a ebullición una olla con agua abundante y {{Sal|gusto}}.","minutes":3,"kind":"activo"},{"text":"Cocer {{Orzo}} en el agua hirviendo hasta que esté al dente, siguiendo el tiempo del envase.","minutes":9,"kind":"pasivo"},{"text":"Cortar {{Pepino}} en dados pequeños.","minutes":2,"kind":"paralelo","during":1},{"text":"Cortar {{Tomate cherry}} por la mitad.","minutes":1,"kind":"paralelo","during":1},{"text":"Picar {{Cebolla morada}} muy fina.","minutes":1,"kind":"paralelo","during":1},{"text":"Desmenuzar {{Queso feta}} en trozos irregulares.","minutes":1,"kind":"paralelo","during":1},{"text":"Escurrir el orzo cocido y refrescar bajo agua fría hasta que esté completamente frío.","minutes":1,"kind":"activo"},{"text":"Escurrir bien el orzo y trasladar a un bol grande.","minutes":1,"kind":"activo"},{"text":"Añadir el pepino, el tomate cherry, la cebolla morada y {{Aceitunas negras (kalamata)}} al bol.","minutes":1,"kind":"activo"},{"text":"Añadir {{Aceite de oliva virgen extra}}, {{Zumo de limón}} y {{Orégano seco|pizca}}.","minutes":1,"kind":"activo"},{"text":"Remover con suavidad hasta que todo quede bien aliñado.","minutes":1,"kind":"activo"},{"text":"Añadir el queso feta desmenuzado y remover con cuidado para no romperlo demasiado.","minutes":1,"kind":"activo"},{"text":"Tapar el bol y refrigerar hasta que la ensalada esté bien fría y los sabores integrados.","minutes":10,"kind":"espera"},{"text":"Servir la ensalada fría directamente del bol.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'olla', NULL),
  ('ensaladas_verduras_090', 'Berenjenas a la parmesana', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'horno', 65, 'normal', 'all', 555, 26, 45, 29, 4, true, true, '{"gluten","huevo","lactosa"}', '[{"name":"Berenjena","amount":600,"unit":"g"},{"name":"Harina","amount":60,"unit":"g"},{"name":"Huevo","amount":100,"unit":"g"},{"name":"Pan rallado","amount":80,"unit":"g"},{"name":"Salsa de tomate","amount":400,"unit":"g"},{"name":"Mozzarella rallada","amount":200,"unit":"g"},{"name":"Queso parmesano rallado","amount":60,"unit":"g"},{"name":"Albahaca fresca","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":50,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Cortar berenjena en rodajas de 0,5 cm de grosor.","Salar las rodajas de berenjena con sal y disponerlas en un colador.","Dejar reposar las rodajas saladas hasta que suelten el amargor.","Secar las rodajas de berenjena con papel de cocina presionando suavemente.","Batir huevo en un bol hondo hasta que esté homogéneo.","Preparar 3 platos: uno con harina, uno con el huevo batido y uno con pan rallado.","Pasar cada rodaja de berenjena primero por la harina, cubriéndola por ambos lados.","Pasar cada rodaja enharinada por el huevo batido y después por el pan rallado.","Calentar aceite de oliva en sartén a fuego medio-fuerte.","Freír las rodajas rebozadas por tandas hasta que estén doradas por ambos lados.","Escurrir las rodajas fritas sobre papel absorbente y reservar.","Precalentar el horno a 190 °C.","Cubrir el fondo de una fuente de horno con una capa fina de salsa de tomate.","Disponer una capa de rodajas de berenjena rebozadas sobre la salsa de tomate.","Cubrir la capa de berenjena con salsa de tomate, mozzarella rallada y queso parmesano rallado.","Repetir las capas hasta agotar los ingredientes, acabando con salsa de tomate, mozzarella y parmesano.","Hornear la fuente en el horno a 190 °C hasta que el queso esté fundido y dorado.","Retirar la fuente del horno y dejar reposar antes de servir.","Repartir en platos y decorar con albahaca fresca por encima."}', 'Capas de berenjena rebozada gratinadas con salsa de tomate, mozzarella y parmesano.', '[{"appliance":"horno","time":65,"difficulty":"normal","prepSummary":"Precalienta el horno a 180-200°C. Monta las capas de berenjena rebozada, salsa de tomate y quesos en una fuente apta para horno, horneando durante 45-50 minutos hasta que el queso esté fundido y dorado."},{"appliance":"airfryer","time":35,"difficulty":"normal","prepSummary":"Cocina las rodajas de berenjena rebozadas en la airfryer a 180°C por 15-20 minutos en tandas, hasta que doren. Luego, monta las capas en un molde pequeño apto para airfryer y gratina a 170°C por 15-20 minutos hasta que el queso burbujee y dore."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura","lacteo"}', NULL, '{}'::main_protein[], true, '[{"text":"Cortar {{Berenjena}} en rodajas de 0,5 cm de grosor.","minutes":5,"kind":"prep"},{"text":"Salar las rodajas de berenjena con {{Sal|gusto}} y disponerlas en un colador.","minutes":1,"kind":"prep"},{"text":"Dejar reposar las rodajas saladas hasta que suelten el amargor.","minutes":20,"kind":"espera"},{"text":"Secar las rodajas de berenjena con papel de cocina presionando suavemente.","minutes":2,"kind":"prep"},{"text":"Batir {{Huevo}} en un bol hondo hasta que esté homogéneo.","minutes":1,"kind":"prep"},{"text":"Preparar 3 platos: uno con {{Harina}}, uno con el huevo batido y uno con {{Pan rallado}}.","minutes":1,"kind":"prep"},{"text":"Pasar cada rodaja de berenjena primero por la harina, cubriéndola por ambos lados.","minutes":3,"kind":"prep"},{"text":"Pasar cada rodaja enharinada por el huevo batido y después por el pan rallado.","minutes":3,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|abundante}} en {{@Sartén}} a fuego medio-fuerte.","minutes":2,"kind":"activo"},{"text":"Freír las rodajas rebozadas por tandas hasta que estén doradas por ambos lados.","minutes":10,"kind":"activo"},{"text":"Escurrir las rodajas fritas sobre papel absorbente y reservar.","minutes":1,"kind":"activo"},{"text":"Precalentar el horno a 190 °C.","minutes":10,"kind":"pasivo"},{"text":"Cubrir el fondo de una fuente de horno con una capa fina de {{Salsa de tomate}}.","minutes":1,"kind":"prep"},{"text":"Disponer una capa de rodajas de berenjena rebozadas sobre la salsa de tomate.","minutes":1,"kind":"prep"},{"text":"Cubrir la capa de berenjena con salsa de tomate, {{Mozzarella rallada}} y {{Queso parmesano rallado}}.","minutes":2,"kind":"prep"},{"text":"Repetir las capas hasta agotar los ingredientes, acabando con salsa de tomate, mozzarella y parmesano.","minutes":3,"kind":"prep"},{"text":"Hornear la fuente en el horno a 190 °C hasta que el queso esté fundido y dorado.","minutes":28,"kind":"pasivo"},{"text":"Retirar la fuente del horno y dejar reposar antes de servir.","minutes":5,"kind":"espera"},{"text":"Repartir en platos y decorar con {{Albahaca fresca|gusto}} por encima.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'horno', NULL),
  ('ensaladas_verduras_091', 'Pisto con huevo frito por encima', 'ensaladas_verduras', 'huevo', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 40, 'facil', 'verano', 295, 10, 17, 21, 2, true, false, '{"huevo"}', '[{"name":"Calabacín","amount":200,"unit":"g"},{"name":"Pimiento rojo","amount":100,"unit":"g"},{"name":"Pimiento verde","amount":100,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Tomate maduro","amount":200,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Huevo","amount":100,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Pelar y picar cebolla en dados pequeños.","Pelar y picar ajo fino.","Cortar pimiento rojo y pimiento verde en dados pequeños.","Cortar calabacín en dados pequeños.","Hacer un corte en cruz en la base de tomate maduro y sumergir en agua hirviendo 30 s hasta que la piel se despegue.","Retirar el tomate, pelar y cortar en dados pequeños.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla picada y el ajo picado hasta que estén translúcidos.","Añadir el pimiento rojo y el pimiento verde en dados y sofreír hasta que estén tiernos.","Añadir el calabacín en dados y sofreír hasta que esté tierno.","Añadir el tomate en dados y sal; remover para integrar.","Cocer a fuego suave hasta que el pisto esté meloso y sin exceso de agua.","Calentar aceite de oliva en otra sartén a fuego fuerte.","Freír huevo hasta que la clara esté cuajada y la yema quede jugosa.","Repartir el pisto en 2 platos y colocar un huevo frito encima de cada uno."}', 'Pisto de verduras bien meloso coronado con un huevo frito de yema jugosa.', '[{"appliance":"horno","time":45,"difficulty":"facil","prepSummary":"Corta las verduras en trozos, mézclalas con aceite, ajo y sal. Hornea a 190°C durante 35-40 minutos hasta que estén tiernas y ligeramente doradas, removiendo a mitad. Sirve con el huevo frito hecho aparte."},{"appliance":"thermomix","time":35,"difficulty":"facil","prepSummary":"Trocea las verduras en la Thermomix y sofríelas con aceite. Luego, programa para cocer a temperatura Varoma, velocidad cuchara, durante 25-30 minutos hasta que el pisto esté tierno y meloso. El huevo se fríe aparte."},{"appliance":"olla_express","time":25,"difficulty":"facil","prepSummary":"Sofríe la cebolla y los pimientos en la olla con aceite. Añade el resto de verduras y tomate, cierra y cocina a presión baja unos 8-10 minutos. Despresuriza y sirve con el huevo frito."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], false, '[{"text":"Pelar y picar {{Cebolla}} en dados pequeños.","minutes":3,"kind":"prep","part":"principal"},{"text":"Pelar y picar {{Ajo}} fino.","minutes":1,"kind":"prep","part":"principal"},{"text":"Cortar {{Pimiento rojo}} y {{Pimiento verde}} en dados pequeños.","minutes":3,"kind":"prep","part":"principal"},{"text":"Cortar {{Calabacín}} en dados pequeños.","minutes":2,"kind":"prep","part":"principal"},{"text":"Hacer un corte en cruz en la base de {{Tomate maduro}} y sumergir en agua hirviendo 30 s hasta que la piel se despegue.","minutes":2,"kind":"activo","part":"principal"},{"text":"Retirar el tomate, pelar y cortar en dados pequeños.","minutes":2,"kind":"prep","part":"principal"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego medio.","minutes":1,"kind":"activo","part":"principal"},{"text":"Sofreír la cebolla picada y el ajo picado hasta que estén translúcidos.","minutes":5,"kind":"activo","part":"principal"},{"text":"Añadir el pimiento rojo y el pimiento verde en dados y sofreír hasta que estén tiernos.","minutes":8,"kind":"activo","part":"principal"},{"text":"Añadir el calabacín en dados y sofreír hasta que esté tierno.","minutes":5,"kind":"activo","part":"principal"},{"text":"Añadir el tomate en dados y {{Sal|gusto}}; remover para integrar.","minutes":1,"kind":"activo","part":"principal"},{"text":"Cocer a fuego suave hasta que el pisto esté meloso y sin exceso de agua.","minutes":15,"kind":"pasivo","part":"principal"},{"text":"Calentar {{Aceite de oliva|abundante}} en otra {{@Sartén}} a fuego fuerte.","minutes":1,"kind":"activo","part":"guarnicion"},{"text":"Freír {{Huevo}} hasta que la clara esté cuajada y la yema quede jugosa.","minutes":2,"kind":"activo","part":"guarnicion"},{"text":"Repartir el pisto en 2 platos y colocar un huevo frito encima de cada uno.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL),
  ('ensaladas_verduras_092', 'Coliflor asada entera con tahini y granada', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'horno', 65, 'normal', 'all', 270, 8, 21, 18, 4, true, true, '{"sesamo"}', '[{"name":"Coliflor entera","amount":1000,"unit":"g"},{"name":"Aceite de oliva","amount":40,"unit":"ml"},{"name":"Comino molido","amount":5,"unit":"g"},{"name":"Pimentón dulce","amount":5,"unit":"g"},{"name":"Cúrcuma","amount":3,"unit":"g"},{"name":"Tahini","amount":60,"unit":"g"},{"name":"Zumo de limón","amount":30,"unit":"ml"},{"name":"Agua","amount":40,"unit":"ml"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Granada (arilos)","amount":100,"unit":"g"},{"name":"Perejil fresco","amount":10,"unit":"g"},{"name":"Sal","amount":5,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C.","Retirar las hojas exteriores de coliflor entera, dejando el tallo intacto para que se sostenga.","Mezclar aceite de oliva, comino molido, pimentón dulce, cúrcuma y sal en un bol pequeño.","Pincelar toda la coliflor con la mezcla de especias, cubriendo bien las hendiduras entre los ramilletes.","Colocar la coliflor en una bandeja de horno y tapar con papel de aluminio.","Hornear tapada a 200 °C durante 30 min.","Picar ajo muy fino.","Mezclar tahini, zumo de limón, agua y el ajo picado en un bol hasta obtener una salsa cremosa y homogénea.","Picar perejil fresco fino y reservar.","Retirar el papel de aluminio y hornear 25 min más, hasta que la coliflor esté tierna por dentro y dorada por fuera.","Sacar la coliflor del horno y trasladarla a una fuente de servir.","Rociar la coliflor generosamente con la salsa de tahini.","Repartir granada (arilos) y el perejil picado por encima y servir entera para trocear en la mesa."}', 'Coliflor entera asada hasta dorarse, bañada en salsa de tahini y coronada con granada.', '[{"appliance":"horno","time":65,"difficulty":"normal","prepSummary":"Precalienta el horno a 190-200°C. Cubre la coliflor con la mezcla de aceite y especias. Ásala durante 60-65 minutos o hasta que esté tierna y dorada, girándola a mitad de cocción para un asado uniforme y una textura perfecta."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], false, '[{"text":"Precalentar el horno a 200 °C.","minutes":10,"kind":"pasivo"},{"text":"Retirar las hojas exteriores de {{Coliflor entera}}, dejando el tallo intacto para que se sostenga.","minutes":3,"kind":"prep"},{"text":"Mezclar {{Aceite de oliva}}, {{Comino molido}}, {{Pimentón dulce}}, {{Cúrcuma}} y {{Sal|gusto}} en un bol pequeño.","minutes":2,"kind":"prep"},{"text":"Pincelar toda la coliflor con la mezcla de especias, cubriendo bien las hendiduras entre los ramilletes.","minutes":3,"kind":"prep"},{"text":"Colocar la coliflor en una bandeja de horno y tapar con papel de aluminio.","minutes":1,"kind":"prep"},{"text":"Hornear tapada a 200 °C durante 30 min.","minutes":30,"kind":"pasivo"},{"text":"Picar {{Ajo}} muy fino.","minutes":2,"kind":"paralelo","during":5},{"text":"Mezclar {{Tahini}}, {{Zumo de limón}}, {{Agua}} y el ajo picado en un bol hasta obtener una salsa cremosa y homogénea.","minutes":3,"kind":"paralelo","during":5},{"text":"Picar {{Perejil fresco}} fino y reservar.","minutes":2,"kind":"paralelo","during":5},{"text":"Retirar el papel de aluminio y hornear 25 min más, hasta que la coliflor esté tierna por dentro y dorada por fuera.","minutes":25,"kind":"pasivo"},{"text":"Sacar la coliflor del horno y trasladarla a una fuente de servir.","minutes":1,"kind":"emplatado"},{"text":"Rociar la coliflor generosamente con la salsa de tahini.","minutes":1,"kind":"emplatado"},{"text":"Repartir {{Granada (arilos)}} y el perejil picado por encima y servir entera para trocear en la mesa.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'horno', 'mediterranea'),
  ('ensaladas_verduras_093', 'Calabacines rellenos de quinoa y verduras', 'ensaladas_verduras', 'none', 'quinoa', ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'horno', 45, 'normal', 'all', 390, 17, 44, 16, 2, true, true, '{"lactosa"}', '[{"name":"Calabacín","amount":400,"unit":"g"},{"name":"Quinoa","amount":80,"unit":"g"},{"name":"Pimiento rojo","amount":50,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Tomate","amount":80,"unit":"g"},{"name":"Maíz dulce","amount":40,"unit":"g"},{"name":"Queso rallado","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Orégano seco","amount":2,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Llevar a ebullición agua con sal en un cazo a fuego fuerte.","Añadir quinoa al cazo y cocer a fuego medio hasta que esté tierna y haya absorbido el agua.","Precalentar el horno a 190 °C.","Cortar calabacín por la mitad a lo largo.","Vaciar la pulpa de cada mitad de calabacín con una cuchara, dejando una base de 1 cm.","Picar la pulpa de calabacín reservada en dados pequeños.","Picar cebolla y ajo finos.","Cortar pimiento rojo y tomate en dados pequeños.","Escurrir la quinoa cocida y reservar.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla y el ajo hasta que estén translúcidos.","Añadir el pimiento rojo y la pulpa de calabacín picada y sofreír a fuego medio.","Incorporar el tomate y maíz dulce a la sartén y remover bien.","Añadir la quinoa escurrida y orégano seco a la sartén y mezclar hasta integrar.","Retirar la sartén del fuego y salpimentar el relleno al gusto.","Disponer las mitades de calabacín en una bandeja de horno con la cavidad hacia arriba.","Rellenar cada mitad de calabacín con el sofrito de quinoa y verduras.","Cubrir cada calabacín relleno con queso rallado repartido a partes iguales.","Hornear a 190 °C durante 22 min hasta que el calabacín esté tierno y el queso gratinado.","Servir templado, 2 mitades de calabacín por ración."}', 'Barcas de calabacín rellenas de quinoa y verduras, gratinadas con queso por encima.', '[{"appliance":"horno","time":45,"difficulty":"normal","prepSummary":"Se vacían los calabacines, se cocina la quinoa y se sofríen las verduras. Se rellenan, se cubren con queso y se hornean a 180-200°C durante 25-30 minutos hasta que estén tiernos y dorados."},{"appliance":"airfryer","time":40,"difficulty":"normal","prepSummary":"Tras vaciar los calabacines y preparar el relleno (cocinar quinoa y saltear verduras), se rellenan y se cocinan en la airfryer a 180°C durante 20-25 minutos, hasta que el calabacín esté tierno y el queso gratinado."},{"appliance":"thermomix","time":50,"difficulty":"normal","prepSummary":"La Thermomix cocina la quinoa y sofríe las verduras para el relleno. Los calabacines vaciados se cocinan al vapor en el Varoma. Luego se rellenan y se espolvorea el queso para que se funda con el calor residual."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura","lacteo"}', NULL, '{}'::main_protein[], true, '[{"text":"Llevar a ebullición agua con {{Sal|gusto}} en un cazo a fuego fuerte.","minutes":3,"kind":"activo"},{"text":"Añadir {{Quinoa}} al cazo y cocer a fuego medio hasta que esté tierna y haya absorbido el agua.","minutes":15,"kind":"pasivo"},{"text":"Precalentar el horno a 190 °C.","minutes":10,"kind":"pasivo"},{"text":"Cortar {{Calabacín}} por la mitad a lo largo.","minutes":2,"kind":"prep"},{"text":"Vaciar la pulpa de cada mitad de calabacín con una cuchara, dejando una base de 1 cm.","minutes":3,"kind":"prep"},{"text":"Picar la pulpa de calabacín reservada en dados pequeños.","minutes":2,"kind":"prep"},{"text":"Picar {{Cebolla}} y {{Ajo}} finos.","minutes":2,"kind":"prep"},{"text":"Cortar {{Pimiento rojo}} y {{Tomate}} en dados pequeños.","minutes":2,"kind":"prep"},{"text":"Escurrir la quinoa cocida y reservar.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla y el ajo hasta que estén translúcidos.","minutes":4,"kind":"activo"},{"text":"Añadir el pimiento rojo y la pulpa de calabacín picada y sofreír a fuego medio.","minutes":5,"kind":"activo"},{"text":"Incorporar el tomate y {{Maíz dulce}} a la sartén y remover bien.","minutes":2,"kind":"activo"},{"text":"Añadir la quinoa escurrida y {{Orégano seco|pizca}} a la sartén y mezclar hasta integrar.","minutes":1,"kind":"activo"},{"text":"Retirar la sartén del fuego y salpimentar el relleno al gusto.","minutes":1,"kind":"activo"},{"text":"Disponer las mitades de calabacín en una bandeja de horno con la cavidad hacia arriba.","minutes":1,"kind":"prep"},{"text":"Rellenar cada mitad de calabacín con el sofrito de quinoa y verduras.","minutes":2,"kind":"activo"},{"text":"Cubrir cada calabacín relleno con {{Queso rallado}} repartido a partes iguales.","minutes":1,"kind":"activo"},{"text":"Hornear a 190 °C durante 22 min hasta que el calabacín esté tierno y el queso gratinado.","minutes":22,"kind":"pasivo"},{"text":"Servir templado, 2 mitades de calabacín por ración.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'horno', NULL),
  ('ensaladas_verduras_094', 'Setas al horno con ajo y perejil', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'horno', 30, 'facil', 'all', 195, 7, 10, 15, 2, true, true, '{}', '[{"name":"Setas (champiñones portobello)","amount":400,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Perejil fresco","amount":10,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":30,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C con calor arriba y abajo.","Limpiar setas (champiñones portobello) con un paño húmedo, sin mojarlas bajo el grifo.","Picar ajo muy fino.","Picar perejil fresco muy fino.","Mezclar en un bol el ajo picado, el perejil picado, aceite de oliva virgen extra y sal.","Colocar las setas en una bandeja de horno con la parte hueca hacia arriba.","Repartir la mezcla de ajo y perejil sobre cada seta hasta que queden bien impregnadas.","Hornear en la bandeja central hasta que las setas estén doradas y hayan soltado su jugo.","Retirar la bandeja del horno y regar las setas con el jugo que hayan soltado.","Servir las setas calientes, recién salidas del horno."}', 'Setas doradas al horno con ajo y perejil, jugosas y con aroma a ajo tostado.', '[{"appliance":"horno","time":30,"difficulty":"facil","prepSummary":"Mezcla las setas con el aceite, ajo, perejil y sal. Extiéndelas en una bandeja y hornea a 190°C durante 25-30 minutos hasta que estén tiernas y ligeramente doradas."},{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 195°C. Mezcla las setas con los ingredientes y cocina en la cesta durante 15-18 minutos, agitando a mitad de cocción para un dorado uniforme y óptimo."}]'::jsonb, '{}', NULL, NULL, NULL, '{"seta"}', NULL, '{}'::main_protein[], false, '[{"text":"Precalentar el horno a 200 °C con calor arriba y abajo.","minutes":10,"kind":"pasivo"},{"text":"Limpiar {{Setas (champiñones portobello)}} con un paño húmedo, sin mojarlas bajo el grifo.","minutes":3,"kind":"prep"},{"text":"Picar {{Ajo}} muy fino.","minutes":2,"kind":"prep"},{"text":"Picar {{Perejil fresco}} muy fino.","minutes":1,"kind":"prep"},{"text":"Mezclar en un bol el ajo picado, el perejil picado, {{Aceite de oliva virgen extra}} y {{Sal|gusto}}.","minutes":1,"kind":"prep"},{"text":"Colocar las setas en una bandeja de horno con la parte hueca hacia arriba.","minutes":1,"kind":"prep"},{"text":"Repartir la mezcla de ajo y perejil sobre cada seta hasta que queden bien impregnadas.","minutes":2,"kind":"activo"},{"text":"Hornear en la bandeja central hasta que las setas estén doradas y hayan soltado su jugo.","minutes":18,"kind":"pasivo"},{"text":"Retirar la bandeja del horno y regar las setas con el jugo que hayan soltado.","minutes":1,"kind":"activo"},{"text":"Servir las setas calientes, recién salidas del horno.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'horno', NULL)
