insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id, extra_proteins, freezable, steps_rich, estrella, occasion, kid_favourite, tecnica, cocina
) values
  ('ensaladas_verduras_095', 'Espárragos trigueros a la brasa con romesco', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'plancha', 35, 'facil', 'all', 505, 10, 21, 43, 2, true, true, '{"frutos_secos","gluten","sulfitos"}', '[{"name":"Espárragos trigueros","amount":300,"unit":"g"},{"name":"Tomate","amount":100,"unit":"g"},{"name":"Pimiento choricero (pulpa)","amount":20,"unit":"g"},{"name":"Almendras","amount":30,"unit":"g"},{"name":"Avellanas","amount":20,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Pan frito","amount":20,"unit":"g"},{"name":"Vinagre de jerez","amount":10,"unit":"ml"},{"name":"Aceite de oliva virgen extra","amount":55,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Calentar plancha a fuego fuerte hasta que esté bien caliente.","Tostar almendras y avellanas en una sartén sin aceite a fuego medio hasta que estén doradas.","Retirar las almendras y avellanas tostadas de la sartén y reservar.","Calentar aceite de oliva virgen extra en la misma sartén a fuego medio.","Freír pan frito en el aceite caliente hasta que esté dorado y crujiente.","Retirar el pan frito y reservar. Añadir tomate a la misma sartén.","Asar el tomate a fuego medio hasta que esté blando y la piel se despegue.","Pelar el tomate asado cuando esté templado y reservar.","Pelar ajo y reservar.","Triturar en una batidora el tomate pelado, pimiento choricero (pulpa), las almendras y avellanas tostadas, el ajo, el pan frito y vinagre de jerez.","Añadir el aceite de oliva virgen extra restante poco a poco mientras se tritura hasta obtener una salsa espesa y homogénea.","Añadir sal a la salsa romesco y triturar brevemente. Reservar.","Limpiar espárragos trigueros retirando la parte final más dura del tallo.","Pincelar los espárragos con un chorrito de aceite de oliva virgen extra.","Asar los espárragos en la plancha caliente hasta que estén tiernos con marcas de brasa, dándoles la vuelta a mitad.","Servir los espárragos calientes con la salsa romesco napada por encima o aparte."}', 'Espárragos trigueros marcados a la plancha sobre una salsa romesco espesa de frutos secos.', '[{"appliance":"airfryer","time":28,"difficulty":"facil","prepSummary":"Cocina los espárragos en la airfryer a 190°C durante 12-15 minutos, agitándolos a mitad para un dorado uniforme. Asa también los tomates y ajos para la romesco antes de triturar todos los ingredientes de la salsa."},{"appliance":"horno","time":38,"difficulty":"facil","prepSummary":"Asa los espárragos, tomates y ajos en el horno precalentado a 200°C durante 20-25 minutos hasta que estén tiernos y ligeramente dorados. Luego, tritura los ingredientes asados con el resto para la salsa romesco."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura","frutos_secos"}', NULL, '{}'::main_protein[], false, '[{"text":"Calentar {{@Plancha}} a fuego fuerte hasta que esté bien caliente.","minutes":3,"kind":"activo","part":"principal"},{"text":"Tostar {{Almendras}} y {{Avellanas}} en una sartén sin aceite a fuego medio hasta que estén doradas.","minutes":3,"kind":"activo","part":"salsa"},{"text":"Retirar las almendras y avellanas tostadas de la sartén y reservar.","minutes":1,"kind":"prep","part":"salsa"},{"text":"Calentar {{Aceite de oliva virgen extra|chorrito}} en la misma sartén a fuego medio.","minutes":1,"kind":"activo","part":"salsa"},{"text":"Freír {{Pan frito}} en el aceite caliente hasta que esté dorado y crujiente.","minutes":2,"kind":"activo","part":"salsa"},{"text":"Retirar el pan frito y reservar. Añadir {{Tomate}} a la misma sartén.","minutes":1,"kind":"activo","part":"salsa"},{"text":"Asar el tomate a fuego medio hasta que esté blando y la piel se despegue.","minutes":8,"kind":"pasivo","part":"salsa"},{"text":"Pelar el tomate asado cuando esté templado y reservar.","minutes":2,"kind":"prep","part":"salsa"},{"text":"Pelar {{Ajo}} y reservar.","minutes":1,"kind":"prep","part":"salsa"},{"text":"Triturar en una batidora el tomate pelado, {{Pimiento choricero (pulpa)}}, las almendras y avellanas tostadas, el ajo, el pan frito y {{Vinagre de jerez}}.","minutes":2,"kind":"activo","part":"salsa"},{"text":"Añadir el aceite de oliva virgen extra restante poco a poco mientras se tritura hasta obtener una salsa espesa y homogénea.","minutes":2,"kind":"activo","part":"salsa"},{"text":"Añadir {{Sal|gusto}} a la salsa romesco y triturar brevemente. Reservar.","minutes":1,"kind":"prep","part":"salsa"},{"text":"Limpiar {{Espárragos trigueros}} retirando la parte final más dura del tallo.","minutes":2,"kind":"prep","part":"principal"},{"text":"Pincelar los espárragos con un chorrito de aceite de oliva virgen extra.","minutes":1,"kind":"prep","part":"principal"},{"text":"Asar los espárragos en la plancha caliente hasta que estén tiernos con marcas de brasa, dándoles la vuelta a mitad.","minutes":5,"kind":"activo","part":"principal"},{"text":"Servir los espárragos calientes con la salsa romesco napada por encima o aparte.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true, NULL, NULL, 'plancha', NULL),
  ('ensaladas_verduras_096', 'Repollo braseado con miso y sésamo', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 25, 'normal', 'all', 220, 5, 17, 15, 2, true, true, '{"soja","sesamo","gluten"}', '[{"name":"Repollo","amount":400,"unit":"g"},{"name":"Aceite de sésamo","amount":10,"unit":"ml"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Miso","amount":20,"unit":"g"},{"name":"Salsa de soja","amount":15,"unit":"ml"},{"name":"Sésamo tostado","amount":10,"unit":"g"},{"name":"Jengibre fresco","amount":8,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Agua","amount":40,"unit":"ml"}]'::jsonb, '{"Cortar repollo en gajos gruesos, dejando parte del tronco para que no se deshagan.","Picar ajo y jengibre fresco muy finos.","Calentar aceite de oliva y aceite de sésamo en sartén amplia a fuego medio-alto.","Colocar los gajos de repollo en sartén y dorar 3 min por cada lado hasta que tomen color.","Mezclar miso con salsa de soja y agua en un bol hasta que se disuelva bien.","Añadir el ajo picado y el jengibre picado a la mezcla de miso y remover para integrar.","Verter la mezcla de miso sobre los gajos de repollo, tapar la sartén y cocer a fuego suave.","Cocer tapado a fuego suave hasta que el repollo esté tierno y caramelizado.","Destapar y subir a fuego medio hasta que el líquido reduzca y quede una salsa espesa.","Servir los gajos de repollo espolvoreados con sésamo tostado."}', 'Gajos de repollo braseados hasta caramelizarse, con una glasa de miso y sésamo tostado.', '[{"appliance":"horno","time":30,"difficulty":"normal","prepSummary":"Corta el repollo en gajos, rocía con aceite de oliva y asa a 180°C durante 20-25 minutos hasta que esté tierno. Luego, vierte la mezcla de miso, soja, jengibre, ajo, aceite de sésamo y agua, y hornea 5-10 minutos más para que se glasee."},{"appliance":"thermomix","time":20,"difficulty":"normal","prepSummary":"Pica el ajo y jengibre, sofríe con aceite. Añade el repollo troceado, la mezcla de miso, soja, aceite de sésamo y agua. Cocina 15-20 minutos a 100°C, velocidad cuchara, giro inverso, hasta que el repollo esté tierno y bien impregnado."},{"appliance":"olla_express","time":15,"difficulty":"normal","prepSummary":"Sofríe el ajo y jengibre con aceite. Incorpora el repollo troceado y la mezcla de miso, soja, aceite de sésamo y agua. Cierra la olla y cocina a presión durante 3-5 minutos. Libera la presión y remueve para que el repollo absorba bien la salsa."},{"appliance":"airfryer","time":20,"difficulty":"facil","prepSummary":"Corta el repollo en gajos, rocía con aceite de oliva y cocina en la airfryer a 180°C durante 15-20 minutos, dándole la vuelta a mitad, hasta que esté tierno y ligeramente dorado. Luego, mezcla con la salsa de miso, soja, jengibre, ajo, aceite de sésamo y agua."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], false, '[{"text":"Cortar {{Repollo}} en gajos gruesos, dejando parte del tronco para que no se deshagan.","minutes":3,"kind":"prep"},{"text":"Picar {{Ajo}} y {{Jengibre fresco}} muy finos.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva}} y {{Aceite de sésamo}} en {{@Sartén}} amplia a fuego medio-alto.","minutes":1,"kind":"activo"},{"text":"Colocar los gajos de repollo en {{@Sartén}} y dorar 3 min por cada lado hasta que tomen color.","minutes":6,"kind":"activo"},{"text":"Mezclar {{Miso}} con {{Salsa de soja}} y {{Agua}} en un bol hasta que se disuelva bien.","minutes":1,"kind":"prep"},{"text":"Añadir el ajo picado y el jengibre picado a la mezcla de miso y remover para integrar.","minutes":1,"kind":"prep"},{"text":"Verter la mezcla de miso sobre los gajos de repollo, tapar la sartén y cocer a fuego suave.","minutes":1,"kind":"activo"},{"text":"Cocer tapado a fuego suave hasta que el repollo esté tierno y caramelizado.","minutes":11,"kind":"pasivo"},{"text":"Destapar y subir a fuego medio hasta que el líquido reduzca y quede una salsa espesa.","minutes":3,"kind":"activo"},{"text":"Servir los gajos de repollo espolvoreados con {{Sésamo tostado}}.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'plancha', NULL),
  ('ensaladas_verduras_097', 'Zanahorias asadas enteras con comino y yogur', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'horno', 35, 'facil', 'all', 235, 7, 26, 13, 2, true, true, '{"lactosa"}', '[{"name":"Zanahoria","amount":400,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Comino molido","amount":3,"unit":"g"},{"name":"Miel","amount":10,"unit":"g"},{"name":"Yogur griego","amount":100,"unit":"g"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Zumo de limón","amount":10,"unit":"ml"},{"name":"Perejil fresco","amount":5,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C con calor arriba y abajo.","Lavar zanahoria bajo el grifo y secar con papel de cocina.","Cortar las zanahorias en mitades a lo largo si son gruesas; dejarlas enteras si son finas.","Mezclar en un bol aceite de oliva, comino molido, miel y sal hasta integrar.","Disponer las zanahorias en una bandeja de horno y verter la mezcla de aceite y especias por encima.","Remover las zanahorias en la bandeja hasta que queden bien impregnadas de la mezcla.","Hornear las zanahorias durante 25 min, dándoles la vuelta a los 12 min, hasta que estén tiernas y caramelizadas.","Rallar ajo muy fino sobre un bol pequeño.","Añadir yogur griego, zumo de limón y sal al bol con el ajo rallado.","Mezclar el yogur, el ajo, el zumo de limón y la sal hasta obtener una salsa homogénea.","Picar perejil fresco fino y reservar.","Extender la salsa de yogur en la base de una fuente de servir.","Colocar las zanahorias asadas encima de la salsa de yogur.","Terminar con el perejil picado por encima y servir templado."}', 'Zanahorias enteras asadas con comino sobre una base cremosa de yogur y ajo.', '[{"appliance":"horno","time":35,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C. Mezcla las zanahorias con el aceite, comino, miel y sal, y ásalas durante 35 minutos hasta que estén tiernas y ligeramente caramelizadas. La salsa de yogur se prepara aparte mezclando el resto de ingredientes."},{"appliance":"airfryer","time":25,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190°C. Cubre las zanahorias con el aceite, comino, miel y sal, y cocínalas por 25 minutos, agitándolas a mitad de cocción, hasta que estén tiernas y doradas. La salsa de yogur se prepara aparte mezclando el resto de ingredientes."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura","lacteo"}', NULL, '{}'::main_protein[], false, '[{"text":"Precalentar el horno a 200 °C con calor arriba y abajo.","minutes":10,"kind":"pasivo"},{"text":"Lavar {{Zanahoria}} bajo el grifo y secar con papel de cocina.","minutes":2,"kind":"prep"},{"text":"Cortar las zanahorias en mitades a lo largo si son gruesas; dejarlas enteras si son finas.","minutes":2,"kind":"prep"},{"text":"Mezclar en un bol {{Aceite de oliva}}, {{Comino molido}}, {{Miel}} y {{Sal|gusto}} hasta integrar.","minutes":1,"kind":"prep"},{"text":"Disponer las zanahorias en una bandeja de horno y verter la mezcla de aceite y especias por encima.","minutes":1,"kind":"prep"},{"text":"Remover las zanahorias en la bandeja hasta que queden bien impregnadas de la mezcla.","minutes":1,"kind":"prep"},{"text":"Hornear las zanahorias durante 25 min, dándoles la vuelta a los 12 min, hasta que estén tiernas y caramelizadas.","minutes":25,"kind":"pasivo"},{"text":"Rallar {{Ajo}} muy fino sobre un bol pequeño.","minutes":1,"kind":"paralelo","during":6},{"text":"Añadir {{Yogur griego}}, {{Zumo de limón}} y {{Sal|gusto}} al bol con el ajo rallado.","minutes":1,"kind":"paralelo","during":6},{"text":"Mezclar el yogur, el ajo, el zumo de limón y la sal hasta obtener una salsa homogénea.","minutes":1,"kind":"paralelo","during":6},{"text":"Picar {{Perejil fresco}} fino y reservar.","minutes":1,"kind":"paralelo","during":6},{"text":"Extender la salsa de yogur en la base de una fuente de servir.","minutes":1,"kind":"emplatado"},{"text":"Colocar las zanahorias asadas encima de la salsa de yogur.","minutes":1,"kind":"emplatado"},{"text":"Terminar con el perejil picado por encima y servir templado.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'horno', NULL),
  ('ensaladas_verduras_098', 'Puerros confitados con vinagreta de mostaza', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 45, 'normal', 'all', 355, 3, 29, 26, 2, true, true, '{"mostaza","sulfitos"}', '[{"name":"Puerro","amount":400,"unit":"g"},{"name":"Aceite de oliva","amount":80,"unit":"ml"},{"name":"Mostaza de Dijon","amount":15,"unit":"g"},{"name":"Vinagre de jerez","amount":15,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Perejil fresco","amount":5,"unit":"g"}]'::jsonb, '{"Retirar las capas exteriores y la parte verde más dura de puerro.","Cortar los puerros en trozos de 6-8 cm.","Lavar los trozos de puerro bajo el grifo hasta eliminar toda la tierra entre las capas.","Colocar los trozos de puerro en una cazuela baja y cubrir con aceite de oliva hasta la mitad de su altura.","Confitar a fuego suave, con el aceite apenas burbujeando, hasta que los puerros estén muy tiernos al pincharlos.","Escurrir los puerros del aceite y reservar 2 cucharadas del aceite de confitar en un bol aparte.","Dejar templar los puerros escurridos.","Picar perejil fresco fino y reservar.","Añadir mostaza de dijon, vinagre de jerez y sal al bol con el aceite de confitar reservado.","Mezclar enérgicamente hasta obtener una vinagreta homogénea.","Disponer los puerros templados en una fuente y rociar con la vinagreta de mostaza.","Terminar con el perejil fresco picado y servir templado o a temperatura ambiente."}', 'Puerros confitados hasta quedar tiernos, con una vinagreta de mostaza con carácter.', '[{"appliance":"horno","time":60,"difficulty":"normal","prepSummary":"Para confitar los puerros en el horno, colócalos limpios y troceados en una fuente apta, cúbrelos con el aceite de oliva y hornea a 150°C durante 60 minutos hasta que estén muy tiernos. La cocción lenta y uniforme es clave para el confitado."},{"appliance":"thermomix","time":50,"difficulty":"normal","prepSummary":"En la Thermomix, trocea los puerros y confítalos con el aceite de oliva a 90-100°C, velocidad cuchara y giro inverso, durante unos 50 minutos. Esto asegura una cocción suave y homogénea, ideal para el confitado."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Retirar las capas exteriores y la parte verde más dura de {{Puerro}}.","minutes":3,"kind":"prep"},{"text":"Cortar los puerros en trozos de 6-8 cm.","minutes":2,"kind":"prep"},{"text":"Lavar los trozos de puerro bajo el grifo hasta eliminar toda la tierra entre las capas.","minutes":2,"kind":"prep"},{"text":"Colocar los trozos de puerro en una cazuela baja y cubrir con {{Aceite de oliva}} hasta la mitad de su altura.","minutes":2,"kind":"activo"},{"text":"Confitar a fuego suave, con el aceite apenas burbujeando, hasta que los puerros estén muy tiernos al pincharlos.","minutes":30,"kind":"pasivo"},{"text":"Escurrir los puerros del aceite y reservar 2 cucharadas del aceite de confitar en un bol aparte.","minutes":2,"kind":"activo"},{"text":"Dejar templar los puerros escurridos.","minutes":10,"kind":"espera"},{"text":"Picar {{Perejil fresco}} fino y reservar.","minutes":2,"kind":"paralelo","during":6},{"text":"Añadir {{Mostaza de Dijon}}, {{Vinagre de jerez}} y {{Sal|gusto}} al bol con el aceite de confitar reservado.","minutes":1,"kind":"activo"},{"text":"Mezclar enérgicamente hasta obtener una vinagreta homogénea.","minutes":1,"kind":"activo"},{"text":"Disponer los puerros templados en una fuente y rociar con la vinagreta de mostaza.","minutes":1,"kind":"emplatado"},{"text":"Terminar con el perejil fresco picado y servir templado o a temperatura ambiente.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL),
  ('ensaladas_verduras_099', 'Calabaza asada con tahini y granada', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'horno', 40, 'facil', 'all', 262, 5, 21, 18, 2, true, true, '{"sesamo"}', '[{"name":"Calabaza","amount":400,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Comino molido","amount":3,"unit":"g"},{"name":"Canela molida","amount":1,"unit":"g"},{"name":"Tahini","amount":30,"unit":"g"},{"name":"Zumo de limón","amount":15,"unit":"ml"},{"name":"Agua","amount":15,"unit":"ml"},{"name":"Granada (arilos)","amount":50,"unit":"g"},{"name":"Perejil fresco","amount":5,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C.","Pelar calabaza y cortarla en gajos grandes.","Mezclar los gajos de calabaza con aceite de oliva, comino molido, canela molida y sal.","Repartir los gajos de calabaza en una bandeja de horno en una sola capa.","Hornear durante 30 min hasta que la calabaza esté tierna y dorada por los bordes.","Dar la vuelta a los gajos de calabaza a mitad de cocción.","Mezclar tahini con zumo de limón, agua y sal hasta obtener una salsa cremosa.","Picar perejil fresco fino.","Disponer los gajos de calabaza en una fuente.","Rociar la calabaza con la salsa de tahini.","Añadir granada (arilos) y el perejil fresco picado. Servir templada."}', 'Calabaza asada dulce y tierna, bañada en salsa de tahini y coronada con granada.', '[{"appliance":"horno","time":40,"difficulty":"facil","prepSummary":"Corta la calabaza en dados, mezcla con aceite, comino, canela y sal. Ásala en el horno precalentado a 190°C durante 30-35 minutos hasta que esté tierna y ligeramente dorada."},{"appliance":"airfryer","time":20,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190-200°C. Cocina la calabaza aderezada en una sola capa durante 15-20 minutos, agitándola a mitad del tiempo para un dorado uniforme y una textura tierna."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], false, '[{"text":"Precalentar el horno a 200 °C.","minutes":10,"kind":"pasivo"},{"text":"Pelar {{Calabaza}} y cortarla en gajos grandes.","minutes":5,"kind":"prep","part":"principal"},{"text":"Mezclar los gajos de calabaza con {{Aceite de oliva}}, {{Comino molido}}, {{Canela molida}} y {{Sal|gusto}}.","minutes":2,"kind":"prep","part":"principal"},{"text":"Repartir los gajos de calabaza en una bandeja de horno en una sola capa.","minutes":1,"kind":"prep","part":"principal"},{"text":"Hornear durante 30 min hasta que la calabaza esté tierna y dorada por los bordes.","minutes":30,"kind":"pasivo","part":"principal"},{"text":"Dar la vuelta a los gajos de calabaza a mitad de cocción.","minutes":1,"kind":"activo","part":"principal"},{"text":"Mezclar {{Tahini}} con {{Zumo de limón}}, {{Agua}} y {{Sal|gusto}} hasta obtener una salsa cremosa.","minutes":3,"kind":"paralelo","part":"salsa","during":4},{"text":"Picar {{Perejil fresco}} fino.","minutes":2,"kind":"paralelo","part":"combinado","during":4},{"text":"Disponer los gajos de calabaza en una fuente.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Rociar la calabaza con la salsa de tahini.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Añadir {{Granada (arilos)}} y el perejil fresco picado. Servir templada.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true, NULL, NULL, 'horno', 'mediterranea'),
  ('ensaladas_verduras_100', 'Berenjenas a la miso (nasu dengaku)', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'horno', 35, 'normal', 'all', 235, 6, 22, 15, 2, false, true, '{"soja","sesamo"}', '[{"name":"Berenjena","amount":400,"unit":"g"},{"name":"Miso blanco","amount":40,"unit":"g"},{"name":"Mirin","amount":30,"unit":"ml"},{"name":"Azúcar moreno","amount":15,"unit":"g"},{"name":"Aceite de sésamo","amount":15,"unit":"ml"},{"name":"Semillas de sésamo","amount":8,"unit":"g"},{"name":"Cebolleta","amount":10,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 220 °C con función grill.","Cortar berenjena por la mitad a lo largo.","Hacer cortes en rombo en la carne de cada mitad sin llegar a la piel.","Pincelar la carne de las berenjenas con la mitad de aceite de sésamo.","Colocar las berenjenas boca abajo en una bandeja de horno.","Hornear 20 min hasta que la carne esté tierna.","Picar cebolleta en rodajas finas y reservar.","Calentar en un cazo miso blanco, mirin, azúcar moreno y el resto del aceite de sésamo a fuego suave.","Remover sin parar hasta que el glaseado sea brillante y homogéneo, unos 3 min.","Dar la vuelta a las berenjenas y pincelar generosamente la carne con el glaseado de miso.","Gratinar con el grill 3 min hasta que el glaseado burbujee y se oscurezca sin quemarse.","Espolvorear semillas de sésamo sobre las berenjenas.","Espolvorear la cebolleta picada y servir templadas."}', 'Berenjenas asadas con un glaseado de miso oscuro y brillante, dulce y salado a la vez, gratinado hasta caramelizar.', '[{"appliance":"horno","time":35,"difficulty":"normal","prepSummary":"Asa las berenjenas a 200°C hasta que estén tiernas (aprox. 25-30 min). Luego, úntalas con la salsa de miso y gratina unos minutos hasta que la salsa burbujee y se caramelice ligeramente."},{"appliance":"airfryer","time":25,"difficulty":"facil","prepSummary":"Cocina las berenjenas a 180-190°C en la airfryer durante 15-20 minutos hasta que estén tiernas. Después, pincela con la salsa de miso y cocina 3-5 minutos más a 200°C para caramelizar."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], false, '[{"text":"Precalentar el horno a 220 °C con función grill.","minutes":10,"kind":"pasivo"},{"text":"Cortar {{Berenjena}} por la mitad a lo largo.","minutes":2,"kind":"prep"},{"text":"Hacer cortes en rombo en la carne de cada mitad sin llegar a la piel.","minutes":2,"kind":"prep"},{"text":"Pincelar la carne de las berenjenas con la mitad de {{Aceite de sésamo}}.","minutes":1,"kind":"prep"},{"text":"Colocar las berenjenas boca abajo en una bandeja de horno.","minutes":1,"kind":"prep"},{"text":"Hornear 20 min hasta que la carne esté tierna.","minutes":20,"kind":"pasivo"},{"text":"Picar {{Cebolleta}} en rodajas finas y reservar.","minutes":2,"kind":"paralelo","during":5},{"text":"Calentar en un cazo {{Miso blanco}}, {{Mirin}}, {{Azúcar moreno}} y el resto del aceite de sésamo a fuego suave.","minutes":1,"kind":"paralelo","during":5},{"text":"Remover sin parar hasta que el glaseado sea brillante y homogéneo, unos 3 min.","minutes":3,"kind":"paralelo","during":5},{"text":"Dar la vuelta a las berenjenas y pincelar generosamente la carne con el glaseado de miso.","minutes":2,"kind":"activo"},{"text":"Gratinar con el grill 3 min hasta que el glaseado burbujee y se oscurezca sin quemarse.","minutes":3,"kind":"pasivo"},{"text":"Espolvorear {{Semillas de sésamo}} sobre las berenjenas.","minutes":1,"kind":"emplatado"},{"text":"Espolvorear la cebolleta picada y servir templadas.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'horno', NULL),
  ('ensaladas_verduras_101', 'Coles de Bruselas laqueadas con miel picante', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'horno', 30, 'facil', 'invierno', 165, 5, 22, 7, 2, false, true, '{}', '[{"name":"Coles de Bruselas","amount":400,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Miel","amount":30,"unit":"g"},{"name":"Guindilla en copos","amount":2,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Zumo de limón","amount":15,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C.","Limpiar coles de bruselas y cortar cada una por la mitad.","Picar ajo muy fino.","Colocar las coles en una bandeja, añadir aceite de oliva y sal y mezclar hasta que queden bien impregnadas.","Hornear las coles a 200 °C durante 22 min hasta que estén doradas y crujientes por fuera.","Mezclar en un bol el ajo picado, miel, guindilla en copos y zumo de limón.","Remover la bandeja a mitad de la cocción para que las coles se doren de forma uniforme.","Calentar la mezcla de miel en una sartén a fuego medio durante 2 min hasta que espese ligeramente.","Verter el laqueado sobre las coles recién salidas del horno.","Remover bien para que las coles queden cubiertas con el laqueado.","Servir las coles calientes de inmediato."}', 'Coles de Bruselas asadas hasta quedar crujientes y laqueadas con un glaseado de miel picante, brillante y pegajoso.', '[{"appliance":"horno","time":30,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C. Mezcla las coles con el aceite, sal y ajo, y ásalas en una bandeja durante 20 minutos. Luego, añade la miel y guindilla, y hornea 10 minutos más hasta que estén tiernas y caramelizadas."},{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190°C. Cocina las coles mezcladas con aceite, sal y ajo durante 12-15 minutos, agitando la cesta a mitad del tiempo. Luego, incorpora la miel y guindilla, y cocina 3-5 minutos más hasta que estén bien lacadas y crujientes."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], false, '[{"text":"Precalentar el horno a 200 °C.","minutes":10,"kind":"pasivo"},{"text":"Limpiar {{Coles de Bruselas}} y cortar cada una por la mitad.","minutes":3,"kind":"prep"},{"text":"Picar {{Ajo}} muy fino.","minutes":1,"kind":"prep"},{"text":"Colocar las coles en una bandeja, añadir {{Aceite de oliva|chorrito}} y {{Sal|gusto}} y mezclar hasta que queden bien impregnadas.","minutes":2,"kind":"activo"},{"text":"Hornear las coles a 200 °C durante 22 min hasta que estén doradas y crujientes por fuera.","minutes":22,"kind":"pasivo"},{"text":"Mezclar en un bol el ajo picado, {{Miel}}, {{Guindilla en copos|pizca}} y {{Zumo de limón}}.","minutes":2,"kind":"paralelo","during":4},{"text":"Remover la bandeja a mitad de la cocción para que las coles se doren de forma uniforme.","minutes":1,"kind":"activo"},{"text":"Calentar la mezcla de miel en una {{@Sartén}} a fuego medio durante 2 min hasta que espese ligeramente.","minutes":2,"kind":"activo"},{"text":"Verter el laqueado sobre las coles recién salidas del horno.","minutes":1,"kind":"activo"},{"text":"Remover bien para que las coles queden cubiertas con el laqueado.","minutes":1,"kind":"activo"},{"text":"Servir las coles calientes de inmediato.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'horno', NULL),
  ('ensaladas_verduras_102', 'Alcachofas fritas a la judía', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 40, 'normal', 'invierno', 290, 6, 16, 22, 2, true, false, '{}', '[{"name":"Alcachofas","amount":4,"unit":"ud"},{"name":"Aceite de oliva","amount":300,"unit":"ml"},{"name":"Limón","amount":1,"unit":"ud"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Retirar las hojas exteriores más duras de alcachofas y cortar la punta y el tallo de cada una.","Exprimir limón y verter el zumo en un bol con agua fría.","Sumergir las alcachofas limpias en el agua con zumo de limón hasta tenerlas todas listas.","Calentar aceite de oliva en una cazuela honda a fuego medio hasta alcanzar 160 °C.","Sacar las alcachofas del agua y secar bien cada una con papel absorbente.","Golpear suavemente cada alcachofa boca abajo contra la encimera para abrir las hojas.","Freír las alcachofas boca abajo en el aceite caliente durante 10 min, hasta que estén tiernas al pincharlas.","Subir el fuego a fuego fuerte y freír 3 min más hasta que las hojas exteriores estén crujientes y doradas.","Escurrir las alcachofas sobre papel absorbente y salar con sal al momento.","Picar perejil fino.","Servir las alcachofas calientes con el perejil picado por encima y gajos del limón restante al lado."}', 'Alcachofas fritas enteras hasta que las hojas quedan doradas y crujientes por fuera, tiernas por dentro; se comen con las manos.', '[{"appliance":"airfryer","time":40,"difficulty":"normal","prepSummary":"Prepara las alcachofas limpiándolas y cortándolas, rocíalas con un poco de aceite de oliva, sal y zumo de limón. Cocínalas en la airfryer a 190°C durante 25-30 minutos, volteando a mitad, hasta que estén tiernas y doradas. El truco es no sobrecargar la cesta para asegurar una fri"},{"appliance":"horno","time":45,"difficulty":"normal","prepSummary":"Limpia y corta las alcachofas, mézclalas con un chorrito de aceite de oliva, sal y zumo de limón. Ásalas en el horno precalentado a 200°C (con ventilador si es posible) durante 35-45 minutos, volteándolas ocasionalmente, hasta que estén tiernas por dentro y crujientes por fuera."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], false, '[{"text":"Retirar las hojas exteriores más duras de {{Alcachofas}} y cortar la punta y el tallo de cada una.","minutes":5,"kind":"prep"},{"text":"Exprimir {{Limón}} y verter el zumo en un bol con agua fría.","minutes":1,"kind":"prep"},{"text":"Sumergir las alcachofas limpias en el agua con zumo de limón hasta tenerlas todas listas.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|abundante}} en una cazuela honda a fuego medio hasta alcanzar 160 °C.","minutes":4,"kind":"activo"},{"text":"Sacar las alcachofas del agua y secar bien cada una con papel absorbente.","minutes":2,"kind":"prep"},{"text":"Golpear suavemente cada alcachofa boca abajo contra la encimera para abrir las hojas.","minutes":1,"kind":"prep"},{"text":"Freír las alcachofas boca abajo en el aceite caliente durante 10 min, hasta que estén tiernas al pincharlas.","minutes":10,"kind":"pasivo"},{"text":"Subir el fuego a fuego fuerte y freír 3 min más hasta que las hojas exteriores estén crujientes y doradas.","minutes":3,"kind":"activo"},{"text":"Escurrir las alcachofas sobre papel absorbente y salar con {{Sal|gusto}} al momento.","minutes":1,"kind":"activo"},{"text":"Picar {{Perejil}} fino.","minutes":1,"kind":"prep"},{"text":"Servir las alcachofas calientes con el perejil picado por encima y gajos del limón restante al lado.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL),
  ('ensaladas_verduras_103', 'Tomates rellenos de arroz y verduras al horno', 'ensaladas_verduras', 'none', 'arroz', ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'horno', 55, 'normal', 'verano', 265, 8, 38, 9, 2, true, true, '{"lactosa"}', '[{"name":"Tomates grandes","amount":4,"unit":"ud"},{"name":"Arroz","amount":80,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Calabacín","amount":60,"unit":"g"},{"name":"Pimiento rojo","amount":60,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Queso rallado","amount":30,"unit":"g"},{"name":"Perejil","amount":5,"unit":"g"},{"name":"Caldo de verduras","amount":100,"unit":"ml"}]'::jsonb, '{"Precalentar el horno a 190 °C.","Cortar la tapa superior de tomates grandes y vaciar la pulpa con una cuchara.","Reservar la pulpa de tomate picada en un bol.","Picar cebolla, calabacín, pimiento rojo y ajo en dados pequeños.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla, el calabacín, el pimiento rojo y el ajo hasta que ablanden.","Añadir arroz y remover para que se impregne del sofrito.","Añadir la pulpa de tomate reservada y sofreír el conjunto.","Rellenar los tomates vaciados con la mezcla de arroz y verduras.","Colocar los tomates rellenos en una fuente de horno.","Verter caldo de verduras en el fondo de la fuente.","Cubrir cada tomate con queso rallado.","Hornear la fuente a 190 °C hasta que el arroz esté cocido y los tomates arrugados.","Picar perejil fino.","Espolvorear el perejil picado sobre los tomates y servir templados."}', 'Tomates asados con la piel arrugada y dulce, rellenos de un arroz colorido con verduras que se descubre al cortarlos.', '[{"appliance":"horno","time":55,"difficulty":"normal","prepSummary":"Prepara el relleno pochando las verduras y cociendo el arroz. Rellena los tomates y hornea a 180-200°C durante 30-40 minutos, hasta que estén tiernos y el queso gratinado."},{"appliance":"airfryer","time":50,"difficulty":"normal","prepSummary":"Prepara el relleno de arroz y verduras previamente en sartén. Rellena los tomates y cocínalos en la airfryer a 170-180°C durante 25-35 minutos, vigilando para que queden tiernos y ligeramente dorados."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], false, '[{"text":"Precalentar el horno a 190 °C.","minutes":10,"kind":"pasivo"},{"text":"Cortar la tapa superior de {{Tomates grandes}} y vaciar la pulpa con una cuchara.","minutes":4,"kind":"prep"},{"text":"Reservar la pulpa de tomate picada en un bol.","minutes":1,"kind":"prep"},{"text":"Picar {{Cebolla}}, {{Calabacín}}, {{Pimiento rojo}} y {{Ajo}} en dados pequeños.","minutes":4,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla, el calabacín, el pimiento rojo y el ajo hasta que ablanden.","minutes":9,"kind":"activo"},{"text":"Añadir {{Arroz}} y remover para que se impregne del sofrito.","minutes":1,"kind":"activo"},{"text":"Añadir la pulpa de tomate reservada y sofreír el conjunto.","minutes":2,"kind":"activo"},{"text":"Rellenar los tomates vaciados con la mezcla de arroz y verduras.","minutes":2,"kind":"prep"},{"text":"Colocar los tomates rellenos en una fuente de horno.","minutes":1,"kind":"prep"},{"text":"Verter {{Caldo de verduras}} en el fondo de la fuente.","minutes":1,"kind":"prep"},{"text":"Cubrir cada tomate con {{Queso rallado}}.","minutes":1,"kind":"prep"},{"text":"Hornear la fuente a 190 °C hasta que el arroz esté cocido y los tomates arrugados.","minutes":33,"kind":"pasivo"},{"text":"Picar {{Perejil}} fino.","minutes":1,"kind":"paralelo","during":12},{"text":"Espolvorear el perejil picado sobre los tomates y servir templados.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'horno', NULL),
  ('ensaladas_verduras_104', 'Champiñones portobello rellenos gratinados', 'ensaladas_verduras', 'none', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, 'horno', 35, 'normal', 'all', 320, 18, 12, 22, 2, true, true, '{"lactosa","gluten"}', '[{"name":"Champiñones portobello","amount":4,"unit":"ud"},{"name":"Queso de cabra","amount":100,"unit":"g"},{"name":"Pan rallado","amount":30,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Perejil","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Jamón serrano","amount":60,"unit":"g"},{"name":"Queso rallado","amount":40,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C.","Limpiar champiñones portobello con un paño húmedo y retirar el pie de cada uno.","Picar fino el pie de los champiñones y reservar.","Picar fino ajo.","Picar fino perejil y reservar.","Cortar jamón serrano en taquitos pequeños y reservar.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír el ajo picado en la sartén hasta que esté dorado, sin que se queme.","Añadir el pie de champiñón picado y sofreír hasta que evapore el agua y esté tierno.","Retirar la sartén del fuego y dejar que el sofrito temple 2 min.","Desmenuzar queso de cabra en un bol.","Añadir al bol el sofrito templado, el jamón en taquitos, pan rallado y el perejil picado.","Mezclar bien todos los ingredientes del bol hasta obtener un relleno homogéneo.","Disponer los sombreros de los champiñones boca arriba en una bandeja de horno.","Rellenar cada sombrero con la mezcla, presionando ligeramente para que quede compacta.","Cubrir cada champiñón relleno con queso rallado repartiéndolo de forma uniforme.","Hornear la bandeja en el horno a 200 °C durante 20 min, hasta que estén tiernos y gratinados.","Retirar la bandeja del horno y servir los champiñones calientes de inmediato."}', 'Sombreros grandes de champiñón portobello rellenos y gratinados, con presentación de plato único.', '[{"appliance":"horno","time":35,"difficulty":"normal","prepSummary":"Precalienta el horno a 190°C. Rellena los champiñones con la mezcla de queso de cabra, jamón, ajo y perejil, espolvorea con queso rallado y hornea durante 20-25 minutos hasta que estén dorados y gratinados."},{"appliance":"airfryer","time":30,"difficulty":"normal","prepSummary":"Prepara los champiñones y el relleno de la misma forma. Cocina en la airfryer a 180°C durante 15-20 minutos, vigilando que el queso se gratine sin quemarse y los champiñones estén tiernos."}]'::jsonb, '{}', NULL, NULL, NULL, '{"lacteo"}', NULL, ARRAY['cerdo']::main_protein[], false, '[{"text":"Precalentar el horno a 200 °C.","minutes":10,"kind":"pasivo"},{"text":"Limpiar {{Champiñones portobello}} con un paño húmedo y retirar el pie de cada uno.","minutes":3,"kind":"prep"},{"text":"Picar fino el pie de los champiñones y reservar.","minutes":2,"kind":"prep"},{"text":"Picar fino {{Ajo}}.","minutes":1,"kind":"prep"},{"text":"Picar fino {{Perejil}} y reservar.","minutes":1,"kind":"prep"},{"text":"Cortar {{Jamón serrano}} en taquitos pequeños y reservar.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír el ajo picado en la sartén hasta que esté dorado, sin que se queme.","minutes":2,"kind":"activo"},{"text":"Añadir el pie de champiñón picado y sofreír hasta que evapore el agua y esté tierno.","minutes":3,"kind":"activo"},{"text":"Retirar la sartén del fuego y dejar que el sofrito temple 2 min.","minutes":2,"kind":"espera"},{"text":"Desmenuzar {{Queso de cabra}} en un bol.","minutes":1,"kind":"prep"},{"text":"Añadir al bol el sofrito templado, el jamón en taquitos, {{Pan rallado}} y el perejil picado.","minutes":1,"kind":"prep"},{"text":"Mezclar bien todos los ingredientes del bol hasta obtener un relleno homogéneo.","minutes":1,"kind":"prep"},{"text":"Disponer los sombreros de los champiñones boca arriba en una bandeja de horno.","minutes":1,"kind":"prep"},{"text":"Rellenar cada sombrero con la mezcla, presionando ligeramente para que quede compacta.","minutes":2,"kind":"activo"},{"text":"Cubrir cada champiñón relleno con {{Queso rallado}} repartiéndolo de forma uniforme.","minutes":1,"kind":"activo"},{"text":"Hornear la bandeja en el horno a 200 °C durante 20 min, hasta que estén tiernos y gratinados.","minutes":20,"kind":"pasivo"},{"text":"Retirar la bandeja del horno y servir los champiñones calientes de inmediato.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'horno', NULL)
