  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id, extra_proteins, freezable, steps_rich, estrella, occasion, kid_favourite, tecnica, cocina
) values
  ('ensaladas_verduras_105', 'Brócoli asado con ajo negro', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'horno', 30, 'facil', 'all', 190, 7, 12, 14, 2, true, true, '{"frutos_secos"}', '[{"name":"Brócoli","amount":400,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Ajo negro","amount":20,"unit":"g"},{"name":"Zumo de limón","amount":10,"unit":"ml"},{"name":"Almendras laminadas","amount":20,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 220 °C.","Cortar brócoli en ramilletes de tamaño similar.","Laminar ajo.","Disponer el brócoli en una bandeja y añadir aceite de oliva, el ajo laminado y sal.","Mezclar bien para que el brócoli quede impregnado de aceite y especias.","Hornear en la bandeja central hasta que los bordes estén tostados y crujientes.","Machacar ajo negro con un chorrito de aceite de oliva hasta obtener una pasta homogénea.","Añadir zumo de limón a la pasta de ajo negro y mezclar hasta que quede una crema lisa.","Tostar almendras laminadas en sartén a fuego medio sin aceite hasta que se doren.","Retirar el brócoli del horno y disponerlo en la fuente de servicio.","Repartir la crema de ajo negro por encima del brócoli.","Esparcir las almendras tostadas y servir de inmediato."}', 'Brócoli asado con los bordes tostados y crujientes, coronado por el dulzor oscuro de una crema de ajo negro.', '[{"appliance":"horno","time":30,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C. Mezcla el brócoli con aceite, ajo picado y sal, y ásalo durante 25-30 minutos hasta que esté tierno y ligeramente dorado. Sirve con el ajo negro, zumo de limón y almendras."},{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190°C. Mezcla el brócoli con aceite, ajo picado y sal, y cocina en la cesta durante 15-18 minutos, agitando a mitad de cocción para un resultado uniforme. Añade el ajo negro, zumo de limón y almendras al servir."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura","frutos_secos"}', NULL, '{}'::main_protein[], false, '[{"text":"Precalentar el horno a 220 °C.","minutes":10,"kind":"pasivo","part":"principal"},{"text":"Cortar {{Brócoli}} en ramilletes de tamaño similar.","minutes":3,"kind":"prep","part":"principal"},{"text":"Laminar {{Ajo}}.","minutes":2,"kind":"prep","part":"principal"},{"text":"Disponer el brócoli en una bandeja y añadir {{Aceite de oliva|chorrito}}, el ajo laminado y {{Sal|gusto}}.","minutes":2,"kind":"activo","part":"principal"},{"text":"Mezclar bien para que el brócoli quede impregnado de aceite y especias.","minutes":1,"kind":"activo","part":"principal"},{"text":"Hornear en la bandeja central hasta que los bordes estén tostados y crujientes.","minutes":20,"kind":"pasivo","part":"principal"},{"text":"Machacar {{Ajo negro}} con un chorrito de aceite de oliva hasta obtener una pasta homogénea.","minutes":2,"kind":"activo","part":"salsa"},{"text":"Añadir {{Zumo de limón}} a la pasta de ajo negro y mezclar hasta que quede una crema lisa.","minutes":1,"kind":"activo","part":"salsa"},{"text":"Tostar {{Almendras laminadas}} en {{@Sartén}} a fuego medio sin aceite hasta que se doren.","minutes":3,"kind":"activo","part":"guarnicion"},{"text":"Retirar el brócoli del horno y disponerlo en la fuente de servicio.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Repartir la crema de ajo negro por encima del brócoli.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Esparcir las almendras tostadas y servir de inmediato.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true, NULL, NULL, 'horno', NULL),
  ('ensaladas_verduras_106', 'Escalivada con anchoas y aceite de oliva', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, 'horno', 60, 'facil', 'verano', 200, 7, 13, 14, 2, false, true, '{"pescado"}', '[{"name":"Berenjena","amount":300,"unit":"g"},{"name":"Pimiento rojo","amount":300,"unit":"g"},{"name":"Cebolla","amount":150,"unit":"g"},{"name":"Anchoas en aceite","amount":40,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":30,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C con calor arriba y abajo.","Lavar berenjena, pimiento rojo y cebolla bajo el grifo y secar bien.","Disponer las verduras enteras y con piel sobre la bandeja del horno.","Hornear las verduras a 200 °C hasta que la piel esté ennegrecida y la carne muy tierna.","Picar ajo muy fino y reservar.","Retirar la bandeja del horno y tapar las verduras con un paño limpio.","Esperar tapadas hasta que suden y se pelen con facilidad.","Pelar las verduras retirando la piel ennegrecida.","Retirar las semillas y los tallos de la berenjena, el pimiento rojo y la cebolla.","Cortar la carne de las verduras en tiras longitudinales.","Disponer las tiras de verdura en una fuente alargada alternando colores.","Repartir anchoas en aceite sobre las verduras.","Añadir el ajo picado y distribuirlo de manera uniforme sobre la fuente.","Aliñar con aceite de oliva virgen extra y sal.","Reposar la escalivada a temperatura ambiente antes de servir."}', 'Verduras asadas de colores ahumados, en tiras, rematadas con anchoas saladas y un buen aceite de oliva.', '[{"appliance":"horno","time":60,"difficulty":"facil","prepSummary":"Asar las verduras enteras o en mitades a 180-200°C durante 45-60 minutos hasta que estén tiernas y la piel ligeramente quemada. Un truco clave es taparlas al sacarlas para que suden y pelarlas fácilmente."},{"appliance":"airfryer","time":35,"difficulty":"facil","prepSummary":"Cortar las verduras en trozos grandes, rociar con aceite y sal. Cocinar en la airfryer a 180-190°C durante 30-40 minutos, removiendo a mitad, hasta que estén tiernas y con la piel ligeramente chamuscada."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, ARRAY['pescado_azul']::main_protein[], false, '[{"text":"Precalentar el horno a 200 °C con calor arriba y abajo.","minutes":10,"kind":"pasivo"},{"text":"Lavar {{Berenjena}}, {{Pimiento rojo}} y {{Cebolla}} bajo el grifo y secar bien.","minutes":3,"kind":"prep"},{"text":"Disponer las verduras enteras y con piel sobre la bandeja del horno.","minutes":2,"kind":"prep"},{"text":"Hornear las verduras a 200 °C hasta que la piel esté ennegrecida y la carne muy tierna.","minutes":50,"kind":"pasivo"},{"text":"Picar {{Ajo}} muy fino y reservar.","minutes":3,"kind":"paralelo","during":3},{"text":"Retirar la bandeja del horno y tapar las verduras con un paño limpio.","minutes":1,"kind":"activo"},{"text":"Esperar tapadas hasta que suden y se pelen con facilidad.","minutes":10,"kind":"espera"},{"text":"Pelar las verduras retirando la piel ennegrecida.","minutes":4,"kind":"prep"},{"text":"Retirar las semillas y los tallos de la berenjena, el pimiento rojo y la cebolla.","minutes":2,"kind":"prep"},{"text":"Cortar la carne de las verduras en tiras longitudinales.","minutes":3,"kind":"prep"},{"text":"Disponer las tiras de verdura en una fuente alargada alternando colores.","minutes":2,"kind":"emplatado"},{"text":"Repartir {{Anchoas en aceite}} sobre las verduras.","minutes":1,"kind":"emplatado"},{"text":"Añadir el ajo picado y distribuirlo de manera uniforme sobre la fuente.","minutes":1,"kind":"emplatado"},{"text":"Aliñar con {{Aceite de oliva virgen extra}} y {{Sal|gusto}}.","minutes":1,"kind":"emplatado"},{"text":"Reposar la escalivada a temperatura ambiente antes de servir.","minutes":15,"kind":"espera"}]'::jsonb, true, NULL, NULL, 'horno', NULL),
  ('ensaladas_verduras_107', 'Espinacas con garbanzos a la andaluza', 'ensaladas_verduras', 'legumbre', NULL, ARRAY['primero','plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'facil', 'all', 315, 14, 34, 14, 2, true, true, '{"gluten","sulfitos"}', '[{"name":"Espinacas frescas","amount":300,"unit":"g"},{"name":"Garbanzos cocidos","amount":300,"unit":"g"},{"name":"Pan","amount":30,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Comino","amount":2,"unit":"g"},{"name":"Pimentón","amount":3,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Vinagre de jerez","amount":10,"unit":"ml"}]'::jsonb, '{"Cortar pan en dados pequeños.","Laminar ajo.","Calentar aceite de oliva en sartén a fuego medio.","Freír los dados de pan en el aceite caliente hasta que estén dorados y crujientes.","Retirar el pan frito con una espumadera y reservar en un plato.","Freír el ajo laminado en el mismo aceite a fuego medio hasta que se dore ligeramente.","Retirar el ajo frito y reservar junto al pan.","Machacar en un mortero el pan frito y el ajo frito reservados hasta obtener una pasta.","Añadir comino y pimentón al mortero y seguir machacando hasta integrar.","Incorporar un chorrito de agua al majado y mezclar hasta lograr una pasta homogénea.","Sofreír espinacas frescas en la misma sartén a fuego medio hasta que reduzcan su volumen.","Añadir garbanzos cocidos a las espinacas y remover para integrar.","Incorporar el majado a la sartén y remover bien hasta que todo quede integrado.","Añadir vinagre de jerez y remover.","Cocer a fuego suave hasta que la salsa espese ligeramente, removiendo de vez en cuando.","Servir caliente en platos hondos."}', 'Espinacas guisadas con garbanzos, majado de pan frito y especias, con el toque crujiente del pan y aroma andaluz.', '[{"appliance":"horno","time":45,"difficulty":"facil","prepSummary":"Sofríe el ajo y el pan en una sartén. Combina con el resto de ingredientes en una fuente apta para horno y hornea a 180°C durante 25-30 minutos para que los sabores se integren bien."},{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Pica el ajo y sofríelo con el pan y el aceite. Añade las espinacas, garbanzos, especias y vinagre, cocinando a 100°C, giro inverso, velocidad cuchara durante 15-20 minutos hasta que las espinacas estén tiernas y los sabores ligados."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], true, '[{"text":"Cortar {{Pan}} en dados pequeños.","minutes":2,"kind":"prep"},{"text":"Laminar {{Ajo}}.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva}} en {{@Sartén}} a fuego medio.","minutes":1,"kind":"activo"},{"text":"Freír los dados de pan en el aceite caliente hasta que estén dorados y crujientes.","minutes":4,"kind":"activo"},{"text":"Retirar el pan frito con una espumadera y reservar en un plato.","minutes":1,"kind":"activo"},{"text":"Freír el ajo laminado en el mismo aceite a fuego medio hasta que se dore ligeramente.","minutes":2,"kind":"activo"},{"text":"Retirar el ajo frito y reservar junto al pan.","minutes":1,"kind":"activo"},{"text":"Machacar en un mortero el pan frito y el ajo frito reservados hasta obtener una pasta.","minutes":2,"kind":"activo"},{"text":"Añadir {{Comino}} y {{Pimentón}} al mortero y seguir machacando hasta integrar.","minutes":1,"kind":"activo"},{"text":"Incorporar un chorrito de agua al majado y mezclar hasta lograr una pasta homogénea.","minutes":1,"kind":"activo"},{"text":"Sofreír {{Espinacas frescas}} en la misma {{@Sartén}} a fuego medio hasta que reduzcan su volumen.","minutes":4,"kind":"activo"},{"text":"Añadir {{Garbanzos cocidos}} a las espinacas y remover para integrar.","minutes":1,"kind":"activo"},{"text":"Incorporar el majado a la sartén y remover bien hasta que todo quede integrado.","minutes":1,"kind":"activo"},{"text":"Añadir {{Vinagre de jerez}} y remover.","minutes":1,"kind":"activo"},{"text":"Cocer a fuego suave hasta que la salsa espese ligeramente, removiendo de vez en cuando.","minutes":9,"kind":"pasivo"},{"text":"Servir caliente en platos hondos.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'olla', NULL),
  ('ensaladas_verduras_108', 'Pimientos del piquillo rellenos de brandada', 'ensaladas_verduras', 'pescado_blanco', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, 'horno', 45, 'normal', 'all', 335, 21, 18, 20, 2, false, true, '{"pescado","lactosa"}', '[{"name":"Pimientos del piquillo","amount":8,"unit":"ud"},{"name":"Bacalao desalado","amount":200,"unit":"g"},{"name":"Patata","amount":150,"unit":"g"},{"name":"Leche","amount":100,"unit":"ml"},{"name":"Nata para cocinar","amount":50,"unit":"ml"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Pelar patata y cortar en trozos medianos.","Picar ajo fino y reservar.","Picar perejil fino y reservar.","Colocar la patata troceada y bacalao desalado en un cazo. Cubrir con leche y llevar a ebullición a fuego medio.","Cocer a fuego suave hasta que la patata y el bacalao estén tiernos.","Escurrir la patata y el bacalao, reservando el líquido de cocción en un bol.","Precalentar el horno a 180 °C.","Triturar la patata escurrida y el bacalao escurrido con el ajo picado en un bol hasta obtener una pasta homogénea.","Añadir aceite de oliva en hilo fino mientras se remueve la pasta hasta ligarla en crema.","Añadir nata para cocinar y remover hasta obtener una brandada suave.","Añadir un poco del líquido de cocción reservado si la brandada resulta demasiado espesa, hasta ajustar la textura.","Rellenar pimientos del piquillo con la brandada con ayuda de una cuchara.","Colocar los pimientos rellenos en una fuente de horno y hornear a 180 °C hasta que estén bien calientes.","Servir los pimientos espolvoreados con el perejil picado."}', 'Pimientos del piquillo de un rojo brillante rellenos de una brandada cremosa de bacalao.', NULL, '{}', NULL, NULL, NULL, '{"verdura","lacteo"}', NULL, '{}'::main_protein[], true, '[{"text":"Pelar {{Patata}} y cortar en trozos medianos.","minutes":3,"kind":"prep"},{"text":"Picar {{Ajo}} fino y reservar.","minutes":2,"kind":"prep"},{"text":"Picar {{Perejil}} fino y reservar.","minutes":1,"kind":"prep"},{"text":"Colocar la patata troceada y {{Bacalao desalado}} en un cazo. Cubrir con {{Leche}} y llevar a ebullición a fuego medio.","minutes":3,"kind":"activo"},{"text":"Cocer a fuego suave hasta que la patata y el bacalao estén tiernos.","minutes":15,"kind":"pasivo"},{"text":"Escurrir la patata y el bacalao, reservando el líquido de cocción en un bol.","minutes":2,"kind":"activo"},{"text":"Precalentar el horno a 180 °C.","minutes":10,"kind":"pasivo"},{"text":"Triturar la patata escurrida y el bacalao escurrido con el ajo picado en un bol hasta obtener una pasta homogénea.","minutes":3,"kind":"activo"},{"text":"Añadir {{Aceite de oliva|chorrito}} en hilo fino mientras se remueve la pasta hasta ligarla en crema.","minutes":2,"kind":"activo"},{"text":"Añadir {{Nata para cocinar}} y remover hasta obtener una brandada suave.","minutes":1,"kind":"activo"},{"text":"Añadir un poco del líquido de cocción reservado si la brandada resulta demasiado espesa, hasta ajustar la textura.","minutes":1,"kind":"activo"},{"text":"Rellenar {{Pimientos del piquillo}} con la brandada con ayuda de una cuchara.","minutes":5,"kind":"activo"},{"text":"Colocar los pimientos rellenos en una fuente de horno y hornear a 180 °C hasta que estén bien calientes.","minutes":12,"kind":"pasivo"},{"text":"Servir los pimientos espolvoreados con el perejil picado.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'horno', NULL),
  ('ensaladas_verduras_109', 'Calabacín a la plancha con menta y feta', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'verano', 220, 9, 8, 17, 2, true, true, '{"lactosa"}', '[{"name":"Calabacín","amount":400,"unit":"g"},{"name":"Queso feta","amount":100,"unit":"g"},{"name":"Menta fresca","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Zumo de limón","amount":10,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"},{"name":"Pimienta","amount":1,"unit":"g"}]'::jsonb, '{"Laminar calabacín en tiras longitudinales de 0,5 cm de grosor.","Calentar plancha a fuego fuerte con aceite de oliva.","Colocar las láminas de calabacín en la plancha y dorar 2 min por cada cara hasta que estén marcadas.","Retirar las láminas de calabacín y disponer en una fuente plana.","Desmenuzar queso feta con las manos sobre las láminas de calabacín.","Picar menta fresca y repartir sobre el plato.","Aliñar con aceite de oliva, zumo de limón, sal y pimienta.","Servir templado o a temperatura ambiente."}', 'Calabacín marcado a la plancha con el dorado bien visible, coronado con menta fresca y feta desmenuzado.', NULL, '{}', NULL, NULL, NULL, '{"verdura","lacteo"}', NULL, '{}'::main_protein[], false, '[{"text":"Laminar {{Calabacín}} en tiras longitudinales de 0,5 cm de grosor.","minutes":3,"kind":"prep"},{"text":"Calentar {{@Plancha}} a fuego fuerte con {{Aceite de oliva|chorrito}}.","minutes":2,"kind":"activo"},{"text":"Colocar las láminas de calabacín en la plancha y dorar 2 min por cada cara hasta que estén marcadas.","minutes":4,"kind":"activo"},{"text":"Retirar las láminas de calabacín y disponer en una fuente plana.","minutes":1,"kind":"activo"},{"text":"Desmenuzar {{Queso feta}} con las manos sobre las láminas de calabacín.","minutes":1,"kind":"emplatado"},{"text":"Picar {{Menta fresca}} y repartir sobre el plato.","minutes":1,"kind":"emplatado"},{"text":"Aliñar con {{Aceite de oliva|chorrito}}, {{Zumo de limón}}, {{Sal|gusto}} y {{Pimienta|pizca}}.","minutes":1,"kind":"emplatado"},{"text":"Servir templado o a temperatura ambiente.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'plancha', NULL),
  ('ensaladas_verduras_110', 'Remolacha asada entera con queso de cabra y avellanas', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, 'horno', 65, 'normal', 'invierno', 285, 10, 19, 19, 2, true, false, '{"lactosa","frutos_secos","sulfitos"}', '[{"name":"Remolacha","amount":400,"unit":"g"},{"name":"Rúcula","amount":40,"unit":"g"},{"name":"Queso de cabra","amount":100,"unit":"g"},{"name":"Avellanas tostadas","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Vinagre balsámico","amount":15,"unit":"ml"},{"name":"Miel","amount":10,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C.","Lavar remolacha bajo el grifo frotando bien la piel.","Envolver cada remolacha entera, con piel, en papel de aluminio formando un paquete cerrado.","Hornear los paquetes en la bandeja central durante 50 min, hasta que estén tiernas al pincharlas.","Mezclar aceite de oliva, vinagre balsámico y miel en un bol pequeño hasta emulsionar.","Picar avellanas tostadas groseramente con el cuchillo.","Retirar los paquetes del horno y dejar templar sin abrir durante 10 min.","Abrir el papel de aluminio y pelar las remolachas frotando la piel con un paño de cocina.","Cortar las remolachas en gajos.","Disponer rúcula en una fuente formando una base uniforme.","Colocar los gajos de remolacha sobre la rúcula.","Desmenuzar queso de cabra sobre la remolacha y repartir las avellanas picadas.","Aliñar con la mezcla de aceite, vinagre balsámico y miel justo antes de servir."}', 'Remolacha asada entera de un magenta intenso, servida con queso de cabra cremoso y avellanas tostadas.', NULL, '{}', NULL, NULL, NULL, '{"verdura","lacteo","frutos_secos"}', NULL, '{}'::main_protein[], false, '[{"text":"Precalentar el horno a 200 °C.","minutes":10,"kind":"pasivo"},{"text":"Lavar {{Remolacha}} bajo el grifo frotando bien la piel.","minutes":2,"kind":"prep"},{"text":"Envolver cada remolacha entera, con piel, en papel de aluminio formando un paquete cerrado.","minutes":3,"kind":"prep"},{"text":"Hornear los paquetes en la bandeja central durante 50 min, hasta que estén tiernas al pincharlas.","minutes":50,"kind":"pasivo"},{"text":"Mezclar {{Aceite de oliva|chorrito}}, {{Vinagre balsámico}} y {{Miel}} en un bol pequeño hasta emulsionar.","minutes":2,"kind":"paralelo","during":3},{"text":"Picar {{Avellanas tostadas}} groseramente con el cuchillo.","minutes":2,"kind":"paralelo","during":3},{"text":"Retirar los paquetes del horno y dejar templar sin abrir durante 10 min.","minutes":10,"kind":"espera"},{"text":"Abrir el papel de aluminio y pelar las remolachas frotando la piel con un paño de cocina.","minutes":3,"kind":"prep"},{"text":"Cortar las remolachas en gajos.","minutes":2,"kind":"prep"},{"text":"Disponer {{Rúcula}} en una fuente formando una base uniforme.","minutes":1,"kind":"emplatado"},{"text":"Colocar los gajos de remolacha sobre la rúcula.","minutes":1,"kind":"emplatado"},{"text":"Desmenuzar {{Queso de cabra}} sobre la remolacha y repartir las avellanas picadas.","minutes":1,"kind":"emplatado"},{"text":"Aliñar con la mezcla de aceite, vinagre balsámico y miel justo antes de servir.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'horno', NULL),
  ('ensaladas_verduras_111', 'Verduras de temporada al vapor con vinagreta de cítricos', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 165, 5, 17, 9, 2, true, true, '{"mostaza"}', '[{"name":"Zanahoria","amount":150,"unit":"g"},{"name":"Brócoli","amount":150,"unit":"g"},{"name":"Calabacín","amount":150,"unit":"g"},{"name":"Judías verdes","amount":100,"unit":"g"},{"name":"Zumo de naranja","amount":60,"unit":"ml"},{"name":"Zumo de limón","amount":20,"unit":"ml"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Mostaza","amount":5,"unit":"g"},{"name":"Miel","amount":5,"unit":"g"}]'::jsonb, '{"Lavar y pelar zanahoria, luego cortar en rodajas de 0,5 cm.","Lavar judías verdes y retirar los extremos; cortar en trozos de 4 cm.","Lavar calabacín y brócoli; cortar el calabacín en medias lunas y el brócoli en ramilletes.","Llevar agua a ebullición en una olla con cesto de vapor a fuego fuerte.","Colocar la zanahoria y las judías verdes en el cesto; tapar y cocer al vapor hasta que estén tiernas pero firmes.","Mezclar zumo de naranja, zumo de limón, mostaza y miel en un bol hasta integrar.","Añadir aceite de oliva poco a poco al bol sin dejar de batir hasta emulsionar la vinagreta.","Retirar la zanahoria y las judías verdes del cesto; reservar en la fuente.","Colocar el calabacín y el brócoli en el cesto; tapar y cocer al vapor hasta que estén tiernos pero firmes.","Retirar el calabacín y el brócoli del cesto y añadir a la fuente junto al resto de las verduras.","Regar las verduras con la vinagreta de cítricos y servir templadas."}', 'Verduras de temporada al vapor que conservan sus colores intactos, despertadas con una vinagreta de cítricos.', NULL, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], false, '[{"text":"Lavar y pelar {{Zanahoria}}, luego cortar en rodajas de 0,5 cm.","minutes":3,"kind":"prep"},{"text":"Lavar {{Judías verdes}} y retirar los extremos; cortar en trozos de 4 cm.","minutes":2,"kind":"prep"},{"text":"Lavar {{Calabacín}} y {{Brócoli}}; cortar el calabacín en medias lunas y el brócoli en ramilletes.","minutes":3,"kind":"prep"},{"text":"Llevar agua a ebullición en una olla con cesto de vapor a fuego fuerte.","minutes":3,"kind":"activo"},{"text":"Colocar la zanahoria y las judías verdes en el cesto; tapar y cocer al vapor hasta que estén tiernas pero firmes.","minutes":8,"kind":"pasivo"},{"text":"Mezclar {{Zumo de naranja}}, {{Zumo de limón}}, {{Mostaza}} y {{Miel}} en un bol hasta integrar.","minutes":2,"kind":"paralelo","during":4},{"text":"Añadir {{Aceite de oliva|chorrito}} poco a poco al bol sin dejar de batir hasta emulsionar la vinagreta.","minutes":1,"kind":"paralelo","during":4},{"text":"Retirar la zanahoria y las judías verdes del cesto; reservar en la fuente.","minutes":1,"kind":"activo"},{"text":"Colocar el calabacín y el brócoli en el cesto; tapar y cocer al vapor hasta que estén tiernos pero firmes.","minutes":6,"kind":"pasivo"},{"text":"Retirar el calabacín y el brócoli del cesto y añadir a la fuente junto al resto de las verduras.","minutes":1,"kind":"activo"},{"text":"Regar las verduras con la vinagreta de cítricos y servir templadas.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'olla', NULL),
  ('ensaladas_verduras_112', 'Endivias braseadas con naranja y nueces', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 30, 'facil', 'invierno', 215, 4, 18, 14, 2, true, true, '{"frutos_secos","lactosa"}', '[{"name":"Endivias","amount":4,"unit":"ud"},{"name":"Naranja","amount":150,"unit":"g"},{"name":"Nueces","amount":30,"unit":"g"},{"name":"Mantequilla","amount":15,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"},{"name":"Azúcar","amount":10,"unit":"g"},{"name":"Sal","amount":1,"unit":"g"}]'::jsonb, '{"Cortar endivias por la mitad a lo largo.","Exprimir naranja y reservar el zumo; separar el resto en gajos pelados al vivo.","Trocear nueces en trozos gruesos y reservar.","Calentar sartén a fuego medio y fundir mantequilla con aceite de oliva.","Colocar las endivias con el corte hacia abajo y dorar hasta que tomen color dorado.","Dar la vuelta a las endivias.","Añadir el zumo de naranja reservado, azúcar y sal.","Tapar la sartén y cocer a fuego suave hasta que las endivias estén tiernas.","Destapar y reducir el jugo a fuego medio hasta que espese ligeramente.","Servir las endivias con los gajos de naranja y las nueces troceadas por encima."}', 'Endivias braseadas con las hojas doradas por los bordes y el dulzor cítrico de la naranja.', NULL, '{}', NULL, NULL, NULL, '{"fruta","frutos_secos"}', NULL, '{}'::main_protein[], false, '[{"text":"Cortar {{Endivias}} por la mitad a lo largo.","minutes":2,"kind":"prep"},{"text":"Exprimir {{Naranja}} y reservar el zumo; separar el resto en gajos pelados al vivo.","minutes":3,"kind":"prep"},{"text":"Trocear {{Nueces}} en trozos gruesos y reservar.","minutes":1,"kind":"prep"},{"text":"Calentar {{@Sartén}} a fuego medio y fundir {{Mantequilla}} con {{Aceite de oliva|chorrito}}.","minutes":2,"kind":"activo"},{"text":"Colocar las endivias con el corte hacia abajo y dorar hasta que tomen color dorado.","minutes":5,"kind":"activo"},{"text":"Dar la vuelta a las endivias.","minutes":1,"kind":"activo"},{"text":"Añadir el zumo de naranja reservado, {{Azúcar}} y {{Sal|gusto}}.","minutes":1,"kind":"activo"},{"text":"Tapar la sartén y cocer a fuego suave hasta que las endivias estén tiernas.","minutes":13,"kind":"pasivo"},{"text":"Destapar y reducir el jugo a fuego medio hasta que espese ligeramente.","minutes":3,"kind":"activo"},{"text":"Servir las endivias con los gajos de naranja y las nueces troceadas por encima.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'plancha', NULL),
  ('ensaladas_verduras_113', 'Setas confitadas al ajillo con perejil', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 30, 'facil', 'all', 230, 6, 7, 20, 2, true, true, '{}', '[{"name":"Setas variadas","amount":400,"unit":"g"},{"name":"Ajo","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":80,"unit":"ml"},{"name":"Guindilla","amount":2,"unit":"g"},{"name":"Perejil","amount":10,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Limpiar setas variadas con un paño húmedo para retirar la tierra.","Cortar las setas más grandes en trozos y dejar las pequeñas enteras.","Laminar ajo.","Picar perejil fino y reservar.","Calentar aceite de oliva en una cazuela a fuego suave hasta que esté caliente pero sin humear.","Añadir el ajo laminado y guindilla y sofreír a fuego suave hasta que el ajo aromatice sin dorarse.","Añadir las setas a la cazuela y remover para que se impregnen del aceite aromatizado.","Confitar las setas a fuego suave, tapado, removiendo de vez en cuando, hasta que estén tiernas.","Añadir sal al final de la cocción y remover.","Servir las setas templadas espolvoreadas con el perejil picado y un poco del aceite de la cocción."}', 'Setas confitadas a fuego lento en aceite de oliva y ajo, con el brillo del aceite y perejil fresco por encima.', NULL, '{}', true, NULL, NULL, '{"seta"}', NULL, '{}'::main_protein[], false, '[{"text":"Limpiar {{Setas variadas}} con un paño húmedo para retirar la tierra.","minutes":3,"kind":"prep"},{"text":"Cortar las setas más grandes en trozos y dejar las pequeñas enteras.","minutes":2,"kind":"prep"},{"text":"Laminar {{Ajo}}.","minutes":2,"kind":"prep"},{"text":"Picar {{Perejil}} fino y reservar.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva}} en una cazuela a fuego suave hasta que esté caliente pero sin humear.","minutes":2,"kind":"activo"},{"text":"Añadir el ajo laminado y {{Guindilla}} y sofreír a fuego suave hasta que el ajo aromatice sin dorarse.","minutes":3,"kind":"activo"},{"text":"Añadir las setas a la cazuela y remover para que se impregnen del aceite aromatizado.","minutes":1,"kind":"activo"},{"text":"Confitar las setas a fuego suave, tapado, removiendo de vez en cuando, hasta que estén tiernas.","minutes":17,"kind":"pasivo"},{"text":"Añadir {{Sal|gusto}} al final de la cocción y remover.","minutes":1,"kind":"activo"},{"text":"Servir las setas templadas espolvoreadas con el perejil picado y un poco del aceite de la cocción.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL),
  ('ensaladas_verduras_114', 'Calabaza rellena de arroz y verduras al horno', 'ensaladas_verduras', 'none', 'arroz', ARRAY['primero','plato_unico']::meal_role[], 'completo', NULL, 'horno', 70, 'normal', 'invierno', 340, 10, 48, 12, 2, true, true, '{"lactosa"}', '[{"name":"Calabaza","amount":800,"unit":"g"},{"name":"Arroz","amount":100,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Calabacín","amount":80,"unit":"g"},{"name":"Pimiento rojo","amount":80,"unit":"g"},{"name":"Champiñones","amount":80,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Caldo de verduras","amount":150,"unit":"ml"},{"name":"Queso rallado","amount":40,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 190 °C.","Cortar calabaza por la mitad a lo largo y retirar las semillas con una cuchara.","Salpimentar el interior de las mitades de calabaza.","Colocar las mitades de calabaza boca abajo en una bandeja con un dedo de agua.","Hornear la calabaza 25 min hasta que empiece a ablandarse.","Picar cebolla, pimiento rojo, calabacín, champiñones y ajo en trozos pequeños.","Calentar aceite de oliva en una sartén a fuego medio.","Sofreír la cebolla, el ajo, el pimiento rojo, el calabacín y los champiñones 6 min hasta que estén tiernos.","Añadir arroz al sofrito y remover 2 min para que se impregne.","Verter caldo de verduras y cocer a fuego medio 10 min hasta que el arroz esté casi al dente.","Picar perejil fino y reservar.","Retirar la calabaza del horno y girarla boca arriba con cuidado.","Rellenar las mitades de calabaza con el sofrito de arroz repartiéndolo a partes iguales.","Cubrir cada mitad con queso rallado a partes iguales.","Hornear 20 min hasta que la calabaza esté tierna y el queso se haya dorado.","Espolvorear el perejil picado sobre la calabaza y servir de inmediato."}', 'Media calabaza como fuente, rellena de un arroz de verduras colorido que se descubre al abrirla.', NULL, '{}', NULL, NULL, NULL, '{"verdura","lacteo","seta"}', NULL, '{}'::main_protein[], false, '[{"text":"Precalentar el horno a 190 °C.","minutes":10,"kind":"pasivo"},{"text":"Cortar {{Calabaza}} por la mitad a lo largo y retirar las semillas con una cuchara.","minutes":3,"kind":"prep"},{"text":"Salpimentar el interior de las mitades de calabaza.","minutes":1,"kind":"prep"},{"text":"Colocar las mitades de calabaza boca abajo en una bandeja con un dedo de agua.","minutes":2,"kind":"prep"},{"text":"Hornear la calabaza 25 min hasta que empiece a ablandarse.","minutes":25,"kind":"pasivo","part":"principal"},{"text":"Picar {{Cebolla}}, {{Pimiento rojo}}, {{Calabacín}}, {{Champiñones}} y {{Ajo}} en trozos pequeños.","minutes":5,"kind":"paralelo","part":"principal","during":4},{"text":"Calentar {{Aceite de oliva|chorrito}} en una sartén a fuego medio.","minutes":1,"kind":"activo","part":"principal"},{"text":"Sofreír la cebolla, el ajo, el pimiento rojo, el calabacín y los champiñones 6 min hasta que estén tiernos.","minutes":6,"kind":"activo","part":"principal"},{"text":"Añadir {{Arroz}} al sofrito y remover 2 min para que se impregne.","minutes":2,"kind":"activo","part":"principal"},{"text":"Verter {{Caldo de verduras}} y cocer a fuego medio 10 min hasta que el arroz esté casi al dente.","minutes":10,"kind":"pasivo","part":"principal"},{"text":"Picar {{Perejil}} fino y reservar.","minutes":1,"kind":"paralelo","part":"principal","during":9},{"text":"Retirar la calabaza del horno y girarla boca arriba con cuidado.","minutes":1,"kind":"activo","part":"combinado"},{"text":"Rellenar las mitades de calabaza con el sofrito de arroz repartiéndolo a partes iguales.","minutes":2,"kind":"activo","part":"combinado"},{"text":"Cubrir cada mitad con {{Queso rallado}} a partes iguales.","minutes":1,"kind":"activo","part":"combinado"},{"text":"Hornear 20 min hasta que la calabaza esté tierna y el queso se haya dorado.","minutes":20,"kind":"pasivo","part":"combinado"},{"text":"Espolvorear el perejil picado sobre la calabaza y servir de inmediato.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true, NULL, NULL, 'horno', NULL)
