insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id, extra_proteins, freezable, steps_rich, estrella, occasion, kid_favourite, tecnica, cocina
) values
  ('ensaladas_verduras_115', 'Timbal de verduras y queso de cabra gratinado', 'ensaladas_verduras', 'none', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, 'horno', 55, 'normal', 'verano', 260, 14, 12, 17, 2, true, true, '{"lactosa"}', '[{"name":"Berenjena","amount":150,"unit":"g"},{"name":"Calabacín","amount":150,"unit":"g"},{"name":"Pimiento rojo","amount":100,"unit":"g"},{"name":"Tomate","amount":150,"unit":"g"},{"name":"Queso de cabra","amount":150,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Orégano","amount":2,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"},{"name":"Pimienta","amount":1,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C con calor arriba y abajo.","Laminar berenjena en rodajas finas de unos 3 mm.","Laminar calabacín en rodajas finas de unos 3 mm.","Laminar pimiento rojo en tiras finas.","Laminar tomate en rodajas finas de unos 3 mm.","Laminar queso de cabra en rodajas de unos 5 mm y reservar.","Disponer una primera capa de berenjena en 2 moldes individuales o en una fuente.","Añadir una capa de calabacín sobre la berenjena.","Añadir una capa de tomate sobre el calabacín.","Añadir una capa de pimiento rojo y salpimentar con sal y pimienta.","Repetir las capas hasta agotar las verduras, salpimentando entre cada capa.","Regar la superficie con aceite de oliva.","Tapar la fuente con papel de aluminio y hornear a 200 °C durante 30 min.","Retirar el papel de aluminio y colocar las rodajas de queso de cabra sobre las verduras.","Espolvorear orégano sobre el queso de cabra.","Hornear sin tapar a 200 °C con el gratinador encendido hasta que el queso se dore, unos 8 min.","Retirar del horno y dejar reposar 5 min antes de servir.","Servir el timbal caliente directamente en los moldes o desmoldado en el plato."}', 'Capas de verduras asadas visibles al cortar, coronadas con queso de cabra dorado y gratinado.', NULL, '{}', true, NULL, NULL, '{"verdura","lacteo"}', NULL, '{}'::main_protein[], true, '[{"text":"Precalentar el horno a 200 °C con calor arriba y abajo.","minutes":10,"kind":"pasivo"},{"text":"Laminar {{Berenjena}} en rodajas finas de unos 3 mm.","minutes":3,"kind":"prep"},{"text":"Laminar {{Calabacín}} en rodajas finas de unos 3 mm.","minutes":2,"kind":"paralelo","during":0},{"text":"Laminar {{Pimiento rojo}} en tiras finas.","minutes":2,"kind":"paralelo","during":0},{"text":"Laminar {{Tomate}} en rodajas finas de unos 3 mm.","minutes":2,"kind":"paralelo","during":0},{"text":"Laminar {{Queso de cabra}} en rodajas de unos 5 mm y reservar.","minutes":1,"kind":"paralelo","during":0},{"text":"Disponer una primera capa de berenjena en 2 moldes individuales o en una fuente.","minutes":1,"kind":"prep"},{"text":"Añadir una capa de calabacín sobre la berenjena.","minutes":1,"kind":"prep"},{"text":"Añadir una capa de tomate sobre el calabacín.","minutes":1,"kind":"prep"},{"text":"Añadir una capa de pimiento rojo y salpimentar con {{Sal|gusto}} y {{Pimienta|pizca}}.","minutes":1,"kind":"prep"},{"text":"Repetir las capas hasta agotar las verduras, salpimentando entre cada capa.","minutes":3,"kind":"prep"},{"text":"Regar la superficie con {{Aceite de oliva|chorrito}}.","minutes":1,"kind":"prep"},{"text":"Tapar la fuente con papel de aluminio y hornear a 200 °C durante 30 min.","minutes":30,"kind":"pasivo"},{"text":"Retirar el papel de aluminio y colocar las rodajas de queso de cabra sobre las verduras.","minutes":2,"kind":"activo"},{"text":"Espolvorear {{Orégano|pizca}} sobre el queso de cabra.","minutes":1,"kind":"activo"},{"text":"Hornear sin tapar a 200 °C con el gratinador encendido hasta que el queso se dore, unos 8 min.","minutes":8,"kind":"pasivo"},{"text":"Retirar del horno y dejar reposar 5 min antes de servir.","minutes":5,"kind":"espera"},{"text":"Servir el timbal caliente directamente en los moldes o desmoldado en el plato.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'horno', NULL),
  ('ensaladas_verduras_116', 'Milhojas de berenjena, tomate y mozzarella', 'ensaladas_verduras', 'none', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, 'horno', 45, 'normal', 'verano', 310, 18, 10, 22, 2, true, true, '{"lactosa"}', '[{"name":"Berenjena","amount":300,"unit":"g"},{"name":"Tomate","amount":250,"unit":"g"},{"name":"Mozzarella fresca","amount":200,"unit":"g"},{"name":"Albahaca fresca","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"},{"name":"Pimienta","amount":1,"unit":"g"}]'::jsonb, '{"Cortar berenjena en láminas de 0,5 cm de grosor.","Salar las láminas de berenjena con sal y disponerlas en un colador.","Dejar reposar las láminas de berenjena 15 min para que suelten el amargor.","Cortar tomate en rodajas de 0,5 cm de grosor.","Cortar mozzarella fresca en rodajas de 0,5 cm de grosor.","Secar las láminas de berenjena con papel de cocina para eliminar la humedad.","Calentar plancha a fuego fuerte con aceite de oliva.","Marcar las láminas de berenjena hasta que se doren por ambos lados.","Precalentar el horno a 190 °C.","Montar el milhojas en una fuente de horno alternando capas de berenjena, tomate y mozzarella fresca.","Salpimentar el milhojas con pimienta y regar con un chorrito de aceite de oliva.","Hornear la fuente a 190 °C durante 15 min hasta que la mozzarella fresca funda.","Distribuir albahaca fresca por encima y regar con un hilo de aceite de oliva.","Servir el milhojas templado."}', 'Capas apiladas de berenjena, tomate y mozzarella fundida, con hilos de queso al partirlas.', NULL, '{}', true, NULL, NULL, '{"verdura","lacteo"}', NULL, '{}'::main_protein[], false, '[{"text":"Cortar {{Berenjena}} en láminas de 0,5 cm de grosor.","minutes":3,"kind":"prep"},{"text":"Salar las láminas de berenjena con {{Sal|gusto}} y disponerlas en un colador.","minutes":1,"kind":"prep"},{"text":"Dejar reposar las láminas de berenjena 15 min para que suelten el amargor.","minutes":15,"kind":"espera"},{"text":"Cortar {{Tomate}} en rodajas de 0,5 cm de grosor.","minutes":2,"kind":"paralelo","during":2},{"text":"Cortar {{Mozzarella fresca}} en rodajas de 0,5 cm de grosor.","minutes":2,"kind":"paralelo","during":2},{"text":"Secar las láminas de berenjena con papel de cocina para eliminar la humedad.","minutes":2,"kind":"prep"},{"text":"Calentar {{@Plancha}} a fuego fuerte con {{Aceite de oliva|chorrito}}.","minutes":2,"kind":"activo"},{"text":"Marcar las láminas de berenjena hasta que se doren por ambos lados.","minutes":8,"kind":"activo"},{"text":"Precalentar el horno a 190 °C.","minutes":10,"kind":"pasivo"},{"text":"Montar el milhojas en una fuente de horno alternando capas de berenjena, tomate y mozzarella fresca.","minutes":3,"kind":"activo"},{"text":"Salpimentar el milhojas con {{Pimienta|pizca}} y regar con un chorrito de aceite de oliva.","minutes":1,"kind":"activo"},{"text":"Hornear la fuente a 190 °C durante 15 min hasta que la mozzarella fresca funda.","minutes":15,"kind":"pasivo"},{"text":"Distribuir {{Albahaca fresca}} por encima y regar con un hilo de aceite de oliva.","minutes":1,"kind":"emplatado"},{"text":"Servir el milhojas templado.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'horno', NULL),
  ('ensaladas_verduras_117', 'Ensalada templada de perdiz escabechada', 'ensaladas_verduras', 'pollo', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 70, 'normal', 'invierno', 385, 30, 6, 26, 2, false, false, '{"sulfitos"}', '[{"name":"Perdiz","amount":2,"unit":"ud"},{"name":"Vino blanco","amount":100,"unit":"ml"},{"name":"Vinagre de vino","amount":100,"unit":"ml"},{"name":"Aceite de oliva","amount":150,"unit":"ml"},{"name":"Ajo","amount":20,"unit":"g"},{"name":"Laurel","amount":2,"unit":"g"},{"name":"Zanahoria","amount":80,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Hojas verdes variadas","amount":100,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Laminar ajo.","Cortar zanahoria en rodajas y cebolla en rodajas.","Salpimentar perdiz por todos los lados con sal.","Calentar aceite de oliva en una cazuela a fuego fuerte.","Dorar las perdices en la cazuela hasta que estén doradas por todos los lados.","Retirar las perdices de la cazuela y reservar.","Sofreír la cebolla, la zanahoria y el ajo laminado en el mismo aceite a fuego medio hasta que estén blandos.","Añadir laurel y remover.","Devolver las perdices a la cazuela sobre las verduras.","Añadir vino blanco, vinagre de vino y el resto del aceite de oliva.","Tapar la cazuela y cocer a fuego suave hasta que la carne esté tierna.","Retirar la cazuela del fuego y dejar enfriar las perdices dentro del escabeche.","Deshuesar las perdices y trocear la carne en piezas generosas.","Colar el escabeche y reservar el líquido resultante.","Disponer hojas verdes variadas en la base de los platos.","Colocar los trozos de perdiz templada sobre las hojas verdes.","Regar con el escabeche colado y servir."}', 'Piezas de perdiz escabechadas y doradas sobre hojas frescas, con el brillo característico del escabeche.', NULL, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], false, '[{"text":"Laminar {{Ajo}}.","minutes":2,"kind":"prep"},{"text":"Cortar {{Zanahoria}} en rodajas y {{Cebolla}} en rodajas.","minutes":3,"kind":"prep"},{"text":"Salpimentar {{Perdiz}} por todos los lados con {{Sal|gusto}}.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una cazuela a fuego fuerte.","minutes":2,"kind":"activo"},{"text":"Dorar las perdices en la cazuela hasta que estén doradas por todos los lados.","minutes":8,"kind":"activo"},{"text":"Retirar las perdices de la cazuela y reservar.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla, la zanahoria y el ajo laminado en el mismo aceite a fuego medio hasta que estén blandos.","minutes":6,"kind":"activo"},{"text":"Añadir {{Laurel}} y remover.","minutes":1,"kind":"activo"},{"text":"Devolver las perdices a la cazuela sobre las verduras.","minutes":1,"kind":"activo"},{"text":"Añadir {{Vino blanco}}, {{Vinagre de vino}} y el resto del aceite de oliva.","minutes":1,"kind":"activo"},{"text":"Tapar la cazuela y cocer a fuego suave hasta que la carne esté tierna.","minutes":45,"kind":"pasivo"},{"text":"Retirar la cazuela del fuego y dejar enfriar las perdices dentro del escabeche.","minutes":720,"kind":"espera"},{"text":"Deshuesar las perdices y trocear la carne en piezas generosas.","minutes":5,"kind":"prep"},{"text":"Colar el escabeche y reservar el líquido resultante.","minutes":2,"kind":"prep"},{"text":"Disponer {{Hojas verdes variadas}} en la base de los platos.","minutes":1,"kind":"emplatado"},{"text":"Colocar los trozos de perdiz templada sobre las hojas verdes.","minutes":1,"kind":"emplatado"},{"text":"Regar con el escabeche colado y servir.","minutes":1,"kind":"emplatado"}]'::jsonb, true, 'especial', NULL, 'sarten', NULL),
  ('ensaladas_verduras_118', 'Croquetas de boletus', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 60, 'normal', 'invierno', 420, 12, 32, 26, 2, true, false, '{"gluten","lactosa","huevo"}', '[{"name":"Boletus","amount":200,"unit":"g"},{"name":"Mantequilla","amount":50,"unit":"g"},{"name":"Harina","amount":60,"unit":"g"},{"name":"Leche","amount":400,"unit":"ml"},{"name":"Cebolla","amount":40,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Pan rallado","amount":100,"unit":"g"},{"name":"Aceite de oliva","amount":300,"unit":"ml"},{"name":"Nuez moscada","amount":1,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Limpiar boletus con un paño húmedo para retirar la tierra.","Picar los boletus en trozos pequeños y reservar.","Picar cebolla muy fina.","Picar ajo muy fino.","Fundir mantequilla en sartén a fuego suave.","Sofreír la cebolla picada y el ajo picado en la mantequilla fundida hasta que estén transparentes.","Añadir los boletus picados y saltear a fuego medio hasta que suelten el agua y esta se evapore.","Añadir harina sobre el sofrito y remover sin parar durante 2 min hasta que se tueste ligeramente.","Calentar leche en un cazo a fuego suave hasta que esté caliente pero sin hervir.","Verter la leche caliente sobre la sartén poco a poco, removiendo sin parar para integrar.","Añadir sal y nuez moscada y remover para integrar.","Cocer la bechamel a fuego suave, removiendo sin parar, hasta que esté espesa y se despegue de las paredes.","Extender la masa en una fuente y cubrir con film a contacto directo con la superficie.","Dejar enfriar la masa en la nevera hasta que esté firme y fácil de manejar.","Batir huevo en un bol hasta obtener una mezcla homogénea.","Volcar pan rallado en un plato llano y reservar.","Tomar porciones de masa fría y darles forma ovalada con las manos para formar las croquetas.","Pasar cada croqueta por el huevo batido y escurrir el exceso.","Rebozar cada croqueta en el pan rallado y presionar para que se adhiera bien.","Calentar aceite de oliva en sartén a fuego fuerte hasta alcanzar 180 °C.","Freír las croquetas por tandas hasta que estén doradas por todos los lados.","Escurrir las croquetas sobre papel absorbente para retirar el exceso de aceite.","Servir las croquetas calientes."}', 'Croquetas de interior oscuro y cremoso, con aroma a bosque y textura crujiente por fuera.', NULL, '{}', true, NULL, NULL, '{"lacteo","seta"}', NULL, '{}'::main_protein[], true, '[{"text":"Limpiar {{Boletus}} con un paño húmedo para retirar la tierra.","minutes":3,"kind":"prep"},{"text":"Picar los boletus en trozos pequeños y reservar.","minutes":2,"kind":"prep"},{"text":"Picar {{Cebolla}} muy fina.","minutes":2,"kind":"prep"},{"text":"Picar {{Ajo}} muy fino.","minutes":1,"kind":"prep"},{"text":"Fundir {{Mantequilla}} en {{@Sartén}} a fuego suave.","minutes":2,"kind":"activo"},{"text":"Sofreír la cebolla picada y el ajo picado en la mantequilla fundida hasta que estén transparentes.","minutes":5,"kind":"activo"},{"text":"Añadir los boletus picados y saltear a fuego medio hasta que suelten el agua y esta se evapore.","minutes":5,"kind":"activo"},{"text":"Añadir {{Harina}} sobre el sofrito y remover sin parar durante 2 min hasta que se tueste ligeramente.","minutes":2,"kind":"activo"},{"text":"Calentar {{Leche}} en un cazo a fuego suave hasta que esté caliente pero sin hervir.","minutes":3,"kind":"activo"},{"text":"Verter la leche caliente sobre la {{@Sartén}} poco a poco, removiendo sin parar para integrar.","minutes":3,"kind":"activo"},{"text":"Añadir {{Sal|gusto}} y {{Nuez moscada|pizca}} y remover para integrar.","minutes":1,"kind":"activo"},{"text":"Cocer la bechamel a fuego suave, removiendo sin parar, hasta que esté espesa y se despegue de las paredes.","minutes":10,"kind":"activo"},{"text":"Extender la masa en una fuente y cubrir con film a contacto directo con la superficie.","minutes":2,"kind":"activo"},{"text":"Dejar enfriar la masa en la nevera hasta que esté firme y fácil de manejar.","minutes":180,"kind":"espera"},{"text":"Batir {{Huevo}} en un bol hasta obtener una mezcla homogénea.","minutes":2,"kind":"prep"},{"text":"Volcar {{Pan rallado}} en un plato llano y reservar.","minutes":1,"kind":"prep"},{"text":"Tomar porciones de masa fría y darles forma ovalada con las manos para formar las croquetas.","minutes":5,"kind":"prep"},{"text":"Pasar cada croqueta por el huevo batido y escurrir el exceso.","minutes":3,"kind":"prep"},{"text":"Rebozar cada croqueta en el pan rallado y presionar para que se adhiera bien.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|abundante}} en {{@Sartén}} a fuego fuerte hasta alcanzar 180 °C.","minutes":3,"kind":"activo"},{"text":"Freír las croquetas por tandas hasta que estén doradas por todos los lados.","minutes":4,"kind":"activo"},{"text":"Escurrir las croquetas sobre papel absorbente para retirar el exceso de aceite.","minutes":1,"kind":"activo"},{"text":"Servir las croquetas calientes.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL),
  ('ensaladas_verduras_119', 'Moussaka de berenjena', 'ensaladas_verduras', 'ternera', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, 'horno', 90, 'elaborada', 'all', 480, 26, 22, 32, 4, true, true, '{"gluten","lactosa","sulfitos"}', '[{"name":"Berenjena","amount":800,"unit":"g"},{"name":"Carne picada de ternera","amount":500,"unit":"g"},{"name":"Cebolla","amount":150,"unit":"g"},{"name":"Ajo","amount":20,"unit":"g"},{"name":"Tomate triturado","amount":500,"unit":"g"},{"name":"Vino tinto","amount":80,"unit":"ml"},{"name":"Aceite de oliva","amount":50,"unit":"ml"},{"name":"Mantequilla","amount":50,"unit":"g"},{"name":"Harina","amount":50,"unit":"g"},{"name":"Leche","amount":600,"unit":"ml"},{"name":"Queso rallado","amount":100,"unit":"g"},{"name":"Canela","amount":2,"unit":"g"},{"name":"Nuez moscada","amount":1,"unit":"g"},{"name":"Sal","amount":4,"unit":"g"},{"name":"Pimienta","amount":2,"unit":"g"}]'::jsonb, '{"Cortar berenjena en láminas de 0,5 cm de grosor.","Salar las láminas de berenjena y dejar reposar para que suelten el amargor.","Picar cebolla en daditos finos.","Picar ajo fino.","Secar las láminas de berenjena con papel de cocina para eliminar el exceso de humedad.","Calentar plancha a fuego fuerte y marcar las láminas de berenjena hasta que estén doradas por ambos lados.","Reservar las láminas de berenjena marcadas en un plato.","Calentar aceite de oliva en una sartén a fuego medio.","Sofreír la cebolla picada y el ajo picado hasta que estén transparentes.","Añadir carne picada de ternera y dorar deshaciendo los grumos hasta que esté bien cocinada.","Añadir vino tinto y remover hasta que se evapore el alcohol.","Añadir tomate triturado, canela, sal y pimienta; remover para integrar.","Cocer la salsa de carne a fuego suave, tapada, hasta que espese y los sabores se concentren.","Fundir mantequilla en un cazo a fuego medio.","Añadir harina a la mantequilla fundida y remover sin parar hasta obtener un roux dorado.","Incorporar leche poco a poco sin dejar de remover hasta que la bechamel espese y esté lisa.","Añadir nuez moscada a la bechamel y salpimentar; retirar del fuego y reservar.","Precalentar el horno a 190 °C.","Disponer una capa de láminas de berenjena en el fondo de una fuente de horno.","Cubrir la capa de berenjena con la mitad de la salsa de carne, extendiéndola de forma uniforme.","Repetir con otra capa de berenjena y el resto de la salsa de carne.","Verter la bechamel sobre las capas cubriendo toda la superficie de forma uniforme.","Repartir queso rallado sobre la bechamel de manera uniforme.","Hornear la fuente en el horno a 190 °C hasta que la superficie esté dorada y gratinada.","Retirar la fuente del horno y dejar reposar antes de cortar y servir.","Servir la moussaka cortada en porciones."}', 'Capas de berenjena y carne especiada bajo una bechamel gratinada y dorada.', NULL, '{}', NULL, NULL, NULL, '{"verdura","lacteo"}', NULL, '{}'::main_protein[], true, '[{"text":"Cortar {{Berenjena}} en láminas de 0,5 cm de grosor.","minutes":5,"kind":"prep","part":"principal"},{"text":"Salar las láminas de berenjena y dejar reposar para que suelten el amargor.","minutes":20,"kind":"espera","part":"principal"},{"text":"Picar {{Cebolla}} en daditos finos.","minutes":3,"kind":"paralelo","part":"principal","during":1},{"text":"Picar {{Ajo}} fino.","minutes":2,"kind":"paralelo","part":"principal","during":1},{"text":"Secar las láminas de berenjena con papel de cocina para eliminar el exceso de humedad.","minutes":2,"kind":"prep","part":"principal"},{"text":"Calentar {{@Plancha}} a fuego fuerte y marcar las láminas de berenjena hasta que estén doradas por ambos lados.","minutes":8,"kind":"activo","part":"principal"},{"text":"Reservar las láminas de berenjena marcadas en un plato.","minutes":1,"kind":"prep","part":"principal"},{"text":"Calentar {{Aceite de oliva}} en una sartén a fuego medio.","minutes":1,"kind":"activo","part":"principal"},{"text":"Sofreír la cebolla picada y el ajo picado hasta que estén transparentes.","minutes":6,"kind":"activo","part":"principal"},{"text":"Añadir {{Carne picada de ternera}} y dorar deshaciendo los grumos hasta que esté bien cocinada.","minutes":5,"kind":"activo","part":"principal"},{"text":"Añadir {{Vino tinto}} y remover hasta que se evapore el alcohol.","minutes":3,"kind":"activo","part":"principal"},{"text":"Añadir {{Tomate triturado}}, {{Canela}}, {{Sal|gusto}} y {{Pimienta|gusto}}; remover para integrar.","minutes":2,"kind":"activo","part":"principal"},{"text":"Cocer la salsa de carne a fuego suave, tapada, hasta que espese y los sabores se concentren.","minutes":20,"kind":"pasivo","part":"principal"},{"text":"Fundir {{Mantequilla}} en un cazo a fuego medio.","minutes":2,"kind":"paralelo","part":"salsa","during":12},{"text":"Añadir {{Harina}} a la mantequilla fundida y remover sin parar hasta obtener un roux dorado.","minutes":2,"kind":"activo","part":"salsa"},{"text":"Incorporar {{Leche}} poco a poco sin dejar de remover hasta que la bechamel espese y esté lisa.","minutes":8,"kind":"activo","part":"salsa"},{"text":"Añadir {{Nuez moscada|pizca}} a la bechamel y salpimentar; retirar del fuego y reservar.","minutes":1,"kind":"activo","part":"salsa"},{"text":"Precalentar el horno a 190 °C.","minutes":10,"kind":"pasivo","part":"combinado"},{"text":"Disponer una capa de láminas de berenjena en el fondo de una fuente de horno.","minutes":2,"kind":"paralelo","part":"combinado","during":17},{"text":"Cubrir la capa de berenjena con la mitad de la salsa de carne, extendiéndola de forma uniforme.","minutes":2,"kind":"paralelo","part":"combinado","during":17},{"text":"Repetir con otra capa de berenjena y el resto de la salsa de carne.","minutes":2,"kind":"paralelo","part":"combinado","during":17},{"text":"Verter la bechamel sobre las capas cubriendo toda la superficie de forma uniforme.","minutes":1,"kind":"paralelo","part":"combinado","during":17},{"text":"Repartir {{Queso rallado}} sobre la bechamel de manera uniforme.","minutes":1,"kind":"paralelo","part":"combinado","during":17},{"text":"Hornear la fuente en el horno a 190 °C hasta que la superficie esté dorada y gratinada.","minutes":35,"kind":"pasivo","part":"combinado"},{"text":"Retirar la fuente del horno y dejar reposar antes de cortar y servir.","minutes":10,"kind":"espera","part":"combinado"},{"text":"Servir la moussaka cortada en porciones.","minutes":2,"kind":"emplatado","part":"combinado"}]'::jsonb, true, NULL, NULL, 'horno', 'mediterranea'),
  ('ensaladas_verduras_120', 'Pizza casera con burrata y rúcula', 'ensaladas_verduras', 'none', 'pan', ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, 'horno', 100, 'facil', 'all', 530, 22, 55, 25, 2, true, false, '{"gluten","lactosa"}', '[{"name":"Harina de fuerza","amount":250,"unit":"g"},{"name":"Agua","amount":150,"unit":"ml"},{"name":"Levadura fresca","amount":5,"unit":"g"},{"name":"Sal","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Tomate triturado","amount":150,"unit":"g"},{"name":"Burrata","amount":200,"unit":"g"},{"name":"Rúcula","amount":40,"unit":"g"},{"name":"Parmesano","amount":20,"unit":"g"},{"name":"Orégano","amount":2,"unit":"g"}]'::jsonb, '{"Disolver levadura fresca en agua templada hasta que no queden grumos.","Mezclar harina de fuerza, sal y aceite de oliva con el agua con levadura hasta obtener una masa homogénea.","Amasar sobre la encimera durante 10 min hasta que la masa esté lisa y elástica.","Colocar la masa en un bol, tapar con un paño y dejar fermentar en un lugar templado hasta que doble su volumen.","Precalentar el horno a 250 °C con la bandeja dentro.","Extender la masa sobre papel de horno hasta obtener una base fina y uniforme.","Repartir tomate triturado sobre la base estirada, dejando un borde de 1-2 cm libre.","Espolvorear orégano sobre el tomate triturado.","Hornear a 250 °C durante 10 min hasta que la base esté dorada y crujiente.","Rallar parmesano en láminas finas con un pelador o rallador.","Retirar la pizza del horno y repartir burrata troceada por encima.","Añadir rúcula y el parmesano rallado sobre la pizza.","Terminar con un chorrito de aceite de oliva y servir de inmediato."}', 'Pizza casera de base crujiente coronada con el corte cremoso de la burrata sobre rúcula fresca.', NULL, '{}', NULL, NULL, NULL, '{"verdura","lacteo"}', NULL, '{}'::main_protein[], false, '[{"text":"Disolver {{Levadura fresca}} en {{Agua}} templada hasta que no queden grumos.","minutes":2,"kind":"prep"},{"text":"Mezclar {{Harina de fuerza}}, {{Sal}} y {{Aceite de oliva}} con el agua con levadura hasta obtener una masa homogénea.","minutes":3,"kind":"activo"},{"text":"Amasar sobre la encimera durante 10 min hasta que la masa esté lisa y elástica.","minutes":10,"kind":"activo"},{"text":"Colocar la masa en un bol, tapar con un paño y dejar fermentar en un lugar templado hasta que doble su volumen.","minutes":60,"kind":"espera"},{"text":"Precalentar el horno a 250 °C con la bandeja dentro.","minutes":15,"kind":"pasivo"},{"text":"Extender la masa sobre papel de horno hasta obtener una base fina y uniforme.","minutes":3,"kind":"paralelo","during":4},{"text":"Repartir {{Tomate triturado}} sobre la base estirada, dejando un borde de 1-2 cm libre.","minutes":2,"kind":"paralelo","during":4},{"text":"Espolvorear {{Orégano|pizca}} sobre el tomate triturado.","minutes":1,"kind":"paralelo","during":4},{"text":"Hornear a 250 °C durante 10 min hasta que la base esté dorada y crujiente.","minutes":10,"kind":"pasivo"},{"text":"Rallar {{Parmesano}} en láminas finas con un pelador o rallador.","minutes":2,"kind":"paralelo","during":8},{"text":"Retirar la pizza del horno y repartir {{Burrata}} troceada por encima.","minutes":1,"kind":"emplatado"},{"text":"Añadir {{Rúcula}} y el parmesano rallado sobre la pizza.","minutes":1,"kind":"emplatado"},{"text":"Terminar con un chorrito de aceite de oliva y servir de inmediato.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, true, 'horno', 'italiana'),
  ('ensaladas_verduras_121', 'Tarta salada de calabacín y feta', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'horno', 55, 'facil', 'verano', 340, 13, 22, 22, 4, true, true, '{"gluten","lactosa","huevo"}', '[{"name":"Masa quebrada","amount":230,"unit":"g"},{"name":"Calabacín","amount":300,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Queso feta","amount":150,"unit":"g"},{"name":"Huevo","amount":3,"unit":"ud"},{"name":"Nata para cocinar","amount":150,"unit":"ml"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Eneldo","amount":3,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Pimienta","amount":1,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 190 °C.","Laminar calabacín en rodajas finas.","Cortar cebolla en juliana fina.","Forrar un molde con masa quebrada y pinchar la base con un tenedor.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla hasta que esté transparente.","Añadir el calabacín y saltear hasta que ablande ligeramente.","Batir huevo con nata para cocinar en un bol.","Añadir sal, pimienta y eneldo a la mezcla y remover.","Repartir la cebolla y el calabacín sobre la base de masa quebrada.","Desmenuzar queso feta por encima del relleno.","Verter la mezcla de huevo y nata sobre el relleno.","Hornear hasta que cuaje y la superficie esté dorada.","Retirar del horno y dejar templar antes de desmoldar.","Servir la tarta cortada en porciones."}', 'Tarta salada de verde y blanco, ligera y muy vistosa, con calabacín y feta cuajados en una base crujiente.', NULL, '{}', NULL, NULL, NULL, '{"verdura","lacteo"}', NULL, '{}'::main_protein[], true, '[{"text":"Precalentar el horno a 190 °C.","minutes":10,"kind":"pasivo"},{"text":"Laminar {{Calabacín}} en rodajas finas.","minutes":3,"kind":"prep"},{"text":"Cortar {{Cebolla}} en juliana fina.","minutes":2,"kind":"paralelo","during":0},{"text":"Forrar un molde con {{Masa quebrada}} y pinchar la base con un tenedor.","minutes":2,"kind":"paralelo","during":0},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla hasta que esté transparente.","minutes":5,"kind":"activo"},{"text":"Añadir el calabacín y saltear hasta que ablande ligeramente.","minutes":5,"kind":"activo"},{"text":"Batir {{Huevo}} con {{Nata para cocinar}} en un bol.","minutes":2,"kind":"prep"},{"text":"Añadir {{Sal|gusto}}, {{Pimienta|pizca}} y {{Eneldo|pizca}} a la mezcla y remover.","minutes":1,"kind":"prep"},{"text":"Repartir la cebolla y el calabacín sobre la base de masa quebrada.","minutes":1,"kind":"activo"},{"text":"Desmenuzar {{Queso feta}} por encima del relleno.","minutes":1,"kind":"activo"},{"text":"Verter la mezcla de huevo y nata sobre el relleno.","minutes":1,"kind":"activo"},{"text":"Hornear hasta que cuaje y la superficie esté dorada.","minutes":38,"kind":"pasivo"},{"text":"Retirar del horno y dejar templar antes de desmoldar.","minutes":10,"kind":"espera"},{"text":"Servir la tarta cortada en porciones.","minutes":2,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'horno', NULL),
  ('ensaladas_verduras_122', 'Tartar de aguacate con soja y sésamo', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 285, 4, 10, 26, 2, true, false, '{"soja","sesamo","gluten"}', '[{"name":"Aguacate","amount":400,"unit":"g"},{"name":"Pepino","amount":100,"unit":"g"},{"name":"Cebolleta","amount":20,"unit":"g"},{"name":"Salsa de soja","amount":20,"unit":"ml"},{"name":"Aceite de sésamo","amount":10,"unit":"ml"},{"name":"Semillas de sésamo tostado","amount":10,"unit":"g"},{"name":"Zumo de lima","amount":20,"unit":"ml"}]'::jsonb, '{"Cortar aguacate en dados de aproximadamente 1 cm.","Rociar el aguacate con zumo de lima para evitar que se oxide.","Cortar pepino en dados del mismo tamaño que el aguacate.","Picar cebolleta muy fina.","Mezclar en un bol el aguacate, el pepino y la cebolleta con salsa de soja y aceite de sésamo.","Remover con suavidad hasta que todo quede integrado sin aplastar el aguacate.","Colocar un aro metálico en el centro de cada plato y rellenar con la mezcla, presionando ligeramente.","Retirar el aro con cuidado para mantener la forma.","Espolvorear semillas de sésamo tostado por encima y servir inmediatamente bien frío."}', 'Tartar de aguacate verde brillante montado en aro perfecto, con un toque asiático de soja y sésamo que lo levanta.', NULL, '{}', true, true, NULL, '{"verdura"}', NULL, '{}'::main_protein[], false, '[{"text":"Cortar {{Aguacate}} en dados de aproximadamente 1 cm.","minutes":2,"kind":"prep"},{"text":"Rociar el aguacate con {{Zumo de lima}} para evitar que se oxide.","minutes":1,"kind":"prep"},{"text":"Cortar {{Pepino}} en dados del mismo tamaño que el aguacate.","minutes":2,"kind":"prep"},{"text":"Picar {{Cebolleta}} muy fina.","minutes":1,"kind":"prep"},{"text":"Mezclar en un bol el aguacate, el pepino y la cebolleta con {{Salsa de soja}} y {{Aceite de sésamo}}.","minutes":1,"kind":"activo"},{"text":"Remover con suavidad hasta que todo quede integrado sin aplastar el aguacate.","minutes":1,"kind":"activo"},{"text":"Colocar un aro metálico en el centro de cada plato y rellenar con la mezcla, presionando ligeramente.","minutes":2,"kind":"emplatado"},{"text":"Retirar el aro con cuidado para mantener la forma.","minutes":1,"kind":"emplatado"},{"text":"Espolvorear {{Semillas de sésamo tostado}} por encima y servir inmediatamente bien frío.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'crudo', NULL),
  ('ensaladas_verduras_123', 'Espinacas a la crema', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, 'horno', 30, 'facil', 'all', 200, 9, 13, 12, 2, true, true, '{"gluten","lactosa"}', '[{"name":"Espinaca fresca","amount":400,"unit":"g"},{"name":"Mantequilla","amount":25,"unit":"g"},{"name":"Harina","amount":25,"unit":"g"},{"name":"Leche","amount":300,"unit":"ml"},{"name":"Nuez moscada","amount":1,"unit":"g"},{"name":"Queso rallado","amount":30,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Lavar espinaca fresca bajo agua fría con cuidado.","Llevar a ebullición una olla con abundante agua.","Escaldar las espinacas en el agua hirviendo hasta que reduzcan de volumen, unos 2 min.","Escurrir las espinacas en un colador y apretar bien para retirar el exceso de agua.","Picar las espinacas escurridas en trozos y reservar.","Fundir mantequilla en un cazo a fuego medio.","Añadir harina de golpe y remover sin parar durante 1 min hasta obtener un roux homogéneo.","Añadir leche poco a poco sin dejar de remover hasta integrarla por completo.","Salpimentar con sal y pimienta negra y añadir nuez moscada.","Cocer la bechamel a fuego suave, removiendo, hasta que esté espesa y sin grumos, unos 5 min.","Incorporar las espinacas picadas a la bechamel y mezclar hasta integrarlas por completo.","Precalentar el grill del horno a temperatura alta.","Verter la mezcla en una fuente apta para horno y extender en capa uniforme.","Cubrir la superficie con queso rallado de forma homogénea.","Gratinar en el horno con el grill hasta que la superficie esté dorada, unos 6 min.","Servir caliente directamente desde la fuente."}', 'Espinacas envueltas en una salsa bechamel sedosa con nuez moscada, gratinadas y doradas por encima.', NULL, '{}', NULL, NULL, NULL, '{"verdura","lacteo"}', NULL, '{}'::main_protein[], true, '[{"text":"Lavar {{Espinaca fresca}} bajo agua fría con cuidado.","minutes":2,"kind":"prep"},{"text":"Llevar a ebullición una olla con abundante agua.","minutes":5,"kind":"activo"},{"text":"Escaldar las espinacas en el agua hirviendo hasta que reduzcan de volumen, unos 2 min.","minutes":2,"kind":"activo"},{"text":"Escurrir las espinacas en un colador y apretar bien para retirar el exceso de agua.","minutes":2,"kind":"activo"},{"text":"Picar las espinacas escurridas en trozos y reservar.","minutes":2,"kind":"prep"},{"text":"Fundir {{Mantequilla}} en un cazo a fuego medio.","minutes":1,"kind":"activo"},{"text":"Añadir {{Harina}} de golpe y remover sin parar durante 1 min hasta obtener un roux homogéneo.","minutes":1,"kind":"activo"},{"text":"Añadir {{Leche}} poco a poco sin dejar de remover hasta integrarla por completo.","minutes":3,"kind":"activo"},{"text":"Salpimentar con {{Sal|gusto}} y {{Pimienta negra|pizca}} y añadir {{Nuez moscada|pizca}}.","minutes":1,"kind":"activo"},{"text":"Cocer la bechamel a fuego suave, removiendo, hasta que esté espesa y sin grumos, unos 5 min.","minutes":5,"kind":"activo"},{"text":"Incorporar las espinacas picadas a la bechamel y mezclar hasta integrarlas por completo.","minutes":1,"kind":"activo"},{"text":"Precalentar el grill del horno a temperatura alta.","minutes":5,"kind":"pasivo"},{"text":"Verter la mezcla en una fuente apta para horno y extender en capa uniforme.","minutes":1,"kind":"activo"},{"text":"Cubrir la superficie con {{Queso rallado}} de forma homogénea.","minutes":1,"kind":"activo"},{"text":"Gratinar en el horno con el grill hasta que la superficie esté dorada, unos 6 min.","minutes":6,"kind":"pasivo"},{"text":"Servir caliente directamente desde la fuente.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'horno', NULL),
  ('guarniciones_024', 'Puré de patata con mantequilla y nuez moscada', 'guarniciones', 'none', 'patatas', ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, NULL, 25, 'facil', 'all', 310, 6, 38, 14, 2, true, true, '{"lactosa"}', '[{"name":"Patata","amount":400,"unit":"g"},{"name":"Leche entera","amount":100,"unit":"ml"},{"name":"Mantequilla","amount":30,"unit":"g"},{"name":"Nuez moscada molida","amount":1,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Pelar patata y cortar en trozos regulares de unos 3 cm.","Colocar los trozos de patata en una olla, cubrir con agua fría y añadir sal.","Llevar a ebullición a fuego fuerte.","Cocer a fuego medio hasta que la patata esté muy tierna al pinchar, unos 18 min.","Calentar leche entera con mantequilla en un cazo a fuego suave hasta que la mantequilla se derrita.","Escurrir las patatas y devolverlas a la olla caliente fuera del fuego.","Machacar las patatas con un pasapurés añadiendo la leche caliente poco a poco.","Remover hasta conseguir una textura sedosa y sin grumos.","Añadir nuez moscada molida y ajustar de sal al gusto, mezclar bien.","Servir el puré caliente de inmediato."}', 'Puré de patata cremoso, con el brillo de la mantequilla derretida y un toque de nuez moscada.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Pelar {{Patata}} y cortar en trozos regulares de unos 3 cm.","minutes":5,"kind":"prep"},{"text":"Colocar los trozos de patata en una olla, cubrir con agua fría y añadir {{Sal|gusto}}.","minutes":2,"kind":"activo"},{"text":"Llevar a ebullición a fuego fuerte.","minutes":3,"kind":"activo"},{"text":"Cocer a fuego medio hasta que la patata esté muy tierna al pinchar, unos 18 min.","minutes":18,"kind":"pasivo"},{"text":"Calentar {{Leche entera}} con {{Mantequilla}} en un cazo a fuego suave hasta que la mantequilla se derrita.","minutes":3,"kind":"paralelo","during":3},{"text":"Escurrir las patatas y devolverlas a la olla caliente fuera del fuego.","minutes":1,"kind":"activo"},{"text":"Machacar las patatas con un pasapurés añadiendo la leche caliente poco a poco.","minutes":3,"kind":"activo"},{"text":"Remover hasta conseguir una textura sedosa y sin grumos.","minutes":2,"kind":"activo"},{"text":"Añadir {{Nuez moscada molida|pizca}} y ajustar de sal al gusto, mezclar bien.","minutes":1,"kind":"activo"},{"text":"Servir el puré caliente de inmediato.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, NULL, NULL)
