insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id, extra_proteins, freezable, steps_rich, estrella, occasion, kid_favourite, tecnica, cocina
) values
  ('guarniciones_025', 'Boniato asado con miel y tomillo', 'guarniciones', 'none', NULL, ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, 'horno', 40, 'facil', 'all', 260, 3, 46, 7, 2, true, true, '{}', '[{"name":"Boniato","amount":400,"unit":"g"},{"name":"Miel","amount":20,"unit":"g"},{"name":"Tomillo fresco","amount":3,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C con calor arriba y abajo.","Lavar boniato bajo el grifo y secar bien.","Cortar el boniato en gajos de unos 3 cm sin pelarlo.","Disponer los gajos en una bandeja forrada con papel de horno.","Añadir aceite de oliva y sal sobre los gajos y mezclar hasta cubrirlos bien.","Hornear a 200 °C durante 20 min.","Retirar la bandeja, remover los gajos y volver a hornear hasta que estén tiernos y dorados.","Calentar miel en un cazo a fuego suave durante 1 min hasta que fluya con facilidad.","Retirar la bandeja del horno y rociar la miel templada sobre los gajos.","Repartir tomillo fresco por encima y servir de inmediato."}', 'Boniato asado hasta caramelizarse en los bordes, con un toque dulce de miel y tomillo fresco.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Precalentar el horno a 200 °C con calor arriba y abajo.","minutes":10,"kind":"pasivo"},{"text":"Lavar {{Boniato}} bajo el grifo y secar bien.","minutes":2,"kind":"prep"},{"text":"Cortar el boniato en gajos de unos 3 cm sin pelarlo.","minutes":3,"kind":"prep"},{"text":"Disponer los gajos en una bandeja forrada con papel de horno.","minutes":1,"kind":"prep"},{"text":"Añadir {{Aceite de oliva|chorrito}} y {{Sal|gusto}} sobre los gajos y mezclar hasta cubrirlos bien.","minutes":1,"kind":"activo"},{"text":"Hornear a 200 °C durante 20 min.","minutes":20,"kind":"pasivo"},{"text":"Retirar la bandeja, remover los gajos y volver a hornear hasta que estén tiernos y dorados.","minutes":12,"kind":"pasivo"},{"text":"Calentar {{Miel}} en un cazo a fuego suave durante 1 min hasta que fluya con facilidad.","minutes":1,"kind":"activo"},{"text":"Retirar la bandeja del horno y rociar la miel templada sobre los gajos.","minutes":1,"kind":"activo"},{"text":"Repartir {{Tomillo fresco|gusto}} por encima y servir de inmediato.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, NULL, NULL),
  ('guarniciones_026', 'Coles de Bruselas con panceta y balsámico', 'guarniciones', 'none', NULL, ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, NULL, 25, 'facil', 'all', 270, 9, 18, 17, 2, false, true, '{"sulfitos"}', '[{"name":"Coles de Bruselas","amount":350,"unit":"g"},{"name":"Panceta ahumada en taquitos","amount":60,"unit":"g"},{"name":"Vinagre balsámico","amount":20,"unit":"ml"},{"name":"Aceite de oliva","amount":10,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Retirar las hojas exteriores de coles de bruselas y cortarlas por la mitad.","Llevar a ebullición una olla con agua y sal.","Escaldar las coles en el agua hirviendo durante 4 min, hasta que empiecen a ablandarse.","Escurrir las coles y reservar.","Calentar sartén a fuego medio-alto y añadir panceta ahumada en taquitos.","Dorar la panceta, removiendo, durante 4 min, hasta que quede crujiente y haya soltado su grasa.","Añadir aceite de oliva a la sartén y colocar las coles con el corte hacia abajo.","Saltear las coles a fuego medio-alto durante 5 min, hasta que el corte se dore bien.","Añadir vinagre balsámico y remover para glasear las coles.","Dejar reducir el vinagre balsámico 2 min, removiendo, hasta que las coles queden bien lacadas.","Rectificar de sal y servir las coles bien calientes."}', 'Coles de Bruselas doradas y crujientes con panceta, envueltas en un glaseado oscuro de vinagre balsámico.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, ARRAY['cerdo']::main_protein[], false, '[{"text":"Retirar las hojas exteriores de {{Coles de Bruselas}} y cortarlas por la mitad.","minutes":3,"kind":"prep"},{"text":"Llevar a ebullición una olla con agua y {{Sal|gusto}}.","minutes":3,"kind":"activo"},{"text":"Escaldar las coles en el agua hirviendo durante 4 min, hasta que empiecen a ablandarse.","minutes":4,"kind":"pasivo"},{"text":"Escurrir las coles y reservar.","minutes":1,"kind":"prep"},{"text":"Calentar {{@Sartén}} a fuego medio-alto y añadir {{Panceta ahumada en taquitos}}.","minutes":1,"kind":"activo"},{"text":"Dorar la panceta, removiendo, durante 4 min, hasta que quede crujiente y haya soltado su grasa.","minutes":4,"kind":"activo"},{"text":"Añadir {{Aceite de oliva|chorrito}} a la sartén y colocar las coles con el corte hacia abajo.","minutes":1,"kind":"activo"},{"text":"Saltear las coles a fuego medio-alto durante 5 min, hasta que el corte se dore bien.","minutes":5,"kind":"activo"},{"text":"Añadir {{Vinagre balsámico}} y remover para glasear las coles.","minutes":1,"kind":"activo"},{"text":"Dejar reducir el vinagre balsámico 2 min, removiendo, hasta que las coles queden bien lacadas.","minutes":2,"kind":"activo"},{"text":"Rectificar de sal y servir las coles bien calientes.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, NULL, NULL),
  ('guarniciones_027', 'Espárragos trigueros con huevo poché', 'guarniciones', 'none', NULL, ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, NULL, 20, 'normal', 'all', 170, 9, 6, 13, 2, true, false, '{"huevo"}', '[{"name":"Espárragos trigueros","amount":300,"unit":"g"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Vinagre","amount":15,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Lavar espárragos trigueros bajo agua fría y retirar la parte leñosa del tallo rompiéndola con los dedos.","Llevar a ebullición un cazo con agua y vinagre.","Calentar plancha con aceite de oliva a fuego fuerte.","Asar los espárragos trigueros 5 min, dándoles la vuelta a mitad, hasta que estén tiernos y algo tostados.","Cascar huevo uno a uno en un cuenco pequeño, sin romper la yema.","Bajar el fuego del cazo hasta que el agua esté sin hervir con fuerza y crear un remolino con una cuchara.","Verter un huevo desde el cuenco en el centro del remolino con cuidado.","Cocer 3 min hasta que la clara cuaje y la yema quede líquida.","Retirar el huevo poché con una espumadera y escurrir sobre papel absorbente.","Repetir el remolino y cocer el segundo huevo de la misma forma 3 min.","Retirar el segundo huevo con la espumadera y escurrir sobre papel absorbente.","Repartir los espárragos trigueros en los platos, colocar un huevo poché sobre cada ración y añadir sal."}', 'Espárragos trigueros a la plancha coronados con un huevo poché cuya yema los baña al romperse.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Lavar {{Espárragos trigueros}} bajo agua fría y retirar la parte leñosa del tallo rompiéndola con los dedos.","minutes":2,"kind":"prep"},{"text":"Llevar a ebullición un cazo con agua y {{Vinagre}}.","minutes":3,"kind":"activo"},{"text":"Calentar {{@Plancha}} con {{Aceite de oliva|chorrito}} a fuego fuerte.","minutes":1,"kind":"activo"},{"text":"Asar los espárragos trigueros 5 min, dándoles la vuelta a mitad, hasta que estén tiernos y algo tostados.","minutes":5,"kind":"pasivo"},{"text":"Cascar {{Huevo}} uno a uno en un cuenco pequeño, sin romper la yema.","minutes":1,"kind":"prep"},{"text":"Bajar el fuego del cazo hasta que el agua esté sin hervir con fuerza y crear un remolino con una cuchara.","minutes":1,"kind":"activo"},{"text":"Verter un huevo desde el cuenco en el centro del remolino con cuidado.","minutes":1,"kind":"activo"},{"text":"Cocer 3 min hasta que la clara cuaje y la yema quede líquida.","minutes":3,"kind":"pasivo"},{"text":"Retirar el huevo poché con una espumadera y escurrir sobre papel absorbente.","minutes":1,"kind":"activo"},{"text":"Repetir el remolino y cocer el segundo huevo de la misma forma 3 min.","minutes":3,"kind":"pasivo"},{"text":"Retirar el segundo huevo con la espumadera y escurrir sobre papel absorbente.","minutes":1,"kind":"activo"},{"text":"Repartir los espárragos trigueros en los platos, colocar un huevo poché sobre cada ración y añadir {{Sal|gusto}}.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, NULL, NULL),
  ('guarniciones_028', 'Patatas panadera con romero', 'guarniciones', 'none', 'patatas', ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, 'horno', 45, 'facil', 'all', 280, 5, 38, 10, 2, true, true, '{}', '[{"name":"Patata","amount":400,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Caldo de verduras","amount":150,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Romero fresco","amount":3,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 190 °C con calor arriba y abajo.","Pelar patata y cortar en rodajas finas de 3-4 mm.","Cortar cebolla en juliana fina.","Engrasar una fuente de horno con aceite de oliva.","Disponer una capa de patatas en la fuente, cubrir con cebolla y añadir sal. Repetir hasta agotar los ingredientes.","Verter caldo de verduras y el resto del aceite de oliva sobre las capas.","Repartir romero fresco por encima de las patatas.","Tapar la fuente con papel de aluminio y hornear a 190 °C durante 25 min.","Retirar el papel de aluminio y hornear 15 min más hasta que las patatas estén doradas por arriba.","Reposar la fuente 5 min fuera del horno antes de servir.","Servir las patatas directamente desde la fuente, repartiendo capas con un poco del jugo del fondo."}', 'Patatas panadera en capas doradas y jugosas, perfumadas con romero fresco entre capa y capa.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Precalentar el horno a 190 °C con calor arriba y abajo.","minutes":10,"kind":"pasivo"},{"text":"Pelar {{Patata}} y cortar en rodajas finas de 3-4 mm.","minutes":5,"kind":"prep"},{"text":"Cortar {{Cebolla}} en juliana fina.","minutes":3,"kind":"prep"},{"text":"Engrasar una fuente de horno con {{Aceite de oliva|chorrito}}.","minutes":1,"kind":"prep"},{"text":"Disponer una capa de patatas en la fuente, cubrir con cebolla y añadir {{Sal|gusto}}. Repetir hasta agotar los ingredientes.","minutes":3,"kind":"activo"},{"text":"Verter {{Caldo de verduras}} y el resto del aceite de oliva sobre las capas.","minutes":1,"kind":"activo"},{"text":"Repartir {{Romero fresco}} por encima de las patatas.","minutes":1,"kind":"prep"},{"text":"Tapar la fuente con papel de aluminio y hornear a 190 °C durante 25 min.","minutes":25,"kind":"pasivo"},{"text":"Retirar el papel de aluminio y hornear 15 min más hasta que las patatas estén doradas por arriba.","minutes":15,"kind":"pasivo"},{"text":"Reposar la fuente 5 min fuera del horno antes de servir.","minutes":5,"kind":"espera"},{"text":"Servir las patatas directamente desde la fuente, repartiendo capas con un poco del jugo del fondo.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, NULL, NULL),
  ('guarniciones_029', 'Zanahorias glaseadas con miel y comino', 'guarniciones', 'none', NULL, ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, NULL, 20, 'facil', 'all', 160, 2, 25, 6, 2, true, true, '{"lactosa"}', '[{"name":"Zanahoria","amount":350,"unit":"g"},{"name":"Miel","amount":20,"unit":"g"},{"name":"Mantequilla","amount":15,"unit":"g"},{"name":"Comino molido","amount":2,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Pelar zanahoria y cortarlas por la mitad a lo largo si son grandes; dejarlas enteras si son pequeñas.","Llevar a ebullición agua con sal en un cazo.","Cocer las zanahorias en el agua hirviendo hasta que estén tiernas pero firmes.","Escurrir las zanahorias en un colador y reservar.","Calentar sartén a fuego medio y fundir mantequilla hasta que espume.","Añadir las zanahorias escurridas, miel y comino molido a la sartén.","Saltear removiendo con frecuencia hasta que las zanahorias queden glaseadas y brillantes.","Servir las zanahorias calientes con el jugo del glaseado de la sartén."}', 'Zanahorias glaseadas hasta quedar brillantes y pegajosas, con un toque cálido de comino.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Pelar {{Zanahoria}} y cortarlas por la mitad a lo largo si son grandes; dejarlas enteras si son pequeñas.","minutes":3,"kind":"prep"},{"text":"Llevar a ebullición agua con {{Sal|gusto}} en un cazo.","minutes":3,"kind":"activo"},{"text":"Cocer las zanahorias en el agua hirviendo hasta que estén tiernas pero firmes.","minutes":11,"kind":"pasivo"},{"text":"Escurrir las zanahorias en un colador y reservar.","minutes":1,"kind":"activo"},{"text":"Calentar {{@Sartén}} a fuego medio y fundir {{Mantequilla}} hasta que espume.","minutes":1,"kind":"activo"},{"text":"Añadir las zanahorias escurridas, {{Miel}} y {{Comino molido}} a la sartén.","minutes":1,"kind":"activo"},{"text":"Saltear removiendo con frecuencia hasta que las zanahorias queden glaseadas y brillantes.","minutes":4,"kind":"activo"},{"text":"Servir las zanahorias calientes con el jugo del glaseado de la sartén.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, NULL, NULL),
  ('guarniciones_030', 'Champiñones al ajillo enteros', 'guarniciones', 'none', NULL, ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, NULL, 15, 'facil', 'all', 190, 6, 7, 15, 2, true, true, '{"sulfitos"}', '[{"name":"Champiñones enteros","amount":400,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Guindilla seca","amount":2,"unit":"g"},{"name":"Vino blanco","amount":30,"unit":"ml"},{"name":"Perejil fresco","amount":5,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Limpiar champiñones enteros con un paño húmedo y retirar la base terrosa del pie, dejándolos enteros.","Laminar ajo.","Picar perejil fresco fino.","Calentar aceite de oliva en sartén amplia a fuego medio hasta que esté caliente.","Sofreír el ajo laminado junto con guindilla seca hasta que el ajo empiece a dorarse.","Subir el fuego a fuego fuerte y añadir los champiñones enteros.","Saltear los champiñones hasta que empiecen a dorarse, removiendo de vez en cuando.","Añadir vino blanco y remover hasta que evapore el alcohol.","Añadir sal y saltear hasta que los champiñones estén tiernos pero enteros.","Espolvorear el perejil picado sobre los champiñones y servir bien calientes."}', 'Champiñones enteros salteados al ajillo, con el brillo del aceite y el ajo dorado.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Limpiar {{Champiñones enteros}} con un paño húmedo y retirar la base terrosa del pie, dejándolos enteros.","minutes":3,"kind":"prep"},{"text":"Laminar {{Ajo}}.","minutes":1,"kind":"prep"},{"text":"Picar {{Perejil fresco}} fino.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} amplia a fuego medio hasta que esté caliente.","minutes":1,"kind":"activo"},{"text":"Sofreír el ajo laminado junto con {{Guindilla seca}} hasta que el ajo empiece a dorarse.","minutes":2,"kind":"activo"},{"text":"Subir el fuego a fuego fuerte y añadir los champiñones enteros.","minutes":1,"kind":"activo"},{"text":"Saltear los champiñones hasta que empiecen a dorarse, removiendo de vez en cuando.","minutes":5,"kind":"activo"},{"text":"Añadir {{Vino blanco}} y remover hasta que evapore el alcohol.","minutes":2,"kind":"activo"},{"text":"Añadir {{Sal|gusto}} y saltear hasta que los champiñones estén tiernos pero enteros.","minutes":2,"kind":"activo"},{"text":"Espolvorear el perejil picado sobre los champiñones y servir bien calientes.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, NULL, NULL),
  ('guarniciones_031', 'Puré de coliflor con hierbas y aceite de oliva', 'guarniciones', 'none', NULL, ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, NULL, 25, 'facil', 'all', 170, 5, 12, 12, 2, true, true, '{}', '[{"name":"Coliflor","amount":500,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Perejil fresco","amount":5,"unit":"g"},{"name":"Cebollino","amount":3,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Separar coliflor en ramilletes y lavar bajo agua fría.","Pelar ajo y dejar los dientes enteros.","Llevar una olla con agua abundante y sal a ebullición a fuego fuerte.","Añadir los ramilletes de coliflor y el ajo a la olla cuando rompa a hervir.","Cocer a fuego medio hasta que la coliflor esté muy tierna, unos 13 min.","Picar perejil fresco y cebollino muy finos y reservar.","Escurrir la coliflor y el ajo, reservando un vaso del agua de cocción.","Triturar la coliflor y el ajo con la batidora hasta obtener una textura fina.","Añadir un poco del agua de cocción reservada si el puré queda demasiado espeso y triturar de nuevo.","Añadir la mitad de aceite de oliva mientras se tritura hasta que el puré quede sedoso.","Servir el puré en un plato hondo y terminar con el aceite de oliva restante en hilo y las hierbas picadas."}', 'Puré de coliflor de un blanco inmaculado, terminado con un hilo de aceite de oliva y hierbas frescas.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Separar {{Coliflor}} en ramilletes y lavar bajo agua fría.","minutes":2,"kind":"prep"},{"text":"Pelar {{Ajo}} y dejar los dientes enteros.","minutes":1,"kind":"prep"},{"text":"Llevar una olla con agua abundante y {{Sal|gusto}} a ebullición a fuego fuerte.","minutes":4,"kind":"activo"},{"text":"Añadir los ramilletes de coliflor y el ajo a la olla cuando rompa a hervir.","minutes":1,"kind":"activo"},{"text":"Cocer a fuego medio hasta que la coliflor esté muy tierna, unos 13 min.","minutes":13,"kind":"pasivo"},{"text":"Picar {{Perejil fresco}} y {{Cebollino}} muy finos y reservar.","minutes":2,"kind":"paralelo","during":4},{"text":"Escurrir la coliflor y el ajo, reservando un vaso del agua de cocción.","minutes":1,"kind":"activo"},{"text":"Triturar la coliflor y el ajo con la batidora hasta obtener una textura fina.","minutes":2,"kind":"activo"},{"text":"Añadir un poco del agua de cocción reservada si el puré queda demasiado espeso y triturar de nuevo.","minutes":1,"kind":"opcional"},{"text":"Añadir la mitad de {{Aceite de oliva}} mientras se tritura hasta que el puré quede sedoso.","minutes":1,"kind":"activo"},{"text":"Servir el puré en un plato hondo y terminar con el aceite de oliva restante en hilo y las hierbas picadas.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, NULL, NULL),
  ('guarniciones_032', 'Alcachofas confitadas con jamón', 'guarniciones', 'none', NULL, ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, NULL, 35, 'normal', 'all', 290, 8, 10, 19, 2, true, true, '{}', '[{"name":"Alcachofa","amount":4,"unit":"ud"},{"name":"Jamón serrano en virutas","amount":40,"unit":"g"},{"name":"Aceite de oliva","amount":200,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Laurel","amount":1,"unit":"ud"},{"name":"Limón","amount":15,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Retirar las hojas exteriores duras de alcachofa hasta llegar a las hojas tiernas.","Cortar la punta de cada alcachofa y frotar con limón para evitar la oxidación.","Cortar cada alcachofa por la mitad y retirar la pelusa interior con una cuchara.","Aplastar ajo con el lateral del cuchillo para agrietarlo sin pelarlo del todo.","Verter aceite de oliva en una cazuela pequeña y añadir el ajo aplastado y laurel.","Calentar el aceite a fuego suave hasta que esté templado, sin que humee.","Sumergir las alcachofas en el aceite templado, con el corte hacia abajo.","Confitar a fuego muy suave durante 25 min, sin que el aceite llegue a burbujear.","Comprobar la terneza pinchando con una punta de cuchillo; deben ceder sin resistencia.","Retirar las alcachofas del aceite y escurrir sobre papel absorbente.","Salpimentar con sal y abrir ligeramente cada mitad en forma de abanico.","Disponer las alcachofas en el plato y repartir jamón serrano en virutas por encima."}', 'Corazones de alcachofa confitados hasta quedar tiernísimos, abiertos en abanico y coronados con virutas de jamón.', NULL, '{}', true, NULL, NULL, '{}', NULL, ARRAY['cerdo']::main_protein[], false, '[{"text":"Retirar las hojas exteriores duras de {{Alcachofa}} hasta llegar a las hojas tiernas.","minutes":3,"kind":"prep"},{"text":"Cortar la punta de cada alcachofa y frotar con {{Limón}} para evitar la oxidación.","minutes":2,"kind":"prep"},{"text":"Cortar cada alcachofa por la mitad y retirar la pelusa interior con una cuchara.","minutes":2,"kind":"prep"},{"text":"Aplastar {{Ajo}} con el lateral del cuchillo para agrietarlo sin pelarlo del todo.","minutes":1,"kind":"prep"},{"text":"Verter {{Aceite de oliva}} en una cazuela pequeña y añadir el ajo aplastado y {{Laurel}}.","minutes":1,"kind":"activo"},{"text":"Calentar el aceite a fuego suave hasta que esté templado, sin que humee.","minutes":2,"kind":"activo"},{"text":"Sumergir las alcachofas en el aceite templado, con el corte hacia abajo.","minutes":1,"kind":"activo"},{"text":"Confitar a fuego muy suave durante 25 min, sin que el aceite llegue a burbujear.","minutes":25,"kind":"pasivo"},{"text":"Comprobar la terneza pinchando con una punta de cuchillo; deben ceder sin resistencia.","minutes":1,"kind":"activo"},{"text":"Retirar las alcachofas del aceite y escurrir sobre papel absorbente.","minutes":1,"kind":"activo"},{"text":"Salpimentar con {{Sal|gusto}} y abrir ligeramente cada mitad en forma de abanico.","minutes":1,"kind":"prep"},{"text":"Disponer las alcachofas en el plato y repartir {{Jamón serrano en virutas}} por encima.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, NULL, NULL),
  ('guarniciones_033', 'Setas salteadas con jamón ibérico', 'guarniciones', 'none', NULL, ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, NULL, 15, 'facil', 'all', 190, 12, 5, 14, 2, true, true, '{}', '[{"name":"Setas variadas","amount":350,"unit":"g"},{"name":"Jamón ibérico en taquitos","amount":50,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Perejil fresco","amount":5,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Limpiar setas variadas con un paño húmedo y cortar las más grandes en trozos, dejando las pequeñas enteras.","Picar ajo fino.","Picar perejil fresco fino.","Calentar aceite de oliva en sartén amplia a fuego fuerte hasta que esté bien caliente.","Saltear las setas a fuego fuerte sin remover en exceso hasta que se doren y suelten su agua.","Añadir el ajo picado y saltear hasta que esté dorado.","Añadir jamón ibérico en taquitos y saltear hasta que se dore ligeramente y suelte su grasa.","Añadir sal y espolvorear el perejil picado por encima.","Servir de inmediato en el plato."}', 'Setas de temporada salteadas con jamón ibérico, con la grasa dorada del jamón impregnándolo todo.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, ARRAY['cerdo']::main_protein[], false, '[{"text":"Limpiar {{Setas variadas}} con un paño húmedo y cortar las más grandes en trozos, dejando las pequeñas enteras.","minutes":3,"kind":"prep"},{"text":"Picar {{Ajo}} fino.","minutes":1,"kind":"prep"},{"text":"Picar {{Perejil fresco}} fino.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} amplia a fuego fuerte hasta que esté bien caliente.","minutes":1,"kind":"activo"},{"text":"Saltear las setas a fuego fuerte sin remover en exceso hasta que se doren y suelten su agua.","minutes":5,"kind":"activo"},{"text":"Añadir el ajo picado y saltear hasta que esté dorado.","minutes":1,"kind":"activo"},{"text":"Añadir {{Jamón ibérico en taquitos}} y saltear hasta que se dore ligeramente y suelte su grasa.","minutes":2,"kind":"activo"},{"text":"Añadir {{Sal|gusto}} y espolvorear el perejil picado por encima.","minutes":1,"kind":"activo"},{"text":"Servir de inmediato en el plato.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, NULL, NULL),
  ('guarniciones_034', 'Puerros a la brasa con romesco', 'guarniciones', 'none', NULL, ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, 'plancha', 30, 'normal', 'all', 340, 7, 20, 23, 2, false, true, '{"frutos_secos","gluten","sulfitos"}', '[{"name":"Puerro","amount":4,"unit":"ud"},{"name":"Tomate maduro","amount":50,"unit":"g"},{"name":"Pimiento choricero","amount":10,"unit":"g"},{"name":"Almendra tostada","amount":20,"unit":"g"},{"name":"Avellana tostada","amount":10,"unit":"g"},{"name":"Pan frito","amount":15,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Vinagre de Jerez","amount":10,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Retirar la parte verde más dura y las raíces de puerro, lavar bien entre las capas y escurrir.","Llevar a ebullición agua con sal en una olla grande a fuego fuerte.","Cocer los puerros enteros durante 9 min, hasta que estén tiernos pero no blandos.","Escurrir los puerros cocidos y dejar templar sobre un trapo limpio.","Triturar tomate maduro, pimiento choricero, almendra tostada, avellana tostada y pan frito en el vaso de la batidora.","Añadir ajo, aceite de oliva y vinagre de jerez al vaso y triturar hasta obtener una salsa espesa y homogénea.","Salpimentar el romesco con sal al gusto, remover y reservar.","Calentar plancha a fuego fuerte hasta que humee.","Marcar los puerros por todos los lados hasta que queden bien tostados y con marcas oscuras.","Cortar los puerros por la mitad a lo largo y disponerlos en el plato.","Napar los puerros con el romesco o servirlo aparte en un cuenco junto al plato."}', 'Puerros marcados a la brasa hasta tostarse, servidos sobre un intenso romesco rojo.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Retirar la parte verde más dura y las raíces de {{Puerro}}, lavar bien entre las capas y escurrir.","minutes":5,"kind":"prep","part":"principal"},{"text":"Llevar a ebullición agua con {{Sal|gusto}} en una olla grande a fuego fuerte.","minutes":3,"kind":"activo","part":"principal"},{"text":"Cocer los puerros enteros durante 9 min, hasta que estén tiernos pero no blandos.","minutes":9,"kind":"pasivo","part":"principal"},{"text":"Escurrir los puerros cocidos y dejar templar sobre un trapo limpio.","minutes":3,"kind":"espera","part":"principal"},{"text":"Triturar {{Tomate maduro}}, {{Pimiento choricero}}, {{Almendra tostada}}, {{Avellana tostada}} y {{Pan frito}} en el vaso de la batidora.","minutes":2,"kind":"paralelo","part":"salsa","during":2},{"text":"Añadir {{Ajo}}, {{Aceite de oliva}} y {{Vinagre de Jerez}} al vaso y triturar hasta obtener una salsa espesa y homogénea.","minutes":2,"kind":"activo","part":"salsa"},{"text":"Salpimentar el romesco con sal al gusto, remover y reservar.","minutes":1,"kind":"prep","part":"salsa"},{"text":"Calentar {{@Plancha}} a fuego fuerte hasta que humee.","minutes":2,"kind":"activo","part":"principal"},{"text":"Marcar los puerros por todos los lados hasta que queden bien tostados y con marcas oscuras.","minutes":5,"kind":"activo","part":"principal"},{"text":"Cortar los puerros por la mitad a lo largo y disponerlos en el plato.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Napar los puerros con el romesco o servirlo aparte en un cuenco junto al plato.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, NULL, NULL, NULL, NULL, NULL)
