insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id, extra_proteins, freezable, steps_rich, estrella, occasion, kid_favourite, tecnica, cocina
) values
  ('guarniciones_035', 'Calabaza asada con queso de cabra y nueces', 'guarniciones', 'none', NULL, ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, 'horno', 35, 'facil', 'all', 380, 13, 20, 28, 2, true, true, '{"lactosa","frutos_secos"}', '[{"name":"Calabaza","amount":400,"unit":"g"},{"name":"Queso de cabra","amount":80,"unit":"g"},{"name":"Nuez","amount":30,"unit":"g"},{"name":"Miel","amount":15,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Tomillo fresco","amount":2,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C.","Pelar calabaza y cortarla en dados de unos 2 cm.","Disponer la calabaza en una bandeja de horno en una sola capa.","Aliñar con aceite de oliva, sal y tomillo fresco y mezclar bien.","Hornear la bandeja en la rejilla central hasta que la calabaza esté tierna y dorada en los bordes.","Picar nuez groseramente mientras la calabaza se hornea.","Retirar la bandeja del horno y desmenuzar queso de cabra por encima para que se ablande con el calor residual.","Repartir las nueces picadas sobre la calabaza con queso de cabra.","Terminar con un hilo de miel repartido por toda la bandeja.","Servir templado directamente de la bandeja."}', 'Calabaza asada de naranja intenso, con queso de cabra cremoso y nueces tostadas por encima.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Precalentar el horno a 200 °C.","minutes":10,"kind":"pasivo"},{"text":"Pelar {{Calabaza}} y cortarla en dados de unos 2 cm.","minutes":5,"kind":"paralelo","during":0},{"text":"Disponer la calabaza en una bandeja de horno en una sola capa.","minutes":1,"kind":"prep"},{"text":"Aliñar con {{Aceite de oliva|chorrito}}, {{Sal|gusto}} y {{Tomillo fresco|pizca}} y mezclar bien.","minutes":1,"kind":"prep"},{"text":"Hornear la bandeja en la rejilla central hasta que la calabaza esté tierna y dorada en los bordes.","minutes":25,"kind":"pasivo"},{"text":"Picar {{Nuez}} groseramente mientras la calabaza se hornea.","minutes":2,"kind":"paralelo","during":4},{"text":"Retirar la bandeja del horno y desmenuzar {{Queso de cabra}} por encima para que se ablande con el calor residual.","minutes":1,"kind":"activo"},{"text":"Repartir las nueces picadas sobre la calabaza con queso de cabra.","minutes":1,"kind":"activo"},{"text":"Terminar con un hilo de {{Miel}} repartido por toda la bandeja.","minutes":1,"kind":"activo"},{"text":"Servir templado directamente de la bandeja.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, NULL, NULL),
  ('guarniciones_036', 'Patatas bravas caseras', 'guarniciones', 'none', 'patatas', ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, NULL, 35, 'normal', 'all', 400, 7, 36, 23, 2, false, false, '{"huevo"}', '[{"name":"Patata","amount":400,"unit":"g"},{"name":"Aceite de oliva","amount":300,"unit":"ml"},{"name":"Tomate triturado","amount":100,"unit":"g"},{"name":"Pimentón picante","amount":5,"unit":"g"},{"name":"Cayena molida","amount":1,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Limón","amount":10,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Pelar patata y cortar en dados irregulares de unos 3 cm.","Picar ajo fino y dividir en 2 partes: una para la salsa brava y otra para el alioli.","Calentar aceite de oliva en sartén honda a fuego medio hasta que esté caliente.","Freír las patatas en el aceite caliente hasta que estén doradas y crujientes por fuera y tiernas por dentro.","Calentar aceite de oliva en un cazo a fuego suave hasta que esté templado.","Sofreír la mitad del ajo picado en el cazo a fuego suave hasta que empiece a dorarse.","Retirar el cazo del fuego y añadir pimentón picante removiendo para que no se queme.","Añadir tomate triturado y cayena molida al cazo y volver al fuego suave.","Cocer la salsa a fuego suave hasta que espese ligeramente.","Poner huevo en un vaso alto junto con la otra mitad del ajo picado y limón.","Triturar con batidora de mano arrancando desde el fondo hasta que emulsione.","Añadir aceite de oliva en hilo fino mientras se tritura hasta que el alioli espese.","Escurrir las patatas fritas sobre papel absorbente y salar con sal.","Repartir las patatas en el plato y cubrir con la salsa brava.","Añadir el alioli en líneas por encima y servir de inmediato."}', 'Dados de patata dorados y crujientes, cubiertos de brava roja picante y líneas de alioli casero.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Pelar {{Patata}} y cortar en dados irregulares de unos 3 cm.","minutes":5,"kind":"prep","part":"principal"},{"text":"Picar {{Ajo}} fino y dividir en 2 partes: una para la salsa brava y otra para el alioli.","minutes":2,"kind":"prep","part":"principal"},{"text":"Calentar {{Aceite de oliva|abundante}} en {{@Sartén}} honda a fuego medio hasta que esté caliente.","minutes":2,"kind":"activo","part":"principal"},{"text":"Freír las patatas en el aceite caliente hasta que estén doradas y crujientes por fuera y tiernas por dentro.","minutes":12,"kind":"pasivo","part":"principal"},{"text":"Calentar {{Aceite de oliva|chorrito}} en un cazo a fuego suave hasta que esté templado.","minutes":1,"kind":"activo","part":"salsa"},{"text":"Sofreír la mitad del ajo picado en el cazo a fuego suave hasta que empiece a dorarse.","minutes":2,"kind":"activo","part":"salsa"},{"text":"Retirar el cazo del fuego y añadir {{Pimentón picante}} removiendo para que no se queme.","minutes":1,"kind":"activo","part":"salsa"},{"text":"Añadir {{Tomate triturado}} y {{Cayena molida}} al cazo y volver al fuego suave.","minutes":1,"kind":"activo","part":"salsa"},{"text":"Cocer la salsa a fuego suave hasta que espese ligeramente.","minutes":6,"kind":"pasivo","part":"salsa"},{"text":"Poner {{Huevo}} en un vaso alto junto con la otra mitad del ajo picado y {{Limón}}.","minutes":1,"kind":"prep","part":"guarnicion"},{"text":"Triturar con batidora de mano arrancando desde el fondo hasta que emulsione.","minutes":1,"kind":"activo","part":"guarnicion"},{"text":"Añadir aceite de oliva en hilo fino mientras se tritura hasta que el alioli espese.","minutes":2,"kind":"activo","part":"guarnicion"},{"text":"Escurrir las patatas fritas sobre papel absorbente y salar con {{Sal|gusto}}.","minutes":1,"kind":"prep","part":"combinado"},{"text":"Repartir las patatas en el plato y cubrir con la salsa brava.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Añadir el alioli en líneas por encima y servir de inmediato.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, NULL, NULL, NULL, NULL, NULL),
  ('guarniciones_037', 'Espinacas con piñones y pasas', 'guarniciones', 'none', NULL, ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, NULL, 15, 'facil', 'all', 250, 8, 18, 18, 2, true, true, '{"frutos_secos","sulfitos"}', '[{"name":"Espinacas frescas","amount":400,"unit":"g"},{"name":"Piñones","amount":25,"unit":"g"},{"name":"Pasas","amount":25,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Sumergir pasas en agua templada para hidratarlas.","Laminar ajo.","Lavar espinacas frescas con abundante agua fría y escurrirlas bien.","Escurrir las pasas y reservar.","Tostar piñones en sartén sin aceite a fuego medio, removiendo hasta que se doren.","Retirar los piñones de la sartén y reservar.","Calentar aceite de oliva en la misma sartén a fuego medio.","Sofreír el ajo laminado hasta que esté dorado.","Añadir las espinacas por tandas y saltear a fuego fuerte hasta que reduzcan y suelten el agua.","Incorporar las pasas escurridas y los piñones tostados y mezclar bien.","Salpimentar con sal y servir caliente."}', 'Espinacas salteadas de un verde brillante, salpicadas de piñones dorados y pasas granate.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Sumergir {{Pasas}} en agua templada para hidratarlas.","minutes":10,"kind":"espera"},{"text":"Laminar {{Ajo}}.","minutes":1,"kind":"prep"},{"text":"Lavar {{Espinacas frescas}} con abundante agua fría y escurrirlas bien.","minutes":2,"kind":"prep"},{"text":"Escurrir las pasas y reservar.","minutes":1,"kind":"prep"},{"text":"Tostar {{Piñones}} en {{@Sartén}} sin aceite a fuego medio, removiendo hasta que se doren.","minutes":3,"kind":"activo"},{"text":"Retirar los piñones de la sartén y reservar.","minutes":1,"kind":"activo"},{"text":"Calentar {{Aceite de oliva|chorrito}} en la misma sartén a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír el ajo laminado hasta que esté dorado.","minutes":2,"kind":"activo"},{"text":"Añadir las espinacas por tandas y saltear a fuego fuerte hasta que reduzcan y suelten el agua.","minutes":5,"kind":"activo"},{"text":"Incorporar las pasas escurridas y los piñones tostados y mezclar bien.","minutes":1,"kind":"activo"},{"text":"Salpimentar con {{Sal|gusto}} y servir caliente.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, NULL, NULL),
  ('guarniciones_038', 'Patatas Hasselback gratinadas', 'guarniciones', 'none', 'patatas', ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, 'horno', 55, 'normal', 'all', 480, 12, 42, 26, 2, true, true, '{"lactosa"}', '[{"name":"Patata","amount":4,"unit":"ud"},{"name":"Mantequilla","amount":30,"unit":"g"},{"name":"Queso rallado","amount":50,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Tomillo fresco","amount":2,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C.","Pelar patata y apoyar cada una entre 2 palillos o cucharas para no cortarla del todo.","Hacer cortes finos y paralelos en cada patata, sin llegar al fondo, separados unos 3 mm.","Picar ajo muy fino.","Fundir mantequilla en un cazo a fuego suave hasta que esté líquida.","Retirar el cazo del fuego y mezclar la mantequilla fundida con aceite de oliva y el ajo picado.","Colocar las patatas en una fuente de horno y pincelar con la mezcla, introduciendo la brocha entre las láminas.","Añadir sal sobre las patatas.","Hornear la fuente en el centro del horno durante 35 min, hasta que las patatas empiecen a abrirse en abanico y doren.","Retirar la fuente del horno y repartir queso rallado sobre y entre las láminas de cada patata.","Volver a introducir la fuente en el horno y hornear 12 min más, hasta que el queso funda y esté dorado.","Retirar la fuente del horno y repartir tomillo fresco por encima. Servir de inmediato."}', 'Patatas Hasselback abiertas en abanico, doradas y crujientes, con el queso fundido entre las láminas.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Precalentar el horno a 200 °C.","minutes":10,"kind":"pasivo"},{"text":"Pelar {{Patata}} y apoyar cada una entre 2 palillos o cucharas para no cortarla del todo.","minutes":3,"kind":"prep"},{"text":"Hacer cortes finos y paralelos en cada patata, sin llegar al fondo, separados unos 3 mm.","minutes":4,"kind":"prep"},{"text":"Picar {{Ajo}} muy fino.","minutes":1,"kind":"prep"},{"text":"Fundir {{Mantequilla}} en un cazo a fuego suave hasta que esté líquida.","minutes":2,"kind":"activo"},{"text":"Retirar el cazo del fuego y mezclar la mantequilla fundida con {{Aceite de oliva|chorrito}} y el ajo picado.","minutes":1,"kind":"activo"},{"text":"Colocar las patatas en una fuente de horno y pincelar con la mezcla, introduciendo la brocha entre las láminas.","minutes":2,"kind":"activo"},{"text":"Añadir {{Sal|gusto}} sobre las patatas.","minutes":1,"kind":"prep"},{"text":"Hornear la fuente en el centro del horno durante 35 min, hasta que las patatas empiecen a abrirse en abanico y doren.","minutes":35,"kind":"pasivo"},{"text":"Retirar la fuente del horno y repartir {{Queso rallado}} sobre y entre las láminas de cada patata.","minutes":2,"kind":"activo"},{"text":"Volver a introducir la fuente en el horno y hornear 12 min más, hasta que el queso funda y esté dorado.","minutes":12,"kind":"pasivo"},{"text":"Retirar la fuente del horno y repartir {{Tomillo fresco|pizca}} por encima. Servir de inmediato.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, NULL, NULL),
  ('guarniciones_039', 'Patatas fritas caseras crujientes', 'guarniciones', 'none', 'patatas', ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, NULL, 20, 'facil', 'all', 250, 4, 34, 12, 2, true, false, '{}', '[{"name":"Patata","amount":400,"unit":"g"},{"name":"Aceite de oliva","amount":350,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Pelar patata y cortar en bastones de 1 cm de grosor, regulares.","Sumergir los bastones en agua fría hasta que el agua salga limpia, unos 10 min.","Escurrir los bastones y secar muy bien con un paño limpio, sin dejar humedad.","Calentar aceite de oliva en una sartén honda a fuego medio hasta alcanzar 160 °C.","Freír los bastones a 160 °C durante 6 min hasta que estén tiernos por dentro sin dorarse.","Retirar los bastones y escurrir sobre papel absorbente.","Subir el fuego hasta que el aceite alcance 190 °C.","Freír los bastones de nuevo a 190 °C durante 3 min hasta que estén dorados y muy crujientes.","Retirar y escurrir sobre papel absorbente.","Añadir sal al momento sobre las patatas recién escurridas y servir enseguida."}', 'Patatas fritas doradas y crujientes por fuera, tiernas por dentro, fritas en dos tandas.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Pelar {{Patata}} y cortar en bastones de 1 cm de grosor, regulares.","minutes":5,"kind":"prep"},{"text":"Sumergir los bastones en agua fría hasta que el agua salga limpia, unos 10 min.","minutes":10,"kind":"espera"},{"text":"Escurrir los bastones y secar muy bien con un paño limpio, sin dejar humedad.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|abundante}} en una sartén honda a fuego medio hasta alcanzar 160 °C.","minutes":3,"kind":"activo"},{"text":"Freír los bastones a 160 °C durante 6 min hasta que estén tiernos por dentro sin dorarse.","minutes":6,"kind":"pasivo"},{"text":"Retirar los bastones y escurrir sobre papel absorbente.","minutes":1,"kind":"activo"},{"text":"Subir el fuego hasta que el aceite alcance 190 °C.","minutes":2,"kind":"activo"},{"text":"Freír los bastones de nuevo a 190 °C durante 3 min hasta que estén dorados y muy crujientes.","minutes":3,"kind":"pasivo"},{"text":"Retirar y escurrir sobre papel absorbente.","minutes":1,"kind":"activo"},{"text":"Añadir {{Sal|gusto}} al momento sobre las patatas recién escurridas y servir enseguida.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, NULL, NULL),
  ('guarniciones_040', 'Patatas fritas con parmesano y perejil', 'guarniciones', 'none', 'patatas', ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, NULL, 25, 'normal', 'all', 380, 9, 34, 21, 2, true, false, '{"lactosa"}', '[{"name":"Patata","amount":400,"unit":"g"},{"name":"Aceite de oliva","amount":350,"unit":"ml"},{"name":"Parmesano rallado","amount":30,"unit":"g"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Perejil fresco","amount":5,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Pelar patata y cortar en bastones de 1 cm de grosor.","Secar bien los bastones de patata con un paño limpio para evitar salpicaduras al freír.","Picar ajo muy fino.","Picar perejil fresco muy fino.","Mezclar el ajo picado y el perejil picado con parmesano rallado en un bol pequeño y reservar.","Calentar aceite de oliva en sartén honda a fuego fuerte hasta que esté bien caliente.","Freír los bastones de patata a fuego medio-fuerte hasta que estén dorados y crujientes por fuera y tiernos por dentro.","Escurrir las patatas fritas sobre papel absorbente.","Salar las patatas escurridas con sal al momento.","Volcar las patatas en un bol grande y espolvorear con la mezcla de parmesano, ajo y perejil.","Remover con energía para que la mezcla se adhiera a las patatas con el calor residual.","Servir de inmediato."}', 'Patatas fritas envueltas en parmesano, ajo y perejil, con un aroma que sube nada más servirlas.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Pelar {{Patata}} y cortar en bastones de 1 cm de grosor.","minutes":5,"kind":"prep"},{"text":"Secar bien los bastones de patata con un paño limpio para evitar salpicaduras al freír.","minutes":2,"kind":"prep"},{"text":"Picar {{Ajo}} muy fino.","minutes":1,"kind":"prep"},{"text":"Picar {{Perejil fresco}} muy fino.","minutes":1,"kind":"prep"},{"text":"Mezclar el ajo picado y el perejil picado con {{Parmesano rallado}} en un bol pequeño y reservar.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|abundante}} en {{@Sartén}} honda a fuego fuerte hasta que esté bien caliente.","minutes":2,"kind":"activo"},{"text":"Freír los bastones de patata a fuego medio-fuerte hasta que estén dorados y crujientes por fuera y tiernos por dentro.","minutes":10,"kind":"pasivo"},{"text":"Escurrir las patatas fritas sobre papel absorbente.","minutes":1,"kind":"activo"},{"text":"Salar las patatas escurridas con {{Sal|gusto}} al momento.","minutes":1,"kind":"activo"},{"text":"Volcar las patatas en un bol grande y espolvorear con la mezcla de parmesano, ajo y perejil.","minutes":1,"kind":"activo"},{"text":"Remover con energía para que la mezcla se adhiera a las patatas con el calor residual.","minutes":1,"kind":"activo"},{"text":"Servir de inmediato.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, NULL, NULL),
  ('guarniciones_041', 'Gratín dauphinois (patatas gratinadas con nata)', 'guarniciones', 'none', 'patatas', ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, 'horno', 70, 'normal', 'all', 540, 13, 47, 44, 2, true, true, '{"lactosa"}', '[{"name":"Patata","amount":500,"unit":"g"},{"name":"Nata para cocinar","amount":200,"unit":"ml"},{"name":"Leche entera","amount":100,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Queso gruyere rallado","amount":40,"unit":"g"},{"name":"Nuez moscada molida","amount":1,"unit":"g"},{"name":"Mantequilla","amount":10,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 170 °C con calor arriba y abajo.","Pelar patata y laminar muy fino, a 2-3 mm, con mandolina o cuchillo afilado.","Frotar una fuente de horno con ajo cortado por la mitad frotando toda la superficie.","Untar la fuente con mantequilla en capa fina por el fondo y las paredes.","Disponer las láminas de patata en capas superpuestas en la fuente, añadir sal entre capa y capa.","Calentar nata para cocinar, leche entera y nuez moscada molida en un cazo a fuego medio hasta que humee sin hervir.","Verter la mezcla caliente de nata y leche sobre las patatas hasta casi cubrirlas.","Repartir queso gruyere rallado de forma uniforme por toda la superficie.","Hornear en el centro del horno durante 50 min, hasta que las patatas estén tiernas al pinchar y la superficie esté dorada.","Reposar el gratín 10 min fuera del horno antes de servir para que asiente.","Servir en la propia fuente cortando porciones con espátula."}', 'Gratín dauphinois en capas finísimas, con una corteza dorada y burbujeante recién salida del horno.', NULL, '{}', true, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Precalentar el horno a 170 °C con calor arriba y abajo.","minutes":10,"kind":"pasivo"},{"text":"Pelar {{Patata}} y laminar muy fino, a 2-3 mm, con mandolina o cuchillo afilado.","minutes":8,"kind":"prep"},{"text":"Frotar una fuente de horno con {{Ajo}} cortado por la mitad frotando toda la superficie.","minutes":1,"kind":"prep"},{"text":"Untar la fuente con {{Mantequilla}} en capa fina por el fondo y las paredes.","minutes":1,"kind":"prep"},{"text":"Disponer las láminas de patata en capas superpuestas en la fuente, añadir {{Sal|gusto}} entre capa y capa.","minutes":4,"kind":"prep"},{"text":"Calentar {{Nata para cocinar}}, {{Leche entera}} y {{Nuez moscada molida|pizca}} en un cazo a fuego medio hasta que humee sin hervir.","minutes":4,"kind":"activo"},{"text":"Verter la mezcla caliente de nata y leche sobre las patatas hasta casi cubrirlas.","minutes":1,"kind":"activo"},{"text":"Repartir {{Queso gruyere rallado}} de forma uniforme por toda la superficie.","minutes":1,"kind":"prep"},{"text":"Hornear en el centro del horno durante 50 min, hasta que las patatas estén tiernas al pinchar y la superficie esté dorada.","minutes":50,"kind":"pasivo"},{"text":"Reposar el gratín 10 min fuera del horno antes de servir para que asiente.","minutes":10,"kind":"espera"},{"text":"Servir en la propia fuente cortando porciones con espátula.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, NULL, NULL),
  ('guarniciones_042', 'Coliflor gratinada con bechamel', 'guarniciones', 'none', NULL, ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, 'horno', 40, 'facil', 'all', 310, 15, 26, 18, 2, true, true, '{"lactosa","gluten"}', '[{"name":"Coliflor","amount":500,"unit":"g"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Harina de trigo","amount":20,"unit":"g"},{"name":"Leche entera","amount":250,"unit":"ml"},{"name":"Queso rallado","amount":40,"unit":"g"},{"name":"Nuez moscada molida","amount":1,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Separar coliflor en ramilletes de tamaño similar para que se cuezan de forma uniforme.","Llevar a ebullición una olla con agua y sal.","Cocer los ramilletes de coliflor a fuego medio durante 8 min, hasta que estén tiernos pero firmes.","Escurrir la coliflor cocida y reservar en una fuente apta para horno.","Precalentar el horno a 200 °C con función gratinar.","Fundir mantequilla en un cazo a fuego medio hasta que esté completamente derretida.","Añadir harina de trigo de golpe y remover sin parar con unas varillas durante 2 min, hasta que la mezcla burbujee sin dorarse.","Verter leche entera poco a poco sin dejar de remover con las varillas para evitar grumos.","Cocer la bechamel a fuego suave, removiendo constantemente, durante 5 min hasta que espese.","Añadir nuez moscada molida y sal, remover y retirar del fuego.","Cubrir la coliflor reservada en la fuente con la bechamel, extendiéndola de forma uniforme.","Repartir queso rallado de manera homogénea por toda la superficie.","Gratinar en el horno a 200 °C durante 8 min, hasta que la superficie quede dorada y burbujeante.","Servir la coliflor gratinada recién salida del horno."}', 'Coliflor cubierta de bechamel y gratinada hasta quedar dorada y burbujeante.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Separar {{Coliflor}} en ramilletes de tamaño similar para que se cuezan de forma uniforme.","minutes":3,"kind":"prep"},{"text":"Llevar a ebullición una olla con agua y {{Sal|gusto}}.","minutes":4,"kind":"activo"},{"text":"Cocer los ramilletes de coliflor a fuego medio durante 8 min, hasta que estén tiernos pero firmes.","minutes":8,"kind":"pasivo"},{"text":"Escurrir la coliflor cocida y reservar en una fuente apta para horno.","minutes":2,"kind":"prep"},{"text":"Precalentar el horno a 200 °C con función gratinar.","minutes":5,"kind":"pasivo"},{"text":"Fundir {{Mantequilla}} en un cazo a fuego medio hasta que esté completamente derretida.","minutes":1,"kind":"activo"},{"text":"Añadir {{Harina de trigo}} de golpe y remover sin parar con unas varillas durante 2 min, hasta que la mezcla burbujee sin dorarse.","minutes":2,"kind":"activo"},{"text":"Verter {{Leche entera}} poco a poco sin dejar de remover con las varillas para evitar grumos.","minutes":2,"kind":"activo"},{"text":"Cocer la bechamel a fuego suave, removiendo constantemente, durante 5 min hasta que espese.","minutes":5,"kind":"activo"},{"text":"Añadir {{Nuez moscada molida|pizca}} y {{Sal|gusto}}, remover y retirar del fuego.","minutes":1,"kind":"activo"},{"text":"Cubrir la coliflor reservada en la fuente con la bechamel, extendiéndola de forma uniforme.","minutes":1,"kind":"activo"},{"text":"Repartir {{Queso rallado}} de manera homogénea por toda la superficie.","minutes":1,"kind":"prep"},{"text":"Gratinar en el horno a 200 °C durante 8 min, hasta que la superficie quede dorada y burbujeante.","minutes":8,"kind":"pasivo"},{"text":"Servir la coliflor gratinada recién salida del horno.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, NULL, NULL),
  ('guarniciones_043', 'Endivias gratinadas con jamón y bechamel', 'guarniciones', 'none', NULL, ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, 'horno', 45, 'normal', 'all', 360, 19, 17, 23, 2, true, true, '{"lactosa","gluten"}', '[{"name":"Endivia","amount":4,"unit":"ud"},{"name":"Jamón cocido","amount":4,"unit":"ud"},{"name":"Mantequilla","amount":25,"unit":"g"},{"name":"Harina de trigo","amount":20,"unit":"g"},{"name":"Leche entera","amount":300,"unit":"ml"},{"name":"Queso rallado","amount":40,"unit":"g"},{"name":"Nuez moscada molida","amount":1,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Llevar a ebullición una olla con agua y sal.","Cocer endivia enteras en el agua hirviendo hasta que estén tiernas.","Escurrir las endivias y apretar con las manos para eliminar el máximo de agua posible.","Fundir mantequilla en un cazo a fuego medio.","Añadir harina de trigo de golpe y remover sin parar hasta obtener una pasta homogénea.","Incorporar leche entera poco a poco, removiendo sin parar para evitar grumos.","Cocer la bechamel a fuego suave, removiendo, hasta que espese y sea fina.","Añadir nuez moscada molida y sal; remover y retirar del fuego.","Precalentar el horno a 200 °C con función gratinar.","Envolver cada endivia con 1 loncha de jamón cocido.","Colocar las endivias envueltas en una fuente de horno en una sola capa.","Cubrir las endivias con la bechamel repartiéndola de manera uniforme.","Repartir queso rallado por encima de la bechamel.","Gratinar en el horno a 200 °C hasta que la superficie esté dorada.","Servir la fuente bien caliente directamente a la mesa."}', 'Endivias envueltas en jamón y bañadas en bechamel, con un gratinado dorado por encima.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, ARRAY['cerdo']::main_protein[], true, '[{"text":"Llevar a ebullición una olla con agua y {{Sal|gusto}}.","minutes":3,"kind":"activo"},{"text":"Cocer {{Endivia}} enteras en el agua hirviendo hasta que estén tiernas.","minutes":12,"kind":"pasivo"},{"text":"Escurrir las endivias y apretar con las manos para eliminar el máximo de agua posible.","minutes":2,"kind":"activo"},{"text":"Fundir {{Mantequilla}} en un cazo a fuego medio.","minutes":2,"kind":"activo"},{"text":"Añadir {{Harina de trigo}} de golpe y remover sin parar hasta obtener una pasta homogénea.","minutes":2,"kind":"activo"},{"text":"Incorporar {{Leche entera}} poco a poco, removiendo sin parar para evitar grumos.","minutes":3,"kind":"activo"},{"text":"Cocer la bechamel a fuego suave, removiendo, hasta que espese y sea fina.","minutes":5,"kind":"activo"},{"text":"Añadir {{Nuez moscada molida|pizca}} y {{Sal|gusto}}; remover y retirar del fuego.","minutes":1,"kind":"activo"},{"text":"Precalentar el horno a 200 °C con función gratinar.","minutes":5,"kind":"pasivo"},{"text":"Envolver cada endivia con 1 loncha de {{Jamón cocido}}.","minutes":2,"kind":"paralelo","during":8},{"text":"Colocar las endivias envueltas en una fuente de horno en una sola capa.","minutes":1,"kind":"activo"},{"text":"Cubrir las endivias con la bechamel repartiéndola de manera uniforme.","minutes":1,"kind":"activo"},{"text":"Repartir {{Queso rallado}} por encima de la bechamel.","minutes":1,"kind":"activo"},{"text":"Gratinar en el horno a 200 °C hasta que la superficie esté dorada.","minutes":10,"kind":"pasivo"},{"text":"Servir la fuente bien caliente directamente a la mesa.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, NULL, NULL),
  ('guarniciones_044', 'Puré de boniato con canela', 'guarniciones', 'none', NULL, ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, NULL, 30, 'facil', 'all', 280, 4, 46, 9, 2, true, true, '{"lactosa"}', '[{"name":"Boniato","amount":450,"unit":"g"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Canela molida","amount":2,"unit":"g"},{"name":"Leche entera","amount":50,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Pelar boniato y cortar en dados de unos 3 cm.","Llevar a ebullición una olla con agua y sal.","Cocer los dados de boniato hasta que estén muy tiernos al pinchar, unos 15 min.","Calentar leche entera en un cazo a fuego suave hasta que esté templada.","Escurrir los dados de boniato y devolver a la olla fuera del fuego.","Añadir mantequilla y machacar con un pasapurés hasta obtener una masa homogénea.","Incorporar la leche caliente poco a poco sin dejar de triturar hasta lograr textura suave.","Añadir canela molida y mezclar bien hasta integrar.","Rectificar de sal y servir el puré templado."}', 'Puré de boniato de un naranja intenso, con el dulzor suave de la canela.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Pelar {{Boniato}} y cortar en dados de unos 3 cm.","minutes":5,"kind":"prep"},{"text":"Llevar a ebullición una olla con agua y {{Sal|gusto}}.","minutes":3,"kind":"activo"},{"text":"Cocer los dados de boniato hasta que estén muy tiernos al pinchar, unos 15 min.","minutes":15,"kind":"pasivo"},{"text":"Calentar {{Leche entera}} en un cazo a fuego suave hasta que esté templada.","minutes":3,"kind":"paralelo","during":2},{"text":"Escurrir los dados de boniato y devolver a la olla fuera del fuego.","minutes":1,"kind":"activo"},{"text":"Añadir {{Mantequilla}} y machacar con un pasapurés hasta obtener una masa homogénea.","minutes":2,"kind":"activo"},{"text":"Incorporar la leche caliente poco a poco sin dejar de triturar hasta lograr textura suave.","minutes":2,"kind":"activo"},{"text":"Añadir {{Canela molida|pizca}} y mezclar bien hasta integrar.","minutes":1,"kind":"activo"},{"text":"Rectificar de sal y servir el puré templado.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, NULL, NULL)
