insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id, extra_proteins, freezable, steps_rich, estrella, occasion, kid_favourite, tecnica, cocina
) values
  ('guarniciones_045', 'Patatas asadas con romero y ajo', 'guarniciones', 'none', 'patatas', ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, 'horno', 40, 'facil', 'all', 230, 4, 32, 9, 2, true, true, '{}', '[{"name":"Patata","amount":350,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Ajo","amount":12,"unit":"g"},{"name":"Romero fresco","amount":3,"unit":"g"},{"name":"Sal","amount":4,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C con calor arriba y abajo.","Lavar patata y cortarlas en gajos gruesos sin pelar.","Machacar ajo con la piel hasta abrirlos.","Picar romero fresco fino.","Mezclar las patatas en un bol con aceite de oliva, el ajo machacado, el romero picado, sal y pimienta negra.","Extender las patatas en una bandeja en una sola capa, sin amontonar.","Hornear durante 15 min a 200 °C.","Dar la vuelta a las patatas y hornear 15 min más hasta que estén doradas y crujientes por fuera.","Retirar la bandeja del horno y servir las patatas calientes."}', 'Patatas asadas al horno en gajos, doradas y crujientes por fuera, con ajo y romero.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Precalentar el horno a 200 °C con calor arriba y abajo.","minutes":10,"kind":"pasivo"},{"text":"Lavar {{Patata}} y cortarlas en gajos gruesos sin pelar.","minutes":3,"kind":"prep"},{"text":"Machacar {{Ajo}} con la piel hasta abrirlos.","minutes":1,"kind":"prep"},{"text":"Picar {{Romero fresco}} fino.","minutes":1,"kind":"prep"},{"text":"Mezclar las patatas en un bol con {{Aceite de oliva}}, el ajo machacado, el romero picado, {{Sal|gusto}} y {{Pimienta negra|pizca}}.","minutes":2,"kind":"activo"},{"text":"Extender las patatas en una bandeja en una sola capa, sin amontonar.","minutes":1,"kind":"prep"},{"text":"Hornear durante 15 min a 200 °C.","minutes":15,"kind":"pasivo"},{"text":"Dar la vuelta a las patatas y hornear 15 min más hasta que estén doradas y crujientes por fuera.","minutes":15,"kind":"pasivo"},{"text":"Retirar la bandeja del horno y servir las patatas calientes.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, NULL, NULL),
  ('guarniciones_046', 'Ensalada de patata templada con mostaza', 'guarniciones', 'none', 'patatas', ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, NULL, 30, 'facil', 'all', 240, 4, 30, 12, 2, true, true, '{"mostaza","sulfitos"}', '[{"name":"Patata","amount":350,"unit":"g"},{"name":"Mostaza de Dijon","amount":20,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Vinagre de vino","amount":10,"unit":"ml"},{"name":"Cebolleta","amount":30,"unit":"g"},{"name":"Perejil fresco","amount":5,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Lavar patata bajo el grifo hasta que estén limpias.","Cocer las patatas enteras con piel en una olla con agua y sal hasta que estén tiernas.","Picar cebolleta en fino mientras las patatas cuecen.","Picar perejil fresco en fino.","Mezclar en un bol mostaza de dijon, aceite de oliva, vinagre de vino y sal.","Batir la mezcla con un tenedor hasta emulsionar la vinagreta.","Escurrir las patatas y dejar templar hasta que se puedan manipular sin quemarse.","Pelar las patatas templadas con los dedos retirando la piel.","Cortar las patatas en rodajas gruesas de unos 1 cm.","Añadir la cebolleta picada y el perejil picado a la vinagreta y remover.","Incorporar las patatas cortadas al bol con la vinagreta y mezclar con cuidado de no romperlas.","Añadir pimienta negra y rectificar de sal al gusto.","Servir la ensalada templada en el momento."}', 'Patatas cocidas templadas, con firmeza justa, aliñadas con una vinagreta de mostaza con carácter.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Lavar {{Patata}} bajo el grifo hasta que estén limpias.","minutes":2,"kind":"prep"},{"text":"Cocer las patatas enteras con piel en una olla con agua y {{Sal|gusto}} hasta que estén tiernas.","minutes":20,"kind":"pasivo"},{"text":"Picar {{Cebolleta}} en fino mientras las patatas cuecen.","minutes":3,"kind":"paralelo","during":1},{"text":"Picar {{Perejil fresco}} en fino.","minutes":2,"kind":"paralelo","during":1},{"text":"Mezclar en un bol {{Mostaza de Dijon}}, {{Aceite de oliva}}, {{Vinagre de vino}} y {{Sal|gusto}}.","minutes":2,"kind":"paralelo","during":1},{"text":"Batir la mezcla con un tenedor hasta emulsionar la vinagreta.","minutes":1,"kind":"activo"},{"text":"Escurrir las patatas y dejar templar hasta que se puedan manipular sin quemarse.","minutes":5,"kind":"espera"},{"text":"Pelar las patatas templadas con los dedos retirando la piel.","minutes":2,"kind":"prep"},{"text":"Cortar las patatas en rodajas gruesas de unos 1 cm.","minutes":2,"kind":"prep"},{"text":"Añadir la cebolleta picada y el perejil picado a la vinagreta y remover.","minutes":1,"kind":"activo"},{"text":"Incorporar las patatas cortadas al bol con la vinagreta y mezclar con cuidado de no romperlas.","minutes":2,"kind":"activo"},{"text":"Añadir {{Pimienta negra|pizca}} y rectificar de sal al gusto.","minutes":1,"kind":"activo"},{"text":"Servir la ensalada templada en el momento.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, NULL, NULL),
  ('guarniciones_047', 'Verduras asadas al horno con miel', 'guarniciones', 'none', NULL, ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, 'horno', 40, 'facil', 'all', 170, 3, 24, 7, 2, true, true, '{}', '[{"name":"Zanahoria","amount":150,"unit":"g"},{"name":"Calabacín","amount":150,"unit":"g"},{"name":"Pimiento rojo","amount":100,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Miel","amount":20,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Tomillo fresco","amount":2,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C con calor arriba y abajo.","Pelar zanahoria y cortar en bastones de unos 5 cm.","Cortar calabacín, pimiento rojo y cebolla en trozos del mismo tamaño que la zanahoria.","Mezclar aceite de oliva con miel y tomillo fresco en un bol hasta integrar.","Disponer todas las verduras en una bandeja de horno forrada con papel vegetal en una sola capa.","Rociar las verduras con la mezcla de aceite y miel y añadir sal.","Hornear a 200 °C durante 15 min.","Remover las verduras con una espátula y hornear 10 min más, hasta que estén tiernas y con los bordes caramelizados.","Servir las verduras calientes directamente de la bandeja."}', 'Verduras de temporada asadas con un toque de miel que caramelizan los bordes al horno.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Precalentar el horno a 200 °C con calor arriba y abajo.","minutes":10,"kind":"pasivo"},{"text":"Pelar {{Zanahoria}} y cortar en bastones de unos 5 cm.","minutes":2,"kind":"paralelo","during":0},{"text":"Cortar {{Calabacín}}, {{Pimiento rojo}} y {{Cebolla}} en trozos del mismo tamaño que la zanahoria.","minutes":3,"kind":"paralelo","during":0},{"text":"Mezclar {{Aceite de oliva}} con {{Miel}} y {{Tomillo fresco}} en un bol hasta integrar.","minutes":1,"kind":"paralelo","during":0},{"text":"Disponer todas las verduras en una bandeja de horno forrada con papel vegetal en una sola capa.","minutes":1,"kind":"prep"},{"text":"Rociar las verduras con la mezcla de aceite y miel y añadir {{Sal|gusto}}.","minutes":1,"kind":"activo"},{"text":"Hornear a 200 °C durante 15 min.","minutes":15,"kind":"pasivo"},{"text":"Remover las verduras con una espátula y hornear 10 min más, hasta que estén tiernas y con los bordes caramelizados.","minutes":10,"kind":"pasivo"},{"text":"Servir las verduras calientes directamente de la bandeja.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, NULL, NULL),
  ('guarniciones_048', 'Pimientos de padrón fritos', 'guarniciones', 'none', NULL, ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, NULL, 15, 'facil', 'all', 160, 2, 6, 14, 2, true, false, '{}', '[{"name":"Pimiento de padrón","amount":300,"unit":"g"},{"name":"Aceite de oliva","amount":60,"unit":"ml"},{"name":"Sal en escamas","amount":3,"unit":"g"}]'::jsonb, '{"Lavar pimiento de padrón bajo el grifo y secarlos bien con un paño limpio.","Calentar aceite de oliva en sartén grande a fuego fuerte hasta que humee ligeramente.","Añadir los pimientos en una sola capa, sin amontonar, para que frían de manera uniforme.","Freír removiendo con frecuencia hasta que los pimientos se arruguen y doren por todos los lados.","Retirar los pimientos con una espumadera y escurrir sobre papel absorbente.","Colocar los pimientos en una fuente y espolvorear sal en escamas justo antes de servir.","Servir de inmediato, muy calientes."}', 'Pimientos de padrón fritos, arrugados y brillantes, con su punto de sal en escamas.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Lavar {{Pimiento de padrón}} bajo el grifo y secarlos bien con un paño limpio.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva}} en {{@Sartén}} grande a fuego fuerte hasta que humee ligeramente.","minutes":2,"kind":"activo"},{"text":"Añadir los pimientos en una sola capa, sin amontonar, para que frían de manera uniforme.","minutes":1,"kind":"activo"},{"text":"Freír removiendo con frecuencia hasta que los pimientos se arruguen y doren por todos los lados.","minutes":4,"kind":"activo"},{"text":"Retirar los pimientos con una espumadera y escurrir sobre papel absorbente.","minutes":1,"kind":"activo"},{"text":"Colocar los pimientos en una fuente y espolvorear {{Sal en escamas|gusto}} justo antes de servir.","minutes":1,"kind":"emplatado"},{"text":"Servir de inmediato, muy calientes.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, NULL, NULL),
  ('guarniciones_049', 'Berenjenas fritas con miel de caña', 'guarniciones', 'none', NULL, ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, NULL, 25, 'facil', 'all', 290, 4, 32, 16, 2, true, false, '{"gluten"}', '[{"name":"Berenjena","amount":300,"unit":"g"},{"name":"Harina","amount":40,"unit":"g"},{"name":"Aceite de oliva","amount":80,"unit":"ml"},{"name":"Miel de caña","amount":30,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Cortar berenjena en bastones de unos 1 cm de grosor, sin pelar.","Sumergir los bastones en agua fría con sal durante 10 min para eliminar el amargor.","Escurrir bien los bastones y secarlos con papel absorbente.","Rebozar los bastones en harina, sacudiendo el exceso para que quede una capa fina.","Calentar aceite de oliva en sartén honda a fuego fuerte hasta que esté bien caliente.","Freír los bastones en tandas a fuego fuerte hasta que estén dorados y crujientes.","Escurrir los bastones fritos sobre papel absorbente y salar ligeramente.","Disponer los bastones en una fuente y regar con miel de caña justo antes de servir."}', 'Berenjenas fritas doradas y crujientes, con un hilo de miel de caña oscura por encima.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Cortar {{Berenjena}} en bastones de unos 1 cm de grosor, sin pelar.","minutes":3,"kind":"prep"},{"text":"Sumergir los bastones en agua fría con {{Sal|gusto}} durante 10 min para eliminar el amargor.","minutes":10,"kind":"espera"},{"text":"Escurrir bien los bastones y secarlos con papel absorbente.","minutes":2,"kind":"prep"},{"text":"Rebozar los bastones en {{Harina}}, sacudiendo el exceso para que quede una capa fina.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|abundante}} en {{@Sartén}} honda a fuego fuerte hasta que esté bien caliente.","minutes":2,"kind":"activo"},{"text":"Freír los bastones en tandas a fuego fuerte hasta que estén dorados y crujientes.","minutes":3,"kind":"activo"},{"text":"Escurrir los bastones fritos sobre papel absorbente y salar ligeramente.","minutes":1,"kind":"activo"},{"text":"Disponer los bastones en una fuente y regar con {{Miel de caña|chorrito}} justo antes de servir.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, NULL, NULL),
  ('guarniciones_050', 'Puré de guisantes con menta', 'guarniciones', 'none', NULL, ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, NULL, 20, 'facil', 'all', 160, 8, 15, 7, 2, true, true, '{"lactosa"}', '[{"name":"Guisantes congelados","amount":300,"unit":"g"},{"name":"Menta fresca","amount":5,"unit":"g"},{"name":"Mantequilla","amount":15,"unit":"g"},{"name":"Nata líquida","amount":30,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Llevar a ebullición una olla con agua y sal.","Añadir guisantes congelados y cocer 5 min hasta que estén tiernos.","Reservar un vaso del agua de cocción antes de escurrir.","Escurrir los guisantes cocidos.","Separar las hojas de menta fresca y desechar los tallos.","Triturar los guisantes escurridos con las hojas de menta, mantequilla y nata líquida hasta obtener un puré fino.","Añadir agua de cocción reservada a cucharadas si el puré ha quedado demasiado espeso y volver a triturar.","Salpimentar con sal y pimienta negra y triturar 10 segundos más hasta integrar.","Servir el puré templado como acompañamiento."}', 'Puré de guisantes de un verde vivo, fresco y ligero gracias a la menta.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Llevar a ebullición una olla con agua y {{Sal|gusto}}.","minutes":3,"kind":"activo"},{"text":"Añadir {{Guisantes congelados}} y cocer 5 min hasta que estén tiernos.","minutes":5,"kind":"pasivo"},{"text":"Reservar un vaso del agua de cocción antes de escurrir.","minutes":1,"kind":"prep"},{"text":"Escurrir los guisantes cocidos.","minutes":1,"kind":"prep"},{"text":"Separar las hojas de {{Menta fresca}} y desechar los tallos.","minutes":1,"kind":"prep"},{"text":"Triturar los guisantes escurridos con las hojas de menta, {{Mantequilla}} y {{Nata líquida}} hasta obtener un puré fino.","minutes":2,"kind":"activo"},{"text":"Añadir agua de cocción reservada a cucharadas si el puré ha quedado demasiado espeso y volver a triturar.","minutes":1,"kind":"activo"},{"text":"Salpimentar con {{Sal|gusto}} y {{Pimienta negra|pizca}} y triturar 10 segundos más hasta integrar.","minutes":1,"kind":"activo"},{"text":"Servir el puré templado como acompañamiento.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, NULL, NULL),
  ('guarniciones_051', 'Cebolla caramelizada', 'guarniciones', 'none', NULL, ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, NULL, 45, 'facil', 'all', 150, 1, 16, 9, 2, true, true, '{"lactosa"}', '[{"name":"Cebolla","amount":400,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Mantequilla","amount":15,"unit":"g"},{"name":"Azúcar","amount":10,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Pelar cebolla y cortarla en juliana fina.","Calentar aceite de oliva y mantequilla en una sartén amplia a fuego medio hasta que la mantequilla se funda.","Añadir la cebolla y sal; remover para que se impregne bien de la grasa.","Bajar el fuego a suave y cocer la cebolla 30 min, removiendo cada 5 min, hasta que esté muy blanda y empiece a dorarse.","Añadir azúcar y remover para integrarlo con la cebolla.","Continuar cocinando 5 min a fuego suave, removiendo a menudo, hasta que la cebolla esté uniformemente dorada y caramelizada.","Retirar la sartén del fuego y servir la cebolla caramelizada templada."}', 'Cebolla cocinada muy despacio hasta quedar dorada, brillante, dulce y untuosa.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Pelar {{Cebolla}} y cortarla en juliana fina.","minutes":5,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} y {{Mantequilla}} en una sartén amplia a fuego medio hasta que la mantequilla se funda.","minutes":2,"kind":"activo"},{"text":"Añadir la cebolla y {{Sal|gusto}}; remover para que se impregne bien de la grasa.","minutes":2,"kind":"activo"},{"text":"Bajar el fuego a suave y cocer la cebolla 30 min, removiendo cada 5 min, hasta que esté muy blanda y empiece a dorarse.","minutes":30,"kind":"pasivo"},{"text":"Añadir {{Azúcar}} y remover para integrarlo con la cebolla.","minutes":1,"kind":"activo"},{"text":"Continuar cocinando 5 min a fuego suave, removiendo a menudo, hasta que la cebolla esté uniformemente dorada y caramelizada.","minutes":5,"kind":"activo"},{"text":"Retirar la sartén del fuego y servir la cebolla caramelizada templada.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, NULL, NULL),
  ('guarniciones_052', 'Boniatos fritos crujientes', 'guarniciones', 'none', NULL, ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, NULL, 25, 'facil', 'all', 260, 2, 34, 12, 2, true, false, '{}', '[{"name":"Boniato","amount":350,"unit":"g"},{"name":"Aceite de oliva","amount":70,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Pelar boniato y cortar en bastones uniformes del tamaño de unas patatas fritas.","Secar bien los bastones con un paño limpio hasta que no quede humedad visible.","Calentar aceite de oliva en sartén honda a fuego fuerte hasta que empiece a humear ligeramente.","Freír los bastones en tandas sin amontonar hasta que estén dorados por fuera y tiernos por dentro.","Retirar los bastones con una espumadera y escurrir sobre papel absorbente.","Repetir el proceso con el resto de bastones hasta terminar toda la tanda.","Añadir sal sobre los bastones recién escurridos y servir de inmediato bien calientes."}', 'Bastones de boniato fritos, dorados y crujientes por fuera, más dulces que la patata clásica.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Pelar {{Boniato}} y cortar en bastones uniformes del tamaño de unas patatas fritas.","minutes":5,"kind":"prep"},{"text":"Secar bien los bastones con un paño limpio hasta que no quede humedad visible.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|abundante}} en {{@Sartén}} honda a fuego fuerte hasta que empiece a humear ligeramente.","minutes":3,"kind":"activo"},{"text":"Freír los bastones en tandas sin amontonar hasta que estén dorados por fuera y tiernos por dentro.","minutes":5,"kind":"activo"},{"text":"Retirar los bastones con una espumadera y escurrir sobre papel absorbente.","minutes":1,"kind":"activo"},{"text":"Repetir el proceso con el resto de bastones hasta terminar toda la tanda.","minutes":5,"kind":"activo"},{"text":"Añadir {{Sal|gusto}} sobre los bastones recién escurridos y servir de inmediato bien calientes.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, NULL, NULL),
  ('guarniciones_053', 'Espárragos blancos con vinagreta', 'guarniciones', 'none', NULL, ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, NULL, 15, 'facil', 'all', 150, 5, 5, 12, 2, true, true, '{"huevo","sulfitos"}', '[{"name":"Espárragos blancos en conserva","amount":300,"unit":"g"},{"name":"Huevo cocido","amount":50,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Vinagre de vino","amount":10,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Escurrir espárragos blancos en conserva y disponerlos en una fuente.","Picar huevo cocido en trozos pequeños.","Verter aceite de oliva en un bol junto con vinagre de vino, sal y pimienta negra.","Batir la mezcla hasta emulsionar.","Regar los espárragos escurridos con la vinagreta.","Repartir el huevo picado por encima de los espárragos.","Dejar reposar en la nevera hasta que los espárragos se impregnen bien con la vinagreta."}', 'Espárragos blancos delicados y pálidos, con un aliño ácido de contraste y huevo picado.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Escurrir {{Espárragos blancos en conserva}} y disponerlos en una fuente.","minutes":2,"kind":"prep"},{"text":"Picar {{Huevo cocido}} en trozos pequeños.","minutes":2,"kind":"prep"},{"text":"Verter {{Aceite de oliva|chorrito}} en un bol junto con {{Vinagre de vino}}, {{Sal|gusto}} y {{Pimienta negra|pizca}}.","minutes":1,"kind":"prep"},{"text":"Batir la mezcla hasta emulsionar.","minutes":1,"kind":"activo"},{"text":"Regar los espárragos escurridos con la vinagreta.","minutes":1,"kind":"emplatado"},{"text":"Repartir el huevo picado por encima de los espárragos.","minutes":1,"kind":"emplatado"},{"text":"Dejar reposar en la nevera hasta que los espárragos se impregnen bien con la vinagreta.","minutes":10,"kind":"espera"}]'::jsonb, NULL, NULL, NULL, NULL, NULL),
  ('guarniciones_054', 'Judías verdes con jamón', 'guarniciones', 'none', NULL, ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, NULL, 25, 'facil', 'all', 140, 9, 8, 8, 2, true, true, '{}', '[{"name":"Judía verde","amount":350,"unit":"g"},{"name":"Jamón serrano","amount":60,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Limpiar judía verde retirando los extremos y los hilos laterales.","Cortar las judías verdes por la mitad.","Llevar a ebullición una olla con agua abundante y sal.","Cocer las judías verdes en el agua hirviendo hasta que estén tiernas pero firmes.","Picar ajo fino.","Cortar jamón serrano en tiras finas.","Escurrir las judías verdes cocidas y reservar.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír el ajo picado a fuego medio hasta que empiece a dorarse sin quemarse.","Añadir el jamón en tiras y saltear hasta que empiece a dorarse.","Incorporar las judías escurridas y saltear todo junto a fuego medio.","Servir las judías con jamón en caliente."}', 'Judías verdes de un verde vivo salteadas con virutas rosadas de jamón.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, ARRAY['cerdo']::main_protein[], false, '[{"text":"Limpiar {{Judía verde}} retirando los extremos y los hilos laterales.","minutes":4,"kind":"prep"},{"text":"Cortar las judías verdes por la mitad.","minutes":2,"kind":"prep"},{"text":"Llevar a ebullición una olla con agua abundante y {{Sal|gusto}}.","minutes":5,"kind":"activo"},{"text":"Cocer las judías verdes en el agua hirviendo hasta que estén tiernas pero firmes.","minutes":9,"kind":"pasivo"},{"text":"Picar {{Ajo}} fino.","minutes":1,"kind":"paralelo","during":3},{"text":"Cortar {{Jamón serrano}} en tiras finas.","minutes":1,"kind":"paralelo","during":3},{"text":"Escurrir las judías verdes cocidas y reservar.","minutes":1,"kind":"activo"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír el ajo picado a fuego medio hasta que empiece a dorarse sin quemarse.","minutes":2,"kind":"activo"},{"text":"Añadir el jamón en tiras y saltear hasta que empiece a dorarse.","minutes":1,"kind":"activo"},{"text":"Incorporar las judías escurridas y saltear todo junto a fuego medio.","minutes":2,"kind":"activo"},{"text":"Servir las judías con jamón en caliente.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, NULL, NULL)
