  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id, extra_proteins, freezable, steps_rich, estrella, occasion, kid_favourite, tecnica, cocina
) values
  ('guarniciones_055', 'Puré de calabaza con jengibre', 'guarniciones', 'none', NULL, ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, NULL, 35, 'facil', 'all', 130, 2, 14, 7, 2, true, true, '{"lactosa"}', '[{"name":"Calabaza","amount":400,"unit":"g"},{"name":"Jengibre fresco","amount":10,"unit":"g"},{"name":"Mantequilla","amount":15,"unit":"g"},{"name":"Nata líquida","amount":30,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Pelar calabaza, retirar las semillas y cortarla en dados de unos 3 cm.","Pelar jengibre fresco y rallarlo fino.","Llevar a ebullición una olla con agua y sal. Añadir la calabaza y cocer a fuego medio hasta que esté muy tierna.","Escurrir la calabaza con un colador y dejarla reposar 1 min para que pierda el exceso de agua.","Triturar la calabaza escurrida junto con el jengibre rallado, mantequilla y nata líquida hasta obtener un puré fino.","Añadir pimienta negra y ajustar de sal al gusto. Triturar de nuevo si hace falta hasta conseguir una textura homogénea.","Servir el puré caliente."}', 'Puré de calabaza de color naranja intenso, con un toque picante de jengibre que lo levanta.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Pelar {{Calabaza}}, retirar las semillas y cortarla en dados de unos 3 cm.","minutes":5,"kind":"prep"},{"text":"Pelar {{Jengibre fresco}} y rallarlo fino.","minutes":2,"kind":"prep"},{"text":"Llevar a ebullición una olla con agua y {{Sal|gusto}}. Añadir la calabaza y cocer a fuego medio hasta que esté muy tierna.","minutes":18,"kind":"pasivo"},{"text":"Escurrir la calabaza con un colador y dejarla reposar 1 min para que pierda el exceso de agua.","minutes":1,"kind":"activo"},{"text":"Triturar la calabaza escurrida junto con el jengibre rallado, {{Mantequilla}} y {{Nata líquida}} hasta obtener un puré fino.","minutes":3,"kind":"activo"},{"text":"Añadir {{Pimienta negra|pizca}} y ajustar de sal al gusto. Triturar de nuevo si hace falta hasta conseguir una textura homogénea.","minutes":1,"kind":"activo"},{"text":"Servir el puré caliente.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, NULL, NULL),
  ('guarniciones_056', 'Calabacines rellenos de verduras gratinados', 'guarniciones', 'none', NULL, ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, 'horno', 55, 'normal', 'all', 190, 8, 15, 11, 2, true, true, '{"lactosa"}', '[{"name":"Calabacín","amount":400,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Pimiento rojo","amount":80,"unit":"g"},{"name":"Zanahoria","amount":60,"unit":"g"},{"name":"Tomate","amount":100,"unit":"g"},{"name":"Queso rallado","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Orégano","amount":2,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 190 °C.","Cortar calabacín por la mitad a lo largo.","Vaciar la pulpa de cada mitad con una cuchara, dejando una base firme. Reservar la pulpa.","Picar cebolla en dados pequeños.","Cortar pimiento rojo en dados pequeños.","Rallar zanahoria.","Picar tomate en dados pequeños.","Picar la pulpa reservada del calabacín en dados pequeños.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla, el pimiento rojo, la zanahoria, el tomate y la pulpa de calabacín hasta que estén tiernos.","Añadir sal y orégano al sofrito. Remover para mezclar bien.","Rellenar las mitades de calabacín con el sofrito de verduras.","Cubrir cada mitad rellena con queso rallado y colocar en una bandeja de horno.","Hornear a 190 °C hasta que el calabacín esté tierno y el queso dorado.","Servir los calabacines rellenos calientes recién salidos del horno."}', 'Calabacines rellenos de un sofrito colorido de verduras, gratinados con queso dorado por encima.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Precalentar el horno a 190 °C.","minutes":10,"kind":"pasivo"},{"text":"Cortar {{Calabacín}} por la mitad a lo largo.","minutes":2,"kind":"prep"},{"text":"Vaciar la pulpa de cada mitad con una cuchara, dejando una base firme. Reservar la pulpa.","minutes":3,"kind":"prep"},{"text":"Picar {{Cebolla}} en dados pequeños.","minutes":2,"kind":"prep"},{"text":"Cortar {{Pimiento rojo}} en dados pequeños.","minutes":2,"kind":"prep"},{"text":"Rallar {{Zanahoria}}.","minutes":2,"kind":"prep"},{"text":"Picar {{Tomate}} en dados pequeños.","minutes":2,"kind":"prep"},{"text":"Picar la pulpa reservada del calabacín en dados pequeños.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla, el pimiento rojo, la zanahoria, el tomate y la pulpa de calabacín hasta que estén tiernos.","minutes":12,"kind":"activo"},{"text":"Añadir {{Sal|gusto}} y {{Orégano|pizca}} al sofrito. Remover para mezclar bien.","minutes":1,"kind":"activo"},{"text":"Rellenar las mitades de calabacín con el sofrito de verduras.","minutes":2,"kind":"activo"},{"text":"Cubrir cada mitad rellena con {{Queso rallado}} y colocar en una bandeja de horno.","minutes":1,"kind":"activo"},{"text":"Hornear a 190 °C hasta que el calabacín esté tierno y el queso dorado.","minutes":22,"kind":"pasivo"},{"text":"Servir los calabacines rellenos calientes recién salidos del horno.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, NULL, NULL),
  ('guarniciones_057', 'Tomates asados con ajo y hierbas', 'guarniciones', 'none', NULL, ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, 'horno', 35, 'facil', 'all', 130, 2, 9, 10, 2, true, true, '{}', '[{"name":"Tomate","amount":400,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Tomillo fresco","amount":2,"unit":"g"},{"name":"Orégano","amount":2,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 180 °C.","Lavar tomate y cortar cada uno por la mitad.","Picar ajo fino.","Mezclar el ajo picado con aceite de oliva, tomillo fresco y orégano en un bol hasta integrar.","Colocar las mitades de tomate con el corte hacia arriba en una bandeja de horno.","Repartir el aceite aromatizado sobre cada mitad de tomate.","Salpimentar con sal y pimienta negra.","Hornear 25 min hasta que la piel esté arrugada y el tomate tierno.","Servir los tomates templados con el jugo de la bandeja por encima."}', 'Tomates asados de piel arrugada y dulce, perfumados con ajo, hierbas y aroma a horno.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Precalentar el horno a 180 °C.","minutes":10,"kind":"pasivo"},{"text":"Lavar {{Tomate}} y cortar cada uno por la mitad.","minutes":2,"kind":"prep"},{"text":"Picar {{Ajo}} fino.","minutes":2,"kind":"prep"},{"text":"Mezclar el ajo picado con {{Aceite de oliva}}, {{Tomillo fresco}} y {{Orégano}} en un bol hasta integrar.","minutes":1,"kind":"prep"},{"text":"Colocar las mitades de tomate con el corte hacia arriba en una bandeja de horno.","minutes":1,"kind":"prep"},{"text":"Repartir el aceite aromatizado sobre cada mitad de tomate.","minutes":1,"kind":"activo"},{"text":"Salpimentar con {{Sal|gusto}} y {{Pimienta negra|pizca}}.","minutes":1,"kind":"activo"},{"text":"Hornear 25 min hasta que la piel esté arrugada y el tomate tierno.","minutes":25,"kind":"pasivo"},{"text":"Servir los tomates templados con el jugo de la bandeja por encima.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, NULL, NULL),
  ('guarniciones_058', 'Patatas duquesa', 'guarniciones', 'none', 'patatas', ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, 'horno', 55, 'normal', 'all', 230, 6, 27, 11, 2, true, true, '{"lactosa","huevo"}', '[{"name":"Patata","amount":400,"unit":"g"},{"name":"Mantequilla","amount":30,"unit":"g"},{"name":"Huevo","amount":60,"unit":"g"},{"name":"Nuez moscada","amount":1,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Pelar patata y cortar en trozos de tamaño similar.","Cocer los trozos de patata en agua con sal hasta que estén muy tiernos.","Precalentar el horno a 200 °C con calor arriba y abajo.","Escurrir las patatas cocidas y triturar en caliente hasta obtener un puré fino sin grumos.","Añadir mantequilla al puré caliente y mezclar hasta que se funda por completo.","Separar huevo: reservar la clara en un bol pequeño y añadir la yema al puré.","Añadir nuez moscada, sal y pimienta negra al puré y mezclar hasta integrar.","Dejar templar el puré hasta que esté manejable sin quemar la mano.","Forrar una bandeja de horno con papel vegetal.","Introducir el puré en una manga pastelera con boquilla rizada.","Formar rosetones sobre la bandeja con la manga, dejando espacio entre ellos.","Batir la clara reservada en el bol y pincelar los rosetones por encima con ella.","Hornear a 200 °C durante 17 min hasta que estén dorados y ligeramente crujientes.","Servir las patatas duquesa calientes recién salidas del horno."}', 'Rosetones de puré de patata, dorados y crujientes por fuera, cremosos por dentro.', NULL, '{}', true, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Pelar {{Patata}} y cortar en trozos de tamaño similar.","minutes":5,"kind":"prep"},{"text":"Cocer los trozos de patata en agua con {{Sal|gusto}} hasta que estén muy tiernos.","minutes":20,"kind":"pasivo"},{"text":"Precalentar el horno a 200 °C con calor arriba y abajo.","minutes":10,"kind":"paralelo","during":1},{"text":"Escurrir las patatas cocidas y triturar en caliente hasta obtener un puré fino sin grumos.","minutes":3,"kind":"activo"},{"text":"Añadir {{Mantequilla}} al puré caliente y mezclar hasta que se funda por completo.","minutes":1,"kind":"activo"},{"text":"Separar {{Huevo}}: reservar la clara en un bol pequeño y añadir la yema al puré.","minutes":2,"kind":"prep"},{"text":"Añadir {{Nuez moscada|pizca}}, {{Sal|gusto}} y {{Pimienta negra|pizca}} al puré y mezclar hasta integrar.","minutes":1,"kind":"activo"},{"text":"Dejar templar el puré hasta que esté manejable sin quemar la mano.","minutes":5,"kind":"espera"},{"text":"Forrar una bandeja de horno con papel vegetal.","minutes":1,"kind":"prep"},{"text":"Introducir el puré en una manga pastelera con boquilla rizada.","minutes":2,"kind":"prep"},{"text":"Formar rosetones sobre la bandeja con la manga, dejando espacio entre ellos.","minutes":3,"kind":"activo"},{"text":"Batir la clara reservada en el bol y pincelar los rosetones por encima con ella.","minutes":2,"kind":"activo"},{"text":"Hornear a 200 °C durante 17 min hasta que estén dorados y ligeramente crujientes.","minutes":17,"kind":"pasivo"},{"text":"Servir las patatas duquesa calientes recién salidas del horno.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, NULL, NULL),
  ('guarniciones_059', 'Champiñones rellenos gratinados', 'guarniciones', 'none', NULL, ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, 'horno', 40, 'normal', 'all', 180, 8, 11, 11, 2, true, true, '{"gluten","lactosa"}', '[{"name":"Champiñón grande","amount":400,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Pan rallado","amount":30,"unit":"g"},{"name":"Queso rallado","amount":50,"unit":"g"},{"name":"Perejil fresco","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 190 °C.","Limpiar champiñón grande y separar los pies de los sombreros.","Picar los pies de champiñón fino.","Picar ajo fino.","Picar perejil fresco fino.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír el ajo picado y los pies de champiñón picados hasta que estén dorados y hayan soltado el agua.","Retirar la sartén del fuego.","Añadir pan rallado, la mitad de queso rallado, el perejil picado y sal al sofrito.","Mezclar bien hasta obtener un relleno homogéneo.","Rellenar cada sombrero de champiñón con la mezcla, presionando ligeramente.","Colocar los champiñones rellenos en una bandeja de horno.","Cubrir cada champiñón con el resto del queso rallado.","Hornear a 190 °C hasta que el queso esté dorado y el champiñón tierno.","Servir los champiñones rellenos calientes."}', 'Champiñones rellenos y gratinados, con sombreros individuales dorados en el horno.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Precalentar el horno a 190 °C.","minutes":10,"kind":"pasivo"},{"text":"Limpiar {{Champiñón grande}} y separar los pies de los sombreros.","minutes":3,"kind":"prep"},{"text":"Picar los pies de champiñón fino.","minutes":2,"kind":"prep"},{"text":"Picar {{Ajo}} fino.","minutes":1,"kind":"prep"},{"text":"Picar {{Perejil fresco}} fino.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír el ajo picado y los pies de champiñón picados hasta que estén dorados y hayan soltado el agua.","minutes":4,"kind":"activo"},{"text":"Retirar la sartén del fuego.","minutes":1,"kind":"activo"},{"text":"Añadir {{Pan rallado}}, la mitad de {{Queso rallado}}, el perejil picado y {{Sal|gusto}} al sofrito.","minutes":1,"kind":"prep"},{"text":"Mezclar bien hasta obtener un relleno homogéneo.","minutes":1,"kind":"prep"},{"text":"Rellenar cada sombrero de champiñón con la mezcla, presionando ligeramente.","minutes":3,"kind":"prep"},{"text":"Colocar los champiñones rellenos en una bandeja de horno.","minutes":1,"kind":"prep"},{"text":"Cubrir cada champiñón con el resto del queso rallado.","minutes":1,"kind":"prep"},{"text":"Hornear a 190 °C hasta que el queso esté dorado y el champiñón tierno.","minutes":17,"kind":"pasivo"},{"text":"Servir los champiñones rellenos calientes.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, NULL, NULL),
  ('guarniciones_060', 'Puré mixto de patata y zanahoria', 'guarniciones', 'none', 'patatas', ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, NULL, 30, 'facil', 'all', 170, 3, 26, 6, 2, true, true, '{"lactosa"}', '[{"name":"Patata","amount":250,"unit":"g"},{"name":"Zanahoria","amount":200,"unit":"g"},{"name":"Mantequilla","amount":15,"unit":"g"},{"name":"Leche","amount":60,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Pelar patata y zanahoria.","Cortar la patata y la zanahoria en trozos similares de unos 3 cm.","Llevar a ebullición una olla con agua abundante y sal.","Cocer la patata y la zanahoria juntas hasta que estén muy tiernas.","Calentar leche en un cazo pequeño a fuego suave hasta que esté caliente, sin que hierva.","Escurrir la patata y la zanahoria, reservando un poco del agua de cocción.","Triturar la patata y la zanahoria escurridas hasta obtener una mezcla homogénea.","Añadir mantequilla y la leche caliente al puré, mezclando hasta que quede cremoso.","Añadir un poco del agua de cocción reservada si el puré ha quedado demasiado espeso.","Salpimentar con pimienta negra y sal, mezclando bien.","Servir el puré caliente."}', 'Puré de patata y zanahoria de color naranja suave, más ligero que el puré clásico.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Pelar {{Patata}} y {{Zanahoria}}.","minutes":3,"kind":"prep"},{"text":"Cortar la patata y la zanahoria en trozos similares de unos 3 cm.","minutes":2,"kind":"prep"},{"text":"Llevar a ebullición una olla con agua abundante y {{Sal|gusto}}.","minutes":3,"kind":"activo"},{"text":"Cocer la patata y la zanahoria juntas hasta que estén muy tiernas.","minutes":20,"kind":"pasivo"},{"text":"Calentar {{Leche}} en un cazo pequeño a fuego suave hasta que esté caliente, sin que hierva.","minutes":3,"kind":"paralelo","during":3},{"text":"Escurrir la patata y la zanahoria, reservando un poco del agua de cocción.","minutes":1,"kind":"activo"},{"text":"Triturar la patata y la zanahoria escurridas hasta obtener una mezcla homogénea.","minutes":2,"kind":"activo"},{"text":"Añadir {{Mantequilla}} y la leche caliente al puré, mezclando hasta que quede cremoso.","minutes":2,"kind":"activo"},{"text":"Añadir un poco del agua de cocción reservada si el puré ha quedado demasiado espeso.","minutes":1,"kind":"opcional"},{"text":"Salpimentar con {{Pimienta negra|pizca}} y {{Sal|gusto}}, mezclando bien.","minutes":1,"kind":"activo"},{"text":"Servir el puré caliente.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, NULL, NULL),
  ('guarniciones_061', 'Verduras salteadas al wok con soja', 'guarniciones', 'none', NULL, ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, NULL, 20, 'facil', 'all', 150, 5, 15, 8, 2, true, true, '{"soja","sesamo","gluten"}', '[{"name":"Pimiento rojo","amount":100,"unit":"g"},{"name":"Zanahoria","amount":100,"unit":"g"},{"name":"Calabacín","amount":100,"unit":"g"},{"name":"Brócoli","amount":100,"unit":"g"},{"name":"Salsa de soja","amount":30,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Jengibre fresco","amount":5,"unit":"g"},{"name":"Aceite de sésamo","amount":10,"unit":"ml"},{"name":"Sésamo tostado","amount":5,"unit":"g"}]'::jsonb, '{"Cortar pimiento rojo y calabacín en tiras finas.","Cortar zanahoria en tiras finas y brócoli en arbolitos pequeños.","Picar ajo y jengibre fresco muy finos.","Calentar aceite de sésamo en sartén a fuego fuerte hasta que humee ligeramente.","Saltear el ajo y el jengibre picados hasta que suelten aroma, sin dejar que se quemen.","Añadir la zanahoria y el brócoli y saltear a fuego fuerte, removiendo sin parar.","Incorporar el pimiento rojo y el calabacín y saltear, removiendo sin parar.","Añadir salsa de soja y saltear hasta que las verduras queden brillantes y al dente.","Servir las verduras espolvoreadas con sésamo tostado."}', 'Verduras salteadas al wok con el brillo del salteado rápido y los colores vivos intactos.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Cortar {{Pimiento rojo}} y {{Calabacín}} en tiras finas.","minutes":3,"kind":"prep"},{"text":"Cortar {{Zanahoria}} en tiras finas y {{Brócoli}} en arbolitos pequeños.","minutes":3,"kind":"prep"},{"text":"Picar {{Ajo}} y {{Jengibre fresco}} muy finos.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de sésamo}} en {{@Sartén}} a fuego fuerte hasta que humee ligeramente.","minutes":1,"kind":"activo"},{"text":"Saltear el ajo y el jengibre picados hasta que suelten aroma, sin dejar que se quemen.","minutes":1,"kind":"activo"},{"text":"Añadir la zanahoria y el brócoli y saltear a fuego fuerte, removiendo sin parar.","minutes":2,"kind":"activo"},{"text":"Incorporar el pimiento rojo y el calabacín y saltear, removiendo sin parar.","minutes":3,"kind":"activo"},{"text":"Añadir {{Salsa de soja}} y saltear hasta que las verduras queden brillantes y al dente.","minutes":1,"kind":"activo"},{"text":"Servir las verduras espolvoreadas con {{Sésamo tostado}}.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, NULL, NULL),
  ('guarniciones_062', 'Chips de boniato al horno', 'guarniciones', 'none', NULL, ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, 'horno', 35, 'facil', 'all', 190, 2, 32, 6, 2, true, false, '{}', '[{"name":"Boniato","amount":350,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Pimentón dulce","amount":2,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C con calor arriba y abajo.","Lavar boniato bajo el grifo y secar la piel con un paño limpio.","Laminar el boniato en rodajas muy finas (2-3 mm) con mandolina o cuchillo.","Secar las láminas de boniato con un paño limpio hasta que no quede humedad visible.","Colocar las láminas en un bol y añadir aceite de oliva, sal y pimentón dulce.","Mezclar bien hasta que todas las láminas queden cubiertas de forma uniforme.","Extender las láminas en una sola capa sobre una bandeja con papel vegetal, sin superponerlas.","Hornear en el centro del horno durante 12 min hasta que empiecen a dorarse.","Dar la vuelta a cada lámina y hornear 8-10 min más hasta que estén doradas y crujientes.","Retirar la bandeja del horno y dejar reposar las chips 2 min para que terminen de crujir.","Servir las chips de boniato recién hechas, en caliente."}', 'Chips de boniato finas y crujientes, horneadas y más dulces que la patata clásica.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Precalentar el horno a 200 °C con calor arriba y abajo.","minutes":10,"kind":"pasivo"},{"text":"Lavar {{Boniato}} bajo el grifo y secar la piel con un paño limpio.","minutes":2,"kind":"prep"},{"text":"Laminar el boniato en rodajas muy finas (2-3 mm) con mandolina o cuchillo.","minutes":4,"kind":"prep"},{"text":"Secar las láminas de boniato con un paño limpio hasta que no quede humedad visible.","minutes":2,"kind":"prep"},{"text":"Colocar las láminas en un bol y añadir {{Aceite de oliva|chorrito}}, {{Sal|gusto}} y {{Pimentón dulce|pizca}}.","minutes":1,"kind":"prep"},{"text":"Mezclar bien hasta que todas las láminas queden cubiertas de forma uniforme.","minutes":1,"kind":"activo"},{"text":"Extender las láminas en una sola capa sobre una bandeja con papel vegetal, sin superponerlas.","minutes":2,"kind":"prep"},{"text":"Hornear en el centro del horno durante 12 min hasta que empiecen a dorarse.","minutes":12,"kind":"pasivo"},{"text":"Dar la vuelta a cada lámina y hornear 8-10 min más hasta que estén doradas y crujientes.","minutes":10,"kind":"pasivo"},{"text":"Retirar la bandeja del horno y dejar reposar las chips 2 min para que terminen de crujir.","minutes":2,"kind":"espera"},{"text":"Servir las chips de boniato recién hechas, en caliente.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, NULL, NULL),
  ('guarniciones_063', 'Patatas aplastadas al horno (smashed potatoes)', 'guarniciones', 'none', 'patatas', ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, 'horno', 45, 'facil', 'all', 230, 4, 32, 9, 2, true, false, '{}', '[{"name":"Patata baby","amount":450,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Ajo","amount":12,"unit":"g"},{"name":"Romero fresco","amount":3,"unit":"g"},{"name":"Sal","amount":4,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Cocer patata baby enteras con piel en agua con sal a fuego fuerte hasta que estén tiernas.","Precalentar el horno a 220 °C con calor arriba y abajo.","Picar romero fresco fino.","Picar ajo muy fino.","Mezclar aceite de oliva con el ajo picado y el romero picado en un bol pequeño.","Escurrir las patatas baby cocidas y dejarlas reposar 2 min para que suelten el vapor.","Disponer las patatas escurridas sobre una bandeja con papel vegetal, bien separadas entre sí.","Aplastar cada patata suavemente con el fondo de un vaso hasta que queden aplastadas sin deshacerse.","Rociar las patatas aplastadas con el aceite aromatizado de forma uniforme.","Salpimentar con sal y pimienta negra por encima.","Hornear en el horno precalentado a 220 °C durante 22 min hasta que los bordes estén dorados y crujientes.","Servir las patatas recién salidas del horno."}', 'Patatas baby aplastadas y doradas al horno, con el crujiente que arrasa en redes.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Cocer {{Patata baby}} enteras con piel en agua con {{Sal|gusto}} a fuego fuerte hasta que estén tiernas.","minutes":18,"kind":"pasivo"},{"text":"Precalentar el horno a 220 °C con calor arriba y abajo.","minutes":10,"kind":"paralelo","during":0},{"text":"Picar {{Romero fresco}} fino.","minutes":2,"kind":"paralelo","during":0},{"text":"Picar {{Ajo}} muy fino.","minutes":2,"kind":"paralelo","during":0},{"text":"Mezclar {{Aceite de oliva}} con el ajo picado y el romero picado en un bol pequeño.","minutes":1,"kind":"paralelo","during":0},{"text":"Escurrir las patatas baby cocidas y dejarlas reposar 2 min para que suelten el vapor.","minutes":2,"kind":"espera"},{"text":"Disponer las patatas escurridas sobre una bandeja con papel vegetal, bien separadas entre sí.","minutes":2,"kind":"prep"},{"text":"Aplastar cada patata suavemente con el fondo de un vaso hasta que queden aplastadas sin deshacerse.","minutes":3,"kind":"activo"},{"text":"Rociar las patatas aplastadas con el aceite aromatizado de forma uniforme.","minutes":1,"kind":"activo"},{"text":"Salpimentar con {{Sal|gusto}} y {{Pimienta negra|pizca}} por encima.","minutes":1,"kind":"activo"},{"text":"Hornear en el horno precalentado a 220 °C durante 22 min hasta que los bordes estén dorados y crujientes.","minutes":22,"kind":"pasivo"},{"text":"Servir las patatas recién salidas del horno.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, NULL, NULL),
  ('huevos_001', 'Tortilla de patatas', 'huevos', 'huevo', NULL, ARRAY['segundo','cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 30, 'normal', 'all', 386, 16, 28, 24, 2, true, true, '{"huevo"}', '[{"name":"Patata","amount":300,"unit":"g"},{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Aceite de oliva","amount":60,"unit":"ml"}]'::jsonb, '{"Pelar y laminar las patatas en rodajas de 3 mm y cortar la cebolla en juliana","Calentar el aceite en sartén a fuego medio e incorporar patatas y cebolla","Confitar a fuego suave 20 min removiendo de vez en cuando hasta que estén tiernas","Escurrir en colador y reservar el aceite","Batir los huevos en un bol grande con sal y pimienta","Incorporar las patatas y la cebolla al huevo y remover","Dejar reposar la mezcla 2 min para que el huevo penetre bien","Cuajar en sartén con un poco del aceite reservado 3 min por el primer lado","Dar la vuelta con un plato y cuajar 2 min más; reposar 1 min y servir"}', 'Tortilla de patata con cebolla, jugosa por dentro', '[]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Pelar y laminar las {{Patata}} en rodajas de 3 mm y cortar {{Cebolla}} en juliana fina.","minutes":5,"kind":"prep"},{"text":"Calentar {{Aceite de oliva}} en {{@Sartén}} amplia a fuego medio hasta que esté caliente.","minutes":1,"kind":"activo"},{"text":"Incorporar las patatas y la cebolla, salpimentar y confitar a fuego suave 20 min, removiendo de vez en cuando, hasta que estén tiernas.","minutes":20,"kind":"pasivo"},{"text":"Escurrir las patatas y la cebolla en un colador y reservar el aceite para más adelante.","minutes":2,"kind":"activo"},{"text":"Batir {{Huevo}} en un bol grande con sal y pimienta hasta que la mezcla esté homogénea.","minutes":1,"kind":"activo"},{"text":"Incorporar las patatas y la cebolla al huevo batido y remover hasta que todo quede bien integrado.","minutes":1,"kind":"activo"},{"text":"Dejar reposar la mezcla 2 min para que el huevo penetre bien en las patatas.","minutes":2,"kind":"espera"},{"text":"Calentar 2 cucharadas del aceite reservado en la sartén a fuego fuerte, volcar la mezcla y cuajar 3 min hasta que el fondo esté dorado.","minutes":3,"kind":"activo"},{"text":"Cubrir con un plato plano, dar la vuelta de un golpe y devolver la tortilla a la sartén; cuajar 2 min más hasta que esté cuajada y cremosa.","minutes":2,"kind":"activo"},{"text":"Retirar del fuego, dejar reposar 1 min y servir.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'sarten', NULL)
