insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id, extra_proteins, freezable, steps_rich, estrella, occasion, kid_favourite, tecnica, cocina
) values
  ('huevos_002', 'Tortilla francesa', 'huevos', 'huevo', NULL, ARRAY['cena']::meal_role[], 'principal', NULL, NULL, 5, 'facil', 'all', 232, 14, 1, 18, 2, true, false, '{"huevo"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Aceite de oliva","amount":10,"unit":"ml"}]'::jsonb, '{"Cascar y batir los huevos con sal hasta integrar yema y clara","Calentar el aceite en sartén antiadherente a fuego medio-alto","Verter el huevo, mover el centro con espátula en cuanto los bordes cuajen","Doblar cuando el interior esté aún cremoso y deslizar al plato"}', 'Tortilla francesa sencilla, cuajada por fuera y jugosa', '[]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Cascar {{Huevo}} en un bol y batir con sal hasta que yema y clara estén completamente integradas.","minutes":1,"kind":"prep"},{"text":"Calentar {{@Sartén}} antiadherente a fuego medio-alto con {{Aceite de oliva|chorrito}} hasta que el aceite esté caliente.","minutes":1,"kind":"activo"},{"text":"Verter el huevo batido de golpe; en cuanto los bordes cuajen, mover el centro con una espátula para que el huevo líquido llegue abajo.","minutes":1,"kind":"activo"},{"text":"Doblar la tortilla por la mitad cuando el interior esté aún cremoso y deslizarla al plato.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'sarten', NULL),
  ('huevos_003', 'Huevos rotos con jamón', 'huevos', 'huevo', NULL, ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 482, 22, 32, 30, 2, true, false, '{"huevo"}', '[{"name":"Patata","amount":300,"unit":"g"},{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Jamón serrano","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":60,"unit":"ml"}]'::jsonb, '{"Pelar patata y cortar en bastones de unos 1 cm de grosor.","Calentar aceite de oliva en sartén a fuego fuerte hasta que esté bien caliente.","Freír los bastones de patata en el aceite caliente hasta que estén dorados y tiernos por dentro, removiendo de vez en cuando.","Escurrir las patatas fritas sobre papel absorbente y reservar.","Freír huevo en el mismo aceite caliente a fuego medio hasta que la clara esté cuajada y la yema líquida.","Distribuir las patatas en 2 platos y colocar los huevos fritos encima.","Disponer jamón serrano en virutas sobre los huevos y romper las yemas con un tenedor al momento de servir."}', 'Huevos fritos con yema líquida sobre patatas fritas y jamón', '[{"appliance":"airfryer","time":25,"difficulty":"facil","prepSummary":"Corta las patatas en dados finos, rocíalas con un poco de aceite y sal, y cocínalas en la airfryer a 190°C durante 18-20 minutos, agitando a mitad. Fríe los huevos en una sartén aparte hasta que la clara cuaje y la yema quede líquida. Sirve las patatas con los huevos rotos y el jamón por encima."},{"appliance":"horno","time":40,"difficulty":"facil","prepSummary":"Corta las patatas en dados, mézclalas con aceite de oliva y sal, y extiéndelas en una bandeja de horno. Hornea a 200°C durante 25-30 minutos, hasta que estén tiernas y doradas. Retira, haz huecos y casca los huevos, horneando 5-8 minutos más hasta que la clara cuaje y la yema esté al gusto. Rompe los huevos sobre las patatas y reparte el jamón por encima."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, ARRAY['cerdo']::main_protein[], false, '[{"text":"Pelar {{Patata}} y cortar en bastones de unos 1 cm de grosor.","minutes":5,"kind":"prep"},{"text":"Calentar {{Aceite de oliva}} en {{@Sartén}} a fuego fuerte hasta que esté bien caliente.","minutes":2,"kind":"activo"},{"text":"Freír los bastones de patata en el aceite caliente hasta que estén dorados y tiernos por dentro, removiendo de vez en cuando.","minutes":10,"kind":"activo"},{"text":"Escurrir las patatas fritas sobre papel absorbente y reservar.","minutes":1,"kind":"prep"},{"text":"Freír {{Huevo}} en el mismo aceite caliente a fuego medio hasta que la clara esté cuajada y la yema líquida.","minutes":2,"kind":"activo"},{"text":"Distribuir las patatas en 2 platos y colocar los huevos fritos encima.","minutes":1,"kind":"emplatado"},{"text":"Disponer {{Jamón serrano}} en virutas sobre los huevos y romper las yemas con un tenedor al momento de servir.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'sarten', NULL),
  ('huevos_004', 'Revuelto de champiñones', 'huevos', 'huevo', NULL, ARRAY['cena','primero']::meal_role[], 'principal', NULL, NULL, 15, 'facil', 'all', 268, 16, 4, 22, 2, true, false, '{"huevo"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Champiñones","amount":200,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Limpiar champiñones con un paño húmedo y laminar.","Picar ajo fino.","Picar perejil fino y reservar.","Batir huevo en un bol hasta que estén homogéneos y reservar.","Calentar aceite de oliva en sartén a fuego fuerte hasta que esté bien caliente.","Saltear el ajo picado hasta que empiece a dorarse, sin dejar que se queme.","Añadir los champiñones laminados y saltear a fuego fuerte hasta que pierdan el agua y se doren.","Bajar el fuego a fuego suave y añadir los huevos batidos sobre los champiñones.","Remover suavemente con una espátula hasta que los huevos cuajen cremosos, sin pasarse de cocción.","Servir de inmediato con el perejil picado por encima."}', 'Revuelto cremoso de huevos con champiñones y ajo', '[]'::jsonb, '{}', NULL, NULL, NULL, '{"seta"}', NULL, '{}'::main_protein[], false, '[{"text":"Limpiar {{Champiñones}} con un paño húmedo y laminar.","minutes":3,"kind":"prep"},{"text":"Picar {{Ajo}} fino.","minutes":1,"kind":"prep"},{"text":"Picar {{Perejil}} fino y reservar.","minutes":1,"kind":"prep"},{"text":"Batir {{Huevo}} en un bol hasta que estén homogéneos y reservar.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva}} en {{@Sartén}} a fuego fuerte hasta que esté bien caliente.","minutes":1,"kind":"activo"},{"text":"Saltear el ajo picado hasta que empiece a dorarse, sin dejar que se queme.","minutes":1,"kind":"activo"},{"text":"Añadir los champiñones laminados y saltear a fuego fuerte hasta que pierdan el agua y se doren.","minutes":3,"kind":"activo"},{"text":"Bajar el fuego a fuego suave y añadir los huevos batidos sobre los champiñones.","minutes":1,"kind":"activo"},{"text":"Remover suavemente con una espátula hasta que los huevos cuajen cremosos, sin pasarse de cocción.","minutes":2,"kind":"activo"},{"text":"Servir de inmediato con el perejil picado por encima.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'sarten', NULL),
  ('huevos_005', 'Revuelto de ajetes', 'huevos', 'huevo', NULL, ARRAY['cena','primero']::meal_role[], 'principal', NULL, NULL, 12, 'facil', 'all', 248, 14, 4, 20, 2, false, false, '{"huevo","marisco"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Ajetes tiernos","amount":100,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Gambas","amount":80,"unit":"g"}]'::jsonb, '{"Cortar ajetes tiernos en trozos de unos 2 cm.","Batir huevo en un bol hasta homogeneizar la clara y la yema.","Calentar aceite de oliva en sartén a fuego medio hasta que esté caliente.","Sofreír los ajetes troceados a fuego medio hasta que estén tiernos y ligeramente dorados, unos 3 min.","Añadir gambas y saltear a fuego fuerte hasta que estén rosadas, unos 2 min.","Bajar el fuego a suave y verter los huevos batidos sobre el conjunto.","Remover con movimientos lentos y continuos a fuego suave hasta que el huevo cuaje cremoso sin secarse.","Retirar la sartén del fuego y servir de inmediato en plato caliente."}', 'Revuelto cremoso de ajetes tiernos con gambas', '[]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, ARRAY['marisco']::main_protein[], false, '[{"text":"Cortar {{Ajetes tiernos}} en trozos de unos 2 cm.","minutes":2,"kind":"prep"},{"text":"Batir {{Huevo}} en un bol hasta homogeneizar la clara y la yema.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego medio hasta que esté caliente.","minutes":1,"kind":"activo"},{"text":"Sofreír los ajetes troceados a fuego medio hasta que estén tiernos y ligeramente dorados, unos 3 min.","minutes":3,"kind":"activo"},{"text":"Añadir {{Gambas}} y saltear a fuego fuerte hasta que estén rosadas, unos 2 min.","minutes":2,"kind":"activo"},{"text":"Bajar el fuego a suave y verter los huevos batidos sobre el conjunto.","minutes":1,"kind":"activo"},{"text":"Remover con movimientos lentos y continuos a fuego suave hasta que el huevo cuaje cremoso sin secarse.","minutes":2,"kind":"activo"},{"text":"Retirar la sartén del fuego y servir de inmediato en plato caliente.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'sarten', NULL),
  ('huevos_006', 'Tortilla de calabacín', 'huevos', 'huevo', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 20, 'facil', 'all', 278, 14, 8, 22, 2, true, true, '{"huevo"}', '[{"name":"Calabacín","amount":250,"unit":"g"},{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"}]'::jsonb, '{"Pelar cebolla y cortar en medias lunas finas.","Lavar calabacín y cortar en medias lunas finas.","Calentar aceite de oliva en sartén a fuego medio.","Añadir el calabacín y la cebolla; sofreír a fuego suave hasta que estén tiernos y translúcidos.","Batir huevo en un bol hasta que estén homogéneos.","Escurrir el calabacín y la cebolla pochados y reservar el aceite sobrante.","Añadir el calabacín y la cebolla escurridos al huevo batido, salpimentar y mezclar bien.","Calentar en la sartén un poco del aceite reservado a fuego medio y verter la mezcla.","Cuajar a fuego medio-suave hasta que los bordes estén firmes y el centro ligeramente cremoso.","Dar la vuelta con un plato y cuajar por el otro lado hasta que esté dorada.","Retirar la tortilla de la sartén y servir."}', 'Tortilla de calabacín y cebolla pochada', '[]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], false, '[{"text":"Pelar {{Cebolla}} y cortar en medias lunas finas.","minutes":2,"kind":"prep"},{"text":"Lavar {{Calabacín}} y cortar en medias lunas finas.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva}} en {{@Sartén}} a fuego medio.","minutes":1,"kind":"activo"},{"text":"Añadir el calabacín y la cebolla; sofreír a fuego suave hasta que estén tiernos y translúcidos.","minutes":10,"kind":"pasivo"},{"text":"Batir {{Huevo}} en un bol hasta que estén homogéneos.","minutes":1,"kind":"paralelo","during":3},{"text":"Escurrir el calabacín y la cebolla pochados y reservar el aceite sobrante.","minutes":1,"kind":"prep"},{"text":"Añadir el calabacín y la cebolla escurridos al huevo batido, salpimentar y mezclar bien.","minutes":1,"kind":"prep"},{"text":"Calentar en la {{@Sartén}} un poco del aceite reservado a fuego medio y verter la mezcla.","minutes":1,"kind":"activo"},{"text":"Cuajar a fuego medio-suave hasta que los bordes estén firmes y el centro ligeramente cremoso.","minutes":3,"kind":"activo"},{"text":"Dar la vuelta con un plato y cuajar por el otro lado hasta que esté dorada.","minutes":3,"kind":"activo"},{"text":"Retirar la tortilla de la sartén y servir.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'sarten', NULL),
  ('huevos_007', 'Huevos fritos con puntillas', 'huevos', 'huevo', NULL, ARRAY['cena','segundo']::meal_role[], 'principal', NULL, NULL, 10, 'facil', 'all', 312, 14, 1, 28, 2, true, false, '{"huevo"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Aceite de oliva","amount":60,"unit":"ml"}]'::jsonb, '{"Verter aceite de oliva en una sartén pequeña y calentar a fuego fuerte hasta que humee ligeramente.","Cascar huevo de uno en uno sobre un cuenco pequeño para comprobar que están en buen estado.","Deslizar 1 huevo con cuidado al centro de la sartén con el aceite muy caliente.","Inclinar la sartén y bañar la clara continuamente con el aceite caliente hasta que los bordes burbujeen y formen puntillas doradas.","Retirar el huevo cuando la clara esté cuajada y crujiente en los bordes pero la yema permanezca líquida. Reservar.","Repetir el proceso con los 3 huevos restantes, de uno en uno, bañando siempre con el aceite caliente.","Servir los huevos de inmediato en plato caliente."}', 'Huevos fritos en abundante aceite con bordes crujientes', '[]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Verter {{Aceite de oliva}} en una sartén pequeña y calentar a fuego fuerte hasta que humee ligeramente.","minutes":2,"kind":"activo"},{"text":"Cascar {{Huevo}} de uno en uno sobre un cuenco pequeño para comprobar que están en buen estado.","minutes":1,"kind":"prep"},{"text":"Deslizar 1 huevo con cuidado al centro de la sartén con el aceite muy caliente.","minutes":1,"kind":"activo"},{"text":"Inclinar la sartén y bañar la clara continuamente con el aceite caliente hasta que los bordes burbujeen y formen puntillas doradas.","minutes":1,"kind":"activo"},{"text":"Retirar el huevo cuando la clara esté cuajada y crujiente en los bordes pero la yema permanezca líquida. Reservar.","kind":"activo"},{"text":"Repetir el proceso con los 3 huevos restantes, de uno en uno, bañando siempre con el aceite caliente.","minutes":3,"kind":"activo"},{"text":"Servir los huevos de inmediato en plato caliente.","kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'sarten', NULL),
  ('huevos_008', 'Revuelto de espárragos', 'huevos', 'huevo', NULL, ARRAY['cena','primero']::meal_role[], 'principal', NULL, NULL, 15, 'facil', 'all', 238, 14, 6, 18, 2, true, false, '{"huevo"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Espárragos trigueros","amount":200,"unit":"g"},{"name":"Ajo","amount":6,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"}]'::jsonb, '{"Laminar ajo.","Cortar espárragos trigueros en trozos de unos 3 cm, desechando la parte leñosa del extremo.","Cascar huevo en un bol y batir hasta que la yema y la clara queden integradas.","Calentar aceite de oliva en sartén a fuego medio hasta que esté caliente.","Sofreír el ajo laminado en la sartén a fuego medio hasta que esté dorado.","Añadir los espárragos a la sartén y saltear a fuego medio hasta que estén tiernos.","Añadir los huevos batidos sobre los espárragos y remover a fuego suave hasta que el huevo cuaje cremoso y jugoso.","Retirar la sartén del fuego y servir de inmediato."}', 'Revuelto cremoso de huevos con espárragos trigueros', '[]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], false, '[{"text":"Laminar {{Ajo}}.","minutes":2,"kind":"prep"},{"text":"Cortar {{Espárragos trigueros}} en trozos de unos 3 cm, desechando la parte leñosa del extremo.","minutes":2,"kind":"prep"},{"text":"Cascar {{Huevo}} en un bol y batir hasta que la yema y la clara queden integradas.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego medio hasta que esté caliente.","minutes":1,"kind":"activo"},{"text":"Sofreír el ajo laminado en la sartén a fuego medio hasta que esté dorado.","minutes":1,"kind":"activo"},{"text":"Añadir los espárragos a la sartén y saltear a fuego medio hasta que estén tiernos.","minutes":5,"kind":"activo"},{"text":"Añadir los huevos batidos sobre los espárragos y remover a fuego suave hasta que el huevo cuaje cremoso y jugoso.","minutes":3,"kind":"activo"},{"text":"Retirar la sartén del fuego y servir de inmediato.","kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'sarten', NULL),
  ('huevos_009', 'Huevos al plato', 'huevos', 'huevo', NULL, ARRAY['cena']::meal_role[], 'principal', NULL, 'horno', 20, 'facil', 'all', 328, 18, 10, 24, 2, true, false, '{"huevo"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Jamón serrano","amount":40,"unit":"g"},{"name":"Tomate triturado","amount":120,"unit":"ml"},{"name":"Guisantes","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Chorizo","amount":30,"unit":"g"}]'::jsonb, '{"Cortar chorizo en rodajas finas y reservar.","Cortar jamón serrano en trozos pequeños y reservar.","Precalentar el horno a 200 °C con calor arriba y abajo.","Verter aceite de oliva en el fondo de 2 cazuelitas de barro y repartirlo bien.","Repartir tomate triturado a partes iguales entre las 2 cazuelitas.","Distribuir guisantes, el jamón serrano y el chorizo en rodajas sobre el tomate de cada cazuelita.","Cascar huevo con cuidado, 2 en cada cazuelita, sin romper la yema.","Hornear las cazuelitas a 200 °C durante 10 min, hasta que la clara cuaje y la yema quede ligeramente líquida.","Retirar del horno con cuidado y servir las cazuelitas directamente en la mesa."}', 'Huevos horneados en cazuelita con tomate, jamón y guisantes', '[{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Precalienta el horno a 180°C. En cazuelitas individuales, vierte el tomate, guisantes, jamón y chorizo. Haz un hueco y casca el huevo. Hornea 15-20 minutos hasta que la clara esté cuajada y la yema líquida."},{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 170°C. En una cazuelita apta para airfryer, distribuye el tomate, guisantes, jamón y chorizo, y casca el huevo. Cocina durante 12-15 minutos hasta que la clara esté firme y la yema a tu gusto."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, ARRAY['cerdo']::main_protein[], false, '[{"text":"Cortar {{Chorizo}} en rodajas finas y reservar.","minutes":2,"kind":"prep"},{"text":"Cortar {{Jamón serrano}} en trozos pequeños y reservar.","minutes":2,"kind":"prep"},{"text":"Precalentar el horno a 200 °C con calor arriba y abajo.","minutes":10,"kind":"pasivo"},{"text":"Verter {{Aceite de oliva|chorrito}} en el fondo de 2 cazuelitas de barro y repartirlo bien.","minutes":1,"kind":"prep"},{"text":"Repartir {{Tomate triturado}} a partes iguales entre las 2 cazuelitas.","minutes":1,"kind":"prep"},{"text":"Distribuir {{Guisantes}}, el jamón serrano y el chorizo en rodajas sobre el tomate de cada cazuelita.","minutes":2,"kind":"prep"},{"text":"Cascar {{Huevo}} con cuidado, 2 en cada cazuelita, sin romper la yema.","minutes":1,"kind":"prep"},{"text":"Hornear las cazuelitas a 200 °C durante 10 min, hasta que la clara cuaje y la yema quede ligeramente líquida.","minutes":10,"kind":"pasivo"},{"text":"Retirar del horno con cuidado y servir las cazuelitas directamente en la mesa.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'horno', NULL),
  ('huevos_010', 'Huevos rellenos', 'huevos', 'huevo', NULL, ARRAY['primero','cena']::meal_role[], 'principal', NULL, NULL, 20, 'facil', 'verano', 298, 18, 6, 22, 2, true, true, '{"huevo","pescado"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Atún en conserva","amount":80,"unit":"g"},{"name":"Mayonesa","amount":40,"unit":"g"},{"name":"Tomate triturado","amount":60,"unit":"ml"},{"name":"Pimiento morrón","amount":30,"unit":"g"}]'::jsonb, '{"Llevar a ebullición agua en un cazo a fuego fuerte. Añadir huevo con cuidado y cocer durante 10 min a fuego medio.","Escurrir los huevos y sumergirlos en agua fría hasta que estén completamente fríos.","Pelar los huevos y cortar cada uno por la mitad a lo largo.","Extraer las yemas con una cucharilla y reservarlas en un bol. Reservar las claras en una fuente.","Cortar pimiento morrón en trozos muy pequeños.","Añadir al bol con las yemas atún en conserva, mayonesa y el pimiento morrón picado. Mezclar hasta obtener una pasta homogénea.","Rellenar cada clara con la mezcla usando una cucharilla, formando un montículo generoso.","Napar cada huevo relleno con tomate triturado y servir."}', 'Huevos cocidos rellenos de atún y mayonesa con tomate', '[{"appliance":"vaporera","time":22,"difficulty":"facil","prepSummary":"Cuece los huevos al vapor durante 12-15 minutos para que queden perfectos y fáciles de pelar. Luego, solo tienes que preparar el relleno manualmente y montar los huevos."},{"appliance":"olla_express","time":20,"difficulty":"facil","prepSummary":"Cocina los huevos en la olla express con un poco de agua durante 5-7 minutos a presión alta. Enfría rápidamente para facilitar el pelado y luego procede con el relleno manual."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, ARRAY['pescado_azul']::main_protein[], false, '[{"text":"Llevar a ebullición agua en un cazo a fuego fuerte. Añadir {{Huevo}} con cuidado y cocer durante 10 min a fuego medio.","minutes":12,"kind":"activo"},{"text":"Escurrir los huevos y sumergirlos en agua fría hasta que estén completamente fríos.","minutes":5,"kind":"espera"},{"text":"Pelar los huevos y cortar cada uno por la mitad a lo largo.","minutes":2,"kind":"prep"},{"text":"Extraer las yemas con una cucharilla y reservarlas en un bol. Reservar las claras en una fuente.","minutes":1,"kind":"prep"},{"text":"Cortar {{Pimiento morrón}} en trozos muy pequeños.","minutes":1,"kind":"prep"},{"text":"Añadir al bol con las yemas {{Atún en conserva}}, {{Mayonesa}} y el pimiento morrón picado. Mezclar hasta obtener una pasta homogénea.","minutes":2,"kind":"activo"},{"text":"Rellenar cada clara con la mezcla usando una cucharilla, formando un montículo generoso.","minutes":2,"kind":"activo"},{"text":"Napar cada huevo relleno con {{Tomate triturado}} y servir.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'sarten', NULL),
  ('huevos_011', 'Revuelto de gambas', 'huevos', 'huevo', NULL, ARRAY['cena','segundo']::meal_role[], 'principal', NULL, NULL, 12, 'facil', 'all', 288, 22, 2, 22, 2, true, false, '{"huevo","marisco"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Gambas peladas","amount":150,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Laminar ajo.","Batir huevo en un bol hasta que estén homogéneos.","Picar perejil finamente y reservar.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír el ajo laminado hasta que empiece a dorarse, sin que se queme.","Añadir gambas peladas y saltear a fuego fuerte hasta que estén rosadas, unos 2 min.","Bajar a fuego suave y añadir el huevo batido sobre las gambas.","Remover suavemente con una espátula hasta que el huevo esté cremoso y cuajado a punto.","Retirar del fuego y servir de inmediato con el perejil picado por encima."}', 'Revuelto cremoso de huevos con gambas al ajillo', '[]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, ARRAY['marisco']::main_protein[], false, '[{"text":"Laminar {{Ajo}}.","minutes":2,"kind":"prep"},{"text":"Batir {{Huevo}} en un bol hasta que estén homogéneos.","minutes":1,"kind":"prep"},{"text":"Picar {{Perejil}} finamente y reservar.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír el ajo laminado hasta que empiece a dorarse, sin que se queme.","minutes":1,"kind":"activo"},{"text":"Añadir {{Gambas peladas}} y saltear a fuego fuerte hasta que estén rosadas, unos 2 min.","minutes":2,"kind":"activo"},{"text":"Bajar a fuego suave y añadir el huevo batido sobre las gambas.","minutes":1,"kind":"activo"},{"text":"Remover suavemente con una espátula hasta que el huevo esté cremoso y cuajado a punto.","minutes":2,"kind":"activo"},{"text":"Retirar del fuego y servir de inmediato con el perejil picado por encima.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'sarten', NULL)
