insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id, extra_proteins, freezable, steps_rich, estrella, occasion, kid_favourite, tecnica, cocina
) values
  ('huevos_012', 'Tortilla de espinacas', 'huevos', 'huevo', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 20, 'facil', 'all', 256, 16, 4, 20, 2, true, true, '{"huevo"}', '[{"name":"Espinacas frescas","amount":200,"unit":"g"},{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Ajo","amount":6,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"}]'::jsonb, '{"Pelar y picar ajo fino.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír el ajo picado hasta que esté dorado.","Añadir espinacas frescas y saltear a fuego medio hasta que reduzcan por completo.","Retirar las espinacas de la sartén y escurrir bien el líquido sobrante.","Cortar las espinacas escurridas en trozos gruesos.","Batir huevo en un bol hasta homogeneizar.","Mezclar las espinacas picadas con los huevos batidos y salpimentar al gusto.","Calentar aceite de oliva en la sartén limpia a fuego medio.","Verter la mezcla de huevo y espinacas en la sartén y cocer hasta que los bordes estén cuajados, unos 3 min.","Dar la vuelta a la tortilla con un plato y cuajar el otro lado hasta que esté hecha, unos 3 min.","Retirar y servir en plato."}', 'Tortilla jugosa de espinacas salteadas con ajo', '[]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], false, '[{"text":"Pelar y picar {{Ajo}} fino.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír el ajo picado hasta que esté dorado.","minutes":2,"kind":"activo"},{"text":"Añadir {{Espinacas frescas}} y saltear a fuego medio hasta que reduzcan por completo.","minutes":4,"kind":"activo"},{"text":"Retirar las espinacas de la sartén y escurrir bien el líquido sobrante.","minutes":1,"kind":"prep"},{"text":"Cortar las espinacas escurridas en trozos gruesos.","minutes":1,"kind":"prep"},{"text":"Batir {{Huevo}} en un bol hasta homogeneizar.","minutes":1,"kind":"prep"},{"text":"Mezclar las espinacas picadas con los huevos batidos y salpimentar al gusto.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en la sartén limpia a fuego medio.","minutes":1,"kind":"activo"},{"text":"Verter la mezcla de huevo y espinacas en la sartén y cocer hasta que los bordes estén cuajados, unos 3 min.","minutes":3,"kind":"activo"},{"text":"Dar la vuelta a la tortilla con un plato y cuajar el otro lado hasta que esté hecha, unos 3 min.","minutes":3,"kind":"activo"},{"text":"Retirar y servir en plato.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'sarten', NULL),
  ('huevos_013', 'Huevos a la flamenca', 'huevos', 'huevo', NULL, ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, 'horno', 30, 'facil', 'all', 372, 20, 18, 24, 2, true, false, '{"huevo"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Tomate triturado","amount":200,"unit":"ml"},{"name":"Pimiento rojo","amount":80,"unit":"g"},{"name":"Guisantes","amount":60,"unit":"g"},{"name":"Jamón serrano","amount":40,"unit":"g"},{"name":"Chorizo","amount":40,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Cebolla","amount":50,"unit":"g"}]'::jsonb, '{"Cortar cebolla en brunoise fina y pimiento rojo en tiras de 1 cm.","Cortar chorizo en rodajas de 5 mm y jamón serrano en taquitos pequeños.","Calentar aceite de oliva en una cazuela de barro o sartén apta para horno a fuego medio.","Sofreír la cebolla picada y el pimiento rojo en tiras hasta que estén tiernos, unos 5 min a fuego medio.","Añadir el chorizo en rodajas y el jamón en taquitos; sofreír 2 min hasta que suelten su grasa.","Añadir tomate triturado y guisantes; remover y cocer a fuego medio-suave 8 min hasta que la salsa espese.","Precalentar el horno a 200 °C con calor arriba y abajo.","Repartir la base de sofrito en 2 cazuelitas individuales aptas para horno, dejando hueco en el centro.","Cascar huevo con cuidado, 2 por cazuelita, sobre la base de sofrito sin romper la yema.","Hornear las cazuelitas a 200 °C durante 8-10 min hasta que la clara esté cuajada y la yema aún jugosa.","Retirar del horno con cuidado y servir las cazuelitas directamente en la mesa."}', 'Huevos al horno sobre sofrito con pimiento, jamón y chorizo', '[{"appliance":"horno","time":30,"difficulty":"facil","prepSummary":"Prepara un sofrito con la cebolla, pimiento y tomate. Distribúyelo en cazuelitas individuales con los guisantes, jamón y chorizo. Haz un hueco, casca los huevos y hornea a 180°C durante 15-20 minutos hasta que las claras estén cuajadas y las yemas a tu gusto."},{"appliance":"airfryer","time":25,"difficulty":"facil","prepSummary":"Prepara el sofrito en una sartén o microondas. Distribúyelo en ramequines aptos para airfryer con el resto de ingredientes, casca los huevos y cocina a 160-170°C durante 10-12 minutos. Vigila para que las yemas queden a tu gusto."},{"appliance":"microondas","time":20,"difficulty":"normal","prepSummary":"Prepara el sofrito en un bol apto para microondas. Distribúyelo en tazas o ramequines individuales con el resto de ingredientes. Casca los huevos, pincha ligeramente las yemas y cocina a media potencia (500W) en intervalos de 1 minuto hasta que las claras cuajen, vigilando para no sobrecocer las yemas."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, ARRAY['cerdo']::main_protein[], false, '[{"text":"Cortar {{Cebolla}} en brunoise fina y {{Pimiento rojo}} en tiras de 1 cm.","minutes":4,"kind":"prep"},{"text":"Cortar {{Chorizo}} en rodajas de 5 mm y {{Jamón serrano}} en taquitos pequeños.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una cazuela de barro o sartén apta para horno a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla picada y el pimiento rojo en tiras hasta que estén tiernos, unos 5 min a fuego medio.","minutes":5,"kind":"activo"},{"text":"Añadir el chorizo en rodajas y el jamón en taquitos; sofreír 2 min hasta que suelten su grasa.","minutes":2,"kind":"activo"},{"text":"Añadir {{Tomate triturado}} y {{Guisantes}}; remover y cocer a fuego medio-suave 8 min hasta que la salsa espese.","minutes":8,"kind":"pasivo"},{"text":"Precalentar el horno a 200 °C con calor arriba y abajo.","minutes":5,"kind":"paralelo","during":5},{"text":"Repartir la base de sofrito en 2 cazuelitas individuales aptas para horno, dejando hueco en el centro.","minutes":1,"kind":"emplatado"},{"text":"Cascar {{Huevo}} con cuidado, 2 por cazuelita, sobre la base de sofrito sin romper la yema.","minutes":1,"kind":"activo"},{"text":"Hornear las cazuelitas a 200 °C durante 8-10 min hasta que la clara esté cuajada y la yema aún jugosa.","minutes":10,"kind":"pasivo"},{"text":"Retirar del horno con cuidado y servir las cazuelitas directamente en la mesa.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'horno', NULL),
  ('huevos_014', 'Huevos cocidos con ensalada', 'huevos', 'huevo', NULL, ARRAY['cena','primero']::meal_role[], 'principal', NULL, NULL, 15, 'facil', 'verano', 286, 16, 8, 22, 2, true, true, '{"huevo","sulfitos"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Lechuga","amount":100,"unit":"g"},{"name":"Tomate","amount":120,"unit":"g"},{"name":"Pepino","amount":80,"unit":"g"},{"name":"Aceitunas","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Vinagre","amount":10,"unit":"ml"}]'::jsonb, '{"Llevar una olla con agua abundante a ebullición a fuego fuerte.","Introducir huevo con cuidado y cocer a fuego medio durante 10 min.","Cortar lechuga en trozos y distribuir en una fuente o bol grande.","Cortar tomate en gajos y añadir sobre la lechuga.","Cortar pepino en rodajas y añadir a la fuente.","Añadir aceitunas a la fuente con el resto de la ensalada.","Escurrir los huevos y sumergir en agua fría durante 2 min hasta que estén templados.","Pelar los huevos y cortar cada uno en 4 cuartos.","Aliñar la ensalada con aceite de oliva y vinagre, y remover con suavidad.","Disponer los cuartos de huevo sobre la ensalada y servir de inmediato."}', 'Huevos cocidos en cuartos sobre ensalada mixta aliñada', '[{"appliance":"vaporera","time":20,"difficulty":"facil","prepSummary":"Calienta agua en la base de la vaporera hasta que hierva. Coloca los huevos en la cesta y cocina al vapor durante 12-15 minutos para huevos duros fáciles de pelar."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura","encurtido"}', NULL, '{}'::main_protein[], false, '[{"text":"Llevar una olla con agua abundante a ebullición a fuego fuerte.","minutes":3,"kind":"activo"},{"text":"Introducir {{Huevo}} con cuidado y cocer a fuego medio durante 10 min.","minutes":10,"kind":"pasivo"},{"text":"Cortar {{Lechuga}} en trozos y distribuir en una fuente o bol grande.","minutes":2,"kind":"paralelo","during":1},{"text":"Cortar {{Tomate}} en gajos y añadir sobre la lechuga.","minutes":1,"kind":"paralelo","during":1},{"text":"Cortar {{Pepino}} en rodajas y añadir a la fuente.","minutes":1,"kind":"paralelo","during":1},{"text":"Añadir {{Aceitunas}} a la fuente con el resto de la ensalada.","minutes":1,"kind":"paralelo","during":1},{"text":"Escurrir los huevos y sumergir en agua fría durante 2 min hasta que estén templados.","minutes":2,"kind":"espera"},{"text":"Pelar los huevos y cortar cada uno en 4 cuartos.","minutes":2,"kind":"prep"},{"text":"Aliñar la ensalada con {{Aceite de oliva|chorrito}} y {{Vinagre|chorrito}}, y remover con suavidad.","minutes":1,"kind":"activo"},{"text":"Disponer los cuartos de huevo sobre la ensalada y servir de inmediato.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'olla', NULL),
  ('huevos_015', 'Revuelto de setas', 'huevos', 'huevo', NULL, ARRAY['cena','primero']::meal_role[], 'principal', NULL, NULL, 15, 'facil', 'invierno', 274, 15, 4, 22, 2, true, false, '{"huevo"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Setas variadas","amount":200,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Picar ajo muy fino.","Cortar setas variadas en trozos irregulares de bocado.","Cascar huevo en un bol y batirlos hasta integrar la clara y la yema.","Picar perejil fino y reservar.","Calentar aceite de oliva en sartén a fuego fuerte hasta que humee ligeramente.","Añadir el ajo picado y saltear hasta que empiece a dorarse, sin que se queme.","Añadir las setas troceadas y saltear a fuego fuerte hasta que suelten el agua y se doren.","Salpimentar las setas al gusto y bajar el fuego a suave.","Verter los huevos batidos sobre las setas y remover suavemente con espátula hasta que cuajen de forma cremosa.","Retirar la sartén del fuego cuando los huevos aún estén ligeramente líquidos; el calor residual los termina.","Servir de inmediato con el perejil picado esparcido por encima."}', 'Revuelto cremoso de setas de temporada con ajo y perejil', '[]'::jsonb, '{}', NULL, NULL, NULL, '{"seta"}', NULL, '{}'::main_protein[], false, '[{"text":"Picar {{Ajo}} muy fino.","minutes":1,"kind":"prep"},{"text":"Cortar {{Setas variadas}} en trozos irregulares de bocado.","minutes":2,"kind":"prep"},{"text":"Cascar {{Huevo}} en un bol y batirlos hasta integrar la clara y la yema.","minutes":1,"kind":"prep"},{"text":"Picar {{Perejil}} fino y reservar.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego fuerte hasta que humee ligeramente.","minutes":1,"kind":"activo"},{"text":"Añadir el ajo picado y saltear hasta que empiece a dorarse, sin que se queme.","minutes":1,"kind":"activo"},{"text":"Añadir las setas troceadas y saltear a fuego fuerte hasta que suelten el agua y se doren.","minutes":4,"kind":"activo"},{"text":"Salpimentar las setas al gusto y bajar el fuego a suave.","minutes":1,"kind":"activo"},{"text":"Verter los huevos batidos sobre las setas y remover suavemente con espátula hasta que cuajen de forma cremosa.","minutes":2,"kind":"activo"},{"text":"Retirar la sartén del fuego cuando los huevos aún estén ligeramente líquidos; el calor residual los termina.","minutes":1,"kind":"activo"},{"text":"Servir de inmediato con el perejil picado esparcido por encima.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'sarten', NULL),
  ('huevos_016', 'Pisto con huevos', 'huevos', 'huevo', NULL, ARRAY['cena','segundo']::meal_role[], 'principal', NULL, NULL, 35, 'facil', 'verano', 310, 16, 14, 22, 2, true, false, '{"huevo"}', '[{"name":"Calabacín","amount":180,"unit":"g"},{"name":"Pimiento rojo","amount":100,"unit":"g"},{"name":"Pimiento verde","amount":100,"unit":"g"},{"name":"Cebolla","amount":70,"unit":"g"},{"name":"Tomate maduro","amount":180,"unit":"g"},{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Aceite de oliva","amount":35,"unit":"ml"},{"name":"Ajo","amount":8,"unit":"g"}]'::jsonb, '{"Picar cebolla y ajo en dados pequeños.","Cortar pimiento rojo, pimiento verde y calabacín en dados pequeños.","Pelar tomate maduro y cortar en dados pequeños.","Calentar 20 ml de aceite de oliva en una cazuela a fuego medio.","Sofreír la cebolla y el ajo hasta que la cebolla esté translúcida, unos 4 min.","Añadir los pimientos y sofreír 5 min hasta que estén tiernos.","Incorporar el calabacín, remover y cocer 4 min.","Añadir el tomate, tapar y cocer a fuego suave hasta que las verduras estén tiernas, unos 12 min.","Calentar el resto del aceite en una sartén a fuego medio.","Freír los huevos hasta que la clara esté cuajada y la yema líquida.","Servir el pisto en plato con el huevo frito encima."}', 'Pisto de verduras con huevos fritos encima, para acompañar con guarnición', '[{"appliance":"airfryer","time":30,"difficulty":"facil","prepSummary":"Prepara el pisto en sartén. Fríe los huevos en sartén aparte o casca los huevos sobre el pisto caliente y termina 3-4 min en airfryer a 180 °C hasta cuajar la clara."},{"appliance":"horno","time":40,"difficulty":"facil","prepSummary":"Prepara el pisto en cazuela. Reparte en dos cazuelitas, casca un huevo (o dos) encima de cada una y hornea a 180 °C durante 8-10 min hasta que la clara cuaje y la yema quede líquida."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], true, '[{"text":"Picar {{Cebolla}} y {{Ajo}} en dados pequeños.","minutes":2,"kind":"prep"},{"text":"Cortar {{Pimiento rojo}}, {{Pimiento verde}} y {{Calabacín}} en dados pequeños.","minutes":4,"kind":"prep"},{"text":"Pelar {{Tomate maduro}} y cortar en dados pequeños.","minutes":3,"kind":"prep"},{"text":"Calentar la mayor parte del {{Aceite de oliva}} en una cazuela a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla y el ajo hasta que la cebolla esté translúcida, unos 4 min.","minutes":4,"kind":"activo"},{"text":"Añadir los pimientos y sofreír 5 min hasta que estén tiernos.","minutes":5,"kind":"activo"},{"text":"Incorporar el calabacín, remover y cocer 4 min.","minutes":4,"kind":"activo"},{"text":"Añadir el tomate, tapar y cocer a fuego suave hasta que las verduras estén tiernas, unos 12 min.","minutes":12,"kind":"pasivo"},{"text":"Calentar el resto del aceite en {{@Sartén}} a fuego medio.","minutes":1,"kind":"activo"},{"text":"Freír {{Huevo}} hasta que la clara esté cuajada y la yema líquida.","minutes":3,"kind":"activo"},{"text":"Servir el pisto en plato con el huevo frito encima.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'olla', NULL),
  ('huevos_017', 'Pisto con huevo y patatas fritas', 'huevos', 'huevo', NULL, ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 40, 'facil', 'verano', 520, 20, 38, 32, 2, true, false, '{"huevo"}', '[{"name":"Calabacín","amount":180,"unit":"g"},{"name":"Pimiento rojo","amount":100,"unit":"g"},{"name":"Pimiento verde","amount":100,"unit":"g"},{"name":"Cebolla","amount":70,"unit":"g"},{"name":"Tomate maduro","amount":180,"unit":"g"},{"name":"Patata","amount":300,"unit":"g"},{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Aceite de oliva","amount":50,"unit":"ml"},{"name":"Ajo","amount":8,"unit":"g"}]'::jsonb, '{"Pelar patata y cortar en bastones de 1 cm de grosor.","Calentar aceite de oliva en sartén a fuego fuerte.","Freír los bastones de patata hasta que estén dorados y crujientes.","Escurrir las patatas fritas sobre papel absorbente y reservar.","Picar cebolla y ajo en dados pequeños.","Cortar pimiento rojo, pimiento verde y calabacín en dados pequeños.","Pelar tomate maduro y cortar en dados pequeños.","Calentar un chorrito de aceite de oliva en una cazuela a fuego medio.","Sofreír la cebolla y el ajo hasta que la cebolla esté translúcida.","Añadir el pimiento rojo y el pimiento verde y sofreír hasta que estén tiernos.","Añadir el calabacín y remover para integrar con las verduras.","Cocer el conjunto hasta que el calabacín empiece a ablandarse.","Añadir el tomate maduro, tapar y cocer a fuego suave hasta que todo esté tierno.","Freír huevo en sartén con el aceite restante a fuego medio hasta que la clara esté cuajada.","Servir el pisto en el plato con las patatas fritas al lado y el huevo frito encima."}', 'Pisto manchego con huevos fritos y patatas fritas', '[{"appliance":"airfryer","time":35,"difficulty":"facil","prepSummary":"Prepara el pisto en sartén como de costumbre. Corta las patatas en bastones, rocía con aceite y cocina en la airfryer a 190 °C durante 18-20 min, agitando a mitad. Fríe los huevos en sartén y emplata el pisto con las patatas y el huevo encima."},{"appliance":"horno","time":45,"difficulty":"facil","prepSummary":"Prepara el pisto en cazuela. Extiende las patatas en bastones con aceite en una bandeja y hornea a 200 °C durante 30-35 min. Fríe los huevos en sartén y sirve junto al pisto y las patatas."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], false, '[{"text":"Pelar {{Patata}} y cortar en bastones de 1 cm de grosor.","minutes":4,"kind":"prep","part":"guarnicion"},{"text":"Calentar {{Aceite de oliva|abundante}} en {{@Sartén}} a fuego fuerte.","minutes":1,"kind":"activo","part":"guarnicion"},{"text":"Freír los bastones de patata hasta que estén dorados y crujientes.","minutes":10,"kind":"pasivo","part":"guarnicion"},{"text":"Escurrir las patatas fritas sobre papel absorbente y reservar.","minutes":1,"kind":"prep","part":"guarnicion"},{"text":"Picar {{Cebolla}} y {{Ajo}} en dados pequeños.","minutes":3,"kind":"paralelo","part":"principal","during":2},{"text":"Cortar {{Pimiento rojo}}, {{Pimiento verde}} y {{Calabacín}} en dados pequeños.","minutes":3,"kind":"paralelo","part":"principal","during":2},{"text":"Pelar {{Tomate maduro}} y cortar en dados pequeños.","minutes":2,"kind":"paralelo","part":"principal","during":2},{"text":"Calentar un chorrito de aceite de oliva en una cazuela a fuego medio.","minutes":1,"kind":"activo","part":"principal"},{"text":"Sofreír la cebolla y el ajo hasta que la cebolla esté translúcida.","minutes":4,"kind":"activo","part":"principal"},{"text":"Añadir el pimiento rojo y el pimiento verde y sofreír hasta que estén tiernos.","minutes":5,"kind":"activo","part":"principal"},{"text":"Añadir el calabacín y remover para integrar con las verduras.","minutes":1,"kind":"activo","part":"principal"},{"text":"Cocer el conjunto hasta que el calabacín empiece a ablandarse.","minutes":3,"kind":"activo","part":"principal"},{"text":"Añadir el tomate maduro, tapar y cocer a fuego suave hasta que todo esté tierno.","minutes":12,"kind":"pasivo","part":"principal"},{"text":"Freír {{Huevo}} en {{@Sartén}} con el aceite restante a fuego medio hasta que la clara esté cuajada.","minutes":3,"kind":"activo","part":"principal"},{"text":"Servir el pisto en el plato con las patatas fritas al lado y el huevo frito encima.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL),
  ('huevos_018', 'Tortilla francesa rellena de queso y espinacas', 'huevos', 'huevo', NULL, ARRAY['cena','segundo']::meal_role[], 'principal', NULL, NULL, 10, 'facil', 'all', 320, 20, 4, 25, 2, true, false, '{"huevo","lactosa"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Espinacas frescas","amount":80,"unit":"g"},{"name":"Queso rallado","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Calentar aceite de oliva en sartén a fuego medio.","Añadir espinacas frescas y saltear hasta que reduzcan de volumen.","Retirar las espinacas salteadas de la sartén y reservar.","Batir huevo en un bol hasta integrar bien.","Calentar aceite de oliva en la sartén limpia a fuego medio.","Verter la mitad del huevo batido y dejar que los bordes cuajen.","Repartir la mitad de queso rallado y la mitad de las espinacas sobre una mitad de la tortilla.","Doblar la tortilla sobre el relleno y bajar a fuego suave hasta que el queso funda.","Deslizar la primera tortilla al plato y repetir desde el paso 5 con el resto de ingredientes.","Servir las 2 tortillas inmediatamente, con el queso aún fundido."}', 'Tortilla francesa doblada con queso fundido y espinacas salteadas por dentro', NULL, '{}', NULL, NULL, NULL, '{"verdura","lacteo"}', NULL, '{}'::main_protein[], false, '[{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego medio.","minutes":1,"kind":"activo"},{"text":"Añadir {{Espinacas frescas}} y saltear hasta que reduzcan de volumen.","minutes":3,"kind":"activo"},{"text":"Retirar las espinacas salteadas de la sartén y reservar.","minutes":1,"kind":"prep"},{"text":"Batir {{Huevo}} en un bol hasta integrar bien.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en la sartén limpia a fuego medio.","minutes":1,"kind":"activo"},{"text":"Verter la mitad del huevo batido y dejar que los bordes cuajen.","minutes":1,"kind":"activo"},{"text":"Repartir la mitad de {{Queso rallado}} y la mitad de las espinacas sobre una mitad de la tortilla.","minutes":1,"kind":"activo"},{"text":"Doblar la tortilla sobre el relleno y bajar a fuego suave hasta que el queso funda.","minutes":1,"kind":"activo"},{"text":"Deslizar la primera tortilla al plato y repetir desde el paso 5 con el resto de ingredientes.","minutes":4,"kind":"activo"},{"text":"Servir las 2 tortillas inmediatamente, con el queso aún fundido.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, true, 'sarten', NULL),
  ('huevos_019', 'Revuelto exprés de gambas congeladas y ajo', 'huevos', 'huevo', NULL, ARRAY['cena','segundo']::meal_role[], 'principal', NULL, NULL, 10, 'facil', 'all', 300, 26, 3, 20, 2, true, false, '{"huevo","marisco"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Gambas peladas congeladas","amount":200,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Descongelar gambas peladas congeladas bajo el grifo con agua fría hasta que estén blandas.","Escurrir las gambas y secar bien con papel de cocina para eliminar el exceso de agua.","Picar ajo fino.","Picar perejil fino.","Batir huevo en un bol con sal hasta obtener una mezcla homogénea.","Calentar aceite de oliva en sartén a fuego fuerte.","Sofreír el ajo picado unos segundos hasta que aromatice sin que se dore.","Saltear las gambas a fuego fuerte hasta que cambien de color.","Bajar el fuego a fuego suave y verter el huevo batido sobre las gambas.","Remover con espátula de forma continua hasta que el huevo cuaje cremoso sin secarse.","Retirar del fuego y espolvorear el perejil picado. Servir de inmediato."}', 'Revuelto rápido de gambas y ajo, listo en diez minutos', NULL, '{}', NULL, NULL, NULL, '{}', NULL, ARRAY['marisco']::main_protein[], false, '[{"text":"Descongelar {{Gambas peladas congeladas}} bajo el grifo con agua fría hasta que estén blandas.","minutes":5,"kind":"espera"},{"text":"Escurrir las gambas y secar bien con papel de cocina para eliminar el exceso de agua.","minutes":1,"kind":"prep"},{"text":"Picar {{Ajo}} fino.","minutes":1,"kind":"prep"},{"text":"Picar {{Perejil}} fino.","minutes":1,"kind":"prep"},{"text":"Batir {{Huevo}} en un bol con {{Sal|gusto}} hasta obtener una mezcla homogénea.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego fuerte.","minutes":1,"kind":"activo"},{"text":"Sofreír el ajo picado unos segundos hasta que aromatice sin que se dore.","minutes":1,"kind":"activo"},{"text":"Saltear las gambas a fuego fuerte hasta que cambien de color.","minutes":2,"kind":"activo"},{"text":"Bajar el fuego a fuego suave y verter el huevo batido sobre las gambas.","minutes":1,"kind":"activo"},{"text":"Remover con espátula de forma continua hasta que el huevo cuaje cremoso sin secarse.","minutes":1,"kind":"activo"},{"text":"Retirar del fuego y espolvorear el perejil picado. Servir de inmediato.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL),
  ('huevos_020', 'Huevos revueltos con salmón ahumado exprés', 'huevos', 'huevo', NULL, ARRAY['cena','segundo']::meal_role[], 'principal', NULL, NULL, 8, 'facil', 'all', 300, 21, 2, 23, 2, true, false, '{"huevo","pescado","lactosa"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Salmón ahumado","amount":100,"unit":"g"},{"name":"Nata para cocinar","amount":30,"unit":"ml"},{"name":"Cebollino","amount":5,"unit":"g"},{"name":"Mantequilla","amount":10,"unit":"g"}]'::jsonb, '{"Cortar salmón ahumado en tiras finas.","Picar cebollino muy fino.","Batir huevo junto con nata para cocinar en un bol hasta obtener una mezcla homogénea.","Calentar sartén a fuego suave y fundir mantequilla hasta que espume sin dorarse.","Verter la mezcla de huevo en la sartén y remover despacio con espátula de forma continua.","Incorporar la mitad del salmón cuando el huevo empiece a cuajar en grumos cremosos.","Retirar la sartén del fuego y remover 30 segundos más; el calor residual termina de cuajar el huevo.","Repartir los huevos revueltos en 2 platos.","Coronar con el resto del salmón y el cebollino picado. Servir enseguida."}', 'Huevos revueltos cremosos con tiras de salmón ahumado, listos en cinco minutos', NULL, '{}', true, NULL, NULL, '{}', NULL, ARRAY['pescado_azul']::main_protein[], false, '[{"text":"Cortar {{Salmón ahumado}} en tiras finas.","minutes":1,"kind":"prep"},{"text":"Picar {{Cebollino}} muy fino.","minutes":1,"kind":"prep"},{"text":"Batir {{Huevo}} junto con {{Nata para cocinar}} en un bol hasta obtener una mezcla homogénea.","minutes":1,"kind":"prep"},{"text":"Calentar {{@Sartén}} a fuego suave y fundir {{Mantequilla}} hasta que espume sin dorarse.","minutes":1,"kind":"activo"},{"text":"Verter la mezcla de huevo en la sartén y remover despacio con espátula de forma continua.","minutes":2,"kind":"activo"},{"text":"Incorporar la mitad del salmón cuando el huevo empiece a cuajar en grumos cremosos.","minutes":1,"kind":"activo"},{"text":"Retirar la sartén del fuego y remover 30 segundos más; el calor residual termina de cuajar el huevo.","minutes":1,"kind":"activo"},{"text":"Repartir los huevos revueltos en 2 platos.","minutes":1,"kind":"emplatado"},{"text":"Coronar con el resto del salmón y el cebollino picado. Servir enseguida.","kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL),
  ('huevos_021', 'Revuelto de jamón y queso con ensalada de aguacate, tomate y cebollino', 'huevos', 'huevo', NULL, ARRAY['cena','segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 500, 26, 10, 40, 2, true, false, '{"huevo","lactosa","sulfitos"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Jamón cocido","amount":80,"unit":"g"},{"name":"Queso curado","amount":30,"unit":"g"},{"name":"Aguacate","amount":150,"unit":"g"},{"name":"Tomate","amount":150,"unit":"g"},{"name":"Cebollino","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Vinagre de vino","amount":10,"unit":"ml"}]'::jsonb, '{"Cortar jamón cocido en dados pequeños.","Rallar queso curado finamente.","Batir huevo en un bol con sal hasta que estén bien integrados.","Cortar aguacate en dados medianos.","Cortar tomate en dados medianos.","Picar cebollino fino.","Mezclar el aguacate y el tomate en un bol.","Aliñar la ensalada con aceite de oliva, vinagre de vino y el cebollino picado.","Calentar aceite de oliva en sartén a fuego medio.","Saltear el jamón cocido en la sartén hasta que esté ligeramente dorado.","Verter el huevo batido sobre el jamón y remover con espátula a fuego medio.","Añadir el queso rallado y seguir removiendo hasta obtener un revuelto cremoso.","Retirar la sartén del fuego cuando el revuelto esté cuajado pero aún jugoso.","Servir el revuelto junto a la ensalada de aguacate y tomate."}', 'Revuelto cremoso de jamón y queso junto a una ensalada fresca de aguacate y tomate', NULL, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, ARRAY['cerdo']::main_protein[], false, '[{"text":"Cortar {{Jamón cocido}} en dados pequeños.","minutes":2,"kind":"prep","part":"principal"},{"text":"Rallar {{Queso curado}} finamente.","minutes":1,"kind":"prep","part":"principal"},{"text":"Batir {{Huevo}} en un bol con {{Sal|gusto}} hasta que estén bien integrados.","minutes":1,"kind":"prep","part":"principal"},{"text":"Cortar {{Aguacate}} en dados medianos.","minutes":2,"kind":"prep","part":"guarnicion"},{"text":"Cortar {{Tomate}} en dados medianos.","minutes":1,"kind":"prep","part":"guarnicion"},{"text":"Picar {{Cebollino}} fino.","minutes":1,"kind":"prep","part":"guarnicion"},{"text":"Mezclar el aguacate y el tomate en un bol.","minutes":1,"kind":"activo","part":"guarnicion"},{"text":"Aliñar la ensalada con {{Aceite de oliva|chorrito}}, {{Vinagre de vino}} y el cebollino picado.","minutes":1,"kind":"activo","part":"guarnicion"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego medio.","minutes":1,"kind":"activo","part":"principal"},{"text":"Saltear el jamón cocido en la sartén hasta que esté ligeramente dorado.","minutes":1,"kind":"activo","part":"principal"},{"text":"Verter el huevo batido sobre el jamón y remover con espátula a fuego medio.","minutes":1,"kind":"activo","part":"principal"},{"text":"Añadir el queso rallado y seguir removiendo hasta obtener un revuelto cremoso.","minutes":1,"kind":"activo","part":"principal"},{"text":"Retirar la sartén del fuego cuando el revuelto esté cuajado pero aún jugoso.","minutes":1,"kind":"activo","part":"principal"},{"text":"Servir el revuelto junto a la ensalada de aguacate y tomate.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true, NULL, NULL, 'olla', NULL)
