insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id, extra_proteins, freezable, steps_rich, estrella, occasion, kid_favourite, tecnica, cocina
) values
  ('huevos_022', 'Tortilla francesa de queso de cabra y espinacas con ensalada de tomate y albahaca', 'huevos', 'huevo', NULL, ARRAY['cena','segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 380, 19, 7, 30, 2, true, false, '{"huevo","lactosa","sulfitos"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Queso de cabra","amount":60,"unit":"g"},{"name":"Espinacas frescas","amount":60,"unit":"g"},{"name":"Tomate","amount":200,"unit":"g"},{"name":"Albahaca fresca","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Vinagre de vino","amount":10,"unit":"ml"}]'::jsonb, '{"Calentar sartén a fuego medio con aceite de oliva y añadir espinacas frescas.","Saltear las espinacas hasta que reduzcan por completo, luego retirar y reservar.","Cortar tomate en gajos y disponer en un plato.","Añadir albahaca fresca troceada sobre el tomate.","Aliñar el tomate con aceite de oliva y vinagre de vino.","Batir huevo en un bol con sal hasta obtener una mezcla homogénea.","Calentar la misma sartén a fuego medio con aceite de oliva y verter la mitad del huevo batido.","Repartir la mitad de queso de cabra en trozos y la mitad de las espinacas reservadas sobre una mitad de la tortilla cuando cuajen los bordes.","Doblar la tortilla y dejar fundir el queso hasta que el interior esté cremoso.","Deslizar la primera tortilla a un plato.","Repetir el proceso con el resto del huevo batido, el queso de cabra y las espinacas para hacer la segunda tortilla.","Servir cada tortilla junto a la ensalada de tomate y albahaca."}', 'Tortilla francesa verde por dentro con queso de cabra fundido, junto a tomate y albahaca frescos', NULL, '{}', NULL, NULL, NULL, '{"verdura","lacteo"}', NULL, '{}'::main_protein[], false, '[{"text":"Calentar {{@Sartén}} a fuego medio con {{Aceite de oliva|chorrito}} y añadir {{Espinacas frescas}}.","minutes":1,"kind":"activo","part":"principal"},{"text":"Saltear las espinacas hasta que reduzcan por completo, luego retirar y reservar.","minutes":2,"kind":"activo","part":"principal"},{"text":"Cortar {{Tomate}} en gajos y disponer en un plato.","minutes":2,"kind":"paralelo","part":"guarnicion","during":0},{"text":"Añadir {{Albahaca fresca}} troceada sobre el tomate.","minutes":1,"kind":"paralelo","part":"guarnicion","during":0},{"text":"Aliñar el tomate con {{Aceite de oliva|chorrito}} y {{Vinagre de vino}}.","minutes":1,"kind":"paralelo","part":"guarnicion","during":1},{"text":"Batir {{Huevo}} en un bol con {{Sal|gusto}} hasta obtener una mezcla homogénea.","minutes":1,"kind":"prep","part":"principal"},{"text":"Calentar la misma sartén a fuego medio con {{Aceite de oliva|chorrito}} y verter la mitad del huevo batido.","minutes":1,"kind":"activo","part":"principal"},{"text":"Repartir la mitad de {{Queso de cabra}} en trozos y la mitad de las espinacas reservadas sobre una mitad de la tortilla cuando cuajen los bordes.","minutes":1,"kind":"activo","part":"principal"},{"text":"Doblar la tortilla y dejar fundir el queso hasta que el interior esté cremoso.","minutes":1,"kind":"pasivo","part":"principal"},{"text":"Deslizar la primera tortilla a un plato.","minutes":1,"kind":"activo","part":"principal"},{"text":"Repetir el proceso con el resto del huevo batido, el queso de cabra y las espinacas para hacer la segunda tortilla.","minutes":3,"kind":"activo","part":"principal"},{"text":"Servir cada tortilla junto a la ensalada de tomate y albahaca.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL),
  ('huevos_023', 'Huevos fritos con jamón serrano y ensalada de aguacate, tomate y albahaca', 'huevos', 'huevo', NULL, ARRAY['cena','segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 12, 'facil', 'all', 480, 23, 10, 39, 2, true, false, '{"huevo","sulfitos"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Jamón serrano","amount":60,"unit":"g"},{"name":"Aguacate","amount":150,"unit":"g"},{"name":"Tomate","amount":150,"unit":"g"},{"name":"Albahaca fresca","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Vinagre de vino","amount":10,"unit":"ml"}]'::jsonb, '{"Cortar aguacate en dados de 1 cm.","Cortar tomate en dados de 1 cm.","Picar albahaca fresca en trozos gruesos.","Mezclar el aguacate, el tomate y la albahaca en un bol.","Aliñar la ensalada con vinagre de vino y la mitad de aceite de oliva. Remover y reservar.","Calentar el resto del aceite de oliva en sartén a fuego fuerte.","Freír huevo de 2 en 2 hasta que la clara esté cuajada y la puntilla dorada, con la yema líquida.","Escurrir los huevos fritos sobre papel absorbente y reservar. Repetir con los 2 huevos restantes.","Repartir los huevos fritos en 2 platos y colocar jamón serrano en lonchas encima.","Servir la ensalada de aguacate, tomate y albahaca junto a los huevos y el jamón."}', 'Huevos fritos con jamón serrano y una ensalada fresca de aguacate, tomate y albahaca', NULL, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, ARRAY['cerdo']::main_protein[], false, '[{"text":"Cortar {{Aguacate}} en dados de 1 cm.","minutes":2,"kind":"prep"},{"text":"Cortar {{Tomate}} en dados de 1 cm.","minutes":1,"kind":"prep"},{"text":"Picar {{Albahaca fresca}} en trozos gruesos.","minutes":1,"kind":"prep"},{"text":"Mezclar el aguacate, el tomate y la albahaca en un bol.","minutes":1,"kind":"activo","part":"guarnicion"},{"text":"Aliñar la ensalada con {{Vinagre de vino}} y la mitad de {{Aceite de oliva}}. Remover y reservar.","minutes":1,"kind":"activo","part":"guarnicion"},{"text":"Calentar el resto del aceite de oliva en {{@Sartén}} a fuego fuerte.","minutes":1,"kind":"activo","part":"principal"},{"text":"Freír {{Huevo}} de 2 en 2 hasta que la clara esté cuajada y la puntilla dorada, con la yema líquida.","minutes":2,"kind":"activo","part":"principal"},{"text":"Escurrir los huevos fritos sobre papel absorbente y reservar. Repetir con los 2 huevos restantes.","minutes":2,"kind":"activo","part":"principal"},{"text":"Repartir los huevos fritos en 2 platos y colocar {{Jamón serrano}} en lonchas encima.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Servir la ensalada de aguacate, tomate y albahaca junto a los huevos y el jamón.","kind":"emplatado","part":"combinado"}]'::jsonb, true, NULL, true, 'sarten', NULL),
  ('huevos_024', 'Revuelto de gambas con ensalada de aguacate, mango y cilantro', 'huevos', 'huevo', NULL, ARRAY['cena','segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 500, 27, 21, 35, 2, true, false, '{"huevo","marisco"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Gambas peladas","amount":200,"unit":"g"},{"name":"Aguacate","amount":150,"unit":"g"},{"name":"Mango","amount":150,"unit":"g"},{"name":"Cilantro fresco","amount":10,"unit":"g"},{"name":"Lima","amount":1,"unit":"ud"},{"name":"Aceite de oliva","amount":25,"unit":"ml"}]'::jsonb, '{"Cortar aguacate y mango en dados de 1 cm.","Picar cilantro fresco fino.","Exprimir lima y reservar el zumo.","Mezclar el aguacate, el mango y el cilantro picado en un bol.","Aliñar la mezcla con el zumo de lima y reservar.","Batir huevo en un bol hasta que queden homogéneos.","Calentar aceite de oliva en sartén a fuego fuerte.","Saltear gambas peladas 2 min hasta que cambien de color.","Bajar el fuego a fuego suave y verter el huevo batido sobre las gambas.","Remover con espátula sin parar hasta que el huevo cuaje cremoso.","Retirar la sartén del fuego en cuanto el revuelto esté jugoso.","Repartir el revuelto en 2 platos y servir con la ensalada de aguacate, mango y cilantro al lado."}', 'Revuelto de gambas junto a una ensalada tropical de aguacate, mango y cilantro con vinagreta cítrica', NULL, '{}', NULL, NULL, NULL, '{"verdura","fruta"}', NULL, ARRAY['marisco']::main_protein[], false, '[{"text":"Cortar {{Aguacate}} y {{Mango}} en dados de 1 cm.","minutes":3,"kind":"prep"},{"text":"Picar {{Cilantro fresco}} fino.","minutes":1,"kind":"prep"},{"text":"Exprimir {{Lima}} y reservar el zumo.","minutes":1,"kind":"prep"},{"text":"Mezclar el aguacate, el mango y el cilantro picado en un bol.","minutes":1,"kind":"prep"},{"text":"Aliñar la mezcla con el zumo de lima y reservar.","minutes":1,"kind":"prep"},{"text":"Batir {{Huevo|gusto}} en un bol hasta que queden homogéneos.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego fuerte.","minutes":1,"kind":"activo"},{"text":"Saltear {{Gambas peladas}} 2 min hasta que cambien de color.","minutes":2,"kind":"activo"},{"text":"Bajar el fuego a fuego suave y verter el huevo batido sobre las gambas.","minutes":1,"kind":"activo"},{"text":"Remover con espátula sin parar hasta que el huevo cuaje cremoso.","minutes":2,"kind":"activo"},{"text":"Retirar la sartén del fuego en cuanto el revuelto esté jugoso.","minutes":1,"kind":"activo"},{"text":"Repartir el revuelto en 2 platos y servir con la ensalada de aguacate, mango y cilantro al lado.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL),
  ('huevos_025', 'Tortilla francesa de brie y nueces con ensalada de canónigos y pera', 'huevos', 'huevo', NULL, ARRAY['cena','segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 490, 20, 15, 39, 2, true, false, '{"huevo","lactosa","frutos_secos","sulfitos"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Queso brie","amount":60,"unit":"g"},{"name":"Nueces","amount":30,"unit":"g"},{"name":"Canónigos","amount":60,"unit":"g"},{"name":"Pera","amount":150,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Vinagre de vino","amount":10,"unit":"ml"}]'::jsonb, '{"Cortar queso brie en trozos pequeños.","Picar nueces groseramente.","Batir huevo en un bol hasta obtener una mezcla homogénea.","Laminar pera en láminas finas.","Mezclar canónigos con la pera laminada en un bol.","Aliñar la ensalada con aceite de oliva y vinagre de vino.","Calentar sartén a fuego medio con la mitad del aceite de oliva restante.","Verter la mitad del huevo batido en sartén caliente.","Repartir la mitad del brie y la mitad de las nueces sobre una mitad de la tortilla cuando cuajen los bordes.","Doblar la tortilla sobre el relleno y dejar fundir el queso hasta que esté cremoso.","Deslizar la tortilla al plato y repetir el proceso con el aceite de oliva restante, el huevo, el brie y las nueces.","Servir cada tortilla junto a la ensalada de canónigos y pera."}', 'Tortilla francesa con brie fundido y nueces, junto a una ensalada de canónigos y pera', NULL, '{}', NULL, NULL, NULL, '{"verdura","lacteo","fruta","frutos_secos"}', NULL, '{}'::main_protein[], false, '[{"text":"Cortar {{Queso brie}} en trozos pequeños.","minutes":1,"kind":"prep","part":"principal"},{"text":"Picar {{Nueces}} groseramente.","minutes":1,"kind":"prep","part":"principal"},{"text":"Batir {{Huevo}} en un bol hasta obtener una mezcla homogénea.","minutes":1,"kind":"prep","part":"principal"},{"text":"Laminar {{Pera}} en láminas finas.","minutes":2,"kind":"prep","part":"guarnicion"},{"text":"Mezclar {{Canónigos}} con la pera laminada en un bol.","minutes":1,"kind":"prep","part":"guarnicion"},{"text":"Aliñar la ensalada con {{Aceite de oliva|chorrito}} y {{Vinagre de vino}}.","minutes":1,"kind":"prep","part":"guarnicion"},{"text":"Calentar {{@Sartén}} a fuego medio con la mitad del aceite de oliva restante.","minutes":1,"kind":"activo","part":"principal"},{"text":"Verter la mitad del huevo batido en {{@Sartén}} caliente.","minutes":1,"kind":"activo","part":"principal"},{"text":"Repartir la mitad del brie y la mitad de las nueces sobre una mitad de la tortilla cuando cuajen los bordes.","minutes":1,"kind":"activo","part":"principal"},{"text":"Doblar la tortilla sobre el relleno y dejar fundir el queso hasta que esté cremoso.","minutes":1,"kind":"pasivo","part":"principal"},{"text":"Deslizar la tortilla al plato y repetir el proceso con el aceite de oliva restante, el huevo, el brie y las nueces.","minutes":3,"kind":"activo","part":"principal"},{"text":"Servir cada tortilla junto a la ensalada de canónigos y pera.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL),
  ('huevos_026', 'Bacon crujiente y huevo frito con ensalada de aguacate y rúcula', 'huevos', 'huevo', NULL, ARRAY['cena','segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 12, 'facil', 'all', 530, 25, 8, 45, 2, true, false, '{"huevo","sulfitos"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Bacon en lonchas","amount":60,"unit":"g"},{"name":"Aguacate","amount":150,"unit":"g"},{"name":"Rúcula","amount":50,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Vinagre de vino","amount":10,"unit":"ml"}]'::jsonb, '{"Calentar sartén a fuego fuerte sin aceite hasta que esté bien caliente.","Añadir bacon en lonchas en una sola capa y dorar hasta que esté crujiente, unos 3 min.","Retirar el bacon y escurrir sobre papel absorbente. Reservar la grasa en la sartén.","Laminar aguacate y colocarlo en un bol junto con rúcula.","Aliñar la ensalada con aceite de oliva y vinagre de vino. Reservar.","Freír huevo en la grasa del bacon a fuego medio hasta que la clara esté cuajada y la yema líquida.","Repartir los huevos fritos y el bacon crujiente entre 2 platos.","Servir la ensalada de aguacate y rúcula aliñada junto al resto del plato."}', 'Bacon crujiente y huevo frito de yema líquida junto a una ensalada de aguacate y rúcula', NULL, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, ARRAY['cerdo']::main_protein[], false, '[{"text":"Calentar {{@Sartén}} a fuego fuerte sin aceite hasta que esté bien caliente.","minutes":1,"kind":"activo"},{"text":"Añadir {{Bacon en lonchas}} en una sola capa y dorar hasta que esté crujiente, unos 3 min.","minutes":3,"kind":"activo"},{"text":"Retirar el bacon y escurrir sobre papel absorbente. Reservar la grasa en la sartén.","minutes":1,"kind":"prep"},{"text":"Laminar {{Aguacate}} y colocarlo en un bol junto con {{Rúcula}}.","minutes":2,"kind":"paralelo","during":1},{"text":"Aliñar la ensalada con {{Aceite de oliva|chorrito}} y {{Vinagre de vino}}. Reservar.","minutes":1,"kind":"paralelo","during":1},{"text":"Freír {{Huevo}} en la grasa del bacon a fuego medio hasta que la clara esté cuajada y la yema líquida.","minutes":2,"kind":"activo"},{"text":"Repartir los huevos fritos y el bacon crujiente entre 2 platos.","minutes":1,"kind":"emplatado"},{"text":"Servir la ensalada de aguacate y rúcula aliñada junto al resto del plato.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL),
  ('huevos_027', 'Tortilla de calabacín y feta con ensalada de tomate cherry y menta', 'huevos', 'huevo', NULL, ARRAY['cena','segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 375, 16, 8, 30, 2, true, true, '{"huevo","lactosa","sulfitos"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Calabacín","amount":200,"unit":"g"},{"name":"Queso feta","amount":60,"unit":"g"},{"name":"Tomate cherry","amount":150,"unit":"g"},{"name":"Menta fresca","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Vinagre de vino","amount":8,"unit":"ml"}]'::jsonb, '{"Cortar calabacín en dados pequeños.","Calentar aceite de oliva en sartén a fuego fuerte y saltear el calabacín hasta que esté tierno y ligeramente dorado.","Cortar tomate cherry por la mitad.","Picar menta fresca en trozos gruesos.","Batir huevo en un bol con sal.","Desmenuzar queso feta y añadirlo al bol junto con el calabacín salteado.","Mezclar bien hasta integrar todos los ingredientes del bol.","Calentar un chorrito del aceite de oliva en sartén antiadherente a fuego medio y verter la mezcla de huevo.","Tapar la sartén y cuajar la tortilla 4 min hasta que los bordes estén firmes y el centro apenas líquido.","Mezclar los tomates cherry con la menta picada, el aceite de oliva restante y vinagre de vino.","Dar la vuelta a la tortilla con ayuda de un plato y cuajar 3 min más por el otro lado.","Retirar la tortilla de la sartén y cortar en porciones.","Servir las porciones de tortilla junto a la ensalada de tomate cherry y menta."}', 'Tortilla jugosa de calabacín y feta junto a una ensalada fresca de tomate cherry y menta', NULL, '{}', NULL, NULL, NULL, '{"verdura","lacteo"}', NULL, '{}'::main_protein[], false, '[{"text":"Cortar {{Calabacín}} en dados pequeños.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego fuerte y saltear el calabacín hasta que esté tierno y ligeramente dorado.","minutes":5,"kind":"activo","part":"principal"},{"text":"Cortar {{Tomate cherry}} por la mitad.","minutes":2,"kind":"paralelo","part":"guarnicion","during":1},{"text":"Picar {{Menta fresca}} en trozos gruesos.","minutes":1,"kind":"paralelo","part":"guarnicion","during":1},{"text":"Batir {{Huevo}} en un bol con {{Sal|gusto}}.","minutes":1,"kind":"prep","part":"principal"},{"text":"Desmenuzar {{Queso feta}} y añadirlo al bol junto con el calabacín salteado.","minutes":1,"kind":"prep","part":"principal"},{"text":"Mezclar bien hasta integrar todos los ingredientes del bol.","minutes":1,"kind":"prep","part":"principal"},{"text":"Calentar un chorrito del aceite de oliva en {{@Sartén}} antiadherente a fuego medio y verter la mezcla de huevo.","minutes":1,"kind":"activo","part":"principal"},{"text":"Tapar la sartén y cuajar la tortilla 4 min hasta que los bordes estén firmes y el centro apenas líquido.","minutes":4,"kind":"pasivo","part":"principal"},{"text":"Mezclar los tomates cherry con la menta picada, el aceite de oliva restante y {{Vinagre de vino}}.","minutes":1,"kind":"paralelo","part":"guarnicion","during":8},{"text":"Dar la vuelta a la tortilla con ayuda de un plato y cuajar 3 min más por el otro lado.","minutes":3,"kind":"activo","part":"principal"},{"text":"Retirar la tortilla de la sartén y cortar en porciones.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Servir las porciones de tortilla junto a la ensalada de tomate cherry y menta.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true, NULL, true, 'sarten', NULL),
  ('huevos_028', 'Huevos revueltos con champiñones y ensalada de rúcula, parmesano y piñones', 'huevos', 'huevo', NULL, ARRAY['cena','segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 405, 19, 5, 33, 2, true, false, '{"huevo","lactosa","frutos_secos","sulfitos"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Champiñones","amount":150,"unit":"g"},{"name":"Rúcula","amount":60,"unit":"g"},{"name":"Parmesano en virutas","amount":30,"unit":"g"},{"name":"Piñones","amount":15,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Vinagre de vino","amount":8,"unit":"ml"}]'::jsonb, '{"Limpiar champiñones con un paño húmedo y laminar.","Calentar aceite de oliva en sartén a fuego fuerte.","Saltear los champiñones laminados hasta que doren y suelten el agua.","Batir huevo en un bol hasta integrar.","Tostar piñones en una sartén pequeña sin aceite a fuego medio hasta que doren ligeramente.","Bajar el fuego al mínimo y verter el huevo batido sobre los champiñones.","Remover con espátula sin parar hasta que el huevo cuaje cremoso y retirar del fuego.","Disponer rúcula en un bol junto con parmesano en virutas y los piñones tostados.","Aliñar la ensalada con el resto del aceite de oliva y vinagre de vino y mezclar.","Servir el revuelto de champiñones junto a la ensalada aliñada."}', 'Revuelto cremoso de champiñones junto a una ensalada de rúcula, parmesano y piñones tostados', NULL, '{}', NULL, NULL, NULL, '{"verdura","seta"}', NULL, '{}'::main_protein[], false, '[{"text":"Limpiar {{Champiñones}} con un paño húmedo y laminar.","minutes":3,"kind":"prep","part":"principal"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego fuerte.","minutes":1,"kind":"activo","part":"principal"},{"text":"Saltear los champiñones laminados hasta que doren y suelten el agua.","minutes":4,"kind":"activo","part":"principal"},{"text":"Batir {{Huevo}} en un bol hasta integrar.","minutes":1,"kind":"paralelo","part":"principal","during":2},{"text":"Tostar {{Piñones}} en una sartén pequeña sin aceite a fuego medio hasta que doren ligeramente.","minutes":2,"kind":"activo","part":"guarnicion"},{"text":"Bajar el fuego al mínimo y verter el huevo batido sobre los champiñones.","minutes":1,"kind":"activo","part":"principal"},{"text":"Remover con espátula sin parar hasta que el huevo cuaje cremoso y retirar del fuego.","minutes":2,"kind":"activo","part":"principal"},{"text":"Disponer {{Rúcula}} en un bol junto con {{Parmesano en virutas}} y los piñones tostados.","minutes":1,"kind":"prep","part":"guarnicion"},{"text":"Aliñar la ensalada con el resto del {{Aceite de oliva}} y {{Vinagre de vino}} y mezclar.","minutes":1,"kind":"prep","part":"guarnicion"},{"text":"Servir el revuelto de champiñones junto a la ensalada aliñada.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL),
  ('huevos_029', 'Salmón ahumado con huevo revuelto y ensalada de aguacate y eneldo', 'huevos', 'huevo', NULL, ARRAY['cena','segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 12, 'facil', 'all', 460, 23, 8, 38, 2, true, false, '{"huevo","pescado","lactosa"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Salmón ahumado","amount":100,"unit":"g"},{"name":"Aguacate","amount":150,"unit":"g"},{"name":"Eneldo fresco","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Zumo de limón","amount":10,"unit":"ml"},{"name":"Mantequilla","amount":10,"unit":"g"}]'::jsonb, '{"Batir huevo en un bol hasta homogeneizar; salpimentar al gusto.","Cortar aguacate en láminas y reservar en un bol.","Picar eneldo fresco fino y reservar.","Mezclar aceite de oliva, zumo de limón y el eneldo picado en un bol pequeño.","Aliñar las láminas de aguacate con la mezcla de aceite, limón y eneldo; reservar.","Fundir mantequilla en sartén a fuego suave hasta que espume sin dorarse.","Verter el huevo batido en la sartén y remover despacio con espátula a fuego suave.","Retirar la sartén del fuego cuando el huevo cuaje en grumos cremosos y aún brille.","Cortar salmón ahumado en tiras y disponer sobre el revuelto repartido en 2 platos.","Servir la ensalada de aguacate aliñada junto al plato de revuelto y salmón."}', 'Salmón ahumado sobre huevo revuelto cremoso, junto a una ensalada de aguacate y eneldo', NULL, '{}', true, NULL, NULL, '{"verdura"}', NULL, ARRAY['pescado_azul']::main_protein[], false, '[{"text":"Batir {{Huevo}} en un bol hasta homogeneizar; salpimentar al gusto.","minutes":2,"kind":"prep"},{"text":"Cortar {{Aguacate}} en láminas y reservar en un bol.","minutes":2,"kind":"prep"},{"text":"Picar {{Eneldo fresco}} fino y reservar.","minutes":1,"kind":"prep"},{"text":"Mezclar {{Aceite de oliva|chorrito}}, {{Zumo de limón}} y el eneldo picado en un bol pequeño.","minutes":1,"kind":"prep"},{"text":"Aliñar las láminas de aguacate con la mezcla de aceite, limón y eneldo; reservar.","minutes":1,"kind":"prep"},{"text":"Fundir {{Mantequilla}} en {{@Sartén}} a fuego suave hasta que espume sin dorarse.","minutes":1,"kind":"activo"},{"text":"Verter el huevo batido en la sartén y remover despacio con espátula a fuego suave.","minutes":2,"kind":"activo"},{"text":"Retirar la sartén del fuego cuando el huevo cuaje en grumos cremosos y aún brille.","minutes":1,"kind":"activo"},{"text":"Cortar {{Salmón ahumado}} en tiras y disponer sobre el revuelto repartido en 2 platos.","minutes":1,"kind":"emplatado"},{"text":"Servir la ensalada de aguacate aliñada junto al plato de revuelto y salmón.","kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL),
  ('huevos_030', 'Huevos benedictinos con salsa holandesa', 'huevos', 'huevo', 'pan', ARRAY['cena','segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'normal', 'all', 640, 30, 27, 45, 2, true, false, '{"huevo","lactosa","gluten","sulfitos"}', '[{"name":"Huevo","amount":6,"unit":"ud"},{"name":"Muffin inglés","amount":2,"unit":"ud"},{"name":"Jamón cocido","amount":80,"unit":"g"},{"name":"Mantequilla","amount":60,"unit":"g"},{"name":"Zumo de limón","amount":15,"unit":"ml"},{"name":"Vinagre de vino","amount":15,"unit":"ml"}]'::jsonb, '{"Fundir mantequilla en un cazo a fuego suave hasta que esté completamente líquida; reservar tibia.","Separar 2 yemas de huevo del resto; reservar las yemas en un bol resistente al calor y reservar los 4 huevos enteros aparte.","Añadir zumo de limón a las yemas y batir con varillas hasta mezclar.","Colocar el bol sobre un cazo con agua caliente sin que toque el agua; batir las yemas con el zumo de limón al baño maría.","Incorporar la mantequilla tibia en hilo fino sin dejar de batir hasta que la salsa esté homogénea y cremosa.","Retirar el bol del baño maría y reservar la salsa holandesa en un lugar tibio, tapada.","Llevar a ebullición una cazuela con agua abundante y vinagre de vino a fuego medio.","Bajar el fuego hasta ebullición suave; remover el agua para formar un remolino e introducir 1 huevo entero.","Escalfar el huevo 3 min hasta que la clara esté cuajada y la yema líquida; retirar con espumadera.","Repetir el proceso con los 3 huevos enteros restantes de uno en uno; escurrir cada uno sobre papel absorbente.","Cortar muffin inglés por la mitad y tostar en una sartén a fuego medio hasta que estén dorados.","Calentar jamón cocido en la misma sartén a fuego medio, 1 min por cada lado.","Disponer cada mitad de muffin tostada en el plato y colocar encima una porción de jamón cocido.","Colocar 1 huevo escalfado sobre cada porción de jamón.","Napar con la salsa holandesa reservada y servir de inmediato."}', 'Muffin inglés con jamón, huevo escalfado y salsa holandesa recién montada', NULL, '{}', true, NULL, NULL, '{"lacteo"}', NULL, ARRAY['cerdo']::main_protein[], false, '[{"text":"Fundir {{Mantequilla}} en un cazo a fuego suave hasta que esté completamente líquida; reservar tibia.","minutes":3,"kind":"activo","part":"salsa"},{"text":"Separar 2 yemas de {{Huevo}} del resto; reservar las yemas en un bol resistente al calor y reservar los 4 huevos enteros aparte.","minutes":2,"kind":"prep","part":"salsa"},{"text":"Añadir {{Zumo de limón}} a las yemas y batir con varillas hasta mezclar.","minutes":1,"kind":"prep","part":"salsa"},{"text":"Colocar el bol sobre un cazo con agua caliente sin que toque el agua; batir las yemas con el zumo de limón al baño maría.","minutes":4,"kind":"activo","part":"salsa"},{"text":"Incorporar la mantequilla tibia en hilo fino sin dejar de batir hasta que la salsa esté homogénea y cremosa.","minutes":3,"kind":"activo","part":"salsa"},{"text":"Retirar el bol del baño maría y reservar la salsa holandesa en un lugar tibio, tapada.","minutes":1,"kind":"activo","part":"salsa"},{"text":"Llevar a ebullición una cazuela con agua abundante y {{Vinagre de vino}} a fuego medio.","minutes":4,"kind":"activo","part":"principal"},{"text":"Bajar el fuego hasta ebullición suave; remover el agua para formar un remolino e introducir 1 huevo entero.","minutes":1,"kind":"activo","part":"principal"},{"text":"Escalfar el huevo 3 min hasta que la clara esté cuajada y la yema líquida; retirar con espumadera.","minutes":3,"kind":"pasivo","part":"principal"},{"text":"Repetir el proceso con los 3 huevos enteros restantes de uno en uno; escurrir cada uno sobre papel absorbente.","minutes":12,"kind":"activo","part":"principal"},{"text":"Cortar {{Muffin inglés}} por la mitad y tostar en una {{@Sartén}} a fuego medio hasta que estén dorados.","minutes":3,"kind":"activo","part":"principal"},{"text":"Calentar {{Jamón cocido}} en la misma sartén a fuego medio, 1 min por cada lado.","minutes":2,"kind":"activo","part":"principal"},{"text":"Disponer cada mitad de muffin tostada en el plato y colocar encima una porción de jamón cocido.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Colocar 1 huevo escalfado sobre cada porción de jamón.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Napar con la salsa holandesa reservada y servir de inmediato.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true, NULL, NULL, 'olla', NULL),
  ('huevos_031', 'Huevos rotos con jamón y patatas fritas', 'huevos', 'huevo', 'patatas', ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 535, 26, 31, 34, 2, true, false, '{"huevo"}', '[{"name":"Patata","amount":350,"unit":"g"},{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Jamón serrano","amount":70,"unit":"g"},{"name":"Aceite de oliva","amount":80,"unit":"ml"}]'::jsonb, '{"Pelar patata y cortar en bastones finos tipo paja.","Calentar aceite de oliva en una sartén honda a fuego fuerte hasta que esté bien caliente.","Freír las patatas en 2 tandas hasta que estén doradas y crujientes.","Escurrir las patatas sobre papel absorbente y salar al gusto.","Freír huevo en el mismo aceite a fuego medio hasta que la clara esté cuajada y la yema líquida.","Repartir las patatas fritas en 2 platos formando una base.","Colocar los huevos fritos encima de las patatas.","Disponer jamón serrano en lonchas sobre los huevos.","Romper las yemas con un tenedor al momento de servir para que se mezclen con las patatas."}', 'Patatas paja crujientes con huevos fritos de yema rota y jamón serrano', NULL, '{}', NULL, NULL, NULL, '{}', NULL, ARRAY['cerdo']::main_protein[], false, '[{"text":"Pelar {{Patata}} y cortar en bastones finos tipo paja.","minutes":5,"kind":"prep","part":"guarnicion"},{"text":"Calentar {{Aceite de oliva|abundante}} en una sartén honda a fuego fuerte hasta que esté bien caliente.","minutes":2,"kind":"activo","part":"guarnicion"},{"text":"Freír las patatas en 2 tandas hasta que estén doradas y crujientes.","minutes":8,"kind":"activo","part":"guarnicion"},{"text":"Escurrir las patatas sobre papel absorbente y salar al gusto.","minutes":1,"kind":"activo","part":"guarnicion"},{"text":"Freír {{Huevo}} en el mismo aceite a fuego medio hasta que la clara esté cuajada y la yema líquida.","minutes":3,"kind":"activo","part":"principal"},{"text":"Repartir las patatas fritas en 2 platos formando una base.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Colocar los huevos fritos encima de las patatas.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Disponer {{Jamón serrano}} en lonchas sobre los huevos.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Romper las yemas con un tenedor al momento de servir para que se mezclen con las patatas.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL)
