insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id, extra_proteins, freezable, steps_rich, estrella, occasion, kid_favourite, tecnica, cocina
) values
  ('huevos_032', 'Huevos rotos con jamón y foie', 'huevos', 'huevo', 'patatas', ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 25, 'normal', 'all', 680, 26, 36, 46, 2, false, false, '{"huevo","sulfitos","lactosa"}', '[{"name":"Patata","amount":350,"unit":"g"},{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Jamón serrano","amount":50,"unit":"g"},{"name":"Foie mi-cuit","amount":80,"unit":"g"},{"name":"Aceite de oliva","amount":40,"unit":"ml"},{"name":"Vino Pedro Ximénez","amount":20,"unit":"ml"}]'::jsonb, '{"Pelar patata y cortarlas en bastones finos tipo paja.","Calentar aceite de oliva en sartén honda a fuego fuerte.","Freír las patatas en el aceite caliente hasta que estén doradas y crujientes.","Escurrir las patatas fritas sobre papel absorbente y reservar.","Verter vino pedro ximénez en un cazo a fuego suave hasta que espese ligeramente.","Retirar la reducción del fuego y reservar en el cazo.","Freír huevo en el mismo aceite a fuego medio hasta que la clara esté cuajada y la yema líquida.","Cortar foie mi-cuit en lonchas gruesas de aproximadamente 1 cm.","Calentar sartén sin aceite a fuego fuerte hasta que humee.","Marcar las lonchas de foie 30 segundos por cada lado y retirar.","Repartir las patatas fritas en 2 platos y colocar los huevos fritos encima.","Añadir jamón serrano y las lonchas de foie sobre los huevos.","Terminar con un hilo de la reducción de Pedro Ximénez y romper las yemas al servir."}', 'Versión de lujo del clásico de bar: patatas fritas, huevo roto, jamón y foie marcado', NULL, '{}', true, NULL, NULL, '{}', NULL, ARRAY['cerdo']::main_protein[], false, '[{"text":"Pelar {{Patata}} y cortarlas en bastones finos tipo paja.","minutes":5,"kind":"prep","part":"guarnicion"},{"text":"Calentar {{Aceite de oliva}} en {{@Sartén}} honda a fuego fuerte.","minutes":2,"kind":"activo","part":"guarnicion"},{"text":"Freír las patatas en el aceite caliente hasta que estén doradas y crujientes.","minutes":10,"kind":"activo","part":"guarnicion"},{"text":"Escurrir las patatas fritas sobre papel absorbente y reservar.","minutes":1,"kind":"prep","part":"guarnicion"},{"text":"Verter {{Vino Pedro Ximénez}} en un cazo a fuego suave hasta que espese ligeramente.","minutes":4,"kind":"pasivo","part":"salsa"},{"text":"Retirar la reducción del fuego y reservar en el cazo.","minutes":1,"kind":"activo","part":"salsa"},{"text":"Freír {{Huevo}} en el mismo aceite a fuego medio hasta que la clara esté cuajada y la yema líquida.","minutes":3,"kind":"activo","part":"principal"},{"text":"Cortar {{Foie mi-cuit}} en lonchas gruesas de aproximadamente 1 cm.","minutes":1,"kind":"prep","part":"principal"},{"text":"Calentar {{@Sartén}} sin aceite a fuego fuerte hasta que humee.","minutes":1,"kind":"activo","part":"principal"},{"text":"Marcar las lonchas de foie 30 segundos por cada lado y retirar.","minutes":1,"kind":"activo","part":"principal"},{"text":"Repartir las patatas fritas en 2 platos y colocar los huevos fritos encima.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Añadir {{Jamón serrano}} y las lonchas de foie sobre los huevos.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Terminar con un hilo de la reducción de Pedro Ximénez y romper las yemas al servir.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true, 'especial', NULL, 'sarten', NULL),
  ('huevos_033', 'Tortilla de patatas con queso curado', 'huevos', 'huevo', 'patatas', ARRAY['segundo','cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'normal', 'all', 670, 28, 30, 48, 2, true, true, '{"huevo","lactosa"}', '[{"name":"Patata","amount":300,"unit":"g"},{"name":"Huevo","amount":5,"unit":"ud"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Queso curado","amount":80,"unit":"g"},{"name":"Aceite de oliva","amount":60,"unit":"ml"}]'::jsonb, '{"Pelar patata y laminar en rodajas finas de unos 2-3 mm.","Cortar cebolla en juliana fina.","Calentar aceite de oliva en sartén a fuego suave.","Añadir la patata laminada y la cebolla en juliana a la sartén y confitar a fuego suave.","Cortar queso curado en dados pequeños.","Batir huevo en un bol grande con sal hasta obtener una mezcla homogénea.","Escurrir la patata y la cebolla en un colador, reservando el aceite sobrante.","Añadir la patata escurrida, la cebolla escurrida y el queso en dados al bol con el huevo batido.","Remover la mezcla con cuidado para integrar todos los ingredientes sin romper la patata.","Dejar reposar la mezcla en el bol 2 min para que el huevo penetre bien en la patata.","Calentar un poco del aceite reservado en sartén a fuego fuerte hasta que humee ligeramente.","Verter la mezcla en la sartén, extender y cuajar a fuego medio-fuerte durante 3 min hasta que los bordes estén firmes.","Dar la vuelta a la tortilla con un plato llano y deslizarla de nuevo a la sartén.","Cuajar el segundo lado a fuego medio 2 min hasta que esté dorado pero el interior jugoso.","Reposar la tortilla en la sartén fuera del fuego 1 min antes de servir.","Servir la tortilla entera o en porciones, con el queso fundido en el interior."}', 'Tortilla de patatas con queso curado fundido por dentro, de aroma intenso', NULL, '{}', NULL, NULL, NULL, '{"lacteo"}', NULL, '{}'::main_protein[], false, '[{"text":"Pelar {{Patata}} y laminar en rodajas finas de unos 2-3 mm.","minutes":3,"kind":"prep"},{"text":"Cortar {{Cebolla}} en juliana fina.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|abundante}} en {{@Sartén}} a fuego suave.","minutes":1,"kind":"activo"},{"text":"Añadir la patata laminada y la cebolla en juliana a la sartén y confitar a fuego suave.","minutes":20,"kind":"pasivo"},{"text":"Cortar {{Queso curado}} en dados pequeños.","minutes":2,"kind":"paralelo","during":3},{"text":"Batir {{Huevo}} en un bol grande con {{Sal|gusto}} hasta obtener una mezcla homogénea.","minutes":1,"kind":"paralelo","during":3},{"text":"Escurrir la patata y la cebolla en un colador, reservando el aceite sobrante.","minutes":1,"kind":"activo"},{"text":"Añadir la patata escurrida, la cebolla escurrida y el queso en dados al bol con el huevo batido.","minutes":1,"kind":"activo"},{"text":"Remover la mezcla con cuidado para integrar todos los ingredientes sin romper la patata.","minutes":1,"kind":"activo"},{"text":"Dejar reposar la mezcla en el bol 2 min para que el huevo penetre bien en la patata.","minutes":2,"kind":"espera"},{"text":"Calentar un poco del aceite reservado en {{@Sartén}} a fuego fuerte hasta que humee ligeramente.","minutes":1,"kind":"activo"},{"text":"Verter la mezcla en la sartén, extender y cuajar a fuego medio-fuerte durante 3 min hasta que los bordes estén firmes.","minutes":3,"kind":"activo"},{"text":"Dar la vuelta a la tortilla con un plato llano y deslizarla de nuevo a la sartén.","minutes":1,"kind":"activo"},{"text":"Cuajar el segundo lado a fuego medio 2 min hasta que esté dorado pero el interior jugoso.","minutes":2,"kind":"activo"},{"text":"Reposar la tortilla en la sartén fuera del fuego 1 min antes de servir.","minutes":1,"kind":"espera"},{"text":"Servir la tortilla entera o en porciones, con el queso fundido en el interior.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL),
  ('huevos_034', 'Tortilla abierta de boletus', 'huevos', 'huevo', NULL, ARRAY['cena','segundo']::meal_role[], 'principal', NULL, NULL, 15, 'normal', 'all', 335, 18, 6, 26, 2, true, true, '{"huevo"}', '[{"name":"Huevo","amount":5,"unit":"ud"},{"name":"Boletus","amount":200,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Perejil","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"}]'::jsonb, '{"Limpiar boletus con un paño húmedo y laminarlos.","Picar ajo fino.","Picar perejil fino y reservar.","Batir huevo en un bol con sal hasta que estén homogéneos.","Calentar aceite de oliva en sartén a fuego fuerte.","Sofreír el ajo picado hasta que empiece a dorarse.","Añadir los boletus laminados y saltear a fuego fuerte hasta que suelten el agua y se doren.","Verter el huevo batido sobre los boletus y bajar a fuego medio.","Cuajar sin remover, moviendo la sartén de vez en cuando, hasta que el fondo esté dorado y la superficie aún jugosa.","Espolvorear con el perejil picado y servir directamente desde la sartén."}', 'Tortilla abierta y jugosa con boletus dorados y aroma a bosque', NULL, '{}', true, NULL, NULL, '{"seta"}', NULL, '{}'::main_protein[], false, '[{"text":"Limpiar {{Boletus}} con un paño húmedo y laminarlos.","minutes":3,"kind":"prep"},{"text":"Picar {{Ajo}} fino.","minutes":1,"kind":"prep"},{"text":"Picar {{Perejil}} fino y reservar.","minutes":1,"kind":"prep"},{"text":"Batir {{Huevo}} en un bol con {{Sal|gusto}} hasta que estén homogéneos.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego fuerte.","minutes":1,"kind":"activo"},{"text":"Sofreír el ajo picado hasta que empiece a dorarse.","minutes":1,"kind":"activo"},{"text":"Añadir los boletus laminados y saltear a fuego fuerte hasta que suelten el agua y se doren.","minutes":5,"kind":"activo"},{"text":"Verter el huevo batido sobre los boletus y bajar a fuego medio.","minutes":1,"kind":"activo"},{"text":"Cuajar sin remover, moviendo la sartén de vez en cuando, hasta que el fondo esté dorado y la superficie aún jugosa.","minutes":2,"kind":"pasivo"},{"text":"Espolvorear con el perejil picado y servir directamente desde la sartén.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL),
  ('huevos_035', 'Tortilla de patatas con cebolla caramelizada', 'huevos', 'huevo', 'patatas', ARRAY['segundo','cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 45, 'normal', 'all', 590, 18, 41, 39, 2, true, true, '{"huevo"}', '[{"name":"Patata","amount":300,"unit":"g"},{"name":"Huevo","amount":5,"unit":"ud"},{"name":"Cebolla","amount":200,"unit":"g"},{"name":"Azúcar","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":70,"unit":"ml"}]'::jsonb, '{"Pelar patata y laminar en rodajas finas de unos 2-3 mm.","Cortar cebolla en juliana fina.","Calentar aceite de oliva en sartén a fuego suave y sofreír la cebolla 25 min, removiendo de vez en cuando, hasta que empiece a dorarse.","Añadir azúcar a la cebolla y remover a fuego suave hasta que esté caramelizada y muy tierna.","Retirar la cebolla caramelizada de la sartén y reservar en un bol grande.","Calentar aceite de oliva en sartén a fuego suave y confitar las patatas laminadas hasta que estén tiernas.","Escurrir las patatas confitadas para eliminar el exceso de aceite.","Batir huevo en el bol con la cebolla caramelizada hasta obtener una mezcla homogénea.","Añadir las patatas escurridas al bol con la mezcla de huevo y cebolla y remover con cuidado.","Dejar reposar la mezcla 2 min para que el huevo empape bien las patatas.","Calentar un chorrito de aceite de oliva en sartén a fuego medio y volcar la mezcla, distribuyéndola bien.","Cuajar la tortilla a fuego medio-suave hasta que los bordes estén firmes y el centro ligeramente jugoso.","Dar la vuelta a la tortilla con la ayuda de un plato llano y devolver a la sartén.","Cuajar el segundo lado a fuego suave hasta que esté dorado pero el interior quede jugoso.","Retirar la tortilla de la sartén y dejar reposar 3 min antes de servir.","Servir la tortilla cortada en porciones."}', 'Tortilla de patatas con el dulzor de una cebolla muy pochada y caramelizada', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Pelar {{Patata}} y laminar en rodajas finas de unos 2-3 mm.","minutes":5,"kind":"prep"},{"text":"Cortar {{Cebolla}} en juliana fina.","minutes":3,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego suave y sofreír la cebolla 25 min, removiendo de vez en cuando, hasta que empiece a dorarse.","minutes":25,"kind":"pasivo"},{"text":"Añadir {{Azúcar}} a la cebolla y remover a fuego suave hasta que esté caramelizada y muy tierna.","minutes":8,"kind":"activo"},{"text":"Retirar la cebolla caramelizada de la sartén y reservar en un bol grande.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|abundante}} en {{@Sartén}} a fuego suave y confitar las patatas laminadas hasta que estén tiernas.","minutes":15,"kind":"pasivo"},{"text":"Escurrir las patatas confitadas para eliminar el exceso de aceite.","minutes":2,"kind":"prep"},{"text":"Batir {{Huevo}} en el bol con la cebolla caramelizada hasta obtener una mezcla homogénea.","minutes":2,"kind":"prep"},{"text":"Añadir las patatas escurridas al bol con la mezcla de huevo y cebolla y remover con cuidado.","minutes":1,"kind":"prep"},{"text":"Dejar reposar la mezcla 2 min para que el huevo empape bien las patatas.","minutes":2,"kind":"espera"},{"text":"Calentar un chorrito de aceite de oliva en {{@Sartén}} a fuego medio y volcar la mezcla, distribuyéndola bien.","minutes":1,"kind":"activo"},{"text":"Cuajar la tortilla a fuego medio-suave hasta que los bordes estén firmes y el centro ligeramente jugoso.","minutes":3,"kind":"activo"},{"text":"Dar la vuelta a la tortilla con la ayuda de un plato llano y devolver a la sartén.","minutes":1,"kind":"activo"},{"text":"Cuajar el segundo lado a fuego suave hasta que esté dorado pero el interior quede jugoso.","minutes":2,"kind":"activo"},{"text":"Retirar la tortilla de la sartén y dejar reposar 3 min antes de servir.","minutes":3,"kind":"espera"},{"text":"Servir la tortilla cortada en porciones.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL