  ('huevos_036', 'Revuelto de setas silvestres', 'huevos', 'huevo', NULL, ARRAY['cena','segundo']::meal_role[], 'principal', NULL, NULL, 18, 'normal', 'all', 305, 15, 5, 24, 2, true, false, '{"huevo"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Setas silvestres variadas","amount":250,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Perejil","amount":6,"unit":"g"}]'::jsonb, '{"Limpiar setas silvestres variadas con un paño húmedo, retirando bien la tierra.","Cortar las setas en trozos o laminarlas según su tamaño.","Picar ajo fino.","Picar perejil.","Batir huevo en un bol con sal hasta obtener una mezcla homogénea.","Calentar aceite de oliva en sartén a fuego fuerte.","Sofreír el ajo picado hasta que empiece a dorarse.","Añadir las setas cortadas y saltear a fuego fuerte hasta que suelten el agua y se evapore.","Bajar el fuego a suave y verter el huevo batido sobre las setas.","Remover con espátula con movimientos lentos hasta que el huevo cuaje cremoso y aún jugoso.","Servir de inmediato con el perejil picado por encima."}', 'Revuelto cremoso de setas silvestres de temporada con aroma a bosque', NULL, '{}', true, NULL, NULL, '{"seta"}', NULL, '{}'::main_protein[], false, '[{"text":"Limpiar {{Setas silvestres variadas}} con un paño húmedo, retirando bien la tierra.","minutes":3,"kind":"prep"},{"text":"Cortar las setas en trozos o laminarlas según su tamaño.","minutes":2,"kind":"prep"},{"text":"Picar {{Ajo}} fino.","minutes":1,"kind":"prep"},{"text":"Picar {{Perejil|gusto}}.","minutes":1,"kind":"prep"},{"text":"Batir {{Huevo}} en un bol con {{Sal|gusto}} hasta obtener una mezcla homogénea.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego fuerte.","minutes":1,"kind":"activo"},{"text":"Sofreír el ajo picado hasta que empiece a dorarse.","minutes":1,"kind":"activo"},{"text":"Añadir las setas cortadas y saltear a fuego fuerte hasta que suelten el agua y se evapore.","minutes":6,"kind":"activo"},{"text":"Bajar el fuego a suave y verter el huevo batido sobre las setas.","minutes":1,"kind":"activo"},{"text":"Remover con espátula con movimientos lentos hasta que el huevo cuaje cremoso y aún jugoso.","minutes":2,"kind":"activo"},{"text":"Servir de inmediato con el perejil picado por encima.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL),
  ('huevos_037', 'Revuelto de gambas y ajetes', 'huevos', 'huevo', NULL, ARRAY['cena','segundo']::meal_role[], 'principal', NULL, NULL, 15, 'facil', 'all', 330, 24, 6, 22, 2, true, false, '{"huevo","marisco"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Gambas peladas","amount":180,"unit":"g"},{"name":"Ajetes","amount":150,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"}]'::jsonb, '{"Retirar la primera capa de ajetes y cortarlos en trozos de 3 cm.","Batir huevo en un bol hasta obtener una mezcla homogénea.","Calentar aceite de oliva en sartén a fuego medio-fuerte.","Saltear los ajetes en la sartén hasta que estén tiernos.","Añadir gambas peladas y saltear hasta que cambien de color.","Bajar el fuego a fuego suave y verter el huevo batido sobre las gambas y los ajetes.","Remover con espátula hasta que el huevo cuaje cremoso, sin que llegue a secarse.","Servir de inmediato en plato caliente."}', 'Revuelto de gambas y ajetes tiernos, rosado entre el huevo cuajado', NULL, '{}', NULL, NULL, NULL, '{}', NULL, ARRAY['marisco']::main_protein[], false, '[{"text":"Retirar la primera capa de {{Ajetes}} y cortarlos en trozos de 3 cm.","minutes":3,"kind":"prep"},{"text":"Batir {{Huevo}} en un bol hasta obtener una mezcla homogénea.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego medio-fuerte.","minutes":1,"kind":"activo"},{"text":"Saltear los ajetes en la sartén hasta que estén tiernos.","minutes":5,"kind":"activo"},{"text":"Añadir {{Gambas peladas}} y saltear hasta que cambien de color.","minutes":2,"kind":"activo"},{"text":"Bajar el fuego a fuego suave y verter el huevo batido sobre las gambas y los ajetes.","minutes":1,"kind":"activo"},{"text":"Remover con espátula hasta que el huevo cuaje cremoso, sin que llegue a secarse.","minutes":2,"kind":"activo"},{"text":"Servir de inmediato en plato caliente.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL),
  ('huevos_038', 'Huevos poché sobre espárragos con holandesa', 'huevos', 'huevo', NULL, ARRAY['cena','segundo']::meal_role[], 'principal', NULL, NULL, 25, 'normal', 'all', 480, 21, 5, 40, 2, true, false, '{"huevo","lactosa","sulfitos"}', '[{"name":"Huevo","amount":6,"unit":"ud"},{"name":"Espárragos verdes","amount":300,"unit":"g"},{"name":"Mantequilla","amount":60,"unit":"g"},{"name":"Zumo de limón","amount":15,"unit":"ml"},{"name":"Vinagre de vino","amount":15,"unit":"ml"}]'::jsonb, '{"Cortar la parte final dura del tallo de espárragos verdes.","Llevar a ebullición una olla con agua y sal a fuego fuerte.","Cocer los espárragos en el agua hirviendo hasta que estén tiernos pero firmes.","Escurrir los espárragos y reservar en caliente.","Fundir mantequilla en un cazo a fuego suave hasta que esté líquida; reservar tibia.","Separar 2 yemas de huevo y reservar las claras junto al resto de huevos enteros.","Batir las 2 yemas con zumo de limón al baño maría a fuego suave.","Remover sin parar hasta que las yemas espesen y blanqueen.","Incorporar la mantequilla tibia en hilo fino sin dejar de remover hasta obtener una salsa cremosa.","Salpimentar la salsa holandesa y reservar al baño maría para mantenerla tibia.","Llevar a ebullición suave una cazuela con agua y vinagre de vino a fuego medio.","Remover el agua para formar un remolino y cascar un huevo entero en el centro.","Cocer el huevo hasta que la clara esté cuajada y la yema líquida; retirar con espumadera.","Escurrir el huevo pochado sobre papel absorbente; repetir con los 3 huevos restantes.","Repartir los espárragos en 2 platos y colocar 2 huevos pochados encima de cada uno.","Napar con la salsa holandesa y servir de inmediato."}', 'Espárragos verdes con huevo escalfado y salsa holandesa recién montada', NULL, '{}', true, NULL, NULL, '{"verdura","lacteo"}', NULL, '{}'::main_protein[], false, '[{"text":"Cortar la parte final dura del tallo de {{Espárragos verdes}}.","minutes":2,"kind":"prep","part":"guarnicion"},{"text":"Llevar a ebullición una olla con agua y sal a fuego fuerte.","minutes":3,"kind":"activo","part":"guarnicion"},{"text":"Cocer los espárragos en el agua hirviendo hasta que estén tiernos pero firmes.","minutes":5,"kind":"pasivo","part":"guarnicion"},{"text":"Escurrir los espárragos y reservar en caliente.","minutes":1,"kind":"activo","part":"guarnicion"},{"text":"Fundir {{Mantequilla}} en un cazo a fuego suave hasta que esté líquida; reservar tibia.","minutes":3,"kind":"activo","part":"salsa"},{"text":"Separar 2 yemas de {{Huevo}} y reservar las claras junto al resto de huevos enteros.","minutes":2,"kind":"prep","part":"salsa"},{"text":"Batir las 2 yemas con {{Zumo de limón}} al baño maría a fuego suave.","minutes":1,"kind":"activo","part":"salsa"},{"text":"Remover sin parar hasta que las yemas espesen y blanqueen.","minutes":3,"kind":"activo","part":"salsa"},{"text":"Incorporar la mantequilla tibia en hilo fino sin dejar de remover hasta obtener una salsa cremosa.","minutes":2,"kind":"activo","part":"salsa"},{"text":"Salpimentar la salsa holandesa y reservar al baño maría para mantenerla tibia.","minutes":1,"kind":"activo","part":"salsa"},{"text":"Llevar a ebullición suave una cazuela con agua y {{Vinagre de vino}} a fuego medio.","minutes":3,"kind":"activo","part":"principal"},{"text":"Remover el agua para formar un remolino y cascar un huevo entero en el centro.","minutes":1,"kind":"activo","part":"principal"},{"text":"Cocer el huevo hasta que la clara esté cuajada y la yema líquida; retirar con espumadera.","minutes":3,"kind":"pasivo","part":"principal"},{"text":"Escurrir el huevo pochado sobre papel absorbente; repetir con los 3 huevos restantes.","minutes":1,"kind":"activo","part":"principal"},{"text":"Repartir los espárragos en 2 platos y colocar 2 huevos pochados encima de cada uno.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Napar con la salsa holandesa y servir de inmediato.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true, NULL, NULL, 'olla', NULL),
  ('huevos_039', 'Huevos fritos con jamón y virutas de parmesano', 'huevos', 'huevo', NULL, ARRAY['cena','segundo']::meal_role[], 'principal', NULL, NULL, 10, 'facil', 'all', 355, 26, 2, 27, 2, true, false, '{"huevo","lactosa"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Jamón serrano","amount":60,"unit":"g"},{"name":"Parmesano en virutas","amount":25,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"}]'::jsonb, '{"Calentar aceite de oliva en sartén a fuego fuerte hasta que esté bien caliente.","Cascar huevo de uno en uno y freír hasta que la puntilla esté crujiente y la clara cuajada.","Retirar los huevos fritos y escurrir sobre papel absorbente.","Repartir los huevos escurridos en 2 platos.","Colocar jamón serrano sobre los huevos.","Añadir parmesano en virutas por encima y servir de inmediato."}', 'Huevos fritos de puntilla crujiente y yema líquida con jamón serrano y virutas de parmesano', NULL, '{}', NULL, NULL, NULL, '{}', NULL, ARRAY['cerdo']::main_protein[], false, '[{"text":"Calentar {{Aceite de oliva}} en {{@Sartén}} a fuego fuerte hasta que esté bien caliente.","minutes":2,"kind":"activo"},{"text":"Cascar {{Huevo}} de uno en uno y freír hasta que la puntilla esté crujiente y la clara cuajada.","minutes":3,"kind":"activo"},{"text":"Retirar los huevos fritos y escurrir sobre papel absorbente.","minutes":1,"kind":"activo"},{"text":"Repartir los huevos escurridos en 2 platos.","minutes":1,"kind":"emplatado"},{"text":"Colocar {{Jamón serrano}} sobre los huevos.","minutes":1,"kind":"emplatado"},{"text":"Añadir {{Parmesano en virutas}} por encima y servir de inmediato.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, true, 'sarten', NULL),
  ('huevos_040', 'Huevos al plato con chorizo y pimientos', 'huevos', 'huevo', NULL, ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, 'horno', 30, 'facil', 'all', 398, 21, 16, 29, 2, true, false, '{"huevo"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Chorizo","amount":60,"unit":"g"},{"name":"Pimiento rojo","amount":100,"unit":"g"},{"name":"Pimiento verde","amount":80,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Tomate triturado","amount":150,"unit":"ml"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Precalentar el horno a 200 °C con calor arriba y abajo.","Picar cebolla y ajo fino.","Cortar pimiento rojo y pimiento verde en trozos pequeños.","Laminar chorizo en rodajas finas.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla, el ajo y los pimientos a fuego medio hasta que estén tiernos.","Añadir el chorizo y sofreír hasta que suelte su grasa.","Añadir tomate triturado y salpimentar al gusto.","Cocer a fuego medio hasta que la salsa espese ligeramente.","Repartir el sofrito entre 2 cazuelitas de barro.","Cascar huevo sobre el sofrito, 2 por cazuelita, sin romper la yema.","Hornear hasta que la clara cuaje y la yema quede jugosa.","Servir de inmediato en la misma cazuelita."}', 'Huevos horneados en cazuelita con chorizo, pimientos y tomate, burbujeantes y coloridos recién salidos del horno.', NULL, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, ARRAY['cerdo']::main_protein[], false, '[{"text":"Precalentar el horno a 200 °C con calor arriba y abajo.","minutes":10,"kind":"pasivo"},{"text":"Picar {{Cebolla}} y {{Ajo}} fino.","minutes":3,"kind":"prep"},{"text":"Cortar {{Pimiento rojo}} y {{Pimiento verde}} en trozos pequeños.","minutes":2,"kind":"prep"},{"text":"Laminar {{Chorizo}} en rodajas finas.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla, el ajo y los pimientos a fuego medio hasta que estén tiernos.","minutes":10,"kind":"pasivo"},{"text":"Añadir el chorizo y sofreír hasta que suelte su grasa.","minutes":2,"kind":"activo"},{"text":"Añadir {{Tomate triturado}} y salpimentar al gusto.","minutes":1,"kind":"activo"},{"text":"Cocer a fuego medio hasta que la salsa espese ligeramente.","minutes":5,"kind":"pasivo"},{"text":"Repartir el sofrito entre 2 cazuelitas de barro.","minutes":1,"kind":"activo"},{"text":"Cascar {{Huevo}} sobre el sofrito, 2 por cazuelita, sin romper la yema.","minutes":1,"kind":"activo"},{"text":"Hornear hasta que la clara cuaje y la yema quede jugosa.","minutes":9,"kind":"pasivo"},{"text":"Servir de inmediato en la misma cazuelita.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'horno', NULL),
  ('huevos_041', 'Tortilla de gambas', 'huevos', 'huevo', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 15, 'facil', 'all', 320, 28, 4, 22, 2, true, true, '{"huevo","marisco"}', '[{"name":"Huevo","amount":5,"unit":"ud"},{"name":"Gambas peladas","amount":150,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Perejil","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"}]'::jsonb, '{"Picar ajo muy fino.","Picar perejil muy fino.","Cascar huevo en un bol grande y batir hasta homogeneizar.","Calentar la mitad de aceite de oliva en sartén a fuego medio-alto.","Saltear el ajo picado con gambas peladas hasta que las gambas estén rosadas.","Retirar las gambas y el ajo de la sartén y dejar templar.","Añadir las gambas templadas, el ajo y el perejil picado al huevo batido y mezclar.","Calentar el aceite de oliva restante en la sartén a fuego medio.","Verter la mezcla en la sartén y cuajar 2 min, moviendo el centro con espátula.","Dar la vuelta a la tortilla con un plato y deslizarla de nuevo a la sartén.","Cuajar 1 min más o hasta alcanzar el punto de cuajado deseado.","Servir la tortilla cortada en porciones."}', 'Tortilla jugosa de gambas frescas salteadas con ajo y perejil, rosadas y visibles entre el huevo cuajado.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, ARRAY['marisco']::main_protein[], false, '[{"text":"Picar {{Ajo}} muy fino.","minutes":1,"kind":"prep"},{"text":"Picar {{Perejil}} muy fino.","minutes":1,"kind":"prep"},{"text":"Cascar {{Huevo}} en un bol grande y batir hasta homogeneizar.","minutes":1,"kind":"prep"},{"text":"Calentar la mitad de {{Aceite de oliva}} en {{@Sartén}} a fuego medio-alto.","minutes":1,"kind":"activo"},{"text":"Saltear el ajo picado con {{Gambas peladas}} hasta que las gambas estén rosadas.","minutes":2,"kind":"activo"},{"text":"Retirar las gambas y el ajo de la sartén y dejar templar.","minutes":2,"kind":"espera"},{"text":"Añadir las gambas templadas, el ajo y el perejil picado al huevo batido y mezclar.","minutes":1,"kind":"prep"},{"text":"Calentar el aceite de oliva restante en la sartén a fuego medio.","minutes":1,"kind":"activo"},{"text":"Verter la mezcla en la sartén y cuajar 2 min, moviendo el centro con espátula.","minutes":2,"kind":"activo"},{"text":"Dar la vuelta a la tortilla con un plato y deslizarla de nuevo a la sartén.","minutes":1,"kind":"activo"},{"text":"Cuajar 1 min más o hasta alcanzar el punto de cuajado deseado.","minutes":1,"kind":"activo"},{"text":"Servir la tortilla cortada en porciones.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, true, 'sarten', NULL)
