insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id, extra_proteins, freezable, steps_rich, estrella, occasion, kid_favourite, tecnica, cocina
) values
  ('huevos_042', 'Quiche lorraine', 'huevos', 'huevo', NULL, ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, 'horno', 55, 'normal', 'all', 520, 20, 32, 36, 2, true, true, '{"gluten","huevo","lactosa"}', '[{"name":"Masa quebrada","amount":200,"unit":"g"},{"name":"Panceta ahumada","amount":100,"unit":"g"},{"name":"Huevo","amount":3,"unit":"ud"},{"name":"Nata","amount":150,"unit":"ml"},{"name":"Queso gruyère rallado","amount":60,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 180 °C.","Extender masa quebrada en un molde, presionando bien los bordes.","Pinchar el fondo de la masa con un tenedor para que no suba al hornear.","Hornear la base en blanco a 180 °C durante 10 min hasta que empiece a dorarse ligeramente.","Cortar panceta ahumada en tiras finas.","Dorar la panceta en sartén sin aceite a fuego medio durante 3 min hasta que esté dorada.","Escurrir la panceta sobre papel absorbente y reservar.","Batir huevo con nata en un bol hasta integrar bien.","Repartir la panceta reservada sobre la base horneada.","Espolvorear la mitad de queso gruyère rallado sobre la panceta.","Verter la mezcla de huevo y nata sobre el relleno de manera uniforme.","Espolvorear el resto del queso gruyère rallado por encima.","Hornear a 180 °C durante 30 min hasta que el relleno esté cuajado y la superficie dorada.","Dejar reposar la quiche en el molde 5 min antes de cortar.","Cortar en porciones y servir."}', 'Quiche lorraine clásica, con corteza dorada y un relleno cremoso de bacon y queso gruyère.', NULL, '{}', NULL, NULL, NULL, '{"lacteo"}', NULL, ARRAY['cerdo']::main_protein[], true, '[{"text":"Precalentar el horno a 180 °C.","minutes":10,"kind":"pasivo"},{"text":"Extender {{Masa quebrada}} en un molde, presionando bien los bordes.","minutes":2,"kind":"prep"},{"text":"Pinchar el fondo de la masa con un tenedor para que no suba al hornear.","minutes":1,"kind":"prep"},{"text":"Hornear la base en blanco a 180 °C durante 10 min hasta que empiece a dorarse ligeramente.","minutes":10,"kind":"pasivo"},{"text":"Cortar {{Panceta ahumada}} en tiras finas.","minutes":2,"kind":"prep"},{"text":"Dorar la panceta en {{@Sartén}} sin aceite a fuego medio durante 3 min hasta que esté dorada.","minutes":3,"kind":"activo"},{"text":"Escurrir la panceta sobre papel absorbente y reservar.","minutes":1,"kind":"prep"},{"text":"Batir {{Huevo}} con {{Nata}} en un bol hasta integrar bien.","minutes":2,"kind":"prep"},{"text":"Repartir la panceta reservada sobre la base horneada.","minutes":1,"kind":"activo"},{"text":"Espolvorear la mitad de {{Queso gruyère rallado}} sobre la panceta.","minutes":1,"kind":"activo"},{"text":"Verter la mezcla de huevo y nata sobre el relleno de manera uniforme.","minutes":1,"kind":"activo"},{"text":"Espolvorear el resto del queso gruyère rallado por encima.","minutes":1,"kind":"activo"},{"text":"Hornear a 180 °C durante 30 min hasta que el relleno esté cuajado y la superficie dorada.","minutes":30,"kind":"pasivo"},{"text":"Dejar reposar la quiche en el molde 5 min antes de cortar.","minutes":5,"kind":"espera"},{"text":"Cortar en porciones y servir.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'horno', NULL),
  ('huevos_043', 'Quiche de puerros y queso de cabra', 'huevos', 'huevo', NULL, ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, 'horno', 55, 'normal', 'all', 460, 18, 32, 28, 2, true, true, '{"gluten","huevo","lactosa"}', '[{"name":"Masa quebrada","amount":200,"unit":"g"},{"name":"Puerro","amount":200,"unit":"g"},{"name":"Queso de cabra","amount":80,"unit":"g"},{"name":"Huevo","amount":3,"unit":"ud"},{"name":"Nata","amount":120,"unit":"ml"},{"name":"Aceite de oliva","amount":10,"unit":"ml"}]'::jsonb, '{"Precalentar el horno a 180 °C.","Lavar puerro y cortar en rodajas finas.","Extender masa quebrada en el molde, presionar los bordes y pinchar el fondo con un tenedor.","Hornear la base en blanco 10 min hasta que esté ligeramente dorada.","Calentar aceite de oliva en sartén a fuego suave.","Sofreír el puerro a fuego suave 10 min hasta que esté tierno y sin color.","Batir huevo con nata en un bol hasta obtener una mezcla homogénea.","Salpimentar la mezcla de huevo y nata al gusto.","Repartir el puerro pochado sobre la base horneada.","Desmenuzar queso de cabra por encima del puerro de forma uniforme.","Verter la mezcla de huevo y nata sobre el relleno hasta cubrir.","Hornear a 180 °C durante 30 min hasta que la superficie esté dorada y el relleno cuajado.","Reposar la quiche fuera del horno 5 min antes de cortar.","Servir en porciones directamente desde el molde."}', 'Quiche de puerros pochados y queso de cabra, con base crujiente y relleno verde y blanco por dentro.', NULL, '{}', NULL, NULL, NULL, '{"lacteo"}', NULL, '{}'::main_protein[], true, '[{"text":"Precalentar el horno a 180 °C.","minutes":10,"kind":"pasivo"},{"text":"Lavar {{Puerro}} y cortar en rodajas finas.","minutes":3,"kind":"prep"},{"text":"Extender {{Masa quebrada}} en el molde, presionar los bordes y pinchar el fondo con un tenedor.","minutes":3,"kind":"prep"},{"text":"Hornear la base en blanco 10 min hasta que esté ligeramente dorada.","minutes":10,"kind":"pasivo"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego suave.","minutes":1,"kind":"activo"},{"text":"Sofreír el puerro a fuego suave 10 min hasta que esté tierno y sin color.","minutes":10,"kind":"pasivo"},{"text":"Batir {{Huevo}} con {{Nata}} en un bol hasta obtener una mezcla homogénea.","minutes":2,"kind":"prep"},{"text":"Salpimentar la mezcla de huevo y nata al gusto.","minutes":1,"kind":"prep"},{"text":"Repartir el puerro pochado sobre la base horneada.","minutes":1,"kind":"activo"},{"text":"Desmenuzar {{Queso de cabra}} por encima del puerro de forma uniforme.","minutes":1,"kind":"activo"},{"text":"Verter la mezcla de huevo y nata sobre el relleno hasta cubrir.","minutes":1,"kind":"activo"},{"text":"Hornear a 180 °C durante 30 min hasta que la superficie esté dorada y el relleno cuajado.","minutes":30,"kind":"pasivo"},{"text":"Reposar la quiche fuera del horno 5 min antes de cortar.","minutes":5,"kind":"espera"},{"text":"Servir en porciones directamente desde el molde.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'horno', NULL),
  ('huevos_044', 'Huevos escalfados con salmón ahumado', 'huevos', 'huevo', NULL, ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 15, 'normal', 'all', 340, 20, 24, 18, 2, true, false, '{"huevo","pescado","gluten","sulfitos"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Salmón ahumado","amount":100,"unit":"g"},{"name":"Pan de masa madre","amount":120,"unit":"g"},{"name":"Vinagre","amount":10,"unit":"ml"},{"name":"Eneldo fresco","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"}]'::jsonb, '{"Cortar pan de masa madre en rebanadas de unos 2 cm de grosor.","Tostar las rebanadas en una tostadora o sartén a fuego medio hasta que estén doradas y crujientes.","Llevar agua abundante a ebullición en una cazuela ancha; añadir vinagre y bajar a fuego suave.","Cascar huevo de uno en uno en una taza pequeña antes de deslizarlos al agua.","Remover el agua con una cuchara para formar un remolino suave y deslizar el primer huevo al centro.","Repetir con los 3 huevos restantes, deslizando cada uno con cuidado al agua.","Escalfar los huevos 3 min hasta que la clara esté cuajada y la yema líquida.","Retirar los huevos con una espumadera y reservar sobre papel absorbente.","Picar eneldo fresco fino y reservar.","Repartir aceite de oliva sobre las tostadas.","Repartir salmón ahumado sobre las tostadas.","Colocar un huevo escalfado sobre cada tostada.","Espolvorear el eneldo picado por encima y servir de inmediato."}', 'Huevos escalfados de yema líquida sobre tostadas con salmón ahumado y eneldo, rosa contra el blanco del huevo.', NULL, '{}', true, NULL, NULL, '{}', NULL, ARRAY['pescado_azul']::main_protein[], false, '[{"text":"Cortar {{Pan de masa madre}} en rebanadas de unos 2 cm de grosor.","minutes":1,"kind":"prep"},{"text":"Tostar las rebanadas en una tostadora o sartén a fuego medio hasta que estén doradas y crujientes.","minutes":3,"kind":"activo"},{"text":"Llevar agua abundante a ebullición en una cazuela ancha; añadir {{Vinagre}} y bajar a fuego suave.","minutes":3,"kind":"activo"},{"text":"Cascar {{Huevo}} de uno en uno en una taza pequeña antes de deslizarlos al agua.","minutes":1,"kind":"prep"},{"text":"Remover el agua con una cuchara para formar un remolino suave y deslizar el primer huevo al centro.","minutes":1,"kind":"activo"},{"text":"Repetir con los 3 huevos restantes, deslizando cada uno con cuidado al agua.","minutes":1,"kind":"activo"},{"text":"Escalfar los huevos 3 min hasta que la clara esté cuajada y la yema líquida.","minutes":3,"kind":"pasivo"},{"text":"Retirar los huevos con una espumadera y reservar sobre papel absorbente.","minutes":1,"kind":"activo"},{"text":"Picar {{Eneldo fresco}} fino y reservar.","minutes":1,"kind":"prep"},{"text":"Repartir {{Aceite de oliva|chorrito}} sobre las tostadas.","minutes":1,"kind":"emplatado"},{"text":"Repartir {{Salmón ahumado}} sobre las tostadas.","minutes":1,"kind":"emplatado"},{"text":"Colocar un huevo escalfado sobre cada tostada.","minutes":1,"kind":"emplatado"},{"text":"Espolvorear el eneldo picado por encima y servir de inmediato.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL),
  ('huevos_045', 'Huevos rellenos de atún gratinados', 'huevos', 'huevo', NULL, ARRAY['primero','cena']::meal_role[], 'principal', NULL, 'horno', 30, 'facil', 'all', 360, 22, 10, 25, 2, true, false, '{"huevo","pescado","lactosa","gluten"}', '[{"name":"Huevo","amount":6,"unit":"ud"},{"name":"Atún en conserva","amount":160,"unit":"g"},{"name":"Mantequilla","amount":15,"unit":"g"},{"name":"Harina","amount":15,"unit":"g"},{"name":"Leche","amount":150,"unit":"ml"},{"name":"Queso rallado","amount":40,"unit":"g"}]'::jsonb, '{"Cocer huevo en agua abundante durante 10 min desde que rompa a hervir.","Retirar los huevos y sumergirlos en agua fría hasta que estén templados.","Pelar los huevos y cortarlos por la mitad a lo largo.","Retirar las yemas con cuidado y reservarlas en un bol; reservar las claras en una fuente de horno.","Escurrir atún en conserva y añadirlo al bol con las yemas.","Machacar las yemas con el atún escurrido hasta obtener una pasta homogénea.","Rellenar cada clara con la pasta de yema y atún y colocarlas en la fuente de horno.","Fundir mantequilla en un cazo a fuego medio.","Añadir harina de golpe y remover sin parar durante 1 min hasta que se forme una pasta dorada.","Añadir leche poco a poco sin dejar de remover hasta obtener una bechamel fina y sin grumos.","Cubrir los huevos rellenos con la bechamel y espolvorear queso rallado por encima.","Gratinar en el horno a 220 °C durante 8 min hasta que la superficie esté dorada.","Servir templado directamente desde la fuente."}', 'Huevos rellenos de atún cubiertos de bechamel y gratinados hasta dorar, clásico de aperitivo en versión de cena.', NULL, '{}', NULL, NULL, NULL, '{"lacteo"}', NULL, ARRAY['pescado_azul']::main_protein[], false, '[{"text":"Cocer {{Huevo}} en agua abundante durante 10 min desde que rompa a hervir.","minutes":10,"kind":"pasivo"},{"text":"Retirar los huevos y sumergirlos en agua fría hasta que estén templados.","minutes":5,"kind":"espera"},{"text":"Pelar los huevos y cortarlos por la mitad a lo largo.","minutes":3,"kind":"prep"},{"text":"Retirar las yemas con cuidado y reservarlas en un bol; reservar las claras en una fuente de horno.","minutes":2,"kind":"prep"},{"text":"Escurrir {{Atún en conserva}} y añadirlo al bol con las yemas.","minutes":1,"kind":"prep"},{"text":"Machacar las yemas con el atún escurrido hasta obtener una pasta homogénea.","minutes":2,"kind":"prep"},{"text":"Rellenar cada clara con la pasta de yema y atún y colocarlas en la fuente de horno.","minutes":3,"kind":"activo"},{"text":"Fundir {{Mantequilla}} en un cazo a fuego medio.","minutes":1,"kind":"activo"},{"text":"Añadir {{Harina}} de golpe y remover sin parar durante 1 min hasta que se forme una pasta dorada.","minutes":1,"kind":"activo"},{"text":"Añadir {{Leche}} poco a poco sin dejar de remover hasta obtener una bechamel fina y sin grumos.","minutes":4,"kind":"activo"},{"text":"Cubrir los huevos rellenos con la bechamel y espolvorear {{Queso rallado}} por encima.","minutes":1,"kind":"activo"},{"text":"Gratinar en el horno a 220 °C durante 8 min hasta que la superficie esté dorada.","minutes":8,"kind":"pasivo"},{"text":"Servir templado directamente desde la fuente.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'horno', NULL),
  ('huevos_046', 'Tortilla de bacalao', 'huevos', 'huevo', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 25, 'normal', 'all', 310, 28, 4, 19, 2, true, true, '{"huevo","pescado"}', '[{"name":"Huevo","amount":5,"unit":"ud"},{"name":"Bacalao desalado desmigado","amount":200,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"}]'::jsonb, '{"Cortar cebolla en juliana fina.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla a fuego medio hasta que esté tierna y transparente.","Batir huevo en un bol grande hasta que estén bien integrados.","Añadir bacalao desalado desmigado a la sartén y saltear a fuego medio hasta que esté cocido.","Retirar la sartén del fuego y dejar templar el bacalao con la cebolla.","Incorporar el bacalao templado y la cebolla al huevo batido y remover hasta mezclar.","Calentar un chorrito de aceite de oliva en la sartén limpia a fuego medio.","Verter la mezcla en la sartén y cuajar a fuego medio hasta que los bordes estén firmes.","Dar la vuelta a la tortilla con ayuda de un plato y deslizarla de nuevo a la sartén.","Cuajar por el segundo lado a fuego medio hasta alcanzar el punto deseado.","Retirar la tortilla de la sartén y dejar reposar antes de servir.","Servir la tortilla entera o cortada en porciones."}', 'Tortilla jugosa de bacalao desmigado y cebolla pochada, con textura melosa entre el huevo.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, ARRAY['pescado_blanco']::main_protein[], false, '[{"text":"Cortar {{Cebolla}} en juliana fina.","minutes":3,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla a fuego medio hasta que esté tierna y transparente.","minutes":10,"kind":"pasivo"},{"text":"Batir {{Huevo}} en un bol grande hasta que estén bien integrados.","minutes":2,"kind":"paralelo","during":2},{"text":"Añadir {{Bacalao desalado desmigado}} a la sartén y 