  ('huevos_047', 'Huevos cocotte con nata y champiñones', 'huevos', 'huevo', NULL, ARRAY['cena']::meal_role[], 'principal', NULL, 'horno', 25, 'normal', 'all', 320, 15, 5, 27, 2, true, false, '{"huevo","lactosa"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Champiñones","amount":150,"unit":"g"},{"name":"Nata","amount":100,"unit":"ml"},{"name":"Mantequilla","amount":15,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 180 °C.","Limpiar y laminar champiñones.","Picar ajo fino.","Picar perejil fino y reservar.","Calentar sartén a fuego medio y fundir mantequilla.","Sofreír el ajo picado en la mantequilla fundida hasta que empiece a dorarse.","Añadir los champiñones laminados y saltear a fuego medio hasta que se doren y suelten el agua.","Salpimentar los champiñones y retirar del fuego.","Repartir los champiñones entre 2 cazuelitas individuales.","Verter la mitad de nata sobre los champiñones de cada cazuelita.","Cascar huevo: 2 huevos en cada cazuelita, sobre la nata.","Repartir el resto de la nata alrededor de las yemas en cada cazuelita.","Colocar las cazuelitas en una bandeja con agua caliente hasta la mitad para el baño maría.","Hornear a 180 °C durante 12 min hasta que la clara cuaje y la yema quede cremosa.","Espolvorear el perejil picado sobre cada cazuelita y servir de inmediato."}', 'Huevos cocidos en su propia cazuelita individual con nata y champiñones salteados.', NULL, '{}', NULL, NULL, NULL, '{"lacteo","seta"}', NULL, '{}'::main_protein[], false, '[{"text":"Precalentar el horno a 180 °C.","minutes":10,"kind":"pasivo"},{"text":"Limpiar y laminar {{Champiñones}}.","minutes":3,"kind":"prep"},{"text":"Picar {{Ajo}} fino.","minutes":1,"kind":"prep"},{"text":"Picar {{Perejil}} fino y reservar.","minutes":1,"kind":"prep"},{"text":"Calentar {{@Sartén}} a fuego medio y fundir {{Mantequilla}}.","minutes":1,"kind":"activo"},{"text":"Sofreír el ajo picado en la mantequilla fundida hasta que empiece a dorarse.","minutes":1,"kind":"activo"},{"text":"Añadir los champiñones laminados y saltear a fuego medio hasta que se doren y suelten el agua.","minutes":6,"kind":"activo"},{"text":"Salpimentar los champiñones y retirar del fuego.","minutes":1,"kind":"activo"},{"text":"Repartir los champiñones entre 2 cazuelitas individuales.","minutes":1,"kind":"prep"},{"text":"Verter la mitad de {{Nata}} sobre los champiñones de cada cazuelita.","minutes":1,"kind":"prep"},{"text":"Cascar {{Huevo}}: 2 huevos en cada cazuelita, sobre la nata.","minutes":1,"kind":"prep"},{"text":"Repartir el resto de la nata alrededor de las yemas en cada cazuelita.","minutes":1,"kind":"prep"},{"text":"Colocar las cazuelitas en una bandeja con agua caliente hasta la mitad para el baño maría.","minutes":1,"kind":"prep"},{"text":"Hornear a 180 °C durante 12 min hasta que la clara cuaje y la yema quede cremosa.","minutes":12,"kind":"pasivo"},{"text":"Espolvorear el perejil picado sobre cada cazuelita y servir de inmediato.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'horno', NULL),
  ('huevos_048', 'Huevos mimosa', 'huevos', 'huevo', NULL, ARRAY['primero','cena']::meal_role[], 'principal', NULL, NULL, 20, 'facil', 'all', 240, 15, 3, 19, 2, true, false, '{"huevo","mostaza"}', '[{"name":"Huevo","amount":6,"unit":"ud"},{"name":"Mayonesa","amount":40,"unit":"g"},{"name":"Mostaza","amount":5,"unit":"g"},{"name":"Cebollino","amount":5,"unit":"g"},{"name":"Pimentón dulce","amount":2,"unit":"g"}]'::jsonb, '{"Llevar agua a ebullición en un cazo a fuego fuerte.","Introducir huevo con cuidado y cocer 10 min desde que rompa a hervir.","Escurrir los huevos y sumergir en agua fría hasta que estén templados.","Pelar los huevos con cuidado y cortar cada uno por la mitad a lo largo.","Separar las yemas de las claras y reservar las claras en una fuente.","Machacar las yemas con un tenedor en un bol hasta obtener un granulado fino.","Añadir mayonesa y mostaza a las yemas y mezclar hasta obtener una crema homogénea.","Picar cebollino muy fino.","Rellenar cada clara con la crema de yemas formando un montoncito generoso.","Espolvorear el cebollino picado y pimentón dulce sobre cada huevo.","Refrigerar los huevos rellenos hasta el momento de servir.","Servir los huevos mimosa bien fríos en la fuente."}', 'Huevos rellenos de una crema de yema, mayonesa y mostaza, con la yema rallada como nieve sobre la clara.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Llevar agua a ebullición en un cazo a fuego fuerte.","minutes":3,"kind":"activo"},{"text":"Introducir {{Huevo}} con cuidado y cocer 10 min desde que rompa a hervir.","minutes":10,"kind":"pasivo"},{"text":"Escurrir los huevos y sumergir en agua fría hasta que estén templados.","minutes":5,"kind":"espera"},{"text":"Pelar los huevos con cuidado y cortar cada uno por la mitad a lo largo.","minutes":2,"kind":"prep"},{"text":"Separar las yemas de las claras y reservar las claras en una fuente.","minutes":1,"kind":"prep"},{"text":"Machacar las yemas con un tenedor en un bol hasta obtener un granulado fino.","minutes":1,"kind":"prep"},{"text":"Añadir {{Mayonesa}} y {{Mostaza}} a las yemas y mezclar hasta obtener una crema homogénea.","minutes":1,"kind":"activo"},{"text":"Picar {{Cebollino}} muy fino.","minutes":1,"kind":"prep"},{"text":"Rellenar cada clara con la crema de yemas formando un montoncito generoso.","minutes":2,"kind":"activo"},{"text":"Espolvorear el cebollino picado y {{Pimentón dulce|pizca}} sobre cada huevo.","minutes":1,"kind":"activo"},{"text":"Refrigerar los huevos rellenos hasta el momento de servir.","minutes":15,"kind":"espera"},{"text":"Servir los huevos mimosa bien fríos en la fuente.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'olla', NULL),
  ('huevos_049', 'Soufflé de queso', 'huevos', 'huevo', NULL, ARRAY['cena']::meal_role[], 'principal', NULL, 'horno', 45, 'elaborada', 'all', 400, 19, 16, 28, 2, true, false, '{"huevo","lactosa","gluten"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Mantequilla","amount":30,"unit":"g"},{"name":"Harina","amount":30,"unit":"g"},{"name":"Leche","amount":250,"unit":"ml"},{"name":"Queso gruyère rallado","amount":100,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 190 °C.","Untar 2 moldes individuales con mantequilla.","Separar las claras de las yemas de huevo en 2 boles distintos.","Fundir la mantequilla restante en un cazo a fuego medio.","Añadir harina de golpe y remover sin parar durante 1 min hasta que la mezcla se despegue del cazo.","Incorporar leche poco a poco sin dejar de remover a fuego medio.","Cocer hasta que la bechamel espese y se despegue de las paredes; retirar del fuego.","Añadir las yemas una a una a la bechamel templada, batiendo bien tras cada adición.","Añadir queso gruyère rallado y mezclar hasta integrar por completo.","Montar las claras en un bol limpio a punto de nieve firme.","Incorporar un tercio de las claras a la mezcla de bechamel con movimientos envolventes para aligerarla.","Añadir el resto de las claras en 2 tandas con movimientos envolventes hasta integrar sin bajar la espuma.","Repartir la mezcla en los moldes hasta ¾ de su capacidad.","Hornear 20 min sin abrir el horno hasta que los soufflés suban y estén dorados.","Servir de inmediato, recién sacados del horno."}', 'Soufflé de queso que sube dorado y esponjoso en el horno, para servir al momento.', NULL, '{}', NULL, NULL, NULL, '{"lacteo"}', NULL, '{}'::main_protein[], false, '[{"text":"Precalentar el horno a 190 °C.","minutes":10,"kind":"pasivo"},{"text":"Untar 2 moldes individuales con {{Mantequilla}}.","minutes":2,"kind":"prep"},{"text":"Separar las claras de las yemas de {{Huevo}} en 2 boles distintos.","minutes":2,"kind":"prep"},{"text":"Fundir la mantequilla restante en un cazo a fuego medio.","minutes":1,"kind":"activo"},{"text":"Añadir {{Harina}} de golpe y remover sin parar durante 1 min hasta que la mezcla se despegue del cazo.","minutes":1,"kind":"activo"},{"text":"Incorporar {{Leche}} poco a poco sin dejar de remover a fuego medio.","minutes":2,"kind":"activo"},{"text":"Cocer hasta que la bechamel espese y se despegue de las paredes; retirar del fuego.","minutes":2,"kind":"activo"},{"text":"Añadir las yemas una a una a la bechamel templada, batiendo bien tras cada adición.","minutes":2,"kind":"activo"},{"text":"Añadir {{Queso gruyère rallado}} y mezclar hasta integrar por completo.","minutes":1,"kind":"activo"},{"text":"Montar las claras en un bol limpio a punto de nieve firme.","minutes":3,"kind":"activo"},{"text":"Incorporar un tercio de las claras a la mezcla de bechamel con movimientos envolventes para aligerarla.","minutes":1,"kind":"activo"},{"text":"Añadir el resto de las claras en 2 tandas con movimientos envolventes hasta integrar sin bajar la espuma.","minutes":2,"kind":"activo"},{"text":"Repartir la mezcla en los moldes hasta ¾ de su capacidad.","minutes":1,"kind":"activo"},{"text":"Hornear 20 min sin abrir el horno hasta que los soufflés suban y estén dorados.","minutes":20,"kind":"pasivo"},{"text":"Servir de inmediato, recién sacados del horno.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'horno', NULL),
  ('huevos_050', 'Huevos con jamón y bechamel gratinados', 'huevos', 'huevo', NULL, ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, 'horno', 35, 'normal', 'all', 430, 25, 17, 29, 2, true, true, '{"huevo","lactosa","gluten"}', '[{"name":"Huevo","amount":6,"unit":"ud"},{"name":"Jamón cocido","amount":100,"unit":"g"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Harina","amount":20,"unit":"g"},{"name":"Leche","amount":300,"unit":"ml"},{"name":"Queso rallado","amount":50,"unit":"g"}]'::jsonb, '{"Llevar a ebullición agua en un cazo a fuego fuerte.","Cocer huevo desde que rompa a hervir, a fuego medio, durante 10 min.","Precalentar el horno a 200 °C con función gratinador.","Retirar los huevos del cazo y sumergirlos en agua fría hasta que estén templados.","Pelar los huevos y cortar cada uno por la mitad a lo largo.","Cortar jamón cocido en tiras.","Fundir mantequilla en un cazo a fuego medio.","Añadir harina de golpe y remover sin parar durante 1 min hasta obtener una pasta homogénea.","Añadir leche poco a poco sin dejar de remover a fuego medio hasta que la bechamel esté fina.","Salpimentar la bechamel y retirar el cazo del fuego.","Colocar los huevos con el corte hacia arriba en una fuente de horno y distribuir el jamón cocido entre ellos.","Cubrir con la bechamel caliente hasta que los huevos queden completamente cubiertos.","Espolvorear queso rallado de manera uniforme por toda la superficie.","Gratinar en el horno a 200 °C durante 10 min hasta que la superficie esté dorada y burbujeante.","Servir caliente directamente de la fuente."}', 'Huevos cocidos con jamón cubiertos de bechamel y gratinados, con el huevo escondido debajo del dorado.', NULL, '{}', NULL, NULL, NULL, '{"lacteo"}', NULL, ARRAY['cerdo']::main_protein[], false, '[{"text":"Llevar a ebullición agua en un cazo a fuego fuerte.","minutes":3,"kind":"activo"},{"text":"Cocer {{Huevo}} desde que rompa a hervir, a fuego medio, durante 10 min.","minutes":10,"kind":"pasivo"},{"text":"Precalentar el horno a 200 °C con función gratinador.","minutes":5,"kind":"paralelo","during":1},{"text":"Retirar los huevos del cazo y sumergirlos en agua fría hasta que estén templados.","minutes":3,"kind":"espera"},{"text":"Pelar los huevos y cortar cada uno por la mitad a lo largo.","minutes":2,"kind":"prep"},{"text":"Cortar {{Jamón cocido}} en tiras.","minutes":1,"kind":"prep"},{"text":"Fundir {{Mantequilla}} en un cazo a fuego medio.","minutes":1,"kind":"activo"},{"text":"Añadir {{Harina}} de golpe y remover sin parar durante 1 min hasta obtener una pasta homogénea.","minutes":1,"kind":"activo"},{"text":"Añadir {{Leche}} poco a poco sin dejar de remover a fuego medio hasta que la bechamel esté fina.","minutes":5,"kind":"activo"},{"text":"Salpimentar la bechamel y retirar el cazo del fuego.","minutes":1,"kind":"activo"},{"text":"Colocar los huevos con el corte hacia arriba en una fuente de horno y distribuir el jamón cocido entre ellos.","minutes":2,"kind":"prep"},{"text":"Cubrir con la bechamel caliente hasta que los huevos queden completamente cubiertos.","minutes":1,"kind":"activo"},{"text":"Espolvorear {{Queso rallado}} de manera uniforme por toda la superficie.","minutes":1,"kind":"activo"},{"text":"Gratinar en el horno a 200 °C durante 10 min hasta que la superficie esté dorada y burbujeante.","minutes":10,"kind":"pasivo"},{"text":"Servir caliente directamente de la fuente.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'horno', NULL),
  ('huevos_051', 'Tortilla paisana', 'huevos', 'huevo', NULL, ARRAY['segundo','cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'facil', 'all', 410, 20, 28, 24, 2, true, true, '{"huevo"}', '[{"name":"Patata","amount":200,"unit":"g"},{"name":"Huevo","amount":5,"unit":"ud"},{"name":"Judías verdes","amount":60,"unit":"g"},{"name":"Guisantes","amount":40,"unit":"g"},{"name":"Pimiento rojo","amount":50,"unit":"g"},{"name":"Jamón cocido","amount":50,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Aceite de oliva","amount":40,"unit":"ml"}]'::jsonb, '{"Pelar patata y cortar en dados pequeños.","Cortar cebolla en dados pequeños.","Cortar pimiento rojo en dados pequeños.","Trocear judías verdes en piezas de unos 2 cm.","Llevar a ebullición agua con sal en un cazo a fuego fuerte.","Cocer las judías verdes troceadas y guisantes 5 min hasta que estén tiernos.","Escurrir las judías verdes y los guisantes y reservar.","Cortar jamón cocido en dados pequeños.","Calentar aceite de oliva en sartén a fuego medio.","Añadir la patata y la cebolla y confitar a fuego suave 12 min hasta que estén tiernos.","Añadir el pimiento rojo y sofreír a fuego medio 3 min hasta que esté tierno.","Añadir las judías verdes, los guisantes y el jamón cocido y sofreír 2 min.","Escurrir el conjunto con un colador y reservar el aceite sobrante.","Batir huevo en un bol grande hasta que estén homogéneos.","Incorporar la patata, la cebolla, el pimiento, las judías, los guisantes y el jamón cocido a los huevos batidos.","Dejar reposar la mezcla 2 min para que los huevos impregnen bien el conjunto.","Calentar un chorrito del aceite reservado en la sartén a fuego medio.","Verter la mezcla en la sartén y cuajar a fuego medio 3 min hasta que los bordes estén firmes.","Dar la vuelta a la tortilla con ayuda de un plato y devolverla a la sartén.","Cuajar el segundo lado a fuego medio 2 min hasta alcanzar el punto deseado.","Servir la tortilla en un plato, entera o en porciones."}', 'Tortilla cuajada con patata, verduras y jamón, colorida y contundente.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, ARRAY['cerdo']::main_protein[], false, '[{"text":"Pelar {{Patata}} y cortar en dados pequeños.","minutes":3,"kind":"prep"},{"text":"Cortar {{Cebolla}} en dados pequeños.","minutes":2,"kind":"prep"},{"text":"Cortar {{Pimiento rojo}} en dados pequeños.","minutes":2,"kind":"prep"},{"text":"Trocear {{Judías verdes}} en piezas de unos 2 cm.","minutes":2,"kind":"prep"},{"text":"Llevar a ebullición agua con sal en un cazo a fuego fuerte.","minutes":3,"kind":"activo"},{"text":"Cocer las judías verdes troceadas y {{Guisantes}} 5 min hasta que estén tiernos.","minutes":5,"kind":"pasivo"},{"text":"Escurrir las judías verdes y los guisantes y reservar.","minutes":1,"kind":"prep"},{"text":"Cortar {{Jamón cocido}} en dados pequeños.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva}} en {{@Sartén}} a fuego medio.","minutes":1,"kind":"activo"},{"text":"Añadir la patata y la cebolla y confitar a fuego suave 12 min hasta que estén tiernos.","minutes":12,"kind":"pasivo"},{"text":"Añadir el pimiento rojo y sofreír a fuego medio 3 min hasta que esté tierno.","minutes":3,"kind":"activo"},{"text":"Añadir las judías verdes, los guisantes y el jamón cocido y sofreír 2 min.","minutes":2,"kind":"activo"},{"text":"Escurrir el conjunto con un colador y reservar el aceite sobrante.","minutes":1,"kind":"prep"},{"text":"Batir {{Huevo}} en un bol grande hasta que estén homogéneos.","minutes":2,"kind":"prep"},{"text":"Incorporar la patata, la cebolla, el pimiento, las judías, los guisantes y el jamón cocido a los huevos batidos.","minutes":1,"kind":"prep"},{"text":"Dejar reposar la mezcla 2 min para que los huevos impregnen bien el conjunto.","minutes":2,"kind":"espera"},{"text":"Calentar un chorrito del aceite reservado en la sartén a fuego medio.","minutes":1,"kind":"activo"},{"text":"Verter la mezcla en la sartén y cuajar a fuego medio 3 min hasta que los bordes estén firmes.","minutes":3,"kind":"activo"},{"text":"Dar la vuelta a la tortilla con ayuda de un plato y devolverla a la sartén.","minutes":1,"kind":"activo"},{"text":"Cuajar el segundo lado a fuego medio 2 min hasta alcanzar el punto deseado.","minutes":2,"kind":"activo"},{"text":"Servir la tortilla en un plato, entera o en porciones.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, true, 'olla', NULL)
