  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id, extra_proteins, freezable, steps_rich, estrella, occasion, kid_favourite, tecnica, cocina
) values
  ('huevos_052', 'Huevos turcos (cilbir) con yogur y mantequilla de pimentón', 'huevos', 'huevo', NULL, ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 20, 'normal', 'all', 380, 17, 22, 25, 2, false, false, '{"huevo","lactosa","gluten","sulfitos"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Yogur griego","amount":200,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Mantequilla","amount":30,"unit":"g"},{"name":"Pimentón dulce","amount":4,"unit":"g"},{"name":"Vinagre","amount":10,"unit":"ml"},{"name":"Pan","amount":100,"unit":"g"}]'::jsonb, '{"Rallar ajo muy fino sobre un bol pequeño.","Añadir yogur griego al bol con el ajo rallado y mezclar hasta integrar.","Salpimentar el yogur con ajo al gusto y remover.","Repartir el yogur en 2 platos hondos y reservar.","Tostar pan en sartén a fuego medio hasta que esté crujiente por ambos lados.","Calentar agua en una cazuela con vinagre hasta que rompa a hervir suave.","Escalfar huevo de 2 en 2: cascar cada uno en un cuenco y deslizar al agua con cuidado.","Cocer los huevos 3 min hasta que la clara esté cuajada y la yema líquida.","Retirar los huevos con espumadera y escurrir sobre papel de cocina.","Fundir mantequilla en un cazo pequeño a fuego suave hasta que empiece a dorarse.","Retirar el cazo del fuego e incorporar pimentón dulce, removiendo rápido para que no se queme.","Colocar los huevos escalfados sobre el yogur de cada plato.","Rociar con la mantequilla de pimentón y servir de inmediato con el pan tostado."}', 'Huevos escalfados turcos sobre yogur de ajo, con yogur blanco y mantequilla de pimentón roja y brillante encima.', NULL, '{}', NULL, NULL, NULL, '{"lacteo"}', NULL, '{}'::main_protein[], false, '[{"text":"Rallar {{Ajo}} muy fino sobre un bol pequeño.","minutes":2,"kind":"prep"},{"text":"Añadir {{Yogur griego}} al bol con el ajo rallado y mezclar hasta integrar.","minutes":1,"kind":"prep"},{"text":"Salpimentar el yogur con ajo al gusto y remover.","minutes":1,"kind":"prep"},{"text":"Repartir el yogur en 2 platos hondos y reservar.","minutes":1,"kind":"prep"},{"text":"Tostar {{Pan}} en {{@Sartén}} a fuego medio hasta que esté crujiente por ambos lados.","minutes":3,"kind":"activo"},{"text":"Calentar agua en una cazuela con {{Vinagre}} hasta que rompa a hervir suave.","minutes":3,"kind":"activo"},{"text":"Escalfar {{Huevo}} de 2 en 2: cascar cada uno en un cuenco y deslizar al agua con cuidado.","minutes":1,"kind":"activo"},{"text":"Cocer los huevos 3 min hasta que la clara esté cuajada y la yema líquida.","minutes":3,"kind":"pasivo"},{"text":"Retirar los huevos con espumadera y escurrir sobre papel de cocina.","minutes":1,"kind":"activo"},{"text":"Fundir {{Mantequilla}} en un cazo pequeño a fuego suave hasta que empiece a dorarse.","minutes":2,"kind":"activo"},{"text":"Retirar el cazo del fuego e incorporar {{Pimentón dulce}}, removiendo rápido para que no se queme.","minutes":1,"kind":"activo"},{"text":"Colocar los huevos escalfados sobre el yogur de cada plato.","minutes":1,"kind":"emplatado"},{"text":"Rociar con la mantequilla de pimentón y servir de inmediato con el pan tostado.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL),
  ('huevos_053', 'Huevos poché sobre aguacate y tostada', 'huevos', 'huevo', NULL, ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 380, 16, 30, 22, 2, true, false, '{"huevo","gluten","sulfitos"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Aguacate","amount":200,"unit":"g"},{"name":"Pan de masa madre","amount":120,"unit":"g"},{"name":"Zumo de limón","amount":10,"unit":"ml"},{"name":"Vinagre","amount":10,"unit":"ml"},{"name":"Aceite de oliva","amount":10,"unit":"ml"}]'::jsonb, '{"Cortar pan de masa madre en rebanadas de grosor medio.","Tostar las rebanadas en el tostador hasta que estén doradas.","Cortar aguacate por la mitad, retirar el hueso y extraer la pulpa con una cuchara.","Machacar la pulpa de aguacate en un bol con zumo de limón hasta obtener una crema con textura.","Llevar a ebullición agua en una cazuela ancha con vinagre.","Reducir el fuego hasta mantener un hervor muy suave.","Cascar huevo de uno en uno en una taza y deslizarlo con cuidado al agua girando para formar un remolino.","Escalfar los huevos hasta que la clara esté cuajada y la yema líquida.","Retirar los huevos con una espumadera y escurrir sobre papel absorbente.","Untar las tostadas con la crema de aguacate.","Colocar 2 huevos escalfados sobre cada tostada.","Rociar con aceite de oliva y servir de inmediato."}', 'Tostada de aguacate cremoso coronada con huevo escalfado de yema rota, verde y jugosa.', NULL, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], false, '[{"text":"Cortar {{Pan de masa madre}} en rebanadas de grosor medio.","minutes":1,"kind":"prep"},{"text":"Tostar las rebanadas en el tostador hasta que estén doradas.","minutes":3,"kind":"pasivo"},{"text":"Cortar {{Aguacate}} por la mitad, retirar el hueso y extraer la pulpa con una cuchara.","minutes":1,"kind":"paralelo","during":1},{"text":"Machacar la pulpa de aguacate en un bol con {{Zumo de limón}} hasta obtener una crema con textura.","minutes":1,"kind":"paralelo","during":1},{"text":"Llevar a ebullición agua en una cazuela ancha con {{Vinagre}}.","minutes":2,"kind":"activo"},{"text":"Reducir el fuego hasta mantener un hervor muy suave.","minutes":1,"kind":"activo"},{"text":"Cascar {{Huevo}} de uno en uno en una taza y deslizarlo con cuidado al agua girando para formar un remolino.","minutes":2,"kind":"activo"},{"text":"Escalfar los huevos hasta que la clara esté cuajada y la yema líquida.","minutes":3,"kind":"pasivo"},{"text":"Retirar los huevos con una espumadera y escurrir sobre papel absorbente.","minutes":1,"kind":"activo"},{"text":"Untar las tostadas con la crema de aguacate.","minutes":1,"kind":"emplatado"},{"text":"Colocar 2 huevos escalfados sobre cada tostada.","minutes":1,"kind":"emplatado"},{"text":"Rociar con {{Aceite de oliva|chorrito}} y servir de inmediato.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'olla', NULL),
  ('huevos_054', 'Tortilla francesa rellena de jamón y queso', 'huevos', 'huevo', NULL, ARRAY['cena']::meal_role[], 'principal', NULL, NULL, 10, 'facil', 'all', 350, 24, 3, 27, 2, true, false, '{"huevo","lactosa"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Jamón cocido","amount":60,"unit":"g"},{"name":"Queso en lonchas","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"}]'::jsonb, '{"Cortar jamón cocido en tiras o dados pequeños.","Batir huevo en un bol hasta integrar yemas y claras.","Salpimentar el huevo batido al gusto y remover.","Calentar aceite de oliva en sartén a fuego medio.","Verter la mitad del huevo batido en la sartén y dejar cuajar los bordes.","Distribuir la mitad del jamón cocido y queso en lonchas sobre una mitad de la tortilla.","Doblar la mitad libre de la tortilla sobre el relleno con la espátula.","Cocer a fuego suave hasta que el queso empiece a fundirse.","Retirar la tortilla y reservar en un plato caliente.","Repetir los pasos 4 a 9 con el resto del huevo batido, el jamón cocido y el queso en lonchas.","Servir las 2 tortillas de inmediato mientras el queso está fundido."}', 'Tortilla francesa rellena de jamón y queso, que se derrama al doblarla.', NULL, '{}', NULL, NULL, NULL, '{"lacteo"}', NULL, ARRAY['cerdo']::main_protein[], false, '[{"text":"Cortar {{Jamón cocido}} en tiras o dados pequeños.","minutes":1,"kind":"prep"},{"text":"Batir {{Huevo}} en un bol hasta integrar yemas y claras.","minutes":1,"kind":"prep"},{"text":"Salpimentar el huevo batido al gusto y remover.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego medio.","minutes":1,"kind":"activo"},{"text":"Verter la mitad del huevo batido en la sartén y dejar cuajar los bordes.","minutes":1,"kind":"activo"},{"text":"Distribuir la mitad del jamón cocido y {{Queso en lonchas}} sobre una mitad de la tortilla.","minutes":1,"kind":"activo"},{"text":"Doblar la mitad libre de la tortilla sobre el relleno con la espátula.","minutes":1,"kind":"activo"},{"text":"Cocer a fuego suave hasta que el queso empiece a fundirse.","minutes":2,"kind":"pasivo"},{"text":"Retirar la tortilla y reservar en un plato caliente.","minutes":1,"kind":"activo"},{"text":"Repetir los pasos 4 a 9 con el resto del huevo batido, el jamón cocido y el queso en lonchas.","minutes":6,"kind":"activo"},{"text":"Servir las 2 tortillas de inmediato mientras el queso está fundido.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, true, 'olla', NULL),
  ('huevos_055', 'Huevos fritos con patatas paja y pimentón', 'huevos', 'huevo', NULL, ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 470, 16, 32, 32, 2, true, false, '{"huevo"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Patata","amount":300,"unit":"g"},{"name":"Aceite de oliva","amount":80,"unit":"ml"},{"name":"Pimentón dulce","amount":3,"unit":"g"}]'::jsonb, '{"Pelar patata y cortar en tiras muy finas tipo paja.","Secar bien las patatas paja con un paño limpio para eliminar el exceso de almidón y humedad.","Calentar aceite de oliva en sartén a fuego fuerte hasta que esté bien caliente.","Freír la mitad de las patatas paja hasta que estén doradas y crujientes.","Escurrir las patatas fritas sobre papel absorbente y reservar.","Freír la segunda tanda de patatas paja hasta que estén doradas y crujientes.","Escurrir la segunda tanda sobre papel absorbente y reservar junto a las anteriores.","Freír huevo en el mismo aceite a fuego medio hasta que la clara esté cuajada y la yema líquida.","Repartir las patatas paja reservadas en 2 platos formando un nido.","Colocar los huevos fritos sobre las patatas paja.","Espolvorear pimentón dulce sobre los huevos y las patatas antes de servir."}', 'Huevos fritos de puntilla crujiente sobre una nube de patata paja con pimentón.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Pelar {{Patata}} y cortar en tiras muy finas tipo paja.","minutes":5,"kind":"prep","part":"guarnicion"},{"text":"Secar bien las patatas paja con un paño limpio para eliminar el exceso de almidón y humedad.","minutes":2,"kind":"prep","part":"guarnicion"},{"text":"Calentar {{Aceite de oliva|abundante}} en {{@Sartén}} a fuego fuerte hasta que esté bien caliente.","minutes":2,"kind":"activo","part":"guarnicion"},{"text":"Freír la mitad de las patatas paja hasta que estén doradas y crujientes.","minutes":3,"kind":"activo","part":"guarnicion"},{"text":"Escurrir las patatas fritas sobre papel absorbente y reservar.","minutes":1,"kind":"prep","part":"guarnicion"},{"text":"Freír la segunda tanda de patatas paja hasta que estén doradas y crujientes.","minutes":3,"kind":"activo","part":"guarnicion"},{"text":"Escurrir la segunda tanda sobre papel absorbente y reservar junto a las anteriores.","minutes":1,"kind":"prep","part":"guarnicion"},{"text":"Freír {{Huevo}} en el mismo aceite a fuego medio hasta que la clara esté cuajada y la yema líquida.","minutes":2,"kind":"activo","part":"principal"},{"text":"Repartir las patatas paja reservadas en 2 platos formando un nido.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Colocar los huevos fritos sobre las patatas paja.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Espolvorear {{Pimentón dulce|pizca}} sobre los huevos y las patatas antes de servir.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true, NULL, true, 'sarten', NULL),
  ('huevos_056', 'Revuelto de morcilla y piñones', 'huevos', 'huevo', NULL, ARRAY['cena','primero']::meal_role[], 'principal', NULL, NULL, 15, 'facil', 'all', 430, 17, 7, 37, 2, false, false, '{"huevo","frutos_secos"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Morcilla de Burgos","amount":150,"unit":"g"},{"name":"Piñones","amount":20,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"}]'::jsonb, '{"Retirar la piel de morcilla de burgos y desmenuzarla con los dedos o un tenedor hasta obtener trozos irregulares.","Batir huevo en un bol hasta que estén homogéneos.","Tostar piñones en sartén seca a fuego suave hasta que estén dorados.","Retirar los piñones tostados y reservar.","Calentar aceite de oliva en la misma sartén a fuego medio.","Añadir la morcilla desmenuzada y saltear a fuego medio hasta que esté crujiente por fuera.","Bajar el fuego a suave y verter los huevos batidos sobre la morcilla.","Remover suavemente con una espátula hasta que el huevo cuaje cremoso.","Retirar la sartén del fuego, espolvorear los piñones tostados por encima y servir de inmediato."}', 'Revuelto cremoso de morcilla de Burgos, oscuro y cremoso, con piñones tostados por encima.', NULL, '{}', NULL, NULL, NULL, '{"frutos_secos"}', NULL, ARRAY['cerdo']::main_protein[], false, '[{"text":"Retirar la piel de {{Morcilla de Burgos}} y desmenuzarla con los dedos o un tenedor hasta obtener trozos irregulares.","minutes":2,"kind":"prep"},{"text":"Batir {{Huevo}} en un bol hasta que estén homogéneos.","minutes":1,"kind":"prep"},{"text":"Tostar {{Piñones}} en {{@Sartén}} seca a fuego suave hasta que estén dorados.","minutes":2,"kind":"activo"},{"text":"Retirar los piñones tostados y reservar.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en la misma {{@Sartén}} a fuego medio.","minutes":1,"kind":"activo"},{"text":"Añadir la morcilla desmenuzada y saltear a fuego medio hasta que esté crujiente por fuera.","minutes":4,"kind":"activo"},{"text":"Bajar el fuego a suave y verter los huevos batidos sobre la morcilla.","minutes":1,"kind":"activo"},{"text":"Remover suavemente con una espátula hasta que el huevo cuaje cremoso.","minutes":2,"kind":"activo"},{"text":"Retirar la sartén del fuego, espolvorear los piñones tostados por encima y servir de inmediato.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL),
  ('huevos_057', 'Revuelto de espárragos trigueros con jamón', 'huevos', 'huevo', NULL, ARRAY['cena','primero']::meal_role[], 'principal', NULL, NULL, 15, 'facil', 'all', 300, 20, 5, 22, 2, true, false, '{"huevo"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Espárragos trigueros","amount":150,"unit":"g"},{"name":"Jamón serrano","amount":50,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Lavar espárragos trigueros, retirar la parte dura del tallo y cortar en trozos de 3 cm.","Cortar jamón serrano en tiras finas.","Picar ajo fino.","Batir huevo en un bol hasta obtener una mezcla homogénea.","Calentar aceite de oliva en sartén a fuego medio hasta que esté caliente.","Sofreír el ajo picado hasta que empiece a dorarse.","Añadir los espárragos y saltear a fuego medio hasta que estén tiernos.","Incorporar el jamón serrano en tiras y saltear hasta que se integre con los espárragos.","Bajar el fuego a suave y verter los huevos batidos sobre la sartén.","Remover con movimientos lentos y continuos hasta que los huevos cuajen cremosos sin secarse.","Servir de inmediato en plato caliente."}', 'Revuelto jugoso de espárragos trigueros con jamón serrano, verde y rosado entre el huevo.', NULL, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, ARRAY['cerdo']::main_protein[], false, '[{"text":"Lavar {{Espárragos trigueros}}, retirar la parte dura del tallo y cortar en trozos de 3 cm.","minutes":2,"kind":"prep"},{"text":"Cortar {{Jamón serrano}} en tiras finas.","minutes":1,"kind":"prep"},{"text":"Picar {{Ajo}} fino.","minutes":1,"kind":"prep"},{"text":"Batir {{Huevo}} en un bol hasta obtener una mezcla homogénea.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva}} en {{@Sartén}} a fuego medio hasta que esté caliente.","minutes":1,"kind":"activo"},{"text":"Sofreír el ajo picado hasta que empiece a dorarse.","minutes":1,"kind":"activo"},{"text":"Añadir los espárragos y saltear a fuego medio hasta que estén tiernos.","minutes":5,"kind":"activo"},{"text":"Incorporar el jamón serrano en tiras y saltear hasta que se integre con los espárragos.","minutes":1,"kind":"activo"},{"text":"Bajar el fuego a suave y verter los huevos batidos sobre la sartén.","minutes":1,"kind":"activo"},{"text":"Remover con movimientos lentos y continuos hasta que los huevos cuajen cremosos sin secarse.","minutes":2,"kind":"activo"},{"text":"Servir de inmediato en plato caliente.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL),
  ('huevos_058', 'Huevos escalfados sobre puré de patata', 'huevos', 'huevo', 'patatas', ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 30, 'normal', 'all', 360, 14, 34, 18, 2, true, false, '{"huevo","lactosa","sulfitos"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Patata","amount":400,"unit":"g"},{"name":"Leche","amount":80,"unit":"ml"},{"name":"Mantequilla","amount":30,"unit":"g"},{"name":"Vinagre","amount":10,"unit":"ml"},{"name":"Cebollino","amount":5,"unit":"g"}]'::jsonb, '{"Pelar patata y cortar en trozos de tamaño similar.","Cocer las patatas en una olla con agua con sal hasta que estén tiernas.","Calentar leche y mantequilla en un cazo a fuego suave hasta que la mantequilla se funda.","Escurrir bien las patatas cocidas y pasarlas por el pasapurés sobre un bol grande.","Añadir la leche caliente al puré poco a poco, removiendo hasta obtener una textura cremosa.","Salpimentar el puré y reservar tapado para que se mantenga caliente.","Picar cebollino fino y reservar.","Llevar a ebullición agua en una cazuela ancha con vinagre a fuego medio.","Reducir el fuego hasta que el agua hierva suave, sin borbotones fuertes.","Cascar huevo uno a uno en un cuenco pequeño y deslizar con cuidado al agua.","Cocer los huevos hasta que la clara esté cuajada y la yema líquida.","Retirar los huevos escalfados con una espumadera y escurrir sobre papel de cocina.","Repartir el puré caliente en 2 platos hondos formando una base generosa.","Colocar 2 huevos escalfados sobre el puré de cada plato.","Espolvorear el cebollino picado por encima y servir de inmediato."}', 'Huevos escalfados sobre un puré de patata cremoso, con la yema hundiéndose despacio en lo cremoso.', NULL, '{}', NULL, NULL, NULL, '{"lacteo"}', NULL, '{}'::main_protein[], false, '[{"text":"Pelar {{Patata}} y cortar en trozos de tamaño similar.","minutes":3,"kind":"prep"},{"text":"Cocer las patatas en una olla con agua con sal hasta que estén tiernas.","minutes":17,"kind":"pasivo"},{"text":"Calentar {{Leche}} y {{Mantequilla}} en un cazo a fuego suave hasta que la mantequilla se funda.","minutes":3,"kind":"activo","part":"principal"},{"text":"Escurrir bien las patatas cocidas y pasarlas por el pasapurés sobre un bol grande.","minutes":2,"kind":"activo","part":"principal"},{"text":"Añadir la leche caliente al puré poco a poco, removiendo hasta obtener una textura cremosa.","minutes":2,"kind":"activo","part":"principal"},{"text":"Salpimentar el puré y reservar tapado para que se mantenga caliente.","minutes":1,"kind":"activo","part":"principal"},{"text":"Picar {{Cebollino}} fino y reservar.","minutes":1,"kind":"prep"},{"text":"Llevar a ebullición agua en una cazuela ancha con {{Vinagre}} a fuego medio.","minutes":3,"kind":"activo","part":"principal"},{"text":"Reducir el fuego hasta que el agua hierva suave, sin borbotones fuertes.","minutes":1,"kind":"activo","part":"principal"},{"text":"Cascar {{Huevo}} uno a uno en un cuenco pequeño y deslizar con cuidado al agua.","minutes":2,"kind":"activo","part":"principal"},{"text":"Cocer los huevos hasta que la clara esté cuajada y la yema líquida.","minutes":3,"kind":"pasivo","part":"principal"},{"text":"Retirar los huevos escalfados con una espumadera y escurrir sobre papel de cocina.","minutes":1,"kind":"activo","part":"principal"},{"text":"Repartir el puré caliente en 2 platos hondos formando una base generosa.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Colocar 2 huevos escalfados sobre el puré de cada plato.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Espolvorear el cebollino picado por encima y servir de inmediato.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true, NULL, NULL, 'olla', NULL),
  ('huevos_059', 'Tortilla de calabacín y queso', 'huevos', 'huevo', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 20, 'facil', 'all', 340, 20, 8, 24, 2, true, true, '{"huevo","lactosa"}', '[{"name":"Huevo","amount":5,"unit":"ud"},{"name":"Calabacín","amount":250,"unit":"g"},{"name":"Queso rallado","amount":60,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"}]'::jsonb, '{"Lavar calabacín y cortar en dados pequeños.","Picar cebolla en trozos finos.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla picada hasta que esté transparente.","Añadir el calabacín en dados y saltear a fuego medio hasta que esté tierno y algo dorado.","Salpimentar el calabacín y la cebolla al gusto.","Retirar la sartén del fuego y dejar templar el sofrito.","Batir huevo en un bol grande hasta que estén bien mezclados.","Añadir el sofrito templado de calabacín y cebolla al bol con los huevos batidos.","Incorporar queso rallado y remover hasta que todo quede bien integrado.","Calentar un chorrito de aceite de oliva en la sartén limpia a fuego medio.","Verter la mezcla de huevos en la sartén y cuajar hasta que los bordes estén firmes.","Dar la vuelta a la tortilla con un plato y deslizarla de nuevo a la sartén.","Cuajar por el otro lado hasta que el queso esté fundido por dentro.","Servir cortada en porciones."}', 'Tortilla jugosa de calabacín con hilos de queso fundido.', NULL, '{}', NULL, NULL, NULL, '{"verdura","lacteo"}', NULL, '{}'::main_protein[], false, '[{"text":"Lavar {{Calabacín}} y cortar en dados pequeños.","minutes":3,"kind":"prep"},{"text":"Picar {{Cebolla}} en trozos finos.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla picada hasta que esté transparente.","minutes":3,"kind":"activo"},{"text":"Añadir el calabacín en dados y saltear a fuego medio hasta que esté tierno y algo dorado.","minutes":6,"kind":"activo"},{"text":"Salpimentar el calabacín y la cebolla al gusto.","minutes":1,"kind":"activo"},{"text":"Retirar la sartén del fuego y dejar templar el sofrito.","minutes":2,"kind":"espera"},{"text":"Batir {{Huevo}} en un bol grande hasta que estén bien mezclados.","minutes":1,"kind":"prep"},{"text":"Añadir el sofrito templado de calabacín y cebolla al bol con los huevos batidos.","minutes":1,"kind":"activo"},{"text":"Incorporar {{Queso rallado}} y remover hasta que todo quede bien integrado.","minutes":1,"kind":"activo"},{"text":"Calentar un chorrito de aceite de oliva en la sartén limpia a fuego medio.","minutes":1,"kind":"activo"},{"text":"Verter la mezcla de huevos en la sartén y cuajar hasta que los bordes estén firmes.","minutes":3,"kind":"pasivo"},{"text":"Dar la vuelta a la tortilla con un plato y deslizarla de nuevo a la sartén.","minutes":1,"kind":"activo"},{"text":"Cuajar por el otro lado hasta que el queso esté fundido por dentro.","minutes":2,"kind":"pasivo"},{"text":"Servir cortada en porciones.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, true, 'sarten', NULL),
  ('huevos_060', 'Frittata de verduras al horno', 'huevos', 'huevo', NULL, ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, 'horno', 40, 'facil', 'all', 260, 15, 7, 19, 4, true, true, '{"huevo","lactosa"}', '[{"name":"Huevo","amount":8,"unit":"ud"},{"name":"Calabacín","amount":150,"unit":"g"},{"name":"Pimiento rojo","amount":100,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Espinacas","amount":100,"unit":"g"},{"name":"Queso rallado","amount":80,"unit":"g"},{"name":"Leche","amount":60,"unit":"ml"},{"name":"Aceite de oliva","amount":30,"unit":"ml"}]'::jsonb, '{"Precalentar el horno a 180 °C.","Cortar calabacín en dados pequeños.","Cortar pimiento rojo en dados pequeños.","Cortar cebolla en dados pequeños.","Batir huevo con leche en un bol grande hasta obtener una mezcla homogénea.","Calentar aceite de oliva en sartén apta para horno a fuego medio.","Sofreír la cebolla y el pimiento rojo a fuego medio hasta que estén pochados.","Añadir el calabacín y saltear a fuego medio hasta que esté tierno.","Incorporar espinacas y saltear a fuego medio hasta que se reduzcan.","Añadir la mitad de queso rallado a la mezcla de huevo y leche y remover.","Verter la mezcla de huevo sobre las verduras en la sartén de forma uniforme.","Espolvorear el resto del queso rallado por encima.","Hornear en el horno a 180 °C hasta que la frittata esté dorada y firme al tacto.","Reposar la frittata fuera del horno antes de cortar.","Cortar en porciones y servir."}', 'Frittata de verduras horneada, colorida, que se corta en porciones como una tarta.', NULL, '{}', NULL, NULL, NULL, '{"lacteo"}', NULL, '{}'::main_protein[], false, '[{"text":"Precalentar el horno a 180 °C.","minutes":10,"kind":"pasivo"},{"text":"Cortar {{Calabacín}} en dados pequeños.","minutes":2,"kind":"paralelo","during":0},{"text":"Cortar {{Pimiento rojo}} en dados pequeños.","minutes":2,"kind":"paralelo","during":0},{"text":"Cortar {{Cebolla}} en dados pequeños.","minutes":2,"kind":"paralelo","during":0},{"text":"Batir {{Huevo}} con {{Leche}} en un bol grande hasta obtener una mezcla homogénea.","minutes":2,"kind":"paralelo","during":0},{"text":"Calentar {{Aceite de oliva}} en {{@Sartén}} apta para horno a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla y el pimiento rojo a fuego medio hasta que estén pochados.","minutes":5,"kind":"activo"},{"text":"Añadir el calabacín y saltear a fuego medio hasta que esté tierno.","minutes":5,"kind":"activo"},{"text":"Incorporar {{Espinacas}} y saltear a fuego medio hasta que se reduzcan.","minutes":2,"kind":"activo"},{"text":"Añadir la mitad de {{Queso rallado}} a la mezcla de huevo y leche y remover.","minutes":1,"kind":"prep"},{"text":"Verter la mezcla de huevo sobre las verduras en la sartén de forma uniforme.","minutes":1,"kind":"activo"},{"text":"Espolvorear el resto del queso rallado por encima.","minutes":1,"kind":"activo"},{"text":"Hornear en el horno a 180 °C hasta que la frittata esté dorada y firme al tacto.","minutes":22,"kind":"pasivo"},{"text":"Reposar la frittata fuera del horno antes de cortar.","minutes":5,"kind":"espera"},{"text":"Cortar en porciones y servir.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'horno', NULL),
  ('huevos_061', 'Huevos al horno con tomate y queso', 'huevos', 'huevo', NULL, ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, 'horno', 25, 'facil', 'all', 320, 18, 12, 22, 2, true, false, '{"huevo","lactosa"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Tomate triturado","amount":200,"unit":"ml"},{"name":"Queso mozzarella rallado","amount":60,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Orégano","amount":2,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C.","Picar ajo fino.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír el ajo picado hasta que empiece a dorarse.","Añadir tomate triturado y salpimentar.","Cocer a fuego medio hasta que la salsa espese.","Repartir la salsa de tomate entre 2 cazuelitas aptas para horno.","Cascar huevo sobre el tomate, 2 por cazuelita, sin romper la yema.","Repartir queso mozzarella rallado por encima de los huevos.","Espolvorear orégano sobre el queso.","Hornear hasta que la clara cuaje, la yema quede jugosa y el queso se funda.","Servir de inmediato en las mismas cazuelitas."}', 'Huevos al horno con salsa de tomate y queso fundido, burbujeante con el queso dorado en la superficie.', NULL, '{}', NULL, NULL, NULL, '{"lacteo"}', NULL, '{}'::main_protein[], false, '[{"text":"Precalentar el horno a 200 °C.","minutes":10,"kind":"pasivo"},{"text":"Picar {{Ajo}} fino.","minutes":2,"kind":"paralelo","during":0},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír el ajo picado hasta que empiece a dorarse.","minutes":2,"kind":"activo"},{"text":"Añadir {{Tomate triturado}} y salpimentar.","minutes":1,"kind":"activo"},{"text":"Cocer a fuego medio hasta que la salsa espese.","minutes":8,"kind":"pasivo"},{"text":"Repartir la salsa de tomate entre 2 cazuelitas aptas para horno.","minutes":1,"kind":"activo"},{"text":"Cascar {{Huevo}} sobre el tomate, 2 por cazuelita, sin romper la yema.","minutes":1,"kind":"activo"},{"text":"Repartir {{Queso mozzarella rallado}} por encima de los huevos.","minutes":1,"kind":"activo"},{"text":"Espolvorear {{Orégano|pizca}} sobre el queso.","minutes":1,"kind":"activo"},{"text":"Hornear hasta que la clara cuaje, la yema quede jugosa y el queso se funda.","minutes":11,"kind":"pasivo"},{"text":"Servir de inmediato en las mismas cazuelitas.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'horno', NULL)
