insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id, extra_proteins, freezable, steps_rich, estrella, occasion, kid_favourite, tecnica, cocina
) values
  ('huevos_062', 'Tortilla de espinacas y piñones', 'huevos', 'huevo', NULL, ARRAY['cena','segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 400, 19, 9, 32, 2, true, true, '{"huevo","frutos_secos"}', '[{"name":"Huevo","amount":5,"unit":"ud"},{"name":"Espinacas frescas","amount":200,"unit":"g"},{"name":"Piñones","amount":20,"unit":"g"},{"name":"Cebolla","amount":40,"unit":"g"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"}]'::jsonb, '{"Picar cebolla y ajo finos.","Lavar espinacas frescas bajo el grifo y escurrir.","Tostar piñones en sartén seca a fuego medio hasta que estén ligeramente dorados.","Retirar los piñones a un plato y reservar.","Calentar la mitad de aceite de oliva en la misma sartén a fuego medio.","Sofreír la cebolla y el ajo picados a fuego suave hasta que estén blandos y transparentes.","Añadir las espinacas escurridas por tandas y saltear hasta que reduzcan y suelten el agua.","Escurrir las espinacas con cebolla apretando con una cuchara para retirar el exceso de líquido.","Batir huevo en un bol grande hasta que estén homogéneos.","Añadir las espinacas escurridas, la cebolla y los piñones reservados al huevo batido y mezclar.","Calentar el aceite de oliva restante en la sartén a fuego medio-fuerte.","Verter la mezcla de huevo en la sartén y extender para igualar la superficie.","Cuajar a fuego medio hasta que los bordes estén firmes y el centro ligeramente jugoso.","Dar la vuelta a la tortilla con un plato y deslizarla de nuevo a la sartén.","Cuajar por el segundo lado hasta que esté hecha al punto deseado.","Retirar la tortilla de la sartén y dejar reposar antes de cortar.","Servir la tortilla cortada en porciones."}', 'Tortilla jugosa de espinacas salteadas con piñones tostados, verde por dentro y dorada por fuera.', NULL, '{}', NULL, NULL, NULL, '{"verdura","frutos_secos"}', NULL, '{}'::main_protein[], false, '[{"text":"Picar {{Cebolla}} y {{Ajo}} finos.","minutes":2,"kind":"prep"},{"text":"Lavar {{Espinacas frescas}} bajo el grifo y escurrir.","minutes":1,"kind":"prep"},{"text":"Tostar {{Piñones}} en {{@Sartén}} seca a fuego medio hasta que estén ligeramente dorados.","minutes":2,"kind":"activo"},{"text":"Retirar los piñones a un plato y reservar.","minutes":1,"kind":"prep"},{"text":"Calentar la mitad de {{Aceite de oliva}} en la misma sartén a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla y el ajo picados a fuego suave hasta que estén blandos y transparentes.","minutes":6,"kind":"pasivo"},{"text":"Añadir las espinacas escurridas por tandas y saltear hasta que reduzcan y suelten el agua.","minutes":4,"kind":"activo"},{"text":"Escurrir las espinacas con cebolla apretando con una cuchara para retirar el exceso de líquido.","minutes":1,"kind":"prep"},{"text":"Batir {{Huevo}} en un bol grande hasta que estén homogéneos.","minutes":1,"kind":"prep"},{"text":"Añadir las espinacas escurridas, la cebolla y los piñones reservados al huevo batido y mezclar.","minutes":1,"kind":"prep"},{"text":"Calentar el aceite de oliva restante en la sartén a fuego medio-fuerte.","minutes":1,"kind":"activo"},{"text":"Verter la mezcla de huevo en la sartén y extender para igualar la superficie.","minutes":1,"kind":"activo"},{"text":"Cuajar a fuego medio hasta que los bordes estén firmes y el centro ligeramente jugoso.","minutes":3,"kind":"activo"},{"text":"Dar la vuelta a la tortilla con un plato y deslizarla de nuevo a la sartén.","minutes":1,"kind":"activo"},{"text":"Cuajar por el segundo lado hasta que esté hecha al punto deseado.","minutes":2,"kind":"activo"},{"text":"Retirar la tortilla de la sartén y dejar reposar antes de cortar.","minutes":1,"kind":"espera"},{"text":"Servir la tortilla cortada en porciones.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, true, 'sarten', NULL),
  ('huevos_063', 'Huevos con jamón ibérico y trufa', 'huevos', 'huevo', 'pan', ARRAY['cena','segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 20, 'normal', 'all', 450, 26, 27, 26, 2, false, false, '{"huevo","gluten"}', '[{"name":"Pan rústico","amount":100,"unit":"g"},{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Jamón ibérico en lonchas","amount":60,"unit":"g"},{"name":"Trufa negra fresca","amount":10,"unit":"g"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":15,"unit":"ml"},{"name":"Aceite de trufa","amount":5,"unit":"ml"}]'::jsonb, '{"Pelar ajo y reservar.","Laminar finamente trufa negra fresca y reservar.","Cortar pan rústico en rebanadas gruesas.","Tostar las rebanadas de pan en una tostadora o sartén seca a fuego medio hasta que estén crujientes.","Frotar cada rebanada tostada por una cara con el ajo pelado.","Calentar aceite de oliva virgen extra en sartén a fuego medio.","Freír jamón ibérico en lonchas 1 min hasta que esté crujiente.","Retirar el jamón y reservar sobre papel absorbente.","Freír huevo en la misma sartén a fuego medio, 2 min, hasta que la clara esté cuajada y la yema líquida.","Disponer las rebanadas de pan tostado en los platos.","Repartir el jamón crujiente sobre el pan.","Colocar los huevos fritos encima del jamón.","Repartir las láminas de trufa negra fresca sobre los huevos.","Terminar con unas gotas de aceite de trufa y servir enseguida."}', 'Huevos fritos de yema líquida sobre pan tostado con jamón ibérico crujiente y virutas de trufa negra.', NULL, '{}', true, NULL, NULL, '{}', NULL, ARRAY['cerdo']::main_protein[], false, '[{"text":"Pelar {{Ajo}} y reservar.","minutes":1,"kind":"prep"},{"text":"Laminar finamente {{Trufa negra fresca}} y reservar.","minutes":2,"kind":"prep"},{"text":"Cortar {{Pan rústico}} en rebanadas gruesas.","minutes":1,"kind":"prep"},{"text":"Tostar las rebanadas de pan en una tostadora o sartén seca a fuego medio hasta que estén crujientes.","minutes":3,"kind":"activo"},{"text":"Frotar cada rebanada tostada por una cara con el ajo pelado.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva virgen extra}} en {{@Sartén}} a fuego medio.","minutes":1,"kind":"activo"},{"text":"Freír {{Jamón ibérico en lonchas}} 1 min hasta que esté crujiente.","minutes":1,"kind":"activo"},{"text":"Retirar el jamón y reservar sobre papel absorbente.","minutes":1,"kind":"prep"},{"text":"Freír {{Huevo}} en la misma sartén a fuego medio, 2 min, hasta que la clara esté cuajada y la yema líquida.","minutes":2,"kind":"activo"},{"text":"Disponer las rebanadas de pan tostado en los platos.","minutes":1,"kind":"emplatado"},{"text":"Repartir el jamón crujiente sobre el pan.","minutes":1,"kind":"emplatado"},{"text":"Colocar los huevos fritos encima del jamón.","minutes":1,"kind":"emplatado"},{"text":"Repartir las láminas de trufa negra fresca sobre los huevos.","minutes":1,"kind":"emplatado"},{"text":"Terminar con unas gotas de {{Aceite de trufa}} y servir enseguida.","minutes":1,"kind":"emplatado"}]'::jsonb, true, 'especial', NULL, 'sarten', NULL),
  ('huevos_064', 'Shakshuka de huevos poché en salsa de tomate', 'huevos', 'huevo', NULL, ARRAY['cena','segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 30, 'facil', 'all', 415, 19, 36, 22, 2, true, false, '{"huevo","gluten"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Tomate triturado","amount":400,"unit":"g"},{"name":"Pimiento rojo","amount":100,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Comino molido","amount":3,"unit":"g"},{"name":"Pimentón dulce","amount":3,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Pan rústico","amount":80,"unit":"g"}]'::jsonb, '{"Picar cebolla en dados pequeños.","Cortar pimiento rojo en dados pequeños.","Picar ajo fino.","Calentar aceite de oliva en sartén amplia a fuego medio.","Sofreír la cebolla y el pimiento en la sartén hasta que estén blandos, unos 8 min a fuego medio.","Añadir el ajo picado, comino molido y pimentón dulce.","Remover hasta que las especias desprendan aroma, unos 1 min a fuego medio.","Incorporar tomate triturado y salpimentar al gusto.","Cocer la salsa a fuego medio hasta que espese, unos 10 min.","Hacer 4 huecos en la salsa con una cuchara.","Cascar huevo con cuidado y depositar uno en cada hueco de la salsa.","Tapar la sartén y cocer a fuego suave hasta que la clara cuaje y la yema quede líquida, unos 6 min.","Tostar pan rústico al gusto.","Servir la shakshuka directamente en la sartén acompañada del pan tostado para mojar."}', 'Huevos escalfados hundidos en una salsa de tomate y pimiento especiada, para mojar pan.', NULL, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], false, '[{"text":"Picar {{Cebolla}} en dados pequeños.","minutes":2,"kind":"prep"},{"text":"Cortar {{Pimiento rojo}} en dados pequeños.","minutes":2,"kind":"prep"},{"text":"Picar {{Ajo}} fino.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} amplia a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla y el pimiento en la sartén hasta que estén blandos, unos 8 min a fuego medio.","minutes":8,"kind":"pasivo"},{"text":"Añadir el ajo picado, {{Comino molido|pizca}} y {{Pimentón dulce|pizca}}.","minutes":1,"kind":"activo"},{"text":"Remover hasta que las especias desprendan aroma, unos 1 min a fuego medio.","minutes":1,"kind":"activo"},{"text":"Incorporar {{Tomate triturado}} y salpimentar al gusto.","minutes":1,"kind":"activo"},{"text":"Cocer la salsa a fuego medio hasta que espese, unos 10 min.","minutes":10,"kind":"pasivo"},{"text":"Hacer 4 huecos en la salsa con una cuchara.","minutes":1,"kind":"activo"},{"text":"Cascar {{Huevo}} con cuidado y depositar uno en cada hueco de la salsa.","minutes":1,"kind":"activo"},{"text":"Tapar la sartén y cocer a fuego suave hasta que la clara cuaje y la yema quede líquida, unos 6 min.","minutes":6,"kind":"pasivo"},{"text":"Tostar {{Pan rústico}} al gusto.","minutes":3,"kind":"paralelo","during":11},{"text":"Servir la shakshuka directamente en la sartén acompañada del pan tostado para mojar.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'sarten', 'mediterranea'),
  ('huevos_065', 'Huevos rancheros', 'huevos', 'huevo', NULL, ARRAY['cena','segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 515, 26, 46, 26, 2, false, false, '{"huevo","lactosa"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Tortilla de maíz","amount":4,"unit":"ud"},{"name":"Tomate triturado","amount":200,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Chile jalapeño","amount":15,"unit":"g"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Judías negras cocidas","amount":100,"unit":"g"},{"name":"Queso rallado","amount":40,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Cilantro fresco","amount":5,"unit":"g"}]'::jsonb, '{"Picar cebolla y ajo muy finos.","Picar chile jalapeño muy fino.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla, el ajo y el chile jalapeño hasta que la cebolla esté transparente.","Añadir tomate triturado y salpimentar.","Cocer la salsa a fuego medio hasta que espese, removiendo de vez en cuando.","Calentar judías negras cocidas en un cazo a fuego suave, aplastando ligeramente con un tenedor.","Calentar tortilla de maíz en sartén seca a fuego medio, 30 segundos por cada lado.","Picar cilantro fresco fino.","Freír huevo en sartén con el resto del aceite de oliva a fuego medio, hasta que la clara esté cuajada y la yema líquida.","Repartir las tortillas de maíz en los platos y distribuir las judías negras encima.","Verter la salsa ranchera sobre las judías negras.","Colocar 2 huevos fritos sobre cada tortilla y espolvorear queso rallado por encima.","Terminar con el cilantro fresco picado y servir de inmediato."}', 'Huevos fritos sobre tortilla de maíz con salsa ranchera picante, frijoles y queso fundido.', NULL, '{}', NULL, NULL, NULL, '{"lacteo"}', NULL, '{}'::main_protein[], false, '[{"text":"Picar {{Cebolla}} y {{Ajo}} muy finos.","minutes":2,"kind":"prep"},{"text":"Picar {{Chile jalapeño}} muy fino.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla, el ajo y el chile jalapeño hasta que la cebolla esté transparente.","minutes":5,"kind":"activo"},{"text":"Añadir {{Tomate triturado}} y salpimentar.","minutes":1,"kind":"activo"},{"text":"Cocer la salsa a fuego medio hasta que espese, removiendo de vez en cuando.","minutes":10,"kind":"pasivo"},{"text":"Calentar {{Judías negras cocidas}} en un cazo a fuego suave, aplastando ligeramente con un tenedor.","minutes":3,"kind":"activo"},{"text":"Calentar {{Tortilla de maíz}} en {{@Sartén}} seca a fuego medio, 30 segundos por cada lado.","minutes":2,"kind":"activo"},{"text":"Picar {{Cilantro fresco}} fino.","minutes":1,"kind":"prep"},{"text":"Freír {{Huevo}} en {{@Sartén}} con el resto del aceite de oliva a fuego medio, hasta que la clara esté cuajada y la yema líquida.","minutes":3,"kind":"activo"},{"text":"Repartir las tortillas de maíz en los platos y distribuir las judías negras encima.","minutes":1,"kind":"emplatado"},{"text":"Verter la salsa ranchera sobre las judías negras.","minutes":1,"kind":"emplatado"},{"text":"Colocar 2 huevos fritos sobre cada tortilla y espolvorear {{Queso rallado}} por encima.","minutes":1,"kind":"emplatado"},{"text":"Terminar con el cilantro fresco picado y servir de inmediato.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'sarten', 'mexicana'),
  ('huevos_066', 'Tortilla de patatas con chorizo', 'huevos', 'huevo', 'patatas', ARRAY['segundo','cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'normal', 'all', 460, 20, 29, 30, 2, true, true, '{"huevo"}', '[{"name":"Patata","amount":300,"unit":"g"},{"name":"Huevo","amount":5,"unit":"ud"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Chorizo","amount":80,"unit":"g"},{"name":"Aceite de oliva","amount":50,"unit":"ml"}]'::jsonb, '{"Pelar patata y laminar en rodajas finas de unos 2-3 mm.","Cortar cebolla en juliana fina.","Cortar chorizo en dados pequeños.","Calentar aceite de oliva en sartén amplia a fuego suave.","Añadir las patatas laminadas y la cebolla en juliana. Confitar a fuego suave hasta que estén tiernas.","Añadir el chorizo en dados y sofreír junto a las patatas hasta que suelte su grasa y aroma.","Escurrir las patatas, la cebolla y el chorizo en un colador. Reservar el aceite sobrante.","Batir huevo en un bol grande hasta que estén bien mezclados.","Incorporar las patatas, la cebolla y el chorizo escurridos al huevo batido. Mezclar bien.","Reposar la mezcla en el bol durante 2 min para que el huevo empape bien.","Calentar un poco del aceite reservado en sartén a fuego medio.","Volcar la mezcla en la sartén y cuajar a fuego medio-suave hasta que los bordes estén firmes.","Dar la vuelta a la tortilla con ayuda de un plato llano.","Cuajar el segundo lado a fuego suave hasta que esté dorado y el centro ligeramente jugoso.","Retirar del fuego y reposar 1 min antes de servir.","Servir la tortilla entera o en porciones, recién hecha."}', 'Tortilla de patatas jugosa con trocitos de chorizo que tiñen el huevo de rojo.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, ARRAY['cerdo']::main_protein[], false, '[{"text":"Pelar {{Patata}} y laminar en rodajas finas de unos 2-3 mm.","minutes":5,"kind":"prep"},{"text":"Cortar {{Cebolla}} en juliana fina.","minutes":2,"kind":"prep"},{"text":"Cortar {{Chorizo}} en dados pequeños.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva}} en {{@Sartén}} amplia a fuego suave.","minutes":1,"kind":"activo"},{"text":"Añadir las patatas laminadas y la cebolla en juliana. Confitar a fuego suave hasta que estén tiernas.","minutes":15,"kind":"pasivo"},{"text":"Añadir el chorizo en dados y sofreír junto a las patatas hasta que suelte su grasa y aroma.","minutes":5,"kind":"activo"},{"text":"Escurrir las patatas, la cebolla y el chorizo en un colador. Reservar el aceite sobrante.","minutes":2,"kind":"prep"},{"text":"Batir {{Huevo}} en un bol grande hasta que estén bien mezclados.","minutes":1,"kind":"prep"},{"text":"Incorporar las patatas, la cebolla y el chorizo escurridos al huevo batido. Mezclar bien.","minutes":1,"kind":"prep"},{"text":"Reposar la mezcla en el bol durante 2 min para que el huevo empape bien.","minutes":2,"kind":"espera"},{"text":"Calentar un poco del aceite reservado en {{@Sartén}} a fuego medio.","minutes":1,"kind":"activo"},{"text":"Volcar la mezcla en la sartén y cuajar a fuego medio-suave hasta que los bordes estén firmes.","minutes":3,"kind":"activo"},{"text":"Dar la vuelta a la tortilla con ayuda de un plato llano.","minutes":1,"kind":"activo"},{"text":"Cuajar el segundo lado a fuego suave hasta que esté dorado y el centro ligeramente jugoso.","minutes":3,"kind":"activo"},{"text":"Retirar del fuego y reposar 1 min antes de servir.","minutes":1,"kind":"espera"},{"text":"Servir la tortilla entera o en porciones, recién hecha.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL),
  ('huevos_067', 'Huevo frito sobre risotto de setas', 'huevos', 'huevo', 'arroz', ARRAY['segundo','cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'normal', 'all', 610, 21, 70, 26, 2, true, false, '{"huevo","lactosa","sulfitos"}', '[{"name":"Arroz arborio","amount":160,"unit":"g"},{"name":"Setas variadas","amount":200,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Vino blanco","amount":50,"unit":"ml"},{"name":"Caldo de verduras","amount":600,"unit":"ml"},{"name":"Queso parmesano rallado","amount":30,"unit":"g"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Picar cebolla y ajo muy finos.","Limpiar y cortar setas variadas en trozos medianos.","Calentar caldo de verduras en un cazo a fuego suave hasta que empiece a humear; mantener caliente.","Calentar aceite de oliva en sartén a fuego fuerte.","Saltear las setas cortadas a fuego fuerte durante 5 min hasta que se doren.","Retirar las setas de la sartén y reservar.","Sofreír la cebolla y el ajo picados en la misma sartén a fuego medio hasta que estén tiernos.","Añadir arroz arborio y remover 1 min hasta que los granos estén nacarados.","Añadir vino blanco y remover sin parar hasta que se evapore por completo.","Incorporar un cucharón de caldo caliente y remover hasta que el arroz lo absorba.","Continuar añadiendo caldo cucharón a cucharón, removiendo sin parar, durante 12 min.","Incorporar las setas reservadas al risotto y seguir removiendo 5 min hasta que el arroz esté al dente.","Retirar el risotto del fuego y añadir mantequilla y queso parmesano rallado.","Remover con energía hasta que la mantequilla y el parmesano se integren y el risotto quede cremoso.","Calentar un chorrito de aceite de oliva en otra sartén a fuego fuerte.","Cascar huevo uno a uno y freír a fuego fuerte hasta que el borde esté crujiente y la yema líquida.","Repartir el risotto en 2 platos y colocar un huevo frito encima de cada uno."}', 'Risotto cremoso de setas coronado con un huevo frito de yema líquida.', NULL, '{}', true, NULL, NULL, '{"verdura","seta"}', NULL, '{}'::main_protein[], false, '[{"text":"Picar {{Cebolla}} y {{Ajo}} muy finos.","minutes":3,"kind":"prep"},{"text":"Limpiar y cortar {{Setas variadas}} en trozos medianos.","minutes":3,"kind":"prep"},{"text":"Calentar {{Caldo de verduras}} en un cazo a fuego suave hasta que empiece a humear; mantener caliente.","minutes":4,"kind":"activo"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego fuerte.","minutes":1,"kind":"activo","part":"principal"},{"text":"Saltear las setas cortadas a fuego fuerte durante 5 min hasta que se doren.","minutes":5,"kind":"activo","part":"principal"},{"text":"Retirar las setas de la sartén y reservar.","minutes":1,"kind":"prep","part":"principal"},{"text":"Sofreír la cebolla y el ajo picados en la misma sartén a fuego medio hasta que estén tiernos.","minutes":4,"kind":"activo","part":"principal"},{"text":"Añadir {{Arroz arborio}} y remover 1 min hasta que los granos estén nacarados.","minutes":1,"kind":"activo","part":"principal"},{"text":"Añadir {{Vino blanco}} y remover sin parar hasta que se evapore por completo.","minutes":2,"kind":"activo","part":"principal"},{"text":"Incorporar un cucharón de caldo caliente y remover hasta que el arroz lo absorba.","minutes":2,"kind":"activo","part":"principal"},{"text":"Continuar añadiendo caldo cucharón a cucharón, removiendo sin parar, durante 12 min.","minutes":12,"kind":"activo","part":"principal"},{"text":"Incorporar las setas reservadas al risotto y seguir removiendo 5 min hasta que el arroz esté al dente.","minutes":5,"kind":"activo","part":"principal"},{"text":"Retirar el risotto del fuego y añadir {{Mantequilla}} y {{Queso parmesano rallado}}.","minutes":1,"kind":"activo","part":"principal"},{"text":"Remover con energía hasta que la mantequilla y el parmesano se integren y el risotto quede cremoso.","minutes":1,"kind":"activo","part":"principal"},{"text":"Calentar un chorrito de aceite de oliva en otra {{@Sartén}} a fuego fuerte.","minutes":1,"kind":"activo","part":"guarnicion"},{"text":"Cascar {{Huevo}} uno a uno y freír a fuego fuerte hasta que el borde esté crujiente y la yema líquida.","minutes":2,"kind":"activo","part":"guarnicion"},{"text":"Repartir el risotto en 2 platos y colocar un huevo frito encima de cada uno.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true, NULL, NULL, 'sarten', 'italiana'),
  ('huevos_068', 'Ensaladilla con huevo y gambas', 'huevos', 'huevo', 'patatas', ARRAY['primero','cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'facil', 'all', 505, 22, 26, 35, 4, true, false, '{"huevo","marisco","sulfitos"}', '[{"name":"Patata","amount":400,"unit":"g"},{"name":"Zanahoria","amount":150,"unit":"g"},{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Gambas peladas","amount":200,"unit":"g"},{"name":"Mayonesa","amount":150,"unit":"g"},{"name":"Guisantes cocidos","amount":80,"unit":"g"},{"name":"Aceitunas","amount":30,"unit":"g"}]'::jsonb, '{"Llevar a ebullición agua con sal en una olla grande a fuego fuerte.","Cocer patata y zanahoria enteras y sin pelar hasta que estén tiernas.","Cocer huevo en otro cazo con agua hirviendo durante 10 min.","Calentar sartén a fuego fuerte con aceitunas de aceite.","Saltear gambas peladas hasta que estén rosadas y reservar en un plato para que enfríen.","Transferir los huevos cocidos a un bol con agua fría hasta que estén templados.","Pelar los huevos fríos y reservar 1 entero para decorar.","Picar 3 huevos pelados en dados pequeños y reservar.","Pelar la patata y la zanahoria templadas en cuanto se puedan manipular.","Cortar la patata pelada en dados pequeños y reservar en un bol grande.","Cortar la zanahoria pelada en dados pequeños e incorporar al bol.","Añadir al bol los huevos picados, guisantes cocidos y la mitad de las gambas peladas.","Incorporar mayonesa y remover con cuidado hasta que todo quede bien ligado.","Refrigerar la ensaladilla tapada hasta que esté bien fría.","Cortar el huevo reservado en cuartos y reservar junto al resto de las gambas y aceitunas.","Decorar la ensaladilla con el resto de las gambas, los cuartos de huevo y las aceitunas."}', 'Ensaladilla clásica de patata y mayonesa con huevo duro y gambas por encima.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, ARRAY['marisco']::main_protein[], false, '[{"text":"Llevar a ebullición agua con sal en una olla grande a fuego fuerte.","minutes":5,"kind":"activo"},{"text":"Cocer {{Patata}} y {{Zanahoria}} enteras y sin pelar hasta que estén tiernas.","minutes":20,"kind":"pasivo"},{"text":"Cocer {{Huevo}} en otro cazo con agua hirviendo durante 10 min.","minutes":10,"kind":"pasivo"},{"text":"Calentar {{@Sartén}} a fuego fuerte con {{Aceitunas|chorrito}} de aceite.","minutes":1,"kind":"activo"},{"text":"Saltear {{Gambas peladas}} hasta que estén rosadas y reservar en un plato para que enfríen.","minutes":2,"kind":"activo"},{"text":"Transferir los huevos cocidos a un bol con agua fría hasta que estén templados.","minutes":5,"kind":"espera"},{"text":"Pelar los huevos fríos y reservar 1 entero para decorar.","minutes":3,"kind":"prep"},{"text":"Picar 3 huevos pelados en dados pequeños y reservar.","minutes":2,"kind":"prep"},{"text":"Pelar la patata y la zanahoria templadas en cuanto se puedan manipular.","minutes":3,"kind":"prep"},{"text":"Cortar la patata pelada en dados pequeños y reservar en un bol grande.","minutes":3,"kind":"prep"},{"text":"Cortar la zanahoria pelada en dados pequeños e incorporar al bol.","minutes":2,"kind":"prep"},{"text":"Añadir al bol los huevos picados, {{Guisantes cocidos}} y la mitad de las gambas peladas.","minutes":1,"kind":"activo"},{"text":"Incorporar {{Mayonesa}} y remover con cuidado hasta que todo quede bien ligado.","minutes":2,"kind":"activo"},{"text":"Refrigerar la ensaladilla tapada hasta que esté bien fría.","minutes":60,"kind":"espera"},{"text":"Cortar el huevo reservado en cuartos y reservar junto al resto de las gambas y {{Aceitunas}}.","minutes":1,"kind":"prep"},{"text":"Decorar la ensaladilla con el resto de las gambas, los cuartos de huevo y las aceitunas.","minutes":2,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'olla', NULL),
  ('huevos_069', 'Huevos rellenos de txangurro', 'huevos', 'huevo', NULL, ARRAY['cena','segundo']::meal_role[], 'principal', NULL, NULL, 35, 'normal', 'all', 510, 37, 15, 33, 2, true, true, '{"huevo","lactosa","gluten","marisco"}', '[{"name":"Huevo","amount":6,"unit":"ud"},{"name":"Carne de txangurro","amount":150,"unit":"g"},{"name":"Cebolla","amount":40,"unit":"g"},{"name":"Tomate frito","amount":50,"unit":"g"},{"name":"Brandy","amount":10,"unit":"ml"},{"name":"Leche","amount":100,"unit":"ml"},{"name":"Mantequilla","amount":15,"unit":"g"},{"name":"Harina","amount":15,"unit":"g"},{"name":"Queso rallado","amount":20,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"}]'::jsonb, '{"Llevar a ebullición agua en un cazo e introducir huevo. Cocer 10 min a fuego medio.","Transferir los huevos a un bol con agua fría hasta que estén templados.","Pelar los huevos y cortar cada uno por la mitad a lo largo.","Separar las yemas de las claras con cuidado y reservar ambas por separado.","Picar cebolla en fino.","Calentar aceite de oliva en sartén a fuego medio y sofreír la cebolla picada hasta que esté tierna.","Añadir carne de txangurro y tomate frito. Saltear 3 min removiendo.","Verter brandy y dejar reducir hasta que el alcohol se evapore.","Retirar la sartén del fuego y reservar el relleno de txangurro.","Fundir mantequilla en un cazo a fuego suave.","Añadir harina de golpe y remover sin parar 1 min hasta obtener una pasta homogénea.","Incorporar leche poco a poco sin dejar de remover hasta que la bechamel espese y esté lisa.","Retirar el cazo del fuego y reservar la bechamel.","Desmenuzar las yemas reservadas sobre el relleno de txangurro.","Mezclar la mitad de la bechamel con el relleno de txangurro y las yemas hasta integrar.","Rellenar cada clara con la mezcla de txangurro y colocarlas en una fuente apta para horno.","Napar los huevos rellenos con el resto de la bechamel.","Espolvorear queso rallado por encima de todos los huevos.","Gratinar en el horno a 220 °C con el grill hasta que la superficie esté dorada.","Retirar la fuente del horno y servir los huevos rellenos templados."}', 'Huevos duros rellenos de txangurro cremoso, gratinados hasta dorarse.', NULL, '{}', true, NULL, NULL, '{"lacteo"}', NULL, '{}'::main_protein[], false, '[{"text":"Llevar a ebullición agua en un cazo e introducir {{Huevo}}. Cocer 10 min a fuego medio.","minutes":10,"kind":"pasivo"},{"text":"Transferir los huevos a un bol con agua fría hasta que estén templados.","minutes":5,"kind":"espera"},{"text":"Pelar los huevos y cortar cada uno por la mitad a lo largo.","minutes":3,"kind":"prep"},{"text":"Separar las yemas de las claras con cuidado y reservar ambas por separado.","minutes":2,"kind":"prep"},{"text":"Picar {{Cebolla}} en fino.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego medio y sofreír la cebolla picada hasta que esté tierna.","minutes":6,"kind":"activo"},{"text":"Añadir {{Carne de txangurro}} y {{Tomate frito}}. Saltear 3 min removiendo.","minutes":3,"kind":"activo"},{"text":"Verter {{Brandy}} y dejar reducir hasta que el alcohol se evapore.","minutes":1,"kind":"activo"},{"text":"Retirar la sartén del fuego y reservar el relleno de txangurro.","minutes":1,"kind":"prep"},{"text":"Fundir {{Mantequilla}} en un cazo a fuego suave.","minutes":1,"kind":"activo"},{"text":"Añadir {{Harina}} de golpe y remover sin parar 1 min hasta obtener una pasta homogénea.","minutes":1,"kind":"activo"},{"text":"Incorporar {{Leche}} poco a poco sin dejar de remover hasta que la bechamel espese y esté lisa.","minutes":4,"kind":"activo"},{"text":"Retirar el cazo del fuego y reservar la bechamel.","minutes":1,"kind":"prep"},{"text":"Desmenuzar las yemas reservadas sobre el relleno de txangurro.","minutes":1,"kind":"prep"},{"text":"Mezclar la mitad de la bechamel con el relleno de txangurro y las yemas hasta integrar.","minutes":1,"kind":"prep"},{"text":"Rellenar cada clara con la mezcla de txangurro y colocarlas en una fuente apta para horno.","minutes":3,"kind":"prep"},{"text":"Napar los huevos rellenos con el resto de la bechamel.","minutes":1,"kind":"prep"},{"text":"Espolvorear {{Queso rallado}} por encima de todos los huevos.","minutes":1,"kind":"prep"},{"text":"Gratinar en el horno a 220 °C con el grill hasta que la superficie esté dorada.","minutes":9,"kind":"pasivo"},{"text":"Retirar la fuente del horno y servir los huevos rellenos templados.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'plancha', NULL),
  ('huevos_070', 'Huevos con salsa de queso azul', 'huevos', 'huevo', 'pan', ARRAY['cena','segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 25, 'normal', 'all', 555, 25, 29, 38, 2, false, false, '{"huevo","lactosa","frutos_secos","gluten"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Queso azul","amount":60,"unit":"g"},{"name":"Nata para cocinar","amount":60,"unit":"ml"},{"name":"Nueces","amount":20,"unit":"g"},{"name":"Pan rústico","amount":100,"unit":"g"},{"name":"Vinagre","amount":10,"unit":"ml"}]'::jsonb, '{"Cortar pan rústico en rebanadas gruesas.","Tostar las rebanadas en el tostador o en una sartén seca a fuego medio hasta que estén crujientes.","Trocear nueces en trozos gruesos y reservar.","Calentar nata para cocinar en un cazo a fuego suave.","Desmenuzar queso azul dentro del cazo cuando la nata esté caliente.","Remover hasta que el queso se funda y la salsa quede homogénea, sin que llegue a hervir.","Retirar el cazo del fuego y reservar la salsa caliente.","Llevar a ebullición agua en un cazo amplio con vinagre.","Bajar el fuego hasta mantener un hervor suave; remover el agua para crear un remolino.","Cascar huevo uno a uno sobre el remolino y escalfar 3 min cada uno.","Sacar los huevos con una espumadera y escurrir sobre papel absorbente.","Repartir las rebanadas de pan tostado en los platos y colocar 2 huevos escalfados sobre cada una.","Napar con la salsa de queso azul caliente y esparcir las nueces por encima.","Servir inmediatamente."}', 'Huevos escalfados bañados en una salsa cremosa de queso azul y nueces.', NULL, '{}', NULL, NULL, NULL, '{"lacteo","frutos_secos"}', NULL, '{}'::main_protein[], false, '[{"text":"Cortar {{Pan rústico}} en rebanadas gruesas.","minutes":2,"kind":"prep"},{"text":"Tostar las rebanadas en el tostador o en una sartén seca a fuego medio hasta que estén crujientes.","minutes":4,"kind":"activo"},{"text":"Trocear {{Nueces}} en trozos gruesos y reservar.","minutes":1,"kind":"prep"},{"text":"Calentar {{Nata para cocinar}} en un cazo a fuego suave.","minutes":2,"kind":"activo"},{"text":"Desmenuzar {{Queso azul}} dentro del cazo cuando la nata esté caliente.","minutes":1,"kind":"activo"},{"text":"Remover hasta que el queso se funda y la salsa quede homogénea, sin que llegue a hervir.","minutes":3,"kind":"activo"},{"text":"Retirar el cazo del fuego y reservar la salsa caliente.","minutes":1,"kind":"activo"},{"text":"Llevar a ebullición agua en un cazo amplio con {{Vinagre}}.","minutes":3,"kind":"activo"},{"text":"Bajar el fuego hasta mantener un hervor suave; remover el agua para crear un remolino.","minutes":1,"kind":"activo"},{"text":"Cascar {{Huevo}} uno a uno sobre el remolino y escalfar 3 min cada uno.","minutes":3,"kind":"activo"},{"text":"Sacar los huevos con una espumadera y escurrir sobre papel absorbente.","minutes":1,"kind":"activo"},{"text":"Repartir las rebanadas de pan tostado en los platos y colocar 2 huevos escalfados sobre cada una.","minutes":1,"kind":"emplatado"},{"text":"Napar con la salsa de queso azul caliente y esparcir las nueces por encima.","minutes":1,"kind":"emplatado"},{"text":"Servir inmediatamente.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL),
  ('huevos_071', 'Tortilla de patatas con pimientos verdes', 'huevos', 'huevo', 'patatas', ARRAY['segundo','cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'normal', 'all', 410, 18, 27, 26, 2, true, true, '{"huevo"}', '[{"name":"Patata","amount":300,"unit":"g"},{"name":"Huevo","amount":5,"unit":"ud"},{"name":"Pimiento verde italiano","amount":100,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Aceite de oliva","amount":55,"unit":"ml"}]'::jsonb, '{"Pelar patata y laminar en rodajas finas de unos 2-3 mm.","Cortar cebolla en juliana fina.","Cortar pimiento verde italiano en tiras finas.","Calentar aceite de oliva en sartén amplia a fuego medio hasta que esté caliente.","Añadir las patatas laminadas, la cebolla y el pimiento verde a la sartén.","Confitar a fuego suave 20 min, removiendo de vez en cuando, hasta que todo esté tierno.","Escurrir las patatas, la cebolla y el pimiento en un colador, reservando el aceite sobrante.","Batir huevo en un bol grande con sal hasta obtener una mezcla homogénea.","Añadir las patatas, la cebolla y el pimiento escurridos a los huevos batidos y mezclar.","Reposar la mezcla 2 min para que el huevo empape bien las patatas.","Calentar un chorrito del aceite reservado en la sartén limpia a fuego medio hasta que esté caliente.","Volcar la mezcla en la sartén y cuajar 3 min a fuego medio hasta que los bordes estén firmes.","Dar la vuelta a la tortilla con un plato llano y deslizarla de nuevo en la sartén.","Cuajar el segundo lado 2 min a fuego medio hasta que esté cuajado al gusto.","Reposar la tortilla fuera del fuego 1 min antes de servir.","Servir la tortilla entera o cortada en porciones."}', 'Tortilla de patatas con pimientos verdes fritos, trocitos verdes entre el huevo cuajado.', NULL, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], false, '[{"text":"Pelar {{Patata}} y laminar en rodajas finas de unos 2-3 mm.","minutes":4,"kind":"prep"},{"text":"Cortar {{Cebolla}} en juliana fina.","minutes":2,"kind":"prep"},{"text":"Cortar {{Pimiento verde italiano}} en tiras finas.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva}} en {{@Sartén}} amplia a fuego medio hasta que esté caliente.","minutes":1,"kind":"activo"},{"text":"Añadir las patatas laminadas, la cebolla y el pimiento verde a la sartén.","minutes":1,"kind":"activo"},{"text":"Confitar a fuego suave 20 min, removiendo de vez en cuando, hasta que todo esté tierno.","minutes":20,"kind":"pasivo"},{"text":"Escurrir las patatas, la cebolla y el pimiento en un colador, reservando el aceite sobrante.","minutes":1,"kind":"activo"},{"text":"Batir {{Huevo}} en un bol grande con {{Sal|gusto}} hasta obtener una mezcla homogénea.","minutes":1,"kind":"prep"},{"text":"Añadir las patatas, la cebolla y el pimiento escurridos a los huevos batidos y mezclar.","minutes":1,"kind":"activo"},{"text":"Reposar la mezcla 2 min para que el huevo empape bien las patatas.","minutes":2,"kind":"espera"},{"text":"Calentar un chorrito del aceite reservado en la sartén limpia a fuego medio hasta que esté caliente.","minutes":1,"kind":"activo"},{"text":"Volcar la mezcla en la sartén y cuajar 3 min a fuego medio hasta que los bordes estén firmes.","minutes":3,"kind":"pasivo"},{"text":"Dar la vuelta a la tortilla con un plato llano y deslizarla de nuevo en la sartén.","minutes":1,"kind":"activo"},{"text":"Cuajar el segundo lado 2 min a fuego medio hasta que esté cuajado al gusto.","minutes":2,"kind":"pasivo"},{"text":"Reposar la tortilla fuera del fuego 1 min antes de servir.","minutes":1,"kind":"espera"},{"text":"Servir la tortilla entera o cortada en porciones.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL)
