insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id, extra_proteins, freezable, steps_rich, estrella, occasion, kid_favourite, tecnica, cocina
) values
  ('huevos_072', 'Huevos poché con crema de guisantes y menta', 'huevos', 'huevo', NULL, ARRAY['cena','segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 25, 'normal', 'all', 450, 20, 24, 30, 2, true, false, '{"huevo","lactosa"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Guisantes","amount":300,"unit":"g"},{"name":"Caldo de verduras","amount":200,"unit":"ml"},{"name":"Menta fresca","amount":5,"unit":"g"},{"name":"Nata para cocinar","amount":50,"unit":"ml"},{"name":"Mantequilla","amount":15,"unit":"g"},{"name":"Cebolleta","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"},{"name":"Vinagre","amount":10,"unit":"ml"}]'::jsonb, '{"Picar cebolleta muy fina.","Calentar mantequilla y aceite de oliva en un cazo a fuego medio.","Sofreír la cebolleta picada hasta que esté translúcida, unos 4 min.","Añadir guisantes y caldo de verduras. Llevar a ebullición.","Cocer a fuego medio hasta que los guisantes estén tiernos, unos 8 min.","Retirar del fuego. Añadir nata para cocinar y menta fresca.","Triturar el conjunto hasta obtener una crema fina.","Llevar a ebullición abundante agua en un cazo. Añadir vinagre.","Reducir el fuego hasta que el agua apenas se mueva. Remover para crear un remolino suave.","Cascar huevo de uno en uno en un bol pequeño y deslizarlo con cuidado al centro del remolino.","Cocer cada huevo poché 3 min hasta que la clara esté cuajada y la yema líquida.","Retirar cada huevo con una espumadera y escurrir sobre papel absorbente.","Repetir con los huevos restantes de uno en uno.","Repartir la crema de guisantes caliente en los platos.","Colocar 2 huevos poché sobre la crema en cada plato.","Terminar con unas hojas de menta fresca y un hilo de aceite de oliva."}', 'Huevos poché sobre una crema fina de guisantes y menta.', NULL, '{}', NULL, NULL, NULL, '{"verdura","lacteo"}', NULL, '{}'::main_protein[], false, '[{"text":"Picar {{Cebolleta}} muy fina.","minutes":2,"kind":"prep"},{"text":"Calentar {{Mantequilla}} y {{Aceite de oliva|chorrito}} en un cazo a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolleta picada hasta que esté translúcida, unos 4 min.","minutes":4,"kind":"activo"},{"text":"Añadir {{Guisantes}} y {{Caldo de verduras}}. Llevar a ebullición.","minutes":2,"kind":"activo"},{"text":"Cocer a fuego medio hasta que los guisantes estén tiernos, unos 8 min.","minutes":8,"kind":"pasivo"},{"text":"Retirar del fuego. Añadir {{Nata para cocinar}} y {{Menta fresca}}.","minutes":1,"kind":"activo"},{"text":"Triturar el conjunto hasta obtener una crema fina.","minutes":2,"kind":"activo"},{"text":"Llevar a ebullición abundante agua en un cazo. Añadir {{Vinagre}}.","minutes":3,"kind":"paralelo","during":4},{"text":"Reducir el fuego hasta que el agua apenas se mueva. Remover para crear un remolino suave.","minutes":1,"kind":"activo"},{"text":"Cascar {{Huevo}} de uno en uno en un bol pequeño y deslizarlo con cuidado al centro del remolino.","minutes":1,"kind":"activo"},{"text":"Cocer cada huevo poché 3 min hasta que la clara esté cuajada y la yema líquida.","minutes":3,"kind":"pasivo"},{"text":"Retirar cada huevo con una espumadera y escurrir sobre papel absorbente.","minutes":1,"kind":"activo"},{"text":"Repetir con los huevos restantes de uno en uno.","minutes":8,"kind":"activo"},{"text":"Repartir la crema de guisantes caliente en los platos.","minutes":1,"kind":"emplatado"},{"text":"Colocar 2 huevos poché sobre la crema en cada plato.","minutes":1,"kind":"emplatado"},{"text":"Terminar con unas hojas de menta fresca y un hilo de aceite de oliva.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'olla', NULL),
  ('huevos_073', 'Huevos con setas y jamón al horno', 'huevos', 'huevo', 'pan', ARRAY['cena','segundo','plato_unico']::meal_role[], 'completo', NULL, 'horno', 25, 'facil', 'all', 505, 28, 26, 33, 2, true, false, '{"huevo","lactosa","gluten"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Setas variadas","amount":200,"unit":"g"},{"name":"Jamón serrano en taquitos","amount":60,"unit":"g"},{"name":"Nata para cocinar","amount":60,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Perejil fresco","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Pan rústico","amount":80,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C.","Laminar setas variadas.","Picar ajo fino.","Picar perejil fresco fino y reservar.","Calentar aceite de oliva en sartén a fuego fuerte.","Sofreír las setas laminadas y el ajo picado hasta que se doren y suelten el agua.","Añadir jamón serrano en taquitos y saltear 1 min hasta que tome color.","Repartir la mezcla de setas y jamón en 2 cazuelitas individuales aptas para horno.","Verter nata para cocinar a partes iguales sobre cada cazuelita.","Cascar huevo encima de cada cazuelita, 2 huevos por ración.","Hornear 10 min hasta que la clara cuaje y la yema quede semilíquida.","Cortar pan rústico en rebanadas y tostar en el horno los últimos 3 min.","Espolvorear el perejil picado sobre cada cazuelita y servir muy caliente con el pan tostado."}', 'Huevos al horno con setas salteadas y jamón, burbujeantes recién sacados del horno.', NULL, '{}', NULL, NULL, NULL, '{"lacteo","seta"}', NULL, ARRAY['cerdo']::main_protein[], false, '[{"text":"Precalentar el horno a 200 °C.","minutes":10,"kind":"pasivo"},{"text":"Laminar {{Setas variadas}}.","minutes":2,"kind":"paralelo","during":0},{"text":"Picar {{Ajo}} fino.","minutes":1,"kind":"paralelo","during":0},{"text":"Picar {{Perejil fresco}} fino y reservar.","minutes":1,"kind":"paralelo","during":0},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego fuerte.","minutes":1,"kind":"activo"},{"text":"Sofreír las setas laminadas y el ajo picado hasta que se doren y suelten el agua.","minutes":5,"kind":"activo"},{"text":"Añadir {{Jamón serrano en taquitos}} y saltear 1 min hasta que tome color.","minutes":1,"kind":"activo"},{"text":"Repartir la mezcla de setas y jamón en 2 cazuelitas individuales aptas para horno.","minutes":1,"kind":"prep"},{"text":"Verter {{Nata para cocinar}} a partes iguales sobre cada cazuelita.","minutes":1,"kind":"prep"},{"text":"Cascar {{Huevo}} encima de cada cazuelita, 2 huevos por ración.","minutes":1,"kind":"prep"},{"text":"Hornear 10 min hasta que la clara cuaje y la yema quede semilíquida.","minutes":10,"kind":"pasivo"},{"text":"Cortar {{Pan rústico}} en rebanadas y tostar en el horno los últimos 3 min.","minutes":3,"kind":"paralelo","during":10},{"text":"Espolvorear el perejil picado sobre cada cazuelita y servir muy caliente con el pan tostado.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'horno', NULL),
  ('huevos_074', 'Tortilla de patatas con pulpo', 'huevos', 'huevo', 'patatas', ARRAY['segundo','cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 40, 'normal', 'all', 475, 26, 28, 27, 2, true, true, '{"huevo","moluscos"}', '[{"name":"Patata","amount":300,"unit":"g"},{"name":"Huevo","amount":5,"unit":"ud"},{"name":"Pulpo cocido","amount":150,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Pimentón dulce","amount":3,"unit":"g"},{"name":"Aceite de oliva","amount":50,"unit":"ml"}]'::jsonb, '{"Pelar patata y laminar en rodajas finas de unos 2-3 mm.","Cortar cebolla en juliana fina.","Calentar aceite de oliva en sartén grande a fuego suave.","Añadir la patata laminada y la cebolla en juliana hasta que queden confitadas, sin dorarse.","Cortar pulpo cocido en rodajas de 1 cm.","Batir huevo en un bol grande hasta integrar.","Añadir pimentón dulce al huevo batido y mezclar.","Escurrir la patata y la cebolla en un colador, reservando el aceite de oliva sobrante.","Incorporar la patata escurrida, la cebolla escurrida y el pulpo al huevo batido.","Remover bien y dejar reposar la mezcla para que el huevo empape la patata.","Calentar un poco del aceite reservado en la sartén a fuego medio.","Verter la mezcla en la sartén y cuajar hasta que los bordes estén firmes y el centro algo jugoso.","Dar la vuelta con un plato y devolver la tortilla a la sartén por el otro lado.","Cuajar hasta que el segundo lado esté firme, dejando el interior ligeramente meloso.","Retirar la tortilla del fuego y dejar reposar antes de servir.","Servir la tortilla cortada en porciones."}', 'Tortilla de patatas con rodajas de pulpo y un toque de pimentón.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, ARRAY['marisco']::main_protein[], false, '[{"text":"Pelar {{Patata}} y laminar en rodajas finas de unos 2-3 mm.","minutes":4,"kind":"prep"},{"text":"Cortar {{Cebolla}} en juliana fina.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|abundante}} en {{@Sartén}} grande a fuego suave.","minutes":1,"kind":"activo"},{"text":"Añadir la patata laminada y la cebolla en juliana hasta que queden confitadas, sin dorarse.","minutes":20,"kind":"pasivo"},{"text":"Cortar {{Pulpo cocido}} en rodajas de 1 cm.","minutes":2,"kind":"paralelo","during":3},{"text":"Batir {{Huevo}} en un bol grande hasta integrar.","minutes":1,"kind":"paralelo","during":3},{"text":"Añadir {{Pimentón dulce|pizca}} al huevo batido y mezclar.","minutes":1,"kind":"paralelo","during":3},{"text":"Escurrir la patata y la cebolla en un colador, reservando el aceite de oliva sobrante.","minutes":1,"kind":"activo"},{"text":"Incorporar la patata escurrida, la cebolla escurrida y el pulpo al huevo batido.","minutes":1,"kind":"activo"},{"text":"Remover bien y dejar reposar la mezcla para que el huevo empape la patata.","minutes":2,"kind":"espera"},{"text":"Calentar un poco del aceite reservado en la {{@Sartén}} a fuego medio.","minutes":1,"kind":"activo"},{"text":"Verter la mezcla en la {{@Sartén}} y cuajar hasta que los bordes estén firmes y el centro algo jugoso.","minutes":3,"kind":"activo"},{"text":"Dar la vuelta con un plato y devolver la tortilla a la {{@Sartén}} por el otro lado.","minutes":1,"kind":"activo"},{"text":"Cuajar hasta que el segundo lado esté firme, dejando el interior ligeramente meloso.","minutes":2,"kind":"activo"},{"text":"Retirar la tortilla del fuego y dejar reposar antes de servir.","minutes":1,"kind":"espera"},{"text":"Servir la tortilla cortada en porciones.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'olla', NULL),
  ('huevos_075', 'Huevos a la Florentina con espinacas y bechamel', 'huevos', 'huevo', NULL, ARRAY['cena','segundo','plato_unico']::meal_role[], 'completo', NULL, 'horno', 35, 'normal', 'all', 525, 28, 23, 36, 2, true, true, '{"huevo","lactosa","gluten"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Espinacas frescas","amount":300,"unit":"g"},{"name":"Leche","amount":250,"unit":"ml"},{"name":"Mantequilla","amount":25,"unit":"g"},{"name":"Harina","amount":25,"unit":"g"},{"name":"Queso rallado","amount":40,"unit":"g"},{"name":"Nuez moscada","amount":1,"unit":"g"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"}]'::jsonb, '{"Precalentar el horno a 200 °C con calor arriba y abajo.","Picar ajo muy fino.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír el ajo picado 1 min hasta que esté dorado sin quemarse.","Añadir espinacas frescas por tandas y saltear a fuego medio hasta que reduzcan por completo.","Escurrir las espinacas salteadas presionando con una cuchara para eliminar el exceso de agua.","Fundir mantequilla en un cazo a fuego suave.","Añadir harina de golpe y remover sin parar 1 min hasta obtener una pasta homogénea.","Verter leche poco a poco sin dejar de remover a fuego suave.","Remover sin parar hasta que la bechamel espese y se despegue de las paredes del cazo.","Sazonar la bechamel con nuez moscada y sal al gusto.","Repartir las espinacas escurridas en 2 cazuelitas individuales aptas para horno.","Cascar huevo de 2 en 2 sobre las espinacas de cada cazuelita, colocando las yemas enteras.","Cubrir cada cazuelita con la bechamel sin tapar del todo las yemas.","Espolvorear queso rallado por encima de la bechamel en cada cazuelita.","Hornear en el horno a 200 °C durante 10 min hasta que la clara cuaje y la superficie esté dorada.","Servir las cazuelitas recién salidas del horno con cuidado de no romper las yemas."}', 'Huevos a la florentina con espinacas y bechamel, gratinados hasta dorarse por encima.', NULL, '{}', NULL, NULL, NULL, '{"verdura","lacteo"}', NULL, '{}'::main_protein[], false, '[{"text":"Precalentar el horno a 200 °C con calor arriba y abajo.","minutes":10,"kind":"pasivo"},{"text":"Picar {{Ajo}} muy fino.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír el ajo picado 1 min hasta que esté dorado sin quemarse.","minutes":1,"kind":"activo"},{"text":"Añadir {{Espinacas frescas}} por tandas y saltear a fuego medio hasta que reduzcan por completo.","minutes":4,"kind":"activo"},{"text":"Escurrir las espinacas salteadas presionando con una cuchara para eliminar el exceso de agua.","minutes":2,"kind":"prep"},{"text":"Fundir {{Mantequilla}} en un cazo a fuego suave.","minutes":1,"kind":"activo"},{"text":"Añadir {{Harina}} de golpe y remover sin parar 1 min hasta obtener una pasta homogénea.","minutes":1,"kind":"activo"},{"text":"Verter {{Leche}} poco a poco sin dejar de remover a fuego suave.","minutes":1,"kind":"activo"},{"text":"Remover sin parar hasta que la bechamel espese y se despegue de las paredes del cazo.","minutes":3,"kind":"activo"},{"text":"Sazonar la bechamel con {{Nuez moscada|pizca}} y sal al gusto.","minutes":1,"kind":"activo"},{"text":"Repartir las espinacas escurridas en 2 cazuelitas individuales aptas para horno.","minutes":1,"kind":"prep"},{"text":"Cascar {{Huevo}} de 2 en 2 sobre las espinacas de cada cazuelita, colocando las yemas enteras.","minutes":2,"kind":"prep"},{"text":"Cubrir cada cazuelita con la bechamel sin tapar del todo las yemas.","minutes":1,"kind":"prep"},{"text":"Espolvorear {{Queso rallado}} por encima de la bechamel en cada cazuelita.","minutes":1,"kind":"prep"},{"text":"Hornear en el horno a 200 °C durante 10 min hasta que la clara cuaje y la superficie esté dorada.","minutes":10,"kind":"pasivo"},{"text":"Servir las cazuelitas recién salidas del horno con cuidado de no romper las yemas.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'horno', NULL),
  ('huevos_076', 'Revuelto ajoarriero de bacalao con pimientos', 'huevos', 'huevo', NULL, ARRAY['cena','segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 30, 'normal', 'all', 410, 34, 6, 28, 2, false, false, '{"huevo","pescado"}', '[{"name":"Huevo","amount":5,"unit":"ud"},{"name":"Bacalao desalado desmigado","amount":200,"unit":"g"},{"name":"Pimiento rojo","amount":80,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Guindilla","amount":2,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Perejil fresco","amount":5,"unit":"g"}]'::jsonb, '{"Laminar ajo.","Cortar pimiento rojo en tiras finas.","Picar perejil fresco fino y reservar.","Batir huevo ligeramente en un bol hasta homogeneizar.","Calentar aceite de oliva en sartén a fuego suave.","Sofreír el ajo laminado y guindilla en el aceite caliente hasta que el ajo empiece a dorarse.","Añadir el pimiento rojo en tiras y pochar hasta que esté tierno.","Incorporar bacalao desalado desmigado y remover hasta que esté bien caliente.","Bajar el fuego al mínimo y verter el huevo batido sobre el bacalao y las verduras.","Remover sin parar con una espátula hasta que el huevo esté cuajado pero cremoso.","Retirar la sartén del fuego en cuanto el huevo esté jugoso, antes de que cuaje del todo.","Espolvorear el perejil picado y servir de inmediato."}', 'Revuelto de bacalao desmigado con pimientos y ajo, al estilo ajoarriero.', NULL, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, ARRAY['pescado_blanco']::main_protein[], false, '[{"text":"Laminar {{Ajo}}.","minutes":2,"kind":"prep"},{"text":"Cortar {{Pimiento rojo}} en tiras finas.","minutes":2,"kind":"prep"},{"text":"Picar {{Perejil fresco}} fino y reservar.","minutes":1,"kind":"prep"},{"text":"Batir {{Huevo}} ligeramente en un bol hasta homogeneizar.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego suave.","minutes":1,"kind":"activo"},{"text":"Sofreír el ajo laminado y {{Guindilla}} en el aceite caliente hasta que el ajo empiece a dorarse.","minutes":2,"kind":"activo"},{"text":"Añadir el pimiento rojo en tiras y pochar hasta que esté tierno.","minutes":8,"kind":"pasivo"},{"text":"Incorporar {{Bacalao desalado desmigado}} y remover hasta que esté bien caliente.","minutes":3,"kind":"activo"},{"text":"Bajar el fuego al mínimo y verter el huevo batido sobre el bacalao y las verduras.","minutes":1,"kind":"activo"},{"text":"Remover sin parar con una espátula hasta que el huevo esté cuajado pero cremoso.","minutes":2,"kind":"activo"},{"text":"Retirar la sartén del fuego en cuanto el huevo esté jugoso, antes de que cuaje del todo.","minutes":1,"kind":"activo"},{"text":"Espolvorear el perejil picado y servir de inmediato.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL),
  ('huevos_077', 'Shakshuka verde con espinacas y feta', 'huevos', 'huevo', 'pan', ARRAY['cena','segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 470, 24, 31, 28, 2, true, false, '{"huevo","lactosa","gluten"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Espinacas frescas","amount":250,"unit":"g"},{"name":"Pimiento verde","amount":80,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Queso feta","amount":60,"unit":"g"},{"name":"Comino molido","amount":2,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Pan rústico","amount":80,"unit":"g"}]'::jsonb, '{"Picar cebolla en dados finos.","Cortar pimiento verde en dados finos.","Picar ajo fino.","Calentar aceite de oliva en sartén amplia a fuego medio.","Sofreír la cebolla y el pimiento verde en la sartén hasta que estén blandos.","Añadir el ajo picado y comino molido y remover sin parar hasta que el ajo suelte aroma.","Incorporar espinacas frescas por tandas y saltear hasta que reduzcan por completo.","Retirar la mitad de las espinacas a un vaso de batidora y triturar hasta obtener una crema verde.","Incorporar la crema triturada a la sartén y remover hasta mezclar todo de forma uniforme.","Hacer 4 huecos en la mezcla verde con una cuchara.","Cascar huevo uno a uno y depositar cada huevo en un hueco.","Tapar la sartén y cocer a fuego suave hasta que la clara cuaje y la yema quede líquida.","Desmenuzar queso feta por encima de la sartén.","Tostar pan rústico y servir junto a la sartén para acompañar."}', 'Shakshuka verde de espinacas con huevos escalfados y queso feta desmenuzado.', NULL, '{}', NULL, NULL, NULL, '{"verdura","lacteo"}', NULL, '{}'::main_protein[], false, '[{"text":"Picar {{Cebolla}} en dados finos.","minutes":2,"kind":"prep"},{"text":"Cortar {{Pimiento verde}} en dados finos.","minutes":2,"kind":"prep"},{"text":"Picar {{Ajo}} fino.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} amplia a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla y el pimiento verde en la sartén hasta que estén blandos.","minutes":8,"kind":"activo"},{"text":"Añadir el ajo picado y {{Comino molido|pizca}} y remover sin parar hasta que el ajo suelte aroma.","minutes":1,"kind":"activo"},{"text":"Incorporar {{Espinacas frescas}} por tandas y saltear hasta que reduzcan por completo.","minutes":4,"kind":"activo"},{"text":"Retirar la mitad de las espinacas a un vaso de batidora y triturar hasta obtener una crema verde.","minutes":2,"kind":"activo"},{"text":"Incorporar la crema triturada a la sartén y remover hasta mezclar todo de forma uniforme.","minutes":1,"kind":"activo"},{"text":"Hacer 4 huecos en la mezcla verde con una cuchara.","minutes":1,"kind":"activo"},{"text":"Cascar {{Huevo}} uno a uno y depositar cada huevo en un hueco.","minutes":1,"kind":"activo"},{"text":"Tapar la sartén y cocer a fuego suave hasta que la clara cuaje y la yema quede líquida.","minutes":7,"kind":"pasivo"},{"text":"Desmenuzar {{Queso feta}} por encima de la sartén.","minutes":1,"kind":"emplatado"},{"text":"Tostar {{Pan rústico}} y servir junto a la sartén para acompañar.","minutes":2,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'olla', 'mediterranea'),
  ('huevos_078', 'Huevos al horno con burrata y tomate', 'huevos', 'huevo', 'pan', ARRAY['cena','segundo','plato_unico']::meal_role[], 'completo', NULL, 'horno', 30, 'facil', 'all', 610, 28, 30, 42, 2, true, false, '{"huevo","lactosa","gluten"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Burrata","amount":150,"unit":"g"},{"name":"Tomate triturado","amount":300,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Albahaca fresca","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Pan rústico","amount":80,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C.","Picar ajo fino.","Calentar aceite de oliva en una cazuela apta para horno a fuego medio.","Sofreír el ajo picado hasta que empiece a blanquear, sin que llegue a dorarse.","Añadir tomate triturado y salpimentar al gusto.","Cocer a fuego medio hasta que la salsa espese, removiendo de vez en cuando.","Hacer 4 huecos en la salsa con una cuchara.","Cascar huevo de uno en uno y depositar cada uno en un hueco.","Hornear en el horno a 200 °C hasta que la clara empiece a cuajar pero la yema siga líquida.","Repartir trozos de burrata entre los huevos.","Hornear 2 min más hasta que la burrata se funda ligeramente.","Espolvorear con hojas de albahaca fresca recién arrancadas.","Servir la cazuela muy caliente acompañada de pan rústico."}', 'Huevos al horno con tomate y burrata fundiéndose entre las yemas.', NULL, '{}', NULL, NULL, NULL, '{"lacteo"}', NULL, '{}'::main_protein[], false, '[{"text":"Precalentar el horno a 200 °C.","minutes":10,"kind":"pasivo"},{"text":"Picar {{Ajo}} fino.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una cazuela apta para horno a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír el ajo picado hasta que empiece a blanquear, sin que llegue a dorarse.","minutes":1,"kind":"activo"},{"text":"Añadir {{Tomate triturado}} y salpimentar al gusto.","minutes":1,"kind":"activo"},{"text":"Cocer a fuego medio hasta que la salsa espese, removiendo de vez en cuando.","minutes":10,"kind":"pasivo"},{"text":"Hacer 4 huecos en la salsa con una cuchara.","minutes":1,"kind":"activo"},{"text":"Cascar {{Huevo}} de uno en uno y depositar cada uno en un hueco.","minutes":2,"kind":"activo"},{"text":"Hornear en el horno a 200 °C hasta que la clara empiece a cuajar pero la yema siga líquida.","minutes":9,"kind":"pasivo"},{"text":"Repartir trozos de {{Burrata}} entre los huevos.","minutes":1,"kind":"activo"},{"text":"Hornear 2 min más hasta que la burrata se funda ligeramente.","minutes":2,"kind":"pasivo"},{"text":"Espolvorear con hojas de {{Albahaca fresca|gusto}} recién arrancadas.","minutes":1,"kind":"emplatado"},{"text":"Servir la cazuela muy caliente acompañada de {{Pan rústico}}.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'horno', NULL),
  ('huevos_079', 'Huevos rotos con jamón, patatas paja y salsa de boletus', 'huevos', 'huevo', 'patatas', ARRAY['cena','segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'normal', 'all', 620, 28, 38, 40, 2, true, false, '{"huevo","lactosa"}', '[{"name":"Patata","amount":300,"unit":"g"},{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Jamón serrano en lonchas","amount":80,"unit":"g"},{"name":"Boletus","amount":100,"unit":"g"},{"name":"Nata para cocinar","amount":60,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Vino blanco","amount":20,"unit":"ml"},{"name":"Aceite de oliva para freír","amount":400,"unit":"ml"},{"name":"Aceite de oliva","amount":10,"unit":"ml"}]'::jsonb, '{"Pelar patata y rallar en juliana muy fina con mandolina o rallador.","Secar la patata rallada con papel absorbente hasta eliminar toda la humedad.","Calentar aceite de oliva para freír en una sartén honda a fuego fuerte hasta que humee.","Freír la patata por tandas hasta que esté dorada y crujiente.","Escurrir la patata sobre papel absorbente y reservar.","Picar ajo fino.","Limpiar boletus y cortar en trozos.","Calentar aceite de oliva en una sartén a fuego medio.","Sofreír el ajo picado hasta que empiece a dorarse.","Añadir los boletus troceados y saltear a fuego fuerte hasta que estén dorados.","Añadir vino blanco y cocer hasta que se evapore el alcohol.","Añadir nata para cocinar y cocer a fuego suave hasta que la salsa espese ligeramente.","Freír huevo en sartén a fuego medio hasta que la clara cuaje y la yema quede líquida.","Repartir la patata paja en los platos como base.","Colocar jamón serrano en lonchas sobre la patata.","Disponer los huevos fritos encima del jamón y romper las yemas con un tenedor.","Napar con la salsa de boletus caliente y servir de inmediato."}', 'Huevos rotos sobre patatas paja crujiente con jamón y una salsa cremosa de boletus.', NULL, '{}', true, NULL, NULL, '{"lacteo","seta"}', NULL, ARRAY['cerdo']::main_protein[], false, '[{"text":"Pelar {{Patata}} y rallar en juliana muy fina con mandolina o rallador.","minutes":5,"kind":"prep","part":"guarnicion"},{"text":"Secar la patata rallada con papel absorbente hasta eliminar toda la humedad.","minutes":2,"kind":"prep","part":"guarnicion"},{"text":"Calentar {{Aceite de oliva para freír}} en una sartén honda a fuego fuerte hasta que humee.","minutes":3,"kind":"activo","part":"guarnicion"},{"text":"Freír la patata por tandas hasta que esté dorada y crujiente.","minutes":6,"kind":"activo","part":"guarnicion"},{"text":"Escurrir la patata sobre papel absorbente y reservar.","minutes":1,"kind":"prep","part":"guarnicion"},{"text":"Picar {{Ajo}} fino.","minutes":1,"kind":"prep","part":"salsa"},{"text":"Limpiar {{Boletus}} y cortar en trozos.","minutes":2,"kind":"prep","part":"salsa"},{"text":"Calentar {{Aceite de oliva}} en una sartén a fuego medio.","minutes":1,"kind":"activo","part":"salsa"},{"text":"Sofreír el ajo picado hasta que empiece a dorarse.","minutes":1,"kind":"activo","part":"salsa"},{"text":"Añadir los boletus troceados y saltear a fuego fuerte hasta que estén dorados.","minutes":4,"kind":"activo","part":"salsa"},{"text":"Añadir {{Vino blanco}} y cocer hasta que se evapore el alcohol.","minutes":1,"kind":"activo","part":"salsa"},{"text":"Añadir {{Nata para cocinar}} y cocer a fuego suave hasta que la salsa espese ligeramente.","minutes":3,"kind":"pasivo","part":"salsa"},{"text":"Freír {{Huevo}} en {{@Sartén}} a fuego medio hasta que la clara cuaje y la yema quede líquida.","minutes":3,"kind":"activo","part":"principal"},{"text":"Repartir la patata paja en los platos como base.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Colocar {{Jamón serrano en lonchas}} sobre la patata.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Disponer los huevos fritos encima del jamón y romper las yemas con un tenedor.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Napar con la salsa de boletus caliente y servir de inmediato.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL),
  ('huevos_080', 'Huevos estrellados con jamón y patata paja', 'huevos', 'huevo', 'patatas', ARRAY['cena','segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 560, 26, 33, 36, 2, true, false, '{"huevo"}', '[{"name":"Patata","amount":300,"unit":"g"},{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Jamón serrano en lonchas","amount":80,"unit":"g"},{"name":"Aceite de oliva para freír","amount":400,"unit":"ml"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Pelar patata y laminar en juliana muy fina con mandolina o rallador.","Secar la patata con papel absorbente para eliminar el exceso de humedad.","Calentar aceite de oliva para freír en una sartén honda a fuego fuerte hasta que esté muy caliente.","Freír la patata en tandas hasta que esté dorada y crujiente.","Escurrir la patata sobre papel absorbente y reservar en lugar cálido.","Calentar aceite de oliva en otra sartén a fuego medio hasta que esté caliente.","Freír huevo de uno en uno hasta que la clara cuaje pero la yema quede líquida.","Repartir la patata caliente en los platos formando una base uniforme.","Colocar jamón serrano en lonchas sobre la patata.","Disponer los huevos fritos encima del jamón.","Romper las yemas con un tenedor justo al servir para que se mezclen con la patata y el jamón."}', 'Huevos estrellados clásicos sobre patata paja crujiente con jamón serrano.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, ARRAY['cerdo']::main_protein[], false, '[{"text":"Pelar {{Patata}} y laminar en juliana muy fina con mandolina o rallador.","minutes":5,"kind":"prep","part":"guarnicion"},{"text":"Secar la patata con papel absorbente para eliminar el exceso de humedad.","minutes":2,"kind":"prep","part":"guarnicion"},{"text":"Calentar {{Aceite de oliva para freír}} en una sartén honda a fuego fuerte hasta que esté muy caliente.","minutes":2,"kind":"activo","part":"guarnicion"},{"text":"Freír la patata en tandas hasta que esté dorada y crujiente.","minutes":4,"kind":"activo","part":"guarnicion"},{"text":"Escurrir la patata sobre papel absorbente y reservar en lugar cálido.","minutes":1,"kind":"prep","part":"guarnicion"},{"text":"Calentar {{Aceite de oliva}} en otra sartén a fuego medio hasta que esté caliente.","minutes":1,"kind":"activo","part":"principal"},{"text":"Freír {{Huevo}} de uno en uno hasta que la clara cuaje pero la yema quede líquida.","minutes":2,"kind":"activo","part":"principal"},{"text":"Repartir la patata caliente en los platos formando una base uniforme.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Colocar {{Jamón serrano en lonchas}} sobre la patata.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Disponer los huevos fritos encima del jamón.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Romper las yemas con un tenedor justo al servir para que se mezclen con la patata y el jamón.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL),
  ('huevos_081', 'Quiche de setas y queso de cabra', 'huevos', 'huevo', NULL, ARRAY['cena','segundo','plato_unico']::meal_role[], 'completo', NULL, 'horno', 60, 'normal', 'all', 635, 19, 32, 47, 4, true, true, '{"huevo","lactosa","gluten"}', '[{"name":"Masa quebrada","amount":230,"unit":"g"},{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Nata para cocinar","amount":200,"unit":"ml"},{"name":"Setas variadas","amount":250,"unit":"g"},{"name":"Queso de cabra","amount":120,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Nuez moscada","amount":1,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 180 °C.","Forrar un molde de quiche con masa quebrada y pincharla con un tenedor por toda la superficie.","Refrigerar la base en el molde en la nevera durante 10 min.","Picar cebolla en trozos finos.","Laminar setas variadas.","Cubrir la base fría con papel de horno y peso encima (legumbres secas o bolas de cerámica).","Hornear la base en blanco a 180 °C durante 10 min.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla picada a fuego medio hasta que esté translúcida, unos 6 min.","Añadir las setas laminadas y saltear a fuego fuerte hasta que se doren y suelten el agua, unos 5 min.","Retirar la sartén del fuego y reservar el sofrito.","Batir huevo con nata para cocinar en un bol hasta obtener una mezcla homogénea.","Añadir nuez moscada a la mezcla de huevo y nata y remover.","Retirar el peso y el papel de la base horneada.","Repartir el sofrito de setas y cebolla de manera uniforme sobre la base.","Desmenuzar queso de cabra por encima del sofrito de manera uniforme.","Verter la mezcla de huevo y nata sobre el relleno hasta cubrir.","Hornear a 180 °C durante 30 min hasta que cuaje y la superficie esté dorada.","Dejar templar la quiche fuera del horno durante 5 min antes de cortar.","Cortar la quiche en porciones y servir."}', 'Quiche de setas salteadas y queso de cabra, cremosa por dentro y dorada por fuera.', NULL, '{}', NULL, NULL, NULL, '{"lacteo","seta"}', NULL, '{}'::main_protein[], true, '[{"text":"Precalentar el horno a 180 °C.","minutes":10,"kind":"pasivo"},{"text":"Forrar un molde de quiche con {{Masa quebrada}} y pincharla con un tenedor por toda la superficie.","minutes":3,"kind":"prep"},{"text":"Refrigerar la base en el molde en la nevera durante 10 min.","minutes":10,"kind":"espera"},{"text":"Picar {{Cebolla}} en trozos finos.","minutes":2,"kind":"paralelo","during":2},{"text":"Laminar {{Setas variadas}}.","minutes":3,"kind":"paralelo","during":2},{"text":"Cubrir la base fría con papel de horno y peso encima (legumbres secas o bolas de cerámica).","minutes":2,"kind":"prep"},{"text":"Hornear la base en blanco a 180 °C durante 10 min.","minutes":10,"kind":"pasivo"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla picada a fuego medio hasta que esté translúcida, unos 6 min.","minutes":6,"kind":"activo"},{"text":"Añadir las setas laminadas y saltear a fuego fuerte hasta que se doren y suelten el agua, unos 5 min.","minutes":5,"kind":"activo"},{"text":"Retirar la sartén del fuego y reservar el sofrito.","minutes":1,"kind":"prep"},{"text":"Batir {{Huevo}} con {{Nata para cocinar}} en un bol hasta obtener una mezcla homogénea.","minutes":2,"kind":"prep"},{"text":"Añadir {{Nuez moscada|pizca}} a la mezcla de huevo y nata y remover.","minutes":1,"kind":"prep"},{"text":"Retirar el peso y el papel de la base horneada.","minutes":1,"kind":"prep"},{"text":"Repartir el sofrito de setas y cebolla de manera uniforme sobre la base.","minutes":1,"kind":"activo"},{"text":"Desmenuzar {{Queso de cabra}} por encima del sofrito de manera uniforme.","minutes":1,"kind":"activo"},{"text":"Verter la mezcla de huevo y nata sobre el relleno hasta cubrir.","minutes":1,"kind":"activo"},{"text":"Hornear a 180 °C durante 30 min hasta que cuaje y la superficie esté dorada.","minutes":30,"kind":"pasivo"},{"text":"Dejar templar la quiche fuera del horno durante 5 min antes de cortar.","minutes":5,"kind":"espera"},{"text":"Cortar la quiche en porciones y servir.","minutes":2,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'horno', NULL)
