insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id, extra_proteins, freezable, steps_rich, estrella, occasion, kid_favourite, tecnica, cocina
) values
  ('huevos_082', 'Soufflé de espinacas', 'huevos', 'huevo', NULL, ARRAY['cena','segundo','plato_unico']::meal_role[], 'completo', NULL, 'horno', 55, 'elaborada', 'all', 325, 19, 13, 23, 4, true, false, '{"huevo","lactosa","gluten"}', '[{"name":"Espinacas frescas","amount":300,"unit":"g"},{"name":"Huevo","amount":6,"unit":"ud"},{"name":"Leche","amount":250,"unit":"ml"},{"name":"Mantequilla","amount":40,"unit":"g"},{"name":"Harina","amount":30,"unit":"g"},{"name":"Queso parmesano rallado","amount":50,"unit":"g"},{"name":"Nuez moscada","amount":1,"unit":"g"},{"name":"Ajo","amount":5,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 190 °C.","Untar cuatro moldes individuales con mantequilla.","Separar huevo: reservar las yemas y las claras en boles distintos.","Picar ajo fino.","Calentar sartén a fuego medio y fundir una pequeña parte de la mantequilla.","Sofreír el ajo picado 1 min hasta que esté ligeramente dorado.","Añadir espinacas frescas y saltear a fuego medio 4 min hasta que reduzcan.","Retirar las espinacas de la sartén y escurrir muy bien el exceso de agua.","Picar las espinacas escurridas fino y reservar.","Fundir el resto de la mantequilla en un cazo a fuego medio.","Añadir harina de golpe y remover sin parar 1 min hasta obtener una pasta homogénea.","Incorporar leche poco a poco, removiendo sin parar a fuego medio hasta que la bechamel espese.","Retirar el cazo del fuego y añadir nuez moscada.","Añadir queso parmesano rallado y las espinacas picadas; mezclar bien.","Dejar templar la bechamel de espinacas hasta que no queme al tacto.","Añadir las yemas reservadas una a una a la bechamel templada, mezclando bien tras cada una.","Montar las claras reservadas a punto de nieve firme en un bol limpio hasta que formen picos duros.","Incorporar un tercio de las claras a la mezcla de espinacas y mezclar para aligerar.","Añadir el resto de las claras con movimientos envolventes suaves hasta que no queden vetas blancas.","Repartir la mezcla en los moldes untados hasta tres cuartas partes de su capacidad.","Alisar la superficie de cada molde con una espátula.","Hornear 22 min sin abrir el horno hasta que los soufflés suban y estén dorados.","Servir los soufflés inmediatamente en los propios moldes."}', 'Soufflé de espinacas, esponjoso y dorado, que sube alto en el horno.', NULL, '{}', NULL, NULL, NULL, '{"verdura","lacteo"}', NULL, '{}'::main_protein[], false, '[{"text":"Precalentar el horno a 190 °C.","minutes":10,"kind":"pasivo"},{"text":"Untar cuatro moldes individuales con {{Mantequilla}}.","minutes":2,"kind":"prep"},{"text":"Separar {{Huevo}}: reservar las yemas y las claras en boles distintos.","minutes":3,"kind":"prep"},{"text":"Picar {{Ajo}} fino.","minutes":2,"kind":"prep"},{"text":"Calentar {{@Sartén}} a fuego medio y fundir una pequeña parte de la mantequilla.","minutes":1,"kind":"activo"},{"text":"Sofreír el ajo picado 1 min hasta que esté ligeramente dorado.","minutes":1,"kind":"activo"},{"text":"Añadir {{Espinacas frescas}} y saltear a fuego medio 4 min hasta que reduzcan.","minutes":4,"kind":"activo"},{"text":"Retirar las espinacas de la sartén y escurrir muy bien el exceso de agua.","minutes":2,"kind":"prep"},{"text":"Picar las espinacas escurridas fino y reservar.","minutes":2,"kind":"prep"},{"text":"Fundir el resto de la mantequilla en un cazo a fuego medio.","minutes":1,"kind":"activo"},{"text":"Añadir {{Harina}} de golpe y remover sin parar 1 min hasta obtener una pasta homogénea.","minutes":1,"kind":"activo"},{"text":"Incorporar {{Leche}} poco a poco, removiendo sin parar a fuego medio hasta que la bechamel espese.","minutes":5,"kind":"activo"},{"text":"Retirar el cazo del fuego y añadir {{Nuez moscada|pizca}}.","minutes":1,"kind":"activo"},{"text":"Añadir {{Queso parmesano rallado}} y las espinacas picadas; mezclar bien.","minutes":1,"kind":"activo"},{"text":"Dejar templar la bechamel de espinacas hasta que no queme al tacto.","minutes":5,"kind":"espera"},{"text":"Añadir las yemas reservadas una a una a la bechamel templada, mezclando bien tras cada una.","minutes":3,"kind":"activo"},{"text":"Montar las claras reservadas a punto de nieve firme en un bol limpio hasta que formen picos duros.","minutes":4,"kind":"activo"},{"text":"Incorporar un tercio de las claras a la mezcla de espinacas y mezclar para aligerar.","minutes":1,"kind":"activo"},{"text":"Añadir el resto de las claras con movimientos envolventes suaves hasta que no queden vetas blancas.","minutes":2,"kind":"activo"},{"text":"Repartir la mezcla en los moldes untados hasta tres cuartas partes de su capacidad.","minutes":2,"kind":"activo"},{"text":"Alisar la superficie de cada molde con una espátula.","minutes":1,"kind":"activo"},{"text":"Hornear 22 min sin abrir el horno hasta que los soufflés suban y estén dorados.","minutes":22,"kind":"pasivo"},{"text":"Servir los soufflés inmediatamente en los propios moldes.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'horno', NULL),
  ('huevos_083', 'Revuelto de bacon y champiñones', 'huevos', 'huevo', NULL, ARRAY['cena','segundo']::meal_role[], 'principal', NULL, NULL, 15, 'facil', 'all', 360, 22, 4, 28, 2, true, false, '{"huevo"}', '[{"name":"Huevo","amount":6,"unit":"ud"},{"name":"Bacon en tiras","amount":100,"unit":"g"},{"name":"Champiñones","amount":200,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"}]'::jsonb, '{"Saltear el bacon en tiras en una sartén hasta que esté dorado y suelte su grasa.","Limpiar y laminar los champiñones, añadirlos a la sartén y saltear hasta que se doren.","Batir los huevos con una pizca de sal.","Verter el huevo batido sobre el bacon y los champiñones, remover a fuego medio hasta que cuaje al gusto.","Servir caliente."}', 'Revuelto de huevo con bacon crujiente y champiñones salteados.', NULL, '{}', NULL, NULL, NULL, '{"seta"}', NULL, ARRAY['cerdo']::main_protein[], NULL, NULL, true, NULL, NULL, 'sarten', NULL),
  ('huevos_084', 'Tortilla de espárragos trigueros', 'huevos', 'huevo', NULL, ARRAY['cena','segundo']::meal_role[], 'principal', NULL, NULL, 20, 'facil', 'all', 280, 18, 6, 20, 2, true, true, '{"huevo"}', '[{"name":"Huevo","amount":6,"unit":"ud"},{"name":"Espárragos trigueros","amount":250,"unit":"g"},{"name":"Cebolla","amount":0.5,"unit":"ud"},{"name":"Aceite de oliva","amount":30,"unit":"ml"}]'::jsonb, '{"Cortar los espárragos en trozos, quitando la parte más dura del tallo.","Saltear los espárragos con la cebolla picada en una sartén con aceite hasta que estén tiernos.","Batir los huevos, mezclar con los espárragos salteados y salpimentar.","Cuajar la mezcla en la sartén a fuego medio, dando la vuelta con ayuda de un plato.","Servir en porciones."}', 'Tortilla cuajada de espárragos trigueros y cebolla.', NULL, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], NULL, NULL, true, NULL, NULL, 'sarten', NULL),
  ('huevos_085', 'Huevos con patatas y chorizo crujiente', 'huevos', 'huevo', NULL, ARRAY['cena','segundo']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 460, 22, 24, 30, 2, true, false, '{"huevo"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Patatas","amount":350,"unit":"g"},{"name":"Chorizo","amount":120,"unit":"g"},{"name":"Aceite de oliva","amount":80,"unit":"ml"}]'::jsonb, '{"Pelar y cortar las patatas en rodajas finas.","Freír las patatas a fuego medio en abundante aceite hasta que estén tiernas y doradas.","Freír el chorizo en rodajas en la misma sartén hasta que esté crujiente.","Freír los huevos hasta que la clara esté cuajada y la yema líquida.","Servir todo junto."}', 'Huevos fritos con patatas y chorizo crujiente, plato de siempre.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, ARRAY['cerdo']::main_protein[], NULL, NULL, true, NULL, NULL, 'sarten', NULL),
  ('huevos_086', 'Tortilla de jamón y queso', 'huevos', 'huevo', NULL, ARRAY['cena','segundo']::meal_role[], 'principal', NULL, NULL, 15, 'facil', 'all', 320, 22, 3, 24, 2, true, true, '{"huevo","lactosa"}', '[{"name":"Huevo","amount":6,"unit":"ud"},{"name":"Jamón cocido en tacos","amount":100,"unit":"g"},{"name":"Queso curado rallado","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"}]'::jsonb, '{"Batir los huevos con el jamón en tacos y el queso rallado, salpimentar.","Calentar aceite en una sartén y verter la mezcla.","Cuajar a fuego medio-bajo, dando la vuelta con ayuda de un plato.","Cuajar por el otro lado y servir en porciones."}', 'Tortilla redonda cuajada con jamón en tacos y queso curado.', NULL, '{}', NULL, NULL, NULL, '{"lacteo"}', NULL, ARRAY['cerdo']::main_protein[], NULL, NULL, true, NULL, true, 'sarten', NULL),
  ('huevos_087', 'Huevos fritos con chorizo y pimientos', 'huevos', 'huevo', NULL, ARRAY['cena','segundo']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 440, 20, 10, 34, 2, true, false, '{"huevo"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Chorizo","amount":120,"unit":"g"},{"name":"Pimiento verde","amount":2,"unit":"ud"},{"name":"Aceite de oliva","amount":40,"unit":"ml"}]'::jsonb, '{"Cortar los pimientos en tiras y saltear en aceite hasta que estén tiernos.","Freír el chorizo en rodajas hasta que suelte su grasa y esté dorado.","Freír los huevos en el mismo aceite hasta que la clara esté cuajada.","Servir todo junto."}', 'Huevos fritos con chorizo y pimiento verde salteado.', NULL, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, ARRAY['cerdo']::main_protein[], NULL, NULL, true, NULL, true, 'sarten', NULL),
  ('huevos_088', 'Tortilla de atún y tomate', 'huevos', 'huevo', NULL, ARRAY['cena','segundo']::meal_role[], 'principal', NULL, NULL, 15, 'facil', 'all', 310, 26, 6, 20, 2, true, true, '{"huevo","pescado"}', '[{"name":"Huevo","amount":6,"unit":"ud"},{"name":"Atún en lata","amount":160,"unit":"g"},{"name":"Tomate","amount":150,"unit":"g"},{"name":"Cebolla","amount":0.5,"unit":"ud"},{"name":"Aceite de oliva","amount":20,"unit":"ml"}]'::jsonb, '{"Picar la cebolla y el tomate, saltear brevemente en una sartén con aceite.","Batir los huevos, mezclar con el atún escurrido y el sofrito de tomate.","Cuajar en la sartén por ambos lados con ayuda de un plato.","Servir en porciones."}', 'Tortilla cuajada con atún y un sofrito ligero de tomate.', NULL, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, ARRAY['pescado_azul']::main_protein[], NULL, NULL, true, NULL, true, 'sarten', NULL),
  ('huevos_089', 'Huevos con salchichas y patatas fritas', 'huevos', 'huevo', NULL, ARRAY['cena','segundo']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 500, 22, 30, 32, 2, true, false, '{"huevo"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Salchichas frescas","amount":4,"unit":"ud"},{"name":"Patatas","amount":350,"unit":"g"},{"name":"Aceite de oliva","amount":80,"unit":"ml"}]'::jsonb, '{"Pelar y cortar las patatas en bastones, freír en abundante aceite hasta que estén doradas.","Freír las salchichas hasta que estén doradas por todos los lados.","Freír los huevos hasta que la clara esté cuajada.","Servir todo junto."}', 'Huevos fritos, salchichas y patatas fritas, plato de siempre para los peques y no tan peques.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, ARRAY['cerdo']::main_protein[], NULL, NULL, true, NULL, true, 'sarten', NULL),
  ('legumbres_001', 'Lentejas con verduras', 'legumbres', 'legumbre', NULL, ARRAY['primero','plato_unico']::meal_role[], 'completo', NULL, NULL, 45, 'facil', 'all', 348, 18, 46, 7, 2, true, true, '{}', '[{"name":"Lentejas","amount":200,"unit":"g"},{"name":"Zanahoria","amount":100,"unit":"g"},{"name":"Patata","amount":150,"unit":"g"},{"name":"Pimiento rojo","amount":80,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Tomate triturado","amount":100,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Pimentón","amount":5,"unit":"g"}]'::jsonb, '{"Lavar lentejas bajo el grifo en un colador hasta que el agua salga limpia y escurrir bien.","Pelar zanahoria y cortar en rodajas de medio centímetro.","Pelar patata y cortar en dados de unos 2 cm.","Retirar las semillas de pimiento rojo y cortar en dados pequeños.","Pelar cebolla y picar en dados finos.","Calentar aceite de oliva en una olla a fuego medio hasta que esté caliente.","Sofreír la cebolla picada en el aceite caliente a fuego medio hasta que esté transparente, unos 3 min.","Añadir el pimiento rojo y la zanahoria a la olla y sofreír a fuego medio hasta que empiecen a ablandarse, unos 3 min.","Añadir tomate triturado y pimentón y remover hasta integrar bien con las verduras.","Incorporar las lentejas escurridas y la patata en dados a la olla y remover para mezclar todo.","Cubrir con agua fría hasta superar los ingredientes unos 3 cm y llevar a ebullición a fuego fuerte.","Reducir a fuego suave, tapar la olla y cocer hasta que las lentejas estén tiernas y la patata cocida, unos 20 min.","Retirar del fuego y servir las lentejas con las verduras bien repartidas en cada plato."}', 'Lentejas guisadas con zanahoria, patata y pimiento', '[{"appliance":"thermomix","time":50,"difficulty":"facil","prepSummary":"Pica las verduras y sofríelas con aceite. Añade las lentejas, tomate, pimentón y agua (o caldo), y cocina a 100°C o Varoma, giro inverso y velocidad cuchara durante 35-45 minutos, hasta que las lentejas estén tiernas."},{"appliance":"olla_express","time":35,"difficulty":"facil","prepSummary":"Sofríe las verduras picadas en la olla. Incorpora las lentejas, tomate, pimentón y agua (o caldo). Cierra la olla y cocina a presión durante 15-20 minutos desde que sube la válvula, luego deja despresurizar."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], true, '[{"text":"Lavar {{Lentejas}} bajo el grifo en un colador hasta que el agua salga limpia y escurrir bien.","minutes":2,"kind":"prep"},{"text":"Pelar {{Zanahoria}} y cortar en rodajas de medio centímetro.","minutes":2,"kind":"prep"},{"text":"Pelar {{Patata}} y cortar en dados de unos 2 cm.","minutes":2,"kind":"prep"},{"text":"Retirar las semillas de {{Pimiento rojo}} y cortar en dados pequeños.","minutes":2,"kind":"prep"},{"text":"Pelar {{Cebolla}} y picar en dados finos.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva}} en una olla a fuego medio hasta que esté caliente.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla picada en el aceite caliente a fuego medio hasta que esté transparente, unos 3 min.","minutes":3,"kind":"activo"},{"text":"Añadir el pimiento rojo y la zanahoria a la olla y sofreír a fuego medio hasta que empiecen a ablandarse, unos 3 min.","minutes":3,"kind":"activo"},{"text":"Añadir {{Tomate triturado}} y {{Pimentón|pizca}} y remover hasta integrar bien con las verduras.","minutes":2,"kind":"activo"},{"text":"Incorporar las lentejas escurridas y la patata en dados a la olla y remover para mezclar todo.","minutes":1,"kind":"activo"},{"text":"Cubrir con agua fría hasta superar los ingredientes unos 3 cm y llevar a ebullición a fuego fuerte.","minutes":5,"kind":"activo"},{"text":"Reducir a fuego suave, tapar la olla y cocer hasta que las lentejas estén tiernas y la patata cocida, unos 20 min.","minutes":20,"kind":"pasivo"},{"text":"Retirar del fuego y servir las lentejas con las verduras bien repartidas en cada plato.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'olla', NULL),
  ('legumbres_002', 'Lentejas con chorizo', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 50, 'facil', 'invierno', 432, 22, 44, 18, 2, true, true, '{}', '[{"name":"Lentejas","amount":200,"unit":"g"},{"name":"Chorizo","amount":80,"unit":"g"},{"name":"Zanahoria","amount":80,"unit":"g"},{"name":"Patata","amount":120,"unit":"g"},{"name":"Cebolla","amount":70,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Pimentón","amount":5,"unit":"g"}]'::jsonb, '{"Pelar cebolla y picar en trozos pequeños.","Pelar zanahoria y cortar en rodajas de medio centímetro.","Pelar patata y cortar en trozos medianos de unos 3 cm.","Cortar chorizo en rodajas de medio centímetro.","Calentar aceite de oliva en una olla a fuego medio hasta que esté caliente.","Sofreír la cebolla picada en la olla a fuego medio hasta que esté transparente, unos 5 min.","Añadir la zanahoria y sofreír junto a la cebolla a fuego medio durante 3 min, removiendo con frecuencia.","Añadir el chorizo en rodajas y sofreír 2 min hasta que suelte la grasa.","Añadir pimentón y remover rápidamente durante 20 segundos para que no se queme.","Añadir tomate triturado y sofreír a fuego medio 3 min hasta que reduzca ligeramente.","Incorporar lentejas y la patata troceada; cubrir con agua fría hasta superar 4 cm los ingredientes.","Llevar a ebullición a fuego fuerte y retirar la espuma que suba a la superficie.","Tapar la olla, bajar a fuego suave y cocer hasta que las lentejas estén tiernas, unos 35 min.","Comprobar el punto de sal y servir las lentejas bien calientes en cuenco hondo."}', 'Lentejas tradicionales guisadas con chorizo y patata', '[{"appliance":"thermomix","time":50,"difficulty":"facil","prepSummary":"Sofríe la cebolla, zanahoria y chorizo. Añade el tomate, pimentón, lentejas, patata y agua. Programa 30-35 min a 100°C, velocidad cuchara, giro inverso. Quedarán unas lentejas cremosas y con todo el sabor."},{"appliance":"olla_express","time":40,"difficulty":"facil","prepSummary":"Prepara un sofrito con cebolla, zanahoria y chorizo en la olla. Incorpora el tomate, pimentón, lentejas, patata y agua. Cierra y cocina a presión durante 20-25 minutos. El resultado son unas lentejas tiernas y sabrosas en mucho menos tiempo."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, ARRAY['cerdo']::main_protein[], true, '[{"text":"Pelar {{Cebolla}} y picar en trozos pequeños.","minutes":2,"kind":"prep"},{"text":"Pelar {{Zanahoria}} y cortar en rodajas de medio centímetro.","minutes":2,"kind":"prep"},{"text":"Pelar {{Patata}} y cortar en trozos medianos de unos 3 cm.","minutes":2,"kind":"prep"},{"text":"Cortar {{Chorizo}} en rodajas de medio centímetro.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una olla a fuego medio hasta que esté caliente.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla picada en la olla a fuego medio hasta que esté transparente, unos 5 min.","minutes":5,"kind":"activo"},{"text":"Añadir la zanahoria y sofreír junto a la cebolla a fuego medio durante 3 min, removiendo con frecuencia.","minutes":3,"kind":"activo"},{"text":"Añadir el chorizo en rodajas y sofreír 2 min hasta que suelte la grasa.","minutes":2,"kind":"activo"},{"text":"Añadir {{Pimentón|pizca}} y remover rápidamente durante 20 segundos para que no se queme.","minutes":1,"kind":"activo"},{"text":"Añadir {{Tomate triturado}} y sofreír a fuego medio 3 min hasta que reduzca ligeramente.","minutes":3,"kind":"activo"},{"text":"Incorporar {{Lentejas}} y la patata troceada; cubrir con agua fría hasta superar 4 cm los ingredientes.","minutes":1,"kind":"activo"},{"text":"Llevar a ebullición a fuego fuerte y retirar la espuma que suba a la superficie.","minutes":4,"kind":"activo"},{"text":"Tapar la olla, bajar a fuego suave y cocer hasta que las lentejas estén tiernas, unos 35 min.","minutes":35,"kind":"pasivo"},{"text":"Comprobar el punto de sal y servir las lentejas bien calientes en cuenco hondo.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'olla', NULL)
