  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id, extra_proteins, freezable, steps_rich, estrella, occasion, kid_favourite, tecnica, cocina
) values
  ('legumbres_003', 'Garbanzos con espinacas', 'legumbres', 'legumbre', NULL, ARRAY['primero','plato_unico']::meal_role[], 'completo', NULL, NULL, 30, 'facil', 'all', 384, 16, 42, 16, 2, true, true, '{"gluten"}', '[{"name":"Garbanzos cocidos","amount":300,"unit":"g"},{"name":"Espinacas","amount":200,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Pan del día anterior","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Pimentón","amount":4,"unit":"g"},{"name":"Comino","amount":2,"unit":"g"}]'::jsonb, '{"Pelar y picar ajo fino.","Cortar pan del día anterior en trozos pequeños.","Calentar aceite de oliva en sartén a fuego medio hasta que esté caliente.","Freír los trozos de pan del día anterior en el aceite caliente hasta que estén dorados; retirar y reservar.","Freír el ajo picado en el mismo aceite a fuego suave hasta que se dore ligeramente; retirar y reservar junto al pan.","Triturar el pan frito y el ajo frito con pimentón y comino hasta obtener una majada homogénea; reservar.","Sofreír espinacas en la misma sartén a fuego medio hasta que se reduzcan y estén tiernas.","Añadir tomate triturado sobre las espinacas y remover; cocer a fuego medio hasta que el tomate pierda el agua.","Añadir garbanzos cocidos y la majada reservada; remover para integrar bien.","Cocer a fuego suave, removiendo de vez en cuando, hasta que la salsa espese y los sabores se integren.","Servir los garbanzos con espinacas en platos hondos, bien calientes."}', 'Garbanzos con espinacas y majada de pan frito al estilo andaluz', '[{"appliance":"horno","time":45,"difficulty":"facil","prepSummary":"Sofríe el ajo y las espinacas en una sartén. Traslada a una cazuela de horno con los garbanzos, tomate, especias y el pan tostado. Hornea a 180°C durante unos 30-35 minutos para que los sabores se integren bien, cubierto para mantener la humedad."},{"appliance":"thermomix","time":30,"difficulty":"facil","prepSummary":"Trocea el ajo y sofríelo con aceite. Añade el tomate y cocina unos minutos. Incorpora las espinacas, garbanzos, especias y el pan desmenuzado, cocinando a 100°C, velocidad cuchara, giro inverso, durante 15-20 minutos para que los sabores se fundan."},{"appliance":"olla_express","time":25,"difficulty":"facil","prepSummary":"Sofríe el ajo en la olla abierta con aceite. Añade el tomate, las espinacas, los garbanzos, especias y el pan. Cierra la olla y cocina a presión durante 5-7 minutos. Despresuriza y remueve para integrar los sabores."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], true, '[{"text":"Pelar y picar {{Ajo}} fino.","minutes":2,"kind":"prep"},{"text":"Cortar {{Pan del día anterior}} en trozos pequeños.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego medio hasta que esté caliente.","minutes":1,"kind":"activo"},{"text":"Freír los trozos de pan del día anterior en el aceite caliente hasta que estén dorados; retirar y reservar.","minutes":3,"kind":"activo"},{"text":"Freír el ajo picado en el mismo aceite a fuego suave hasta que se dore ligeramente; retirar y reservar junto al pan.","minutes":2,"kind":"activo"},{"text":"Triturar el pan frito y el ajo frito con {{Pimentón|pizca}} y {{Comino|pizca}} hasta obtener una majada homogénea; reservar.","minutes":2,"kind":"prep"},{"text":"Sofreír {{Espinacas}} en la misma {{@Sartén}} a fuego medio hasta que se reduzcan y estén tiernas.","minutes":3,"kind":"activo"},{"text":"Añadir {{Tomate triturado}} sobre las espinacas y remover; cocer a fuego medio hasta que el tomate pierda el agua.","minutes":3,"kind":"activo"},{"text":"Añadir {{Garbanzos cocidos}} y la majada reservada; remover para integrar bien.","minutes":2,"kind":"activo"},{"text":"Cocer a fuego suave, removiendo de vez en cuando, hasta que la salsa espese y los sabores se integren.","minutes":5,"kind":"pasivo"},{"text":"Servir los garbanzos con espinacas en platos hondos, bien calientes.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'olla', NULL),
  ('legumbres_004', 'Cocido madrileño', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 120, 'elaborada', 'invierno', 618, 38, 40, 32, 2, true, true, '{}', '[{"name":"Garbanzos","amount":250,"unit":"g"},{"name":"Morcillo de ternera","amount":150,"unit":"g"},{"name":"Pollo","amount":120,"unit":"g"},{"name":"Tocino","amount":50,"unit":"g"},{"name":"Chorizo","amount":60,"unit":"g"},{"name":"Patata","amount":150,"unit":"g"},{"name":"Zanahoria","amount":100,"unit":"g"},{"name":"Repollo","amount":150,"unit":"g"}]'::jsonb, '{"Poner garbanzos en un bol grande con agua fría abundante y dejar en remojo un mínimo de 12 horas.","Escurrir los garbanzos remojados y reservar.","Pelar patata y zanahoria.","Cortar la patata en trozos grandes y la zanahoria en rodajas gruesas.","Retirar las hojas exteriores duras de repollo y cortar en cuartos.","Colocar morcillo de ternera, pollo y tocino en una olla grande; cubrir con agua fría abundante.","Llevar a ebullición a fuego fuerte.","Espumar la superficie con una espumadera hasta que el caldo salga limpio.","Añadir los garbanzos escurridos y la zanahoria; bajar el fuego a suave y tapar.","Cocer tapado a fuego suave durante 45 min.","Incorporar la patata y el repollo a la olla.","Añadir chorizo entero; tapar y cocer a fuego suave durante 20 min hasta que la patata esté tierna.","Retirar el morcillo de ternera, el pollo, el tocino y el chorizo de la olla.","Cortar las carnes y el tocino en porciones individuales; reservar en un plato caliente.","Servir primero el caldo en tazón hondo, luego los garbanzos con las verduras y, por último, las carnes."}', 'Cocido tradicional de garbanzos con carnes y verduras en tres vuelcos', '[{"appliance":"horno","time":210,"difficulty":"elaborada","prepSummary":"Cocinar en una olla de hierro fundido o cazuela apta para horno a 150°C durante 3.5 a 4 horas. Este método asegura una cocción lenta y uniforme, logrando carnes y garbanzos extremadamente tiernos y un caldo profundo."},{"appliance":"thermomix","time":100,"difficulty":"normal","prepSummary":"Permite cocer los garbanzos y las carnes en el vaso, y las verduras en el Varoma, optimizando tiempos. Cocinar a 100°C, velocidad cuchara, durante 90-120 minutos, añadiendo los ingredientes en fases para una cocción perfecta y controlada."},{"appliance":"olla_express","time":75,"difficulty":"normal","prepSummary":"Ideal para acortar drásticamente los tiempos de cocción. Cocinar los garbanzos y carnes a presión durante 45-60 minutos, añadiendo las verduras (repollo, patata, zanahoria) al final para que no se deshagan, logrando una ternura excepcional en menos tiempo."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, ARRAY['ternera','cerdo','pollo']::main_protein[], true, '[{"text":"Poner {{Garbanzos}} en un bol grande con agua fría abundante y dejar en remojo un mínimo de 12 horas.","minutes":720,"kind":"espera"},{"text":"Escurrir los garbanzos remojados y reservar.","minutes":2,"kind":"prep"},{"text":"Pelar {{Patata}} y {{Zanahoria}}.","minutes":3,"kind":"prep"},{"text":"Cortar la patata en trozos grandes y la zanahoria en rodajas gruesas.","minutes":3,"kind":"prep"},{"text":"Retirar las hojas exteriores duras de {{Repollo}} y cortar en cuartos.","minutes":2,"kind":"prep"},{"text":"Colocar {{Morcillo de ternera}}, {{Pollo}} y {{Tocino}} en una olla grande; cubrir con agua fría abundante.","minutes":2,"kind":"prep"},{"text":"Llevar a ebullición a fuego fuerte.","minutes":8,"kind":"activo"},{"text":"Espumar la superficie con una espumadera hasta que el caldo salga limpio.","minutes":5,"kind":"activo"},{"text":"Añadir los garbanzos escurridos y la zanahoria; bajar el fuego a suave y tapar.","minutes":2,"kind":"activo"},{"text":"Cocer tapado a fuego suave durante 45 min.","minutes":45,"kind":"pasivo"},{"text":"Incorporar la patata y el repollo a la olla.","minutes":2,"kind":"activo"},{"text":"Añadir {{Chorizo}} entero; tapar y cocer a fuego suave durante 20 min hasta que la patata esté tierna.","minutes":20,"kind":"pasivo"},{"text":"Retirar el morcillo de ternera, el pollo, el tocino y el chorizo de la olla.","minutes":2,"kind":"activo"},{"text":"Cortar las carnes y el tocino en porciones individuales; reservar en un plato caliente.","minutes":3,"kind":"activo"},{"text":"Servir primero el caldo en tazón hondo, luego los garbanzos con las verduras y, por último, las carnes.","minutes":3,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'olla', NULL),
  ('legumbres_005', 'Potaje de garbanzos con bacalao', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 60, 'normal', 'invierno', 412, 30, 40, 12, 2, true, true, '{"pescado"}', '[{"name":"Garbanzos cocidos","amount":300,"unit":"g"},{"name":"Bacalao desalado","amount":150,"unit":"g"},{"name":"Espinacas","amount":150,"unit":"g"},{"name":"Cebolla","amount":70,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Pimentón","amount":5,"unit":"g"}]'::jsonb, '{"Picar cebolla en trozos pequeños y laminar ajo.","Desmigar bacalao desalado con los dedos en lascas medianas y reservar.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla picada hasta que esté transparente, unos 5 min a fuego medio.","Añadir el ajo laminado y sofreír hasta que empiece a dorarse, unos 2 min.","Incorporar pimentón y remover durante 30 segundos para que no se queme.","Añadir tomate triturado y sofreír a fuego medio hasta que reduzca y pierda el agua, unos 4 min.","Incorporar espinacas y remover hasta que se ablanden y reduzcan su volumen, unos 2 min.","Añadir garbanzos cocidos y mezclar bien con el sofrito.","Cubrir con agua hasta superar ligeramente los garbanzos, llevar a ebullición y tapar la olla.","Cocer a fuego suave durante 15 min hasta que el caldo espese y los sabores se integren.","Incorporar el bacalao desmigado, remover con suavidad y cocer 3 min más hasta que esté hecho.","Servir el potaje bien caliente, repartido en 2 platos hondos."}', 'Potaje de vigilia con garbanzos, bacalao y espinacas', '[{"appliance":"horno","time":75,"difficulty":"normal","prepSummary":"Comienza el sofrito de cebolla y ajo en una cazuela apta para horno. Incorpora el resto de ingredientes y cocina a 180°C durante 60 minutos, permitiendo que los sabores se integren lentamente."},{"appliance":"thermomix","time":55,"difficulty":"facil","prepSummary":"Pica y sofríe la cebolla y el ajo. Añade el tomate, garbanzos, bacalao y espinacas, y cocina a 100°C, velocidad cuchara, giro inverso durante 45 minutos para una cocción homogénea."},{"appliance":"olla_express","time":35,"difficulty":"normal","prepSummary":"Sofríe la cebolla y el ajo en la olla. Incorpora el resto de ingredientes, cierra la olla y cocina a presión durante 10-12 minutos desde que sube la válvula para un potaje rápido y sabroso."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, ARRAY['pescado_blanco']::main_protein[], true, '[{"text":"Picar {{Cebolla}} en trozos pequeños y laminar {{Ajo}}.","minutes":3,"kind":"prep"},{"text":"Desmigar {{Bacalao desalado}} con los dedos en lascas medianas y reservar.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una olla a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla picada hasta que esté transparente, unos 5 min a fuego medio.","minutes":5,"kind":"activo"},{"text":"Añadir el ajo laminado y sofreír hasta que empiece a dorarse, unos 2 min.","minutes":2,"kind":"activo"},{"text":"Incorporar {{Pimentón|pizca}} y remover durante 30 segundos para que no se queme.","minutes":1,"kind":"activo"},{"text":"Añadir {{Tomate triturado}} y sofreír a fuego medio hasta que reduzca y pierda el agua, unos 4 min.","minutes":4,"kind":"activo"},{"text":"Incorporar {{Espinacas}} y remover hasta que se ablanden y reduzcan su volumen, unos 2 min.","minutes":2,"kind":"activo"},{"text":"Añadir {{Garbanzos cocidos}} y mezclar bien con el sofrito.","minutes":1,"kind":"activo"},{"text":"Cubrir con agua hasta superar ligeramente los garbanzos, llevar a ebullición y tapar la olla.","minutes":3,"kind":"activo"},{"text":"Cocer a fuego suave durante 15 min hasta que el caldo espese y los sabores se integren.","minutes":15,"kind":"pasivo"},{"text":"Incorporar el bacalao desmigado, remover con suavidad y cocer 3 min más hasta que esté hecho.","minutes":3,"kind":"activo"},{"text":"Servir el potaje bien caliente, repartido en 2 platos hondos.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'olla', NULL),
  ('legumbres_006', 'Fabada asturiana', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 150, 'elaborada', 'invierno', 682, 32, 42, 42, 2, true, true, '{}', '[{"name":"Fabes","amount":250,"unit":"g"},{"name":"Chorizo","amount":80,"unit":"g"},{"name":"Morcilla","amount":80,"unit":"g"},{"name":"Panceta","amount":80,"unit":"g"},{"name":"Lacón","amount":80,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Azafrán","amount":1,"unit":"g"}]'::jsonb, '{"Remojar fabes en agua fría abundante durante un mínimo de 12 horas antes de cocinar.","Escurrir las fabes y colocarlas en una olla grande; cubrir con agua fría hasta 4 cm por encima.","Cortar chorizo, morcilla, panceta y lacón en piezas de unos 4 cm.","Cortar cebolla en 2 mitades sin pelar del todo.","Añadir el chorizo, la morcilla, la panceta, el lacón y la cebolla a la olla con las fabes.","Añadir aceite de oliva y llevar a ebullición a fuego fuerte.","Retirar la espuma que suba a la superficie con una espumadera hasta que el caldo quede limpio.","Reducir el fuego a suave y ''asustar'' la cocción añadiendo un vaso de agua fría; repetir 2 veces más durante la cocción.","Tostar azafrán en seco en una sartén pequeña a fuego suave durante 30 segundos hasta que desprenda aroma.","Disolver el azafrán tostado en un poco del caldo de la olla y verter el líquido de vuelta a la olla.","Cocer a fuego muy suave, con la olla semitapada, hasta que las fabes estén tiernas y el caldo haya espesado ligeramente.","Retirar la cebolla, rectificar de sal si fuera necesario y dejar reposar la fabada tapada fuera del fuego.","Servir en cazuela de barro o plato hondo, repartiendo las fabes y el compango a partes iguales entre las raciones."}', 'Alubias blancas guisadas con chorizo, morcilla, panceta y lacón', '[{"appliance":"horno","time":180,"difficulty":"elaborada","prepSummary":"Tras un remojo previo de las fabes, sofríe la cebolla y los embutidos en una cazuela apta para horno. Añade las fabes, el azafrán y agua, y cocina a fuego lento en el horno a 160°C durante 3 horas, hasta que las fabes estén muy tiernas y los sabores bien integrados."},{"appliance":"thermomix","time":135,"difficulty":"elaborada","prepSummary":"Remoja las fabes la noche anterior. Sofríe la cebolla y los embutidos en el vaso. Incorpora las fabes remojadas, azafrán y agua, y cocina a 100°C, velocidad cuchara, giro inverso, durante 120-150 minutos, ajustando el tiempo hasta que las fabes estén en su punto."},{"appliance":"olla_express","time":60,"difficulty":"normal","prepSummary":"Imprescindible remojar las fabes. Sofríe la cebolla y los embutidos en la olla. Añade las fabes, azafrán y agua, cierra la olla y cocina a presión alta durante 25-35 minutos. Deja despresurizar de forma natural para un resultado óptimo."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, ARRAY['cerdo']::main_protein[], true, '[{"text":"Remojar {{Fabes}} en agua fría abundante durante un mínimo de 12 horas antes de cocinar.","kind":"espera"},{"text":"Escurrir las fabes y colocarlas en una olla grande; cubrir con agua fría hasta 4 cm por encima.","minutes":3,"kind":"prep"},{"text":"Cortar {{Chorizo}}, {{Morcilla}}, {{Panceta}} y {{Lacón}} en piezas de unos 4 cm.","minutes":5,"kind":"prep"},{"text":"Cortar {{Cebolla}} en 2 mitades sin pelar del todo.","minutes":2,"kind":"prep"},{"text":"Añadir el chorizo, la morcilla, la panceta, el lacón y la cebolla a la olla con las fabes.","minutes":2,"kind":"prep"},{"text":"Añadir {{Aceite de oliva|chorrito}} y llevar a ebullición a fuego fuerte.","minutes":8,"kind":"activo"},{"text":"Retirar la espuma que suba a la superficie con una espumadera hasta que el caldo quede limpio.","minutes":5,"kind":"activo"},{"text":"Reducir el fuego a suave y ''asustar'' la cocción añadiendo un vaso de agua fría; repetir 2 veces más durante la cocción.","minutes":3,"kind":"activo"},{"text":"Tostar {{Azafrán|pizca}} en seco en una sartén pequeña a fuego suave durante 30 segundos hasta que desprenda aroma.","minutes":1,"kind":"activo"},{"text":"Disolver el azafrán tostado en un poco del caldo de la olla y verter el líquido de vuelta a la olla.","minutes":2,"kind":"activo"},{"text":"Cocer a fuego muy suave, con la olla semitapada, hasta que las fabes estén tiernas y el caldo haya espesado ligeramente.","minutes":100,"kind":"pasivo"},{"text":"Retirar la cebolla, rectificar de sal si fuera necesario y dejar reposar la fabada tapada fuera del fuego.","minutes":10,"kind":"espera"},{"text":"Servir en cazuela de barro o plato hondo, repartiendo las fabes y el compango a partes iguales entre las raciones.","minutes":3,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'olla', NULL),
  ('legumbres_007', 'Alubias rojas estofadas', 'legumbres', 'legumbre', NULL, ARRAY['primero','plato_unico']::meal_role[], 'completo', NULL, NULL, 60, 'facil', 'invierno', 366, 19, 48, 9, 2, true, true, '{}', '[{"name":"Alubias rojas","amount":250,"unit":"g"},{"name":"Zanahoria","amount":80,"unit":"g"},{"name":"Puerro","amount":80,"unit":"g"},{"name":"Pimiento verde","amount":70,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":18,"unit":"ml"},{"name":"Pimentón","amount":4,"unit":"g"}]'::jsonb, '{"Escurrir alubias rojas del agua de remojo y reservar en un bol.","Pelar zanahoria y cortar en rodajas de 1 cm.","Limpiar puerro, retirar la parte verde oscura y cortar en rodajas de 1 cm.","Limpiar pimiento verde, retirar las semillas y cortar en trozos medianos.","Pelar ajo y picar fino.","Colocar las alubias escurridas en una olla y cubrir con agua fría abundante.","Llevar la olla a ebullición a fuego fuerte.","Añadir la zanahoria, el puerro y el pimiento verde a la olla cuando rompa a hervir.","Bajar a fuego suave, tapar y cocer hasta que las alubias estén tiernas, unos 35 min.","Añadir un chorrito de agua fría 2 veces durante la cocción para ''asustar'' las alubias.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír el ajo picado en la sartén a fuego medio hasta que se dore ligeramente, unos 2 min.","Añadir tomate triturado al sofrito y remover para integrar.","Añadir pimentón al sofrito y remover bien.","Cocer el sofrito a fuego medio, removiendo, hasta que reduzca y pierda el agua, unos 5 min.","Incorporar el sofrito a la olla con las alubias y las verduras; remover con cuidado para integrar.","Cocer el conjunto a fuego suave, destapado, hasta que el caldo ligue y tome cuerpo, unos 10 min.","Servir las alubias estofadas bien calientes, repartidas en 2 platos hondos."}', 'Alubias rojas guisadas con puerro, zanahoria y pimiento', '[{"appliance":"horno","time":80,"difficulty":"facil","prepSummary":"Prepara el sofrito en una olla apta para horno en la encimera. Luego, añade las alubias, tomate, pimentón y agua, cubre y hornea a 160°C durante unos 80 minutos para un guiso tierno y homogéneo."},{"appliance":"thermomix","time":55,"difficulty":"facil","prepSummary":"Pica las verduras en el vaso, sofríelas con aceite. Añade las alubias, tomate, pimentón y agua, y cocina a 100°C, velocidad cuchara, giro inverso, durante 55 minutos hasta que estén tiernas."},{"appliance":"olla_express","time":35,"difficulty":"facil","prepSummary":"Sofríe las verduras en la olla. Incorpora las alubias, tomate, pimentón y agua, cierra la olla y cocina a presión durante 15-20 minutos desde que sube la válvula para un guiso rápido y sabroso."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], true, '[{"text":"Escurrir {{Alubias rojas}} del agua de remojo y reservar en un bol.","minutes":2,"kind":"prep"},{"text":"Pelar {{Zanahoria}} y cortar en rodajas de 1 cm.","minutes":3,"kind":"prep"},{"text":"Limpiar {{Puerro}}, retirar la parte verde oscura y cortar en rodajas de 1 cm.","minutes":2,"kind":"prep"},{"text":"Limpiar {{Pimiento verde}}, retirar las semillas y cortar en trozos medianos.","minutes":2,"kind":"prep"},{"text":"Pelar {{Ajo}} y picar fino.","minutes":1,"kind":"prep"},{"text":"Colocar las alubias escurridas en una olla y cubrir con agua fría abundante.","minutes":1,"kind":"prep"},{"text":"Llevar la olla a ebullición a fuego fuerte.","minutes":5,"kind":"activo"},{"text":"Añadir la zanahoria, el puerro y el pimiento verde a la olla cuando rompa a hervir.","minutes":1,"kind":"activo"},{"text":"Bajar a fuego suave, tapar y cocer hasta que las alubias estén tiernas, unos 35 min.","minutes":35,"kind":"pasivo"},{"text":"Añadir un chorrito de agua fría 2 veces durante la cocción para ''asustar'' las alubias.","minutes":1,"kind":"paralelo","during":8},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego medio.","minutes":1,"kind":"paralelo","during":8},{"text":"Sofreír el ajo picado en la sartén a fuego medio hasta que se dore ligeramente, unos 2 min.","minutes":2,"kind":"activo"},{"text":"Añadir {{Tomate triturado}} al sofrito y remover para integrar.","minutes":1,"kind":"activo"},{"text":"Añadir {{Pimentón|pizca}} al sofrito y remover bien.","minutes":1,"kind":"activo"},{"text":"Cocer el sofrito a fuego medio, removiendo, hasta que reduzca y pierda el agua, unos 5 min.","minutes":5,"kind":"activo"},{"text":"Incorporar el sofrito a la olla con las alubias y las verduras; remover con cuidado para integrar.","minutes":1,"kind":"activo"},{"text":"Cocer el conjunto a fuego suave, destapado, hasta que el caldo ligue y tome cuerpo, unos 10 min.","minutes":10,"kind":"pasivo"},{"text":"Servir las alubias estofadas bien calientes, repartidas en 2 platos hondos.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'olla', NULL)
